fn setWindowData(hwnd: HWND, ptr: ?*anyopaque) void {
    const raw: LONG_PTR = if (ptr) |value|
        @intCast(@intFromPtr(value))
    else
        0;
    _ = sys.SetWindowLongPtrW(hwnd, c.GWLP_USERDATA, raw);
}

fn windowData(comptime T: type, hwnd: HWND) ?*T {
    const raw = sys.GetWindowLongPtrW(hwnd, c.GWLP_USERDATA);
    if (raw == 0) return null;
    return @ptrFromInt(@as(usize, @intCast(raw)));
}

const RTL_OSVERSIONINFOW = sys.RTL_OSVERSIONINFOW;

/// Probe the Windows build number once; cache on `App.os_build`. Build
/// 22000+ is Win11 (integrated titlebar / Snap Layouts); 22621+ supports
/// `DWMWA_SYSTEMBACKDROP_TYPE`. Failure returns 0 so downstream gates
/// fall through to Win10 behaviour (the safe default).
fn probeWindowsBuild() u32 {
    var info: RTL_OSVERSIONINFOW = .{
        .dwOSVersionInfoSize = @sizeOf(RTL_OSVERSIONINFOW),
        .dwMajorVersion = 0,
        .dwMinorVersion = 0,
        .dwBuildNumber = 0,
        .dwPlatformId = 0,
        .szCSDVersion = .{0} ** 128,
    };
    const rc = sys.RtlGetVersion(&info);
    if (rc < 0) return 0;
    return info.dwBuildNumber;
}

fn shouldUseIntegratedTitlebar(
    os_build: u32,
    show_tab_bar: configpkg.Config.WindowShowTabBar,
) bool {
    return os_build >= c.OS_BUILD_WIN11_21H2 and show_tab_bar != .never;
}

/// Whether `window-decoration = none` keeps the system frame and only
/// collapses its caption, the integrated titlebar's mechanism with a 0 px
/// row. The frame gives the window its resize edges, shadow, Snap,
/// work-area maximize and the Alt+Space window menu, with nothing to
/// paint. Windows 11 only: Windows 10 draws its window border inside the
/// non-client top this would remove, and stays frameless. So does the
/// quick terminal, which is sized from config and placed flush with a
/// screen edge by its window rect: the frame's invisible resize margins
/// would pull it in from that edge.
fn undecoratedKeepsFrame(os_build: u32, quick_terminal: bool) bool {
    return os_build >= c.OS_BUILD_WIN11_21H2 and !quick_terminal;
}

fn dispatchDwmNcMessage(
    hwnd: HWND,
    msg: UINT,
    wParam: WPARAM,
    lParam: LPARAM,
) ?LRESULT {
    // Custom Win32 frames should let DWM see caption-hit-test traffic
    // first so native caption-button affordances keep working where
    // the compositor can still own them.
    var result: LRESULT = 0;
    return if (sys.DwmDefWindowProc(hwnd, msg, wParam, lParam, &result) != 0)
        result
    else
        null;
}

