fn decorationsVisibleForConfig(value: configpkg.Config.WindowDecoration) bool {
    return value != .none;
}

fn initialDecorationsVisibleForSource(config: *const configpkg.Config, clone_state_from: ?*const Surface) bool {
    if (clone_state_from) |source| return source.decorations_visible;
    return decorationsVisibleForConfig(config.@"window-decoration");
}

fn decorationVisibilityForChromeValue(active_surface_visible: ?bool, cached_visible: bool) bool {
    return active_surface_visible orelse cached_visible;
}

fn startupHostWindowStyle(framed: bool, fullscreen: bool) u32 {
    return effectiveHostWindowStyle(framed, fullscreen, true) & ~@as(u32, c.WS_VISIBLE);
}

/// The style to write back over the one `CreateWindowEx` gave a host
/// created with `requested`, or null when it kept the request.
///
/// `WS_OVERLAPPED` is 0, so the undecorated host style on Windows 10 (see
/// `undecoratedKeepsFrame`) is a top-level window with neither `WS_POPUP`
/// nor `WS_CHILD`, and `CreateWindowEx` gives every such window
/// `WS_CAPTION` whatever the request says.
/// `SetWindowLongPtr` does not. So with `window-decoration = none`, every
/// window created with no window to copy (the first one, the quick
/// terminal, a restored or adopted window) had a title bar, and a
/// `new_window` clone did not: it and every runtime toggle set the style
/// afterwards through `Surface.applyWindowStyle`. Creating the host as `WS_POPUP` instead would
/// avoid the added caption, but `CW_USEDEFAULT` puts a popup at (0, 0)
/// rather than at the next default position, so the first window would
/// move. Windows also forces `WS_CLIPSIBLINGS` on every top-level window,
/// through either API, so that bit is ignored here.
fn createdHostWindowStyleCorrection(requested: u32, created: u32) ?u32 {
    const forced: u32 = c.WS_CLIPSIBLINGS;
    if ((requested & ~forced) == (created & ~forced)) return null;
    return requested;
}

/// Put back the host style `CreateWindowEx` altered (see
/// `createdHostWindowStyleCorrection`). `App.createHost` calls this while
/// the host is still hidden and has no tabs, so no terminal is sized
/// against, or shown with, the frame Windows added.
fn restoreRequestedHostWindowStyle(hwnd: HWND, requested: u32) void {
    const created: u32 = @truncate(@as(usize, @bitCast(sys.GetWindowLongPtrW(hwnd, c.GWL_STYLE))));
    const style = createdHostWindowStyleCorrection(requested, created) orelse return;
    _ = sys.SetWindowLongPtrW(hwnd, c.GWL_STYLE, @bitCast(@as(usize, style)));
    if (sys.SetWindowPos(
        hwnd,
        null,
        0,
        0,
        0,
        0,
        c.SWP_NOMOVE | c.SWP_NOSIZE | c.SWP_NOZORDER | c.SWP_NOACTIVATE | c.SWP_FRAMECHANGED,
    ) == 0) {
        log.warn("win32 host style restore failed err={}", .{lastError()});
    }
}

/// Windows clipboard text ends its lines with CRLF; the core, and whatever
/// reads an OSC 52 reply, expect LF. A paste turns each LF into one CR, the
/// shell's Enter, so a CRLF left in place arrived as two: an extra empty line
/// after every pasted one, which cmd answers with an extra prompt. Takes
/// ownership of `text` and returns it, or a replacement when it had a CRLF.
fn lfLineEndings(alloc: std.mem.Allocator, text: [:0]u8) ![:0]u8 {
    const size = std.mem.replacementSize(u8, text, "\r\n", "\n");
    if (size == text.len) return text;
    defer alloc.free(text);
    const out = try alloc.allocSentinel(u8, size, 0);
    _ = std.mem.replace(u8, text, "\r\n", "\n", out);
    return out;
}

test "win32 clipboard text gets LF line endings" {
    const alloc = std.testing.allocator;

    const crlf = try lfLineEndings(alloc, try alloc.dupeZ(u8, "cd x\r\nnu\r\n"));
    defer alloc.free(crlf);
    try std.testing.expectEqualStrings("cd x\nnu\n", crlf);

    // A lone CR or LF is left alone, and text without a CRLF is returned as is.
    const plain = try alloc.dupeZ(u8, "a\rb\nc");
    const same = try lfLineEndings(alloc, plain);
    defer alloc.free(same);
    try std.testing.expectEqual(plain.ptr, same.ptr);
    try std.testing.expectEqualStrings("a\rb\nc", same);
}

/// The other direction: the core joins copied lines with LF, and classic
/// Win32 controls (an EDIT, older apps) show an LF-only CF_UNICODETEXT on
/// one line. Returns null when `text` has no bare LF to expand.
fn crlfLineEndings(alloc: std.mem.Allocator, text: []const u8) !?[]u8 {
    var bare: usize = 0;
    for (text, 0..) |byte, i| {
        if (byte == '\n' and (i == 0 or text[i - 1] != '\r')) bare += 1;
    }
    if (bare == 0) return null;
    const out = try alloc.alloc(u8, text.len + bare);
    var o: usize = 0;
    for (text, 0..) |byte, i| {
        if (byte == '\n' and (i == 0 or text[i - 1] != '\r')) {
            out[o] = '\r';
            o += 1;
        }
        out[o] = byte;
        o += 1;
    }
    return out;
}

test "win32 clipboard writes get CRLF line endings" {
    const alloc = std.testing.allocator;

    const crlf = (try crlfLineEndings(alloc, "\na\nb\r\nc\n")).?;
    defer alloc.free(crlf);
    try std.testing.expectEqualStrings("\r\na\r\nb\r\nc\r\n", crlf);

    // Nothing to expand: a CRLF stays one, and a lone CR is left alone.
    try std.testing.expectEqual(@as(?[]u8, null), try crlfLineEndings(alloc, "a\r\nb\rc"));
}

/// The clipboard as UTF-8, for any UTF-16 another program put there. A
/// strict conversion failed the whole paste on one unpaired surrogate (a
/// cut emoji); each one becomes U+FFFD instead, which is also 3 bytes, so
/// the lossy pass runs in place.
fn clipboardTextToUtf8(alloc: std.mem.Allocator, text_w: []const u16) ![:0]u8 {
    const text = try std.unicode.wtf16LeToWtf8AllocZ(alloc, text_w);
    std.unicode.wtf8ToUtf8Lossy(text, text) catch unreachable; // WTF-16 always gives WTF-8
    return text;
}

test "win32 clipboard text with a lone surrogate still pastes" {
    const alloc = std.testing.allocator;
    const text = try clipboardTextToUtf8(alloc, &.{ 'a', 0xD83D, 'b', 0xD83D, 0xDE00, 0xDE00 });
    defer alloc.free(text);
    try std.testing.expectEqualStrings("a\u{FFFD}b\u{1F600}\u{FFFD}", text);
}

/// Another program can hold the clipboard open for a few milliseconds (a
/// clipboard manager, RDP's clipboard sync, Office), and one failed
/// `OpenClipboard` used to drop the whole paste or copy. Retry within a
/// 5 ms QPC budget, without timer-tick sleeps or dispatching messages.
/// Keeping the call synchronous preserves copy/paste order and the
/// confirmation that owns a pending operation. On false, `GetLastError`
/// still holds the last open's error. Scheduling and OpenClipboard itself
/// can take longer; never start another retry after the budget expires.
fn openClipboard(hwnd: ?HWND) bool {
    return openClipboardWith(sys.OpenClipboard, hwnd);
}

const clipboard_open_attempts = 10;
const clipboard_open_budget_ns = 5 * std.time.ns_per_ms;
const clipboard_open_interval_ns = std.time.ns_per_ms / 2;

fn openClipboardWith(open: *const fn (?HWND) callconv(.winapi) BOOL, hwnd: ?HWND) bool {
    var timer = std.time.Timer.start() catch return open(hwnd) != 0;
    return openClipboardWithClock(open, hwnd, &timer);
}

fn openClipboardWithClock(open: *const fn (?HWND) callconv(.winapi) BOOL, hwnd: ?HWND, timer: anytype) bool {
    var open_error: windows.Win32Error = .SUCCESS;
    var next_attempt: u64 = 0;
    for (0..clipboard_open_attempts) |attempt| {
        if (attempt > 0) {
            while (true) {
                const elapsed = timer.read();
                if (elapsed >= clipboard_open_budget_ns) {
                    windows.kernel32.SetLastError(open_error);
                    return false;
                }
                if (elapsed >= next_attempt) break;
                // SwitchToThread, not Sleep: offer the clipboard owner
                // the CPU without waiting for the next timer tick.
                std.Thread.yield() catch {};
            }
        }
        if (open(hwnd) != 0) return true;
        open_error = windows.kernel32.GetLastError();
        const elapsed = timer.read();
        if (elapsed >= clipboard_open_budget_ns) break;
        next_attempt = elapsed + clipboard_open_interval_ns;
    }
    windows.kernel32.SetLastError(open_error);
    return false;
}

test "win32 clipboard open retries while another program holds it" {
    const Fake = struct {
        var calls: usize = 0;
        var fail_first: usize = 0;
        elapsed: u64 = 0,

        fn read(self: *@This()) u64 {
            defer self.elapsed += std.time.ns_per_ms / 20;
            return self.elapsed;
        }

        fn open(_: ?HWND) callconv(.winapi) BOOL {
            calls += 1;
            return if (calls > fail_first) 1 else 0;
        }
    };

    Fake.calls = 0;
    Fake.fail_first = 3;
    var clock: Fake = .{};
    try std.testing.expect(openClipboardWithClock(Fake.open, null, &clock));
    try std.testing.expectEqual(@as(usize, 4), Fake.calls);

    // Held for good: gives up after the last attempt, without one more sleep.
    Fake.calls = 0;
    Fake.fail_first = std.math.maxInt(usize);
    clock = .{};
    try std.testing.expect(!openClipboardWithClock(Fake.open, null, &clock));
    try std.testing.expectEqual(@as(usize, clipboard_open_attempts), Fake.calls);
}

test "win32 clipboard contention stops retrying at its UI budget" {
    const Fake = struct {
        var calls: usize = 0;
        var owner: ?HWND = null;
        elapsed: u64 = 0,
        step: u64,

        fn read(self: *@This()) u64 {
            // A wait (or a preemption) can overrun the whole budget.
            // Clock and yield calls must not replace the open error.
            windows.kernel32.SetLastError(.INVALID_HANDLE);
            defer self.elapsed += self.step;
            return self.elapsed;
        }

        fn open(hwnd: ?HWND) callconv(.winapi) BOOL {
            calls += 1;
            owner = hwnd;
            windows.kernel32.SetLastError(.ACCESS_DENIED);
            return 0;
        }
    };

    for ([_]u64{ clipboard_open_budget_ns, 16 * std.time.ns_per_ms }) |step| {
        Fake.calls = 0;
        var clock: Fake = .{ .step = step };
        const owner: HWND = @ptrFromInt(0x1234); // passed only to the fake
        try std.testing.expect(!openClipboardWithClock(Fake.open, owner, &clock));
        try std.testing.expectEqual(@as(usize, 1), Fake.calls);
        try std.testing.expectEqual(owner, Fake.owner.?);
        try std.testing.expectEqual(windows.Win32Error.ACCESS_DENIED, windows.kernel32.GetLastError());
    }
}

test "win32 clipboard retry stops when a yield crosses its UI budget" {
    // The budget runs out while waiting for the next attempt: no second open.
    const Fake = struct {
        var calls: usize = 0;
        reads: usize = 0,

        fn read(self: *@This()) u64 {
            defer self.reads += 1;
            return switch (self.reads) {
                0 => 0,
                1 => clipboard_open_interval_ns / 2,
                else => clipboard_open_budget_ns,
            };
        }

        fn open(_: ?HWND) callconv(.winapi) BOOL {
            calls += 1;
            windows.kernel32.SetLastError(.ACCESS_DENIED);
            return 0;
        }
    };

    Fake.calls = 0;
    var clock: Fake = .{};
    try std.testing.expect(!openClipboardWithClock(Fake.open, null, &clock));
    try std.testing.expectEqual(@as(usize, 1), Fake.calls);
    try std.testing.expectEqual(windows.Win32Error.ACCESS_DENIED, windows.kernel32.GetLastError());
}

test "win32 clipboard retry uses QPC without opening the real clipboard" {
    const Fake = struct {
        var calls: usize = 0;
        var busy: bool = false;
        fn open(_: ?HWND) callconv(.winapi) BOOL {
            calls += 1;
            windows.kernel32.SetLastError(.ACCESS_DENIED);
            return if (busy) 0 else 1;
        }
    };

    Fake.calls = 0;
    Fake.busy = false;
    try std.testing.expect(openClipboardWith(Fake.open, null));
    try std.testing.expectEqual(@as(usize, 1), Fake.calls);

    Fake.calls = 0;
    Fake.busy = true;
    try std.testing.expect(!openClipboardWith(Fake.open, null));
    try std.testing.expect(Fake.calls >= 1 and Fake.calls <= clipboard_open_attempts);
    try std.testing.expectEqual(windows.Win32Error.ACCESS_DENIED, windows.kernel32.GetLastError());
}

fn surfaceWindowStyle() u32 {
    // Keep the terminal child surface hidden until GL + core init complete,
    // then show it explicitly from Surface.init.
    return c.WS_CHILD | c.WS_CLIPSIBLINGS;
}

/// `framed` picks the system frame: decorated windows, and on Windows 11
/// undecorated ones too (`undecoratedKeepsFrame`).
fn effectiveHostWindowStyle(
    framed: bool,
    fullscreen: bool,
    hosted: bool,
) u32 {
    if (fullscreen) {
        return if (hosted)
            c.WS_VISIBLE | c.WS_POPUP | c.WS_CLIPCHILDREN
        else
            c.WS_VISIBLE | c.WS_POPUP;
    }

    if (framed) {
        return if (hosted)
            c.WS_VISIBLE | WS_OVERLAPPEDWINDOW | c.WS_CLIPCHILDREN
        else
            c.WS_VISIBLE | WS_OVERLAPPEDWINDOW;
    }

    return if (hosted)
        c.WS_VISIBLE | c.WS_OVERLAPPED | c.WS_CLIPCHILDREN
    else
        c.WS_VISIBLE | c.WS_OVERLAPPED;
}

fn sharesHostWindowState(dst_host_id: ?u32, src_host_id: ?u32) bool {
    return dst_host_id != null and src_host_id != null and dst_host_id.? == src_host_id.?;
}

fn sizeLimitEquals(a: apprt.action.SizeLimit, b: apprt.action.SizeLimit) bool {
    return a.min_width == b.min_width and
        a.min_height == b.min_height and
        a.max_width == b.max_width and
        a.max_height == b.max_height;
}

fn shouldShowSurfaceImmediately(host_id: ?u32) bool {
    return host_id == null;
}

fn shouldResizeHostForInitialSize(host_surface_count: usize) bool {
    return host_surface_count == 1;
}

fn sharedHostWindowFrameStateEquals(a: *const Surface, b: *const Surface) bool {
    return a.decorations_visible == b.decorations_visible and
        a.fullscreen == b.fullscreen and
        sizeLimitEquals(a.size_limit, b.size_limit);
}

fn sharedHostWindowTopmostEquals(a: *const Surface, b: *const Surface) bool {
    return a.topmost == b.topmost;
}

fn sharedHostWindowOpacityEquals(a: *const Surface, b: *const Surface) bool {
    return alphaByteForOpacity(effectiveBackgroundOpacity(
        a.background_opacity_default,
        a.background_opacity_force_opaque,
    )) == alphaByteForOpacity(effectiveBackgroundOpacity(
        b.background_opacity_default,
        b.background_opacity_force_opaque,
    ));
}

fn shouldPropagateSharedHostWindowState(source: *const Surface) bool {
    const host = source.host orelse return true;
    return host.activeSurface() == source;
}

fn shouldApplyConfigDecorations(decorations_visible_overridden: bool) bool {
    return !decorations_visible_overridden;
}

fn usesIntegratedTitlebar(
    enabled: bool,
    tab_bar_visible: bool,
    decorations_visible: bool,
) bool {
    return enabled and tab_bar_visible and decorations_visible;
}

/// Whether `window-show-tab-bar` reserves a tab strip at all. `.auto` shows
/// it unconditionally here: the strip also carries the [+] and [▾] controls,
/// which have no other home on this runtime.
fn tabBarVisibleForConfig(value: configpkg.Config.WindowShowTabBar) bool {
    return switch (value) {
        .always, .auto => true,
        .never => false,
    };
}

/// Whether a tab-strip chrome child -- a tab button, the Selection
/// container, the [+] / [▾] cluster -- may be shown.
///
/// `in_strip` is the child's own reason to exist (a tab button inside the
/// visible overflow range, a container with at least one tab). It is not
/// enough on its own: with the tab bar hidden the strip has zero height, so
/// every one of those children still lands as a 1 px window at the top of the
/// client area, above the terminal surface of any tab but the first, and
/// paints itself there (#244).
fn tabStripChildVisible(tab_bar_visible: bool, in_strip: bool) bool {
    return tab_bar_visible and in_strip;
}

fn hostPresentShowCommand(
    is_visible: bool,
    is_iconic: bool,
    is_zoomed: bool,
) ?i32 {
    if (is_iconic) return c.SW_RESTORE;
    if (is_visible) return null;
    return if (is_zoomed) c.SW_MAXIMIZE else c.SW_SHOW;
}

fn intResource(id: usize) INTRESOURCE {
    return @as(INTRESOURCE, @ptrFromInt(id));
}

fn appIconResource() INTRESOURCE {
    return intResource(c.ID_ICON_GHOSTTY);
}

fn loadAppIcon(hinstance: HINSTANCE, small: bool) HICON {
    const cx = if (small) sys.GetSystemMetrics(c.SM_CXSMICON) else sys.GetSystemMetrics(c.SM_CXICON);
    const cy = if (small) sys.GetSystemMetrics(c.SM_CYSMICON) else sys.GetSystemMetrics(c.SM_CYICON);
    return sys.LoadImageW(
        hinstance,
        appIconResource(),
        c.IMAGE_ICON,
        if (cx > 0) cx else if (small) 16 else 32,
        if (cy > 0) cy else if (small) 16 else 32,
        c.LR_SHARED,
    );
}

fn setWindowIcon(hwnd: HWND, hinstance: HINSTANCE) void {
    if (loadAppIcon(hinstance, false)) |icon| {
        _ = sys.SendMessageW(hwnd, c.WM_SETICON, c.ICON_BIG, @as(LPARAM, @bitCast(@intFromPtr(icon))));
    }
    if (loadAppIcon(hinstance, true)) |icon| {
        _ = sys.SendMessageW(hwnd, c.WM_SETICON, c.ICON_SMALL, @as(LPARAM, @bitCast(@intFromPtr(icon))));
    }
}

fn shouldDispatchOcclusion(current: ?bool, visible: bool) bool {
    return current == null or current.? != visible;
}

fn applyProfileSurfaceConfig(
    config: *configpkg.Config,
    profile: *const windows_shell.Profile,
) !void {
    config.@"working-directory" = .home;
    try applyProfileLaunchConfig(config, profile);
}

/// Applies a profile's command plus the kind-specific hardening that has to
/// hold on EVERY launch path — new surface, split, and restore alike. Splits
/// used to apply only the command, which silently dropped the SSH guarantees
/// below, so both paths go through here.
fn applyProfileLaunchConfig(
    config: *configpkg.Config,
    profile: *const windows_shell.Profile,
) !void {
    try applyProfileCommandConfig(config, profile);
    if (profile.kind != .ssh) return;

    try applySshLaunchHardening(config);
}

fn applySshLaunchHardening(config: *configpkg.Config) !void {
    // Shell integration injection rewrites the two-element ssh argv into a
    // space-joined, unquoted `cmd.exe /C` string. A remote session cannot use
    // it anyway: the integration scripts run locally.
    config.@"shell-integration" = .none;

    // `.home` alone loses to an inherited working directory, so resolve the
    // path explicitly and let the drive-absolute branch of the cwd resolver
    // take it. This is the same directory `ssh` itself expands `~` to.
    var home_buf: [std.fs.max_path_bytes]u8 = undefined;
    if (try windows_ssh_hosts.userProfileDir(&home_buf)) |home| {
        const alloc = config._arena.?.allocator();
        config.@"working-directory" = .{ .path = try alloc.dupe(u8, home) };
    }
}

fn applyProfileCommandConfig(
    config: *configpkg.Config,
    profile: *const windows_shell.Profile,
) !void {
    const alloc = config._arena.?.allocator();

    // newConfig() returns a shallow clone, so aliased fields such as
    // command remain owned by the source config arena. Replacing command on
    // the clone must not deinit the inherited value.
    config.command = try profile.command.clone(alloc);
}

fn splitWorkingDirectoryCandidate(live_pwd: ?[]const u8, cached_pwd: ?[]const u8) ?[]const u8 {
    if (live_pwd) |pwd| {
        if (pwd.len > 0) return pwd;
    }
    if (cached_pwd) |pwd| {
        if (pwd.len > 0) return pwd;
    }
    return null;
}

fn applySplitWorkingDirectoryPath(
    config: *configpkg.Config,
    source_pwd: ?[]const u8,
) !bool {
    if (!config.@"split-inherit-working-directory") return false;
    const pwd = source_pwd orelse return false;
    if (pwd.len == 0) return false;

    const alloc = config._arena.?.allocator();
    config.@"working-directory" = .{ .path = try alloc.dupe(u8, pwd) };
    return true;
}

fn shouldTreatWslSplitPwdAsStartupFallback(
    alloc: Allocator,
    command: ?configpkg.Command,
    candidate: []const u8,
    startup_cwd: ?[]const u8,
) !bool {
    const cmd = command orelse return false;
    if (!windows_shell.isWslCommand(cmd)) return false;
    const startup = startup_cwd orelse return false;
    if (candidate.len == 0 or startup.len == 0) return false;

    if (std.ascii.eqlIgnoreCase(candidate, startup)) return true;
    const startup_wsl = (try windows_shell.pathToWsl(alloc, startup)) orelse return false;
    defer alloc.free(startup_wsl);
    return std.mem.eql(u8, candidate, startup_wsl);
}

fn applySplitWorkingDirectoryFromSource(
    app: *App,
    config: *configpkg.Config,
    source: *Surface,
    startup_cwd: ?[]const u8,
) !bool {
    if (!config.@"split-inherit-working-directory") return false;

    const alloc = config._arena.?.allocator();
    const live_pwd = (if (app.test_automation_pwd) |query|
        query(alloc, source)
    else
        source.core().pwd(alloc)) catch |err| blk: {
        log.warn("win32 split cwd inheritance could not query live cwd err={}", .{err});
        break :blk null;
    };

    if (live_pwd) |pwd| {
        if (try shouldTreatWslSplitPwdAsStartupFallback(
            alloc,
            config.command,
            pwd,
            startup_cwd,
        )) {
            if (source.pwd) |cached| {
                if (cached.len > 0) return try applySplitWorkingDirectoryPath(config, cached);
            }
            config.@"working-directory" = .home;
            return true;
        }
    }

    const candidate = splitWorkingDirectoryCandidate(live_pwd, source.pwd) orelse return false;
    if (live_pwd) |pwd| {
        if (candidate.ptr == pwd.ptr and candidate.len == pwd.len) {
            config.@"working-directory" = .{ .path = pwd };
            return true;
        }
    }
    return try applySplitWorkingDirectoryPath(config, candidate);
}

fn shouldInheritSplitWorkingDirectory(source_launched_ssh: bool) bool {
    return !source_launched_ssh;
}

fn shouldResetNewTabWorkingDirectory(
    explicit_window_target: bool,
    inherit_launch_config: bool,
    source_launched_ssh: bool,
) bool {
    return explicit_window_target or (inherit_launch_config and source_launched_ssh);
}

fn detectExplicitStartupWorkingDirectory(alloc: Allocator) bool {
    var iter = cli_args.argsIterator(alloc) catch return false;
    defer iter.deinit();
    while (iter.next()) |arg| {
        if (std.mem.startsWith(u8, arg, "--working-directory=")) return true;
    }
    return false;
}

pub fn getProcAddress(name: [*:0]const u8) callconv(.c) ?*const anyopaque {
    if (sys.wglGetProcAddress(name)) |ptr| {
        const raw = @intFromPtr(ptr);
        if (raw > 3 and raw != std.math.maxInt(usize)) return ptr;
    }

    const wgl = @import("win32/wgl.zig");
    const ptr = wgl.coreProcAddress(name);
    const load_error = wgl.lastLoadError();
    if (load_error != .SUCCESS) {
        recordOpenGLStartupWin32Failure(.load_opengl32, load_error);
    }
    return ptr;
}

const UpdateNotice = struct {
    version_text: ?[]u8 = null,
    release_url: ?[]u8 = null,
    message_text: ?[]u8 = null,
    staged: bool = false,

    fn init(alloc: Allocator, version_text: []const u8, release_url: []const u8, staged: bool) !UpdateNotice {
        return .{
            .version_text = try alloc.dupe(u8, version_text),
            .release_url = try alloc.dupe(u8, release_url),
            .message_text = if (staged)
                try std.fmt.allocPrint(
                    alloc,
                    "Update downloaded and verified: noctty {s} is ready to install. Installing closes all windows and running sessions.",
                    .{version_text},
                )
            else
                try std.fmt.allocPrint(
                    alloc,
                    "Update available: noctty {s} is ready on GitHub Releases.",
                    .{version_text},
                ),
            .staged = staged,
        };
    }

    test "a staged notice says that installing closes the sessions" {
        const alloc = std.testing.allocator;
        var staged = try UpdateNotice.init(alloc, "1.3.200", "https://example.invalid/release", true);
        defer staged.deinit(alloc);
        try std.testing.expect(std.mem.indexOf(u8, staged.message_text.?, "Installing closes all windows and running sessions.") != null);
        var plain = try UpdateNotice.init(alloc, "1.3.200", "https://example.invalid/release", false);
        defer plain.deinit(alloc);
        try std.testing.expect(std.mem.indexOf(u8, plain.message_text.?, "closes") == null);
    }

    fn deinit(self: *UpdateNotice, alloc: Allocator) void {
        if (self.version_text) |value| alloc.free(value);
        if (self.release_url) |value| alloc.free(value);
        if (self.message_text) |value| alloc.free(value);
        self.* = undefined;
    }
};

/// How often a running process asks the automatic check to run again. The
/// check's 24 hour throttle (`updatepkg.throttle_seconds`) decides whether a
/// request is actually made, so this only has to be shorter than the throttle
/// by a margin: six hours means a release is noticed within a day of the
/// throttle expiring, and an early tick just reads the saved state.
const update_recheck_interval_ms: u32 = 6 * 60 * 60 * 1000;

const UpdateCheckRequest = struct {
    alloc: Allocator,
    delivery: *AppDelivery,
    state_path: []u8,
    current_version: std.SemanticVersion,
    current_version_string: []u8,
    release_feed_url: []u8,
    force: bool,
    manual: bool,
    /// Set when a configured or environment feed URL was dropped because it
    /// is not a valid HTTPS URL, naming which one was dropped.
    ignored_feed_source: ?updatepkg.FeedSource,
    respect_dismissal: bool,
    download: bool,
    staged_kind: updatepkg.portable_apply.StagedKind,

    fn deinit(self: *UpdateCheckRequest) void {
        self.alloc.free(self.state_path);
        self.alloc.free(self.current_version_string);
        self.alloc.free(self.release_feed_url);
        self.* = undefined;
    }
};

const UpdateCheckCompletion = struct {
    alloc: Allocator,
    release: ?updatepkg.Release = null,
    manual_message: ?[]u8 = null,
    staged: bool = false,
    /// The check discarded state that belonged to a previously configured
    /// feed, so a notice raised from that feed must not stay actionable.
    clear_stale_notice: bool = false,

    fn deinit(self: *UpdateCheckCompletion) void {
        if (self.release) |*value| value.deinit(self.alloc);
        if (self.manual_message) |value| self.alloc.free(value);
        self.* = undefined;
    }
};

/// A profile discovery that ran off the UI thread (`App.startProfileDiscovery`).
const ProfileDiscoveryCompletion = struct {
    /// Owns everything the discovery allocated, and for the detached worker
    /// the completion itself; its child is the page allocator there, so the
    /// worker borrows nothing from the App.
    arena: std.heap.ArenaAllocator,
    result: anyerror!windows_shell.ProfileDiscovery = error.NotStarted,
    /// `App.profiles_generation` when the discovery started.
    generation: u64,
    /// `App.profile_discovery_attempt` of the worker that ran it, 0 for the
    /// synchronous path.
    attempt: u64 = 0,

    /// Frees the arena, and with it a completion that lives in it.
    fn deinit(self: *ProfileDiscoveryCompletion) void {
        var arena = self.arena;
        arena.deinit();
    }
};

test "an undelivered profile discovery frees what it found" {
    for ([_]bool{ true, false }) |found| {
        var arena: std.heap.ArenaAllocator = .init(std.testing.allocator);
        const completion = try arena.allocator().create(ProfileDiscoveryCompletion);
        completion.* = .{ .arena = arena, .result = error.WslListTimeout, .generation = 0 };
        const alloc = completion.arena.allocator();
        if (found) {
            const profiles = try alloc.alloc(windows_shell.Profile, 1);
            const argv = try alloc.alloc([:0]const u8, 1);
            argv[0] = try alloc.dupeZ(u8, "pwsh.exe");
            profiles[0] = .{
                .kind = .pwsh,
                .key = try alloc.dupe(u8, "pwsh"),
                .label = try alloc.dupe(u8, "PowerShell"),
                .command = .{ .direct = argv },
            };
            completion.result = .{ .profiles = profiles, .complete = true };
        }
        var payload: AppDeliveryPayload = .{ .profiles = completion };
        payload.deinit();
    }
}

const AppDeliveryPayload = union(enum) {
    update: *UpdateCheckCompletion,
    toast: win32_toast_activation.ActivationTarget,
    uia_disconnect: *DeferredUiaDisconnect,
    profiles: *ProfileDiscoveryCompletion,
    jump_list: *win32_jump_list.RebuildJob,

    pub fn deinit(self: *AppDeliveryPayload) void {
        switch (self.*) {
            .update => |completion| {
                const alloc = completion.alloc;
                completion.deinit();
                alloc.destroy(completion);
            },
            .profiles => |completion| completion.deinit(),
            .jump_list => |job| job.deinit(),
            .toast => {},
            .uia_disconnect => |pending| {
                pending.release(pending.ctx);
                std.heap.page_allocator.destroy(pending);
            },
        }
    }
};
const AppDelivery = app_delivery.Channel(AppDeliveryPayload);

const RecoveryStartup = struct {
    attempts: [win32_recovery.max_attempts]win32_recovery.StartupAttempt = undefined,
    count: usize = 0,
    decision: win32_recovery.Decision = .normal,
    /// The decision set the saved session aside and the move happened; the
    /// safe-mode notice says so.
    session_set_aside: bool = false,
};

const recovery_safe_mode_banner =
    "Safe mode: repeated incomplete startups. Built-in defaults are active; your config and saved session were not loaded. Restart noctty to retry normal startup.";
const recovery_safe_mode_banner_w = blk: {
    @setEvalBranchQuota(2_000);
    break :blk std.unicode.utf8ToUtf16LeStringLiteral(recovery_safe_mode_banner);
};
const recovery_session_set_aside_banner =
    "Safe mode: noctty stopped repeatedly while restoring your saved session. Built-in defaults are active and your config was not loaded. The saved session was moved aside with a " ++
    recovery_set_aside_suffix ++ " suffix in noctty's data folder, so the next start opens a fresh window. Restart noctty to retry normal startup.";
const recovery_session_set_aside_banner_w = blk: {
    @setEvalBranchQuota(4_000);
    break :blk std.unicode.utf8ToUtf16LeStringLiteral(recovery_session_set_aside_banner);
};
/// Suffix for a saved session that the last launches died restoring.
const recovery_set_aside_suffix = ".restore-failed";
const recovery_safe_mode_caption_w = std.unicode.utf8ToUtf16LeStringLiteral("noctty safe mode");

test "win32 safe mode reload keeps recovery without loading config" {
    if (builtin.os.tag != .windows) return error.SkipZigTest;
    // No CoreApp or config is installed: recovery reload must return before
    // touching either, for hard and soft reloads alike.
    var app: App = undefined;
    app.safe_mode = true;
    try std.testing.expect(try app.performAction(.app, .reload_config, .{ .soft = false }));
    try std.testing.expect(try app.performAction(.app, .reload_config, .{ .soft = true }));
    var config: configpkg.Config = undefined;
    try app.settingsReconcileDisk(&config, &config, false);
    try app.settingsReconcileDisk(&config, &config, true);
}

/// Filename infix for a startup-ledger record whose write already failed and
/// whose diagnosis is waiting to be folded into the next startup's append.
/// Deliberately disjoint from the `.tmp-` infix used for live atomic-replace
/// sources so cross-instance cleanup can never delete an in-flight write.
const recovery_pending_suffix = ".pending-";

/// How long a ledger transaction waits for another instance to finish its own
/// before giving up. Holders only ever do one small read-merge-write, so a
/// wait this long means something is wrong on the other side; startup must
/// not block on it.
const recovery_ledger_lock_wait_ms: u32 = 2000;
const recovery_ledger_lock_poll_ms: u32 = 10;

/// Serialises every read-merge-append-replace of the startup ledger across
/// processes. Two instances launched at once — a double-click, a jump-list
/// entry plus a shortcut, `wt`-style shell integrations — each load the
/// ledger, append their own attempt and replace the file; the atomic replace
/// keeps the file well-formed but the later writer still overwrites the
/// earlier writer's record. Atomicity was never the problem, serialisation
/// was.
///
/// The lock is a byte-range lock on a sibling `.lock` file. Windows releases
/// it when the holding process exits by any means, so a crashed holder cannot
/// wedge later launches. The sibling is never deleted: removing it while
/// another instance waits on its own handle would let a third instance create
/// a fresh file and lock that instead, splitting the lock in two.
const RecoveryLedgerLock = struct {
    file: std.fs.File,

    /// Returns null when the lock could not be taken inside `wait_ms`; the
    /// caller decides whether that means skip or retry. Errors are the
    /// sibling file itself being unusable, which usually means the ledger
    /// directory is too.
    fn acquire(alloc: Allocator, ledger_path: []const u8, wait_ms: u32) !?RecoveryLedgerLock {
        if (std.fs.path.dirname(ledger_path)) |dir| {
            std.fs.makeDirAbsolute(dir) catch |err| switch (err) {
                error.PathAlreadyExists => {},
                else => return err,
            };
        }
        const lock_path = try std.fmt.allocPrint(alloc, "{s}.lock", .{ledger_path});
        defer alloc.free(lock_path);
        // Open-if-exists, never truncate: the file's bytes are irrelevant and
        // every instance must land on the same one.
        const file = try std.fs.createFileAbsolute(lock_path, .{ .truncate = false, .read = true });
        errdefer file.close();

        const deadline = std.time.milliTimestamp() + wait_ms;
        while (true) {
            if (try tryLockExclusive(file)) return .{ .file = file };
            if (std.time.milliTimestamp() >= deadline) {
                file.close();
                return null;
            }
            std.Thread.sleep(recovery_ledger_lock_poll_ms * std.time.ns_per_ms);
        }
    }

    fn release(self: *RecoveryLedgerLock) void {
        var io_status_block: windows.IO_STATUS_BLOCK = undefined;
        windows.UnlockFile(
            self.file.handle,
            &io_status_block,
            &lock_range_off,
            &lock_range_len,
            null,
        ) catch |err| {
            // Closing the handle drops the lock regardless.
            log.warn("win32 recovery: ledger unlock failed err={}", .{err});
        };
        self.file.close();
        self.* = undefined;
    }

    const lock_range_off: windows.LARGE_INTEGER = 0;
    const lock_range_len: windows.LARGE_INTEGER = 1;

    /// `std.fs.File.tryLock` does not compile on Windows in Zig 0.15.2 (its
    /// `.none` arm returns `void` from a `!bool` function), so the NT call is
    /// made directly with the same one-byte range `std` uses.
    fn tryLockExclusive(file: std.fs.File) !bool {
        var io_status_block: windows.IO_STATUS_BLOCK = undefined;
        windows.LockFile(
            file.handle,
            null,
            null,
            null,
            &io_status_block,
            &lock_range_off,
            &lock_range_len,
            null,
            windows.TRUE, // fail immediately
            windows.TRUE, // exclusive
        ) catch |err| switch (err) {
            error.WouldBlock => return false,
            else => return err,
        };
        return true;
    }
};

const RecoveryLedgerRead = union(enum) {
    /// Missing or invalid: reads as empty history.
    empty,
    /// Written by a newer build, or larger than any history this build writes
    /// (16 attempts are under 2 KiB). It is valid, only not understood here,
    /// and replacing it would reset that build's crash history: callers read
    /// it as empty and write nothing. Waiting does not change that.
    left_alone,
    /// It exists and could not be read just now (a scanner holds it, the
    /// allocator failed). It may be a newer build's, so nothing replaces it;
    /// unlike `left_alone` it may be readable a moment later, and the ready
    /// marker retries.
    unreadable,
    record: std.json.Parsed(win32_recovery.StartupAttemptRecord),

    fn deinit(self: *RecoveryLedgerRead) void {
        if (self.* == .record) self.record.deinit();
    }
};

/// Read and parse the ledger at `path`; `context` names the caller in the log
/// line.
fn readRecoveryLedgerAlloc(
    alloc: Allocator,
    path: []const u8,
    context: []const u8,
) RecoveryLedgerRead {
    // A ledger that exists but cannot be read now (a scanner holds it, the
    // allocator failed) may be a newer build's: reading it as empty would
    // replace it.
    const file = std.fs.openFileAbsolute(path, .{}) catch |err| switch (err) {
        error.FileNotFound => return .empty,
        else => {
            log.warn("win32 recovery: {s} open failed err={}; leaving it untouched", .{ context, err });
            return .unreadable;
        },
    };
    defer file.close();
    const raw = file.readToEndAlloc(alloc, 64 * 1024) catch |err| {
        if (err == error.FileTooBig) {
            log.warn("win32 recovery: {s} history is larger than this build writes; leaving it untouched", .{context});
            return .left_alone;
        }
        log.warn("win32 recovery: {s} read failed err={}; leaving it untouched", .{ context, err });
        return .unreadable;
    };
    defer alloc.free(raw);
    return .{ .record = win32_recovery.parseAlloc(alloc, raw) catch |err| {
        if (err == error.NewerSchema) {
            log.warn("win32 recovery: {s} history was written by a newer noctty; leaving it untouched", .{context});
            return .left_alone;
        }
        if (err == error.OutOfMemory) {
            log.warn("win32 recovery: {s} history could not be parsed; leaving it untouched", .{context});
            return .unreadable;
        }
        log.warn("win32 recovery: {s} ignored invalid history err={}", .{ context, err });
        return .empty;
    } };
}

/// The safe-mode text for `decision`; it names the moved session only when
/// the move happened.
fn recoverySafeModeNotice(decision: win32_recovery.Decision, session_set_aside: bool) ?[:0]const u16 {
    if (decision == .normal) return null;
    return if (session_set_aside) recovery_session_set_aside_banner_w else recovery_safe_mode_banner_w;
}

/// How many message-loop ticks may attempt the ready-marker write before the
/// launch is given up as unresolved.
const recovery_ready_persist_attempts: u8 = 3;

/// Delay before a retried ready-marker write. `GetMessageW` blocks, so an
/// otherwise idle app produces no further ticks on its own and each remaining
/// attempt has to be scheduled. The delay is what makes these retries able to
/// outlast a brief anti-virus or backup handle hold; bounded by the retry
/// budget, the safe-mode notice is released at most
/// `(recovery_ready_persist_attempts - 1) * this` late.
const recovery_ready_retry_delay_ms: u32 = 750;

/// May a tick spend a ready-marker attempt yet?
///
/// The retry timer only guarantees that an attempt *happens*; it cannot stop
/// an earlier unrelated tick — PTY output, a keystroke, a resize — from
/// reaching `resolveRecoveryStartup` first and spending the attempt with no
/// delay at all. A busy terminal would therefore burn the whole budget in
/// microseconds, which is the same defect as retrying on a bare wake. The
/// deadline is what actually makes the spacing real, for every transport.
fn recoveryRetryDue(not_before_ms: ?u64, now_ms: u64) bool {
    const deadline = not_before_ms orelse return true;
    return now_ms >= deadline;
}

/// What to do after a ready-marker attempt failed.
const RecoveryFailureAction = enum {
    /// Budget survives and a spaced retry is armed.
    retry_scheduled,
    /// Budget survives but no retry could be armed, so nothing will bring the
    /// loop back. Retrying immediately instead would spend the remaining
    /// attempts in microseconds — the busy retry the delay exists to prevent —
    /// and would still end with the marker unresolved, just with the failure
    /// counted three times and the log claiming retries that never waited.
    give_up_unschedulable,
    /// Budget exhausted, or an error that cannot clear by waiting.
    give_up_exhausted,
};

fn recoveryFailurePolicy(budget_exhausted: bool, scheduled: bool) RecoveryFailureAction {
    if (budget_exhausted) return .give_up_exhausted;
    return if (scheduled) .retry_scheduled else .give_up_unschedulable;
}

/// Retry budget for the ready marker, spent across message-loop ticks.
///
/// The ready marker is the only thing that breaks a failure streak, so a
/// transient write failure must not be latched as handled — that leaves the
/// launch unresolved on disk for the whole session and feeds the automatic
/// safe mode this branch exists to stop. Retries deliberately ride real
/// message-loop ticks rather than an in-line sleep loop: an earlier ~20 ms
/// three-attempt loop was removed because it could not outlast an anti-virus
/// or backup handle hold, whereas tick-spaced attempts can.
const RecoveryReadyRetry = struct {
    failures: u8 = 0,

    /// Records a failed attempt. Returns true when the launch should be
    /// treated as resolved and no later tick should try again.
    fn recordFailure(self: *RecoveryReadyRetry, err: anyerror) bool {
        self.failures +|= 1;
        // OutOfMemory will not clear by waiting and every retry allocates
        // again, so stop immediately rather than spending the budget.
        if (err == error.OutOfMemory) return true;
        return self.failures >= recovery_ready_persist_attempts;
    }
};

/// Sequencing for the safe-mode dialog.
///
/// The notice is armed at the initial-window boundary but released only once
/// the launch is resolved on disk, so a process terminated while the modal is
/// up has already broken the failure streak.
const RecoverySafeModeNotice = struct {
    armed: bool = false,
    released: bool = false,

    fn arm(self: *RecoverySafeModeNotice, decision: win32_recovery.Decision) void {
        if (decision != .normal) self.armed = true;
    }

    /// Returns true at most once, and only after the ledger write for this
    /// launch has succeeded or exhausted its retries.
    fn release(self: *RecoverySafeModeNotice, launch_resolved: bool) bool {
        if (!self.armed or self.released or !launch_resolved) return false;
        self.released = true;
        return true;
    }
};

/// Ownerless by design; do not "fix" this to take the primary Host HWND.
///
/// The notice runs on a detached thread that nothing joins, so it can outlive
/// any terminal window: the user may close the terminal, or safe mode's quit
/// timer may fire, while the dialog is still up. Destroying an owner destroys
/// its owned windows, which would pull this box's HWND out from under a modal
/// loop running on a different thread.
///
/// An owner would also be cross-thread. `MB_APPLMODAL` disables the owner,
/// and `EnableWindow`/foreground activation against a window belonging to the
/// UI thread sends messages that thread must pump. `App.run` starts this
/// notice at the `showRecoverySafeModeNotice` call site *before* it enters its
/// `GetMessageW` loop, so there is a window where the UI thread is not
/// pumping. The App's message-only window now keeps safe mailbox work moving
/// inside native modal loops, but lifetime-changing work still waits for the
/// outer loop; this informational notice must not delay that work.
///
/// Finally, `initial-window = false` means there is no host HWND at all, so an
/// ownerless path has to exist regardless. Safe mode is a usable session; the
/// notice is informational and must not hold the terminal hostage.
/// `MB_SETFOREGROUND` plus the box's own taskbar button carry the visibility.
fn recoverySafeModeNoticeThread(text: [*:0]const u16) void {
    _ = sys.MessageBoxW(
        null,
        text,
        recovery_safe_mode_caption_w,
        c.MB_OK | c.MB_ICONINFORMATION | c.MB_SETFOREGROUND,
    );
}

fn persistMergedRecoveryReadyAtPath(
    alloc: Allocator,
    path: []const u8,
    startup: *RecoveryStartup,
    merged: win32_recovery.StartupAttemptRecord,
) !void {
    var persisted_attempts: [win32_recovery.max_attempts]win32_recovery.StartupAttempt = undefined;
    @memcpy(persisted_attempts[0..merged.attempts.len], merged.attempts);
    const persisted = persisted_attempts[0..merged.attempts.len];
    try persistRecoveryRecordAtPath(alloc, path, persisted);
    @memcpy(startup.attempts[0..persisted.len], persisted);
    startup.count = persisted.len;
}

/// Record `mark` on this launch's attempt, merged with the disk record under
/// the ledger lock like the ready marker. Around a session restore: the start
/// is on disk before the first window is restored, so a launch that ends during
/// restore leaves it behind, and the finish is on disk before any unrelated
/// startup work, so `decide` can tell a session that keeps failing to restore
/// from any other repeated failure. Best effort: an unrecorded start only
/// means the session is not set aside.
fn markRecoveryAttemptAtPath(
    alloc: Allocator,
    path: []const u8,
    startup: *RecoveryStartup,
    mark: win32_recovery.AttemptMark,
) void {
    if (startup.count == 0) return;
    const memory_attempts = startup.attempts[0..startup.count];
    const target_started_at = memory_attempts[memory_attempts.len - 1].started_at_unix_ms;

    var lock = RecoveryLedgerLock.acquire(alloc, path, recovery_ledger_lock_wait_ms) catch |err| {
        log.warn("win32 recovery: {s} marker skipped, ledger lock unavailable err={}", .{ @tagName(mark), err });
        return;
    } orelse {
        log.warn("win32 recovery: {s} marker skipped, ledger lock busy", .{@tagName(mark)});
        return;
    };
    defer lock.release();

    var disk_record: win32_recovery.StartupAttemptRecord = .{};
    var ledger = readRecoveryLedgerAlloc(alloc, path, @tagName(mark));
    defer ledger.deinit();
    if (ledger == .left_alone or ledger == .unreadable) return;
    if (ledger == .record) disk_record = ledger.record.value;

    var merged_attempts: [win32_recovery.max_attempts]win32_recovery.StartupAttempt = undefined;
    const merged = win32_recovery.mergeMarkAttempt(
        disk_record,
        .{ .attempts = memory_attempts },
        target_started_at,
        mark,
        &merged_attempts,
    ) catch |err| {
        log.warn("win32 recovery: {s} marker merge failed err={}", .{ @tagName(mark), err });
        return;
    };
    persistRecoveryRecordAtPath(alloc, path, merged_attempts[0..merged.attempts.len]) catch |err| {
        log.warn("win32 recovery: {s} marker persist failed err={}", .{ @tagName(mark), err });
        return;
    };
    // Memory keeps this process's own attempt last: the ready marker targets
    // it, so the merged record is not adopted here.
    win32_recovery.applyMark(&memory_attempts[memory_attempts.len - 1], mark);
}

/// Move a saved session aside that the last launches all ended restoring, so
/// the next normal launch starts fresh instead of ending again. A rename into
/// a free slot, never a delete or a replace; skipped while another live process
/// owns the session, and for any file this build would not restore (a newer
/// build's, an oversized or unreadable one, or one the restore path quarantines
/// as `.corrupt` anyway). Returns whether the session was moved.
fn setAsideCrashedSessionState(alloc: Allocator, state_path: []const u8) bool {
    const owner = SessionOwnerLock.acquire(alloc, state_path) catch |err| {
        log.warn("win32 recovery: session not set aside, ownership lock unavailable err={}", .{err});
        return false;
    } orelse {
        log.warn("win32 recovery: session not set aside, another instance owns it", .{});
        return false;
    };
    defer owner.release();
    {
        var current = win32_session_persistence.loadAlloc(
            alloc,
            state_path,
            win32_session_persistence.default_max_state_bytes,
        );
        defer current.deinit();
        if (current != .loaded) {
            if (current != .missing) log.warn("win32 recovery: session not set aside, not one this build restores ({s})", .{@tagName(current)});
            return false;
        }
    }
    const destination = win32_session_persistence.quarantineFileAlloc(
        alloc,
        state_path,
        recovery_set_aside_suffix,
        .keep_source,
    ) catch |err| {
        if (err != error.FileNotFound) {
            log.warn("win32 recovery: session not set aside path={s} err={}", .{ state_path, err });
        }
        return false;
    };
    defer alloc.free(destination);
    log.warn("win32 recovery: repeated failures while restoring the saved session; moved it to {s}", .{destination});
    return true;
}

fn unixMillis() u64 {
    return @intCast(@max(std.time.milliTimestamp(), 0));
}

fn utf8PrefixLen(value: []const u8, capacity: usize) usize {
    var len = @min(value.len, capacity);
    while (len > 0 and !std.unicode.utf8ValidateSlice(value[0..len])) {
        len -= 1;
    }
    return len;
}

fn settingsFileSize(size: u64) win32_settings.SaveError!usize {
    const max_config_size = 16 * 1024 * 1024;
    if (size > max_config_size) return error.SerializeFailed;
    return @intCast(size);
}

const SettingsConfigKey = @import("../config/key.zig").Key;
const SettingsEditedKeySet = std.StaticBitSet(std.enums.values(SettingsConfigKey).len);
fn settingsUserEditedKeys(
    original: *const configpkg.Config,
    pending: *const configpkg.Config,
) SettingsEditedKeySet {
    var edited: SettingsEditedKeySet = .initEmpty();
    inline for (win32_settings.editable_keys) |key| {
        if (original.changed(pending, key)) edited.set(@intFromEnum(key));
    }
    return edited;
}

fn settingsEditedValueMasked(
    pending: *const configpkg.Config,
    reloaded: *const configpkg.Config,
    comptime key: SettingsConfigKey,
) bool {
    if (key == .command and pending.command == null and reloaded._command_defaulted) return false;
    if (key == SettingsConfigKey.@"auto-update-channel") {
        const expected = pending.@"auto-update-channel" orelse build_config.release_channel;
        const actual = reloaded.@"auto-update-channel" orelse build_config.release_channel;
        return expected != actual;
    }
    return pending.changed(reloaded, comptime key);
}

/// The most bytes `settingsMaskedKeyNames` writes: every editable key, and a
/// separator after each.
const settings_masked_keys_capacity = capacity: {
    var total: usize = 0;
    for (win32_settings.editable_keys) |key| total += @tagName(key).len + 2;
    break :capacity total;
};

/// The config keys among the user's edits whose saved value `reloaded` does
/// not hold, because a later config file or a command-line option sets them
/// again: comma separated, in the order the settings are listed, written to
/// `buf`. Empty when the reload holds everything that was saved. It allocates
/// nothing, so it cannot fail after the file was written.
fn settingsMaskedKeyNames(
    buf: *[settings_masked_keys_capacity]u8,
    user_edited: SettingsEditedKeySet,
    pending: *const configpkg.Config,
    reloaded: *const configpkg.Config,
) []const u8 {
    var len: usize = 0;
    inline for (win32_settings.editable_keys) |key| {
        if (user_edited.isSet(@intFromEnum(key)) and settingsEditedValueMasked(pending, reloaded, key)) {
            if (len > 0) {
                @memcpy(buf[len..][0..2], ", ");
                len += 2;
            }
            const name = @tagName(key);
            @memcpy(buf[len..][0..name.len], name);
            len += name.len;
        }
    }
    return buf[0..len];
}

/// Whether the file now says something else, for a setting the draft changes,
/// than both the value this session started from (`original`) and the draft:
/// someone else changed what the user is changing. A file that agrees with the
/// draft lost nothing, and one that agrees with `original` holds only the
/// user's own edit to come.
///
/// `original` is a clone of the app's config, which has the app's conditional
/// state applied (a dark system picks the dark half of a `light:A,dark:B`
/// theme, and that theme can set editable keys), so the file is judged with
/// the same state applied. Raw, an untouched file would differ from
/// `original` for those keys and every Save would stop.
fn settingsDiskEditConflict(
    original: *const configpkg.Config,
    pending: *const configpkg.Config,
    disk: *const configpkg.Config,
    state: configpkg.ConditionalState,
    user_edited: SettingsEditedKeySet,
) bool {
    var applied: ?configpkg.Config = disk.changeConditionalState(state) catch |err| blk: {
        log.warn("settings save: could not apply the conditional state to the config file err={}", .{err});
        break :blk null;
    };
    defer if (applied) |*config| config.deinit();
    const effective: *const configpkg.Config = if (applied) |*config| config else disk;
    inline for (win32_settings.editable_keys) |key| {
        if (user_edited.isSet(@intFromEnum(key)) and
            settingsDiskValueDiffers(original, effective, key) and
            settingsDiskValueDiffers(pending, effective, key)) return true;
    }
    return false;
}

/// `Config.load` takes a config file it cannot open (held without read
/// sharing, access denied, an offline share) for an absent one, or for one that
/// set nothing, and loads the rest. Judged as an edit and applied, that would
/// drop the user's own settings from every terminal, so a file that exists but
/// will not open stops the check, and the save with it. A file that is missing
/// is a first save (or an include the loader reports itself), and there is
/// nothing on disk to conflict with; a directory is not read by the loader
/// either.
///
/// The error is `FileUnopenable`, and `detail` (when given) is told which file
/// and why it is the one: `what` is "the config file" or "the included file",
/// so the status line can name it.
fn settingsFileOpenable(
    alloc: Allocator,
    detail: ?*win32_settings.FailureDetail,
    what: []const u8,
    path: []const u8,
) win32_settings.SaveError!void {
    _ = try settingsFileProbe(alloc, detail, what, path);
}

/// `settingsFileOpenable`, saying whether something is there: false for a
/// missing file, true for one that opens and for a directory.
fn settingsFileProbe(
    alloc: Allocator,
    detail: ?*win32_settings.FailureDetail,
    what: []const u8,
    path: []const u8,
) win32_settings.SaveError!bool {
    const file = std.fs.cwd().openFile(path, .{}) catch |err| switch (err) {
        error.FileNotFound => return false,
        error.IsDir => return true,
        else => {
            log.warn("settings save: could not open {s} to check it for edits path={s} err={}", .{ what, path, err });
            if (detail) |d| {
                const text = std.fmt.allocPrint(alloc, "{s} {s}", .{ what, path }) catch return error.OutOfMemory;
                defer alloc.free(text);
                d.set(alloc, text);
            }
            return error.FileUnopenable;
        },
    };
    file.close();
    return true;
}

/// `settingsFileOpenable` for every file the loaded config pulled in: the
/// list holds the nested ones too, as absolute paths.
fn settingsIncludesOpenable(
    alloc: Allocator,
    detail: ?*win32_settings.FailureDetail,
    disk: *const configpkg.Config,
) win32_settings.SaveError!void {
    for (disk.@"config-file".value.items) |entry| switch (entry) {
        .optional, .required => |path| if (path.len > 0) try settingsFileOpenable(alloc, detail, "the included file", path),
    };
}

/// The theme files the loaded config selects, by the loader's own search
/// (`themepkg.open`: an absolute path, or the name in each theme directory),
/// held to the same rule as an include. A theme that is not there is the
/// loader's to report, and the running config lacks it too; one that is there
/// and will not open is skipped by the load, and the settings it supplies
/// come back as defaults. Both the light and the dark name are checked, since
/// which one the load used depends on the system state.
fn settingsThemeOpenable(
    alloc: Allocator,
    detail: ?*win32_settings.FailureDetail,
    disk: *const configpkg.Config,
) win32_settings.SaveError!void {
    const theme = disk.theme orelse return;
    for ([_][]const u8{ theme.light, theme.dark }) |name| {
        if (std.fs.path.isAbsolute(name)) {
            try settingsFileOpenable(alloc, detail, "the theme file", name);
            continue;
        }
        // A name with a separator is rejected by the loader without a look.
        if (!std.mem.eql(u8, name, std.fs.path.basename(name))) continue;
        var arena: std.heap.ArenaAllocator = .init(alloc);
        defer arena.deinit();
        var dirs: std.ArrayListUnmanaged([]const u8) = .{};
        var it: themepkg.LocationIterator = .{ .arena_alloc = arena.allocator() };
        while (it.next() catch return error.OutOfMemory) |location| {
            dirs.append(arena.allocator(), location.dir) catch return error.OutOfMemory;
        }
        try settingsThemeNameOpenable(alloc, detail, name, dirs.items);
    }
}

/// The loader uses the first directory that has `name` and never looks at the
/// rest, so a later copy that is locked does not matter.
fn settingsThemeNameOpenable(
    alloc: Allocator,
    detail: ?*win32_settings.FailureDetail,
    name: []const u8,
    dirs: []const []const u8,
) win32_settings.SaveError!void {
    for (dirs) |dir| {
        const path = std.fs.path.join(alloc, &.{ dir, name }) catch return error.OutOfMemory;
        defer alloc.free(path);
        if (try settingsFileProbe(alloc, detail, "the theme file", path)) return;
    }
}

/// Whether the loaded `disk` config holds an edit that conflicts with the
/// draft, or an error when it is not the whole config: the save's own reload
/// would apply the same partial load, so a locked include stops the save
/// whether or not an edited setting conflicts.
fn settingsDiskVerdict(
    alloc: Allocator,
    detail: ?*win32_settings.FailureDetail,
    original: *const configpkg.Config,
    pending: *const configpkg.Config,
    disk: *const configpkg.Config,
    state: configpkg.ConditionalState,
    user_edited: SettingsEditedKeySet,
) win32_settings.SaveError!bool {
    try settingsIncludesOpenable(alloc, detail, disk);
    try settingsThemeOpenable(alloc, detail, disk);
    // A UTF-16 file that does not decode is skipped whole, with a diagnostic
    // and everything it set missing: as incomplete as one that will not open.
    if (disk._undecodable_file) |path| {
        if (detail) |d| {
            const text = std.fmt.allocPrint(alloc, "the file {s}", .{path}) catch return error.OutOfMemory;
            defer alloc.free(text);
            d.set(alloc, text);
        }
        return error.UnsupportedEncoding;
    }
    return settingsDiskEditConflict(original, pending, disk, state, user_edited);
}

/// What the palette says when a theme pick could not be saved. Two causes are
/// something the person can act on; the rest share one line.
fn paletteThemeSaveFailureMessage(err: win32_settings.SaveError) []const u8 {
    return switch (err) {
        error.DiskChanged => "The theme changed in the config file. Reload the configuration, then pick again; reverted preview.",
        error.FileUnopenable => "A config file cannot be opened, so the theme was not saved; reverted preview.",
        error.UnsupportedEncoding, error.BinaryConfig => "The config file is not UTF-8 text, so the theme was not saved; reverted preview.",
        else => "Theme save failed; reverted preview.",
    };
}

fn settingsDiskValueDiffers(
    known: *const configpkg.Config,
    disk: *const configpkg.Config,
    comptime key: SettingsConfigKey,
) bool {
    // The window keeps a command nobody set as automatic (null); the load
    // fills in the one it found.
    if (key == .command and disk._command_defaulted and known.command == null) return false;
    return known.changed(disk, key);
}

test "win32 bounded UTF-8 prefix never splits a codepoint" {
    const value = "123\u{1f680}tail";
    try std.testing.expectEqual(@as(usize, 3), utf8PrefixLen(value, 4));
    try std.testing.expectEqual(@as(usize, 7), utf8PrefixLen(value, 7));
    try std.testing.expectEqual(value.len, utf8PrefixLen(value, value.len + 10));
}

test "win32 settings save rejects files above the read cap" {
    try std.testing.expectEqual(@as(usize, 16 * 1024 * 1024), try settingsFileSize(16 * 1024 * 1024));
    try std.testing.expectError(error.SerializeFailed, settingsFileSize(16 * 1024 * 1024 + 1));
}

/// One answer to "is this a portable install?" for the call sites that only
/// need the yes/no, with one error policy: a failed probe is not portable.
/// Every consumer treats portable as the branch that unlocks portable-only
/// behavior, so failing to `.installer` keeps those paths closed and lets the
/// staged-kind check refuse rather than guess.
///
/// `localAppDataPathAlloc` and `warnPortableIgnoredLocalData` still call
/// `portableRoot` directly: they need the root path itself, not the answer.
fn isPortableModeActive(alloc: Allocator) bool {
    const root = internal_os.xdg.portableRoot(alloc) catch |err| {
        log.warn("failed to probe portable mode; treating as non-portable err={}", .{err});
        return false;
    } orelse return false;
    alloc.free(root);
    return true;
}

/// Every noctty shares one AUMID (`win32_aumid.aumid_utf8`), and with it two
/// pieces of per-user state: the AppUserModelId keys that name and badge its
/// toasts, and the taskbar jump list, which the Shell stores per AUMID. A
/// portable copy keeps the AUMID, so its toasts and the single-instance pipe
/// work as before, but leaves the installed copy's state alone (D12): it gets
/// no jump list, whose commit replaced the installed copy's on every launch,
/// and it only creates the registration where none exists, since without one
/// its toasts would not show. This is the one place both are decided. Returns
/// the jump list this copy drives, null when it leaves the Shell's list alone.
fn claimSharedIdentity(
    alloc: Allocator,
    portable: bool,
    register: *const fn (Allocator, bool) void,
    jump_list_state: ?[]const u8,
) ?win32_jump_list.JumpList {
    register(alloc, portable);
    if (portable) return null;
    const path = jump_list_state orelse return null;
    return win32_jump_list.JumpList.init(alloc, path) catch |err| {
        log.warn("jump list state init failed err={}", .{err});
        return null;
    };
}

test "a portable copy gets no jump list and registers only as portable" {
    const alloc = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const root = try tmp.dir.realpathAlloc(alloc, ".");
    defer alloc.free(root);
    const state = try std.fs.path.join(alloc, &.{ root, win32_jump_list.state_filename });
    defer alloc.free(state);
    const Registration = struct {
        var calls: [2]usize = .{ 0, 0 };
        fn register(_: Allocator, portable: bool) void {
            calls[@intFromBool(portable)] += 1;
        }
    };

    try std.testing.expect(claimSharedIdentity(alloc, true, &Registration.register, state) == null);
    try std.testing.expectEqual([2]usize{ 0, 1 }, Registration.calls);

    var installed = claimSharedIdentity(alloc, false, &Registration.register, state) orelse
        return error.TestUnexpectedResult;
    defer installed.deinit();
    try std.testing.expectEqual([2]usize{ 1, 1 }, Registration.calls);
}

/// How this copy of noctty gets updated. A setup-managed copy applies a
/// staged installer and a portable-marker copy a staged ZIP. Anything else
/// (Scoop, a ZIP extracted without its marker) was put there by someone else
/// and cannot apply either, so downloading a staged update for it is wasted
/// and its "ready to install" notice would be untrue.
const InstallKind = enum {
    installer,
    portable,
    other,

    fn classify(portable_marker: bool, installer_managed: bool) InstallKind {
        if (portable_marker) return .portable;
        return if (installer_managed) .installer else .other;
    }

    /// What to stage for this copy, or null when nothing can be applied.
    fn stagedKind(self: InstallKind) ?updatepkg.portable_apply.StagedKind {
        return switch (self) {
            .installer => .installer,
            .portable => .portable,
            .other => null,
        };
    }

    /// A failed probe is `.other`: refusing to stage is the safe answer.
    fn detect(alloc: Allocator) InstallKind {
        if (isPortableModeActive(alloc)) return .portable;
        const install_dir = currentInstallDir(alloc) catch return .other;
        defer alloc.free(install_dir);
        return classify(false, internal_os.windows.isInstallerManagedInstallDir(install_dir));
    }

    test "only setup-managed and portable-marker copies stage an update" {
        try std.testing.expectEqual(InstallKind.installer, classify(false, true));
        try std.testing.expectEqual(InstallKind.portable, classify(true, false));
        // A portable marker beside a setup-managed layout is still portable.
        try std.testing.expectEqual(InstallKind.portable, classify(true, true));
        try std.testing.expectEqual(InstallKind.other, classify(false, false));

        try std.testing.expectEqual(@as(?updatepkg.portable_apply.StagedKind, .installer), InstallKind.installer.stagedKind());
        try std.testing.expectEqual(@as(?updatepkg.portable_apply.StagedKind, .portable), InstallKind.portable.stagedKind());
        try std.testing.expectEqual(@as(?updatepkg.portable_apply.StagedKind, null), InstallKind.other.stagedKind());
    }
};

fn installTerminfo(alloc: Allocator, term: []const u8) void {
    const names = terminfo.compiled.fileNames(terminfo.ghostty) catch return;
    for (names) |name| {
        if (std.mem.eql(u8, name, term)) break;
    } else return;

    var env = std.process.getEnvMap(alloc) catch return;
    defer env.deinit();
    const dir = (win32_terminfo.homeTerminfoDir(alloc, &env) catch null) orelse {
        log.info("terminfo install skipped: no local home that git.exe and the MSYS2 runtime agree on", .{});
        return;
    };
    defer alloc.free(dir);
    const result = win32_terminfo.install(alloc, terminfo.ghostty, dir);
    log.info("terminfo install dir={s} result={s}", .{ dir, @tagName(result) });
}

fn localAppDataPathAlloc(alloc: Allocator, name: []const u8) ?[]u8 {
    // A unit test that constructs a real `App` must never read or write the
    // developer's own profile. It used to: every full `zig build test` run
    // appended an unfinished launch to the real `startup-attempts.json`
    // through "win32 runtime can initialize config", and three runs in a row
    // put the next real noctty launch into safe mode, which ignores the
    // config file and `-e`. The same helper resolves the jump list, session
    // state, palette history and layouts, so it is gated here rather than at
    // the ledger. Every caller already treats null as "nothing to persist",
    // and the ledger's own tests pass explicit temporary paths.
    if (builtin.is_test) return null;

    if (internal_os.xdg.portableRoot(alloc) catch null) |root| {
        defer alloc.free(root);
        return std.fs.path.join(alloc, &.{ root, name }) catch null;
    }

    const local = std.process.getEnvVarOwned(alloc, "LOCALAPPDATA") catch known: {
        var buf: [std.fs.max_path_bytes]u8 = undefined;
        const path = internal_os.windows.knownFolderPathUtf8(
            &internal_os.windows.FOLDERID_LocalAppData,
            &buf,
        ) catch return null;
        break :known alloc.dupe(u8, path orelse return null) catch return null;
    };
    defer alloc.free(local);
    return std.fs.path.join(alloc, &.{ local, build_config.data_dir_name, name }) catch null;
}

fn warnPortableIgnoredLocalData(alloc: Allocator) void {
    const portable_root = (internal_os.xdg.portableRoot(alloc) catch return) orelse return;
    defer alloc.free(portable_root);
    const local = std.process.getEnvVarOwned(alloc, "LOCALAPPDATA") catch known: {
        var buf: [std.fs.max_path_bytes]u8 = undefined;
        const path = internal_os.windows.knownFolderPathUtf8(
            &internal_os.windows.FOLDERID_LocalAppData,
            &buf,
        ) catch return;
        break :known alloc.dupe(u8, path orelse return) catch return;
    };
    defer alloc.free(local);
    const ignored_path = std.fs.path.join(alloc, &.{ local, build_config.data_dir_name }) catch return;
    defer alloc.free(ignored_path);
    if (std.ascii.eqlIgnoreCase(portable_root, ignored_path)) return;
    var ignored_dir = std.fs.openDirAbsolute(ignored_path, .{ .iterate = true }) catch return;
    defer ignored_dir.close();
    var iter = ignored_dir.iterate();
    if ((iter.next() catch return) == null) return;
    log.warn(
        "portable mode active root={s}; existing data under {s} is not being used",
        .{ portable_root, ignored_path },
    );
}

/// `session_state_excluded` is the elevation exclusion: such a process stays
/// out of the saved session, so it never sets one aside either.
fn beginRecoveryStartup(alloc: Allocator, session_state_excluded: bool) RecoveryStartup {
    const path = localAppDataPathAlloc(alloc, "startup-attempts.json") orelse return .{};
    defer alloc.free(path);
    const session_path = if (session_state_excluded) null else localAppDataPathAlloc(alloc, "session-state.json");
    defer if (session_path) |value| alloc.free(value);
    return beginRecoveryStartupAtPath(alloc, path, session_path, unixMillis(), recovery_ledger_lock_wait_ms);
}

/// The whole read -> fold -> append -> replace -> cleanup sequence runs under
/// `RecoveryLedgerLock`. Without it two instances launching together both
/// load the same ledger and the second replace silently drops the first
/// instance's attempt; the `.pending-` fold has the same exposure, since its
/// delete could remove a record a concurrent startup has not folded yet.
///
/// Fail-open: when the lock cannot be taken inside `lock_wait_ms` this launch
/// still reads the ledger for its safe-mode decision but records nothing, so
/// `count` stays 0 and no later marker is attempted. An unrecorded launch is
/// an honest gap in the history; a startup blocked behind a wedged sibling is
/// the outage this ledger exists to prevent.
fn beginRecoveryStartupAtPath(
    alloc: Allocator,
    path: []const u8,
    session_path: ?[]const u8,
    now: u64,
    lock_wait_ms: u32,
) RecoveryStartup {
    var result: RecoveryStartup = .{};

    var lock = RecoveryLedgerLock.acquire(alloc, path, lock_wait_ms) catch |err| unlocked: {
        log.warn("win32 recovery: ledger lock unavailable err={}; startup will not be recorded", .{err});
        break :unlocked null;
    };
    defer if (lock) |*held| held.release();
    if (lock == null) {
        log.warn(
            "win32 recovery: ledger lock not acquired within {d}ms; startup will not be recorded",
            .{lock_wait_ms},
        );
    }

    var record: win32_recovery.StartupAttemptRecord = .{};
    var ledger = readRecoveryLedgerAlloc(alloc, path, "startup history");
    defer ledger.deinit();
    // A history that is not this build's to replace, or could not be read
    // now, is neither counted nor replaced: this launch goes unrecorded, as it
    // does when the lock is unavailable.
    if (ledger == .left_alone or ledger == .unreadable) return result;
    if (ledger == .record) record = ledger.record.value;

    var retained_paths: std.ArrayListUnmanaged([]u8) = .empty;
    defer {
        for (retained_paths.items) |retained_path| alloc.free(retained_path);
        retained_paths.deinit(alloc);
    }
    var retained_merge_buffers: [2][win32_recovery.max_attempts]win32_recovery.StartupAttempt = undefined;
    var retained_merge_buffer_index: usize = 0;
    if (std.fs.path.dirname(path)) |dir_path| retained: {
        var dir = std.fs.openDirAbsolute(dir_path, .{ .iterate = true }) catch |err| {
            log.warn("win32 recovery: retained history directory open failed err={}", .{err});
            break :retained;
        };
        defer dir.close();
        // Only `.pending-` records are folded and deleted here. They are
        // written exclusively by `retainRecoveryPersistDiagnosis`, i.e. after
        // a ledger write has already definitively failed, and are never used
        // as the source of an atomic replacement. The `.tmp-` files that
        // `persistRecoveryRecordAtPath` creates are live replacement sources
        // for whichever process owns them; a concurrently starting instance
        // that deleted one would make that process's ReplaceFileW fail and
        // send it down the in-place fallback, clobbering the record this
        // process just merged. The namespaces stay disjoint even though the
        // ledger lock now serialises ledger transactions: a `.tmp-` can also
        // be left by a writer that died mid-replace, and nothing here should
        // have to reason about whether its owner is alive.
        const retained_prefix = std.fmt.allocPrint(
            alloc,
            "{s}" ++ recovery_pending_suffix,
            .{std.fs.path.basename(path)},
        ) catch break :retained;
        defer alloc.free(retained_prefix);
        var entries = dir.iterate();
        while (true) {
            const entry = entries.next() catch |err| {
                log.warn("win32 recovery: retained history enumeration failed err={}", .{err});
                break;
            } orelse break;
            if (!std.mem.startsWith(u8, entry.name, retained_prefix)) continue;
            const retained_path = std.fs.path.join(alloc, &.{ dir_path, entry.name }) catch continue;
            const retained_file = std.fs.openFileAbsolute(retained_path, .{}) catch {
                alloc.free(retained_path);
                continue;
            };
            defer retained_file.close();
            const raw = retained_file.readToEndAlloc(alloc, 64 * 1024) catch {
                alloc.free(retained_path);
                continue;
            };
            defer alloc.free(raw);
            var parsed = win32_recovery.parseAlloc(alloc, raw) catch {
                alloc.free(retained_path);
                continue;
            };
            defer parsed.deinit();
            const merged = win32_recovery.mergeRecords(
                record,
                parsed.value,
                &retained_merge_buffers[retained_merge_buffer_index],
            ) catch {
                alloc.free(retained_path);
                continue;
            };
            retained_paths.append(alloc, retained_path) catch {
                alloc.free(retained_path);
                continue;
            };
            record = merged;
            retained_merge_buffer_index = 1 - retained_merge_buffer_index;
        }
    }

    result.decision = win32_recovery.decide(record, now, .{});
    // Everything above was read-only. Nothing below may run unlocked: the
    // append-and-replace is the lost-update window, and deleting a folded
    // `.pending-` record is only safe once its contents are on disk under
    // the same lock.
    if (lock == null) return result;

    // Acted on inside the transaction that decided it, so no launch can
    // record a restore or a ready marker in between.
    if (result.decision == .quarantine_session) if (session_path) |value| {
        result.session_set_aside = setAsideCrashedSessionState(alloc, value);
    };

    // Attempts are told apart by their start; two launches in one
    // millisecond must not share one.
    const started_at = if (record.attempts.len > 0)
        @max(now, record.attempts[record.attempts.len - 1].started_at_unix_ms + 1)
    else
        now;
    const appended = win32_recovery.appendBounded(
        record,
        .{ .started_at_unix_ms = started_at, .version = .init(build_config.version_string) },
        &result.attempts,
    ) catch |err| {
        log.warn("win32 recovery: attempt append failed err={}", .{err});
        return result;
    };
    result.count = appended.attempts.len;
    persistRecoveryRecordAtPath(alloc, path, result.attempts[0..result.count]) catch |err| {
        log.warn("win32 recovery: startup marker persist failed err={}", .{err});
        return result;
    };
    for (retained_paths.items) |retained_path| {
        win32_session_persistence.deleteFileIfPresent(retained_path) catch |err| {
            log.warn("win32 recovery: merged retained history cleanup failed path={s} err={}", .{ retained_path, err });
        };
    }
    return result;
}

fn persistRecoveryRecordAtPath(
    alloc: Allocator,
    path: []const u8,
    attempts: []win32_recovery.StartupAttempt,
) !void {
    if (std.fs.path.dirname(path)) |dir| {
        std.fs.makeDirAbsolute(dir) catch |err| switch (err) {
            error.PathAlreadyExists => {},
            else => return err,
        };
    }
    const encoded = try win32_recovery.encodeAlloc(alloc, .{ .attempts = attempts });
    defer alloc.free(encoded);
    const nonce = unixMillis();
    // `.tmp-` is this process's private replacement source and is never read
    // or deleted by another instance. `.pending-` is the post-failure
    // diagnosis another instance folds in and cleans up. See the namespace
    // note in `beginRecoveryStartupAtPath`.
    const temporary_path = try std.fmt.allocPrint(
        alloc,
        "{s}.tmp-{x}-{x}",
        .{ path, sys.GetCurrentProcessId(), nonce },
    );
    defer alloc.free(temporary_path);
    const pending_path = try std.fmt.allocPrint(
        alloc,
        "{s}" ++ recovery_pending_suffix ++ "{x}-{x}",
        .{ path, sys.GetCurrentProcessId(), nonce },
    );
    defer alloc.free(pending_path);
    var atomic_failure: ?win32_session_persistence.AtomicReplaceFailure = null;
    const disposition = win32_session_persistence.writeFileAtomicOrInPlace(
        path,
        temporary_path,
        encoded,
        &atomic_failure,
    ) catch |err| {
        if (atomic_failure) |failure| {
            recordRecoveryPersistFailure(attempts, failure.move_error);
            retainRecoveryPersistDiagnosis(
                alloc,
                temporary_path,
                pending_path,
                attempts,
            );
        }
        return err;
    };
    switch (disposition) {
        .atomic => {},
        .in_place => |failure| {
            recordRecoveryPersistFailure(attempts, failure.move_error);
            const diagnosed = try win32_recovery.encodeAlloc(alloc, .{ .attempts = attempts });
            defer alloc.free(diagnosed);
            win32_session_persistence.writeFileInPlace(path, diagnosed) catch |err| {
                log.warn("win32 recovery: in-place diagnosis persist failed err={}", .{err});
                retainRecoveryPersistDiagnosis(
                    alloc,
                    temporary_path,
                    pending_path,
                    attempts,
                );
            };
        },
    }
}

fn recordRecoveryPersistFailure(
    attempts: []win32_recovery.StartupAttempt,
    raw_win32_error: u32,
) void {
    if (attempts.len == 0) return;
    const latest = &attempts[attempts.len - 1];
    if (latest.ready_at_unix_ms != null) latest.phase = .ready_persist_failed;
    latest.last_win32_error = raw_win32_error;
}

fn retainRecoveryPersistDiagnosis(
    alloc: Allocator,
    temporary_path: []const u8,
    pending_path: []const u8,
    attempts: []const win32_recovery.StartupAttempt,
) void {
    const diagnosed = win32_recovery.encodeAlloc(alloc, .{ .attempts = attempts }) catch return;
    defer alloc.free(diagnosed);
    // Publish under `.pending-`, not the replacement source. The write has
    // already failed, so this record is inert: no process will ever hand it
    // to ReplaceFileW, which makes it safe for a concurrent startup to fold
    // and delete. Then drop the now-dead `.tmp-` source so it does not leak.
    win32_session_persistence.writeFileInPlace(pending_path, diagnosed) catch |err| {
        log.warn("win32 recovery: retained diagnosis persist failed err={}", .{err});
        return;
    };
    win32_session_persistence.deleteFileIfPresent(temporary_path) catch |err| {
        log.warn("win32 recovery: dead replacement source cleanup failed err={}", .{err});
    };
}

fn writePersistentFileAlloc(alloc: Allocator, path: []const u8, data: []const u8) !void {
    if (std.fs.path.dirname(path)) |dir| {
        // Recursive: `layouts\` sits one level below `%LOCALAPPDATA%\noctty`,
        // which itself may not exist yet on a first save.
        std.fs.cwd().makePath(dir) catch |err| switch (err) {
            error.PathAlreadyExists => {},
            else => return err,
        };
    }
    const temporary_path = try std.fmt.allocPrint(
        alloc,
        "{s}.tmp-{x}-{x}",
        .{ path, sys.GetCurrentProcessId(), unixMillis() },
    );
    defer alloc.free(temporary_path);
    try win32_session_persistence.writeFileAtomic(path, temporary_path, data);
}

fn sessionStatePolicyAllows(safe_mode: bool, policy: configpkg.Config.WindowSaveState) bool {
    return !safe_mode and policy != .never;
}

fn layoutActionResult(success: bool) !bool {
    if (!success) return error.LayoutActionFailed;
    return true;
}

const SessionRestoreTransaction = struct {
    app: ?*App = null,
    host: ?*Host = null,
    core_first: *bool,
    core_first_before: bool,
    committed: bool = false,

    fn init(app: *App) SessionRestoreTransaction {
        return .{
            .core_first = &app.core_app.first,
            .core_first_before = app.core_app.first,
        };
    }

    fn noteSurface(self: *SessionRestoreTransaction, surface: *Surface) void {
        if (self.host == null) {
            self.app = surface.app;
            self.host = surface.host;
        }
    }

    fn commit(self: *SessionRestoreTransaction) void {
        self.committed = true;
    }

    fn rollback(self: *SessionRestoreTransaction) void {
        if (self.committed) return;
        if (self.app) |app| if (self.host) |host| {
            app.rollbackSessionRestoreHost(host);
            // A failed DestroyWindow deliberately retains the partial host.
            // Do not make that live surface look like a fresh first surface.
            if (std.mem.indexOfScalar(*Host, app.hosts.items, host) != null) return;
        };
        self.core_first.* = self.core_first_before;
    }
};

fn sessionRestorePolicyAllows(
    safe_mode: bool,
    policy: configpkg.Config.WindowSaveState,
    initial_window: bool,
    has_initial_command: bool,
    startup_profile_picker: bool,
    explicit_startup_working_directory: bool,
) bool {
    return sessionStatePolicyAllows(safe_mode, policy) and
        initial_window and
        !has_initial_command and
        !startup_profile_picker and
        !explicit_startup_working_directory;
}

const SessionSaveKind = enum { final, checkpoint };

/// How long the session must stay unchanged before a structural change is
/// saved (`App.scheduleSessionCheckpoint`).
const session_checkpoint_delay_ms: u32 = 1000;

const shell_audit_warn_interval_ms: u64 = 60 * std.time.ms_per_s;

/// At most one warning per interval; the ones left out are counted and
/// reported with the next.
const RateLimitedWarning = struct {
    last_ms: ?u64 = null,
    suppressed: u32 = 0,

    /// The count left out since the last warning when one may be logged at
    /// `now`, else null.
    fn take(self: *RateLimitedWarning, now: u64, interval_ms: u64) ?u32 {
        if (self.last_ms) |last| if (now -% last < interval_ms) {
            self.suppressed +|= 1;
            return null;
        };
        const suppressed = self.suppressed;
        self.last_ms = now;
        self.suppressed = 0;
        return suppressed;
    }
};

test "a rate-limited warning logs once per interval and counts the rest" {
    var warning: RateLimitedWarning = .{};
    try std.testing.expectEqual(@as(?u32, 0), warning.take(1_000, 60_000));
    try std.testing.expectEqual(@as(?u32, null), warning.take(2_000, 60_000));
    try std.testing.expectEqual(@as(?u32, null), warning.take(60_999, 60_000));
    try std.testing.expectEqual(@as(?u32, 2), warning.take(61_000, 60_000));
    try std.testing.expectEqual(@as(?u32, null), warning.take(61_001, 60_000));
}

/// An empty snapshot ends the saved session only on the owner's final save;
/// a checkpoint keeps the file. True when the file was removed.
fn removeEmptySessionState(path: []const u8, kind: SessionSaveKind) bool {
    if (kind == .checkpoint) return false;
    win32_session_persistence.deleteFileIfPresent(path) catch |err| {
        log.warn("win32 session save: delete stale state failed path={s} err={}", .{ path, err });
        return false;
    };
    return true;
}

/// Held for the life of the one process that owns `session-state.json`.
/// An exclusive byte-range lock on the `.lock` sibling, so the kernel drops
/// it when the owner exits or crashes and the next launch can take over.
const SessionOwnerLock = struct {
    file: std.fs.File,

    /// Null when another live process holds it.
    fn acquire(alloc: Allocator, state_path: []const u8) !?SessionOwnerLock {
        if (std.fs.path.dirname(state_path)) |dir| {
            std.fs.makeDirAbsolute(dir) catch |err| switch (err) {
                error.PathAlreadyExists => {},
                else => return err,
            };
        }
        const lock_path = try std.fmt.allocPrint(alloc, "{s}.lock", .{state_path});
        defer alloc.free(lock_path);
        const file = std.fs.createFileAbsolute(lock_path, .{
            .read = true,
            .truncate = false,
            .lock = .exclusive,
            .lock_nonblocking = true,
        }) catch |err| switch (err) {
            error.WouldBlock => return null,
            else => return err,
        };
        return .{ .file = file };
    }

    fn release(self: SessionOwnerLock) void {
        self.file.close();
    }
};

fn writeOpenUrlTrace(file: std.fs.File, url: []const u8) !void {
    var buffer: [1024]u8 = undefined;
    var writer = file.writer(&buffer);
    try writer.interface.print("{s}\r\n", .{url});
    try writer.interface.flush();
}

/// Explicit Debug-build test seam for URL activation. When set, the Win32
/// runtime records the requested URL instead of dispatching an uncontrolled
/// ShellExecuteW. Release builds always use the system URL handler.
fn recordOpenUrlForTest(alloc: Allocator, url: []const u8) !bool {
    const raw_path = std.process.getEnvVarOwned(
        alloc,
        "NOCTTY_WIN32_OPEN_URL_TRACE_FILE",
    ) catch |err| switch (err) {
        error.EnvironmentVariableNotFound => return false,
        else => return err,
    };
    defer alloc.free(raw_path);
    const path = std.mem.trim(u8, raw_path, " \t\r\n");
    if (path.len == 0) return false;

    const file = try std.fs.createFileAbsolute(path, .{ .truncate = true });
    defer file.close();
    try writeOpenUrlTrace(file, url);
    return true;
}

pub const App = struct {
    pub const must_draw_from_app_thread = true;

    core_app: *CoreApp,
    config: configpkg.Config,
    /// Cached TokenElevation state. This scopes the title and IPC namespace
    /// consistently for the full lifetime of the process.
    is_elevated: bool = false,
    /// Session persistence is excluded for a genuine full split token, and
    /// for an elevated process whose elevation type could not be queried
    /// (unknown fails closed). UAC-off and built-in-Administrator tokens are
    /// elevated but default elevation type, so they keep normal session
    /// persistence.
    session_state_excluded_for_elevation: bool = false,
    config_revision: u64 = 1,
    resolved_theme: ThemeColors = darkTheme(),
    /// Completed `reconfigureTheme` passes; a test reads it to prove that a
    /// settings preview which cannot change the theme does not run one.
    theme_rebuilds: u32 = 0,
    system_theme_refresh: SystemThemeRefresh = .{},
    hinstance: HINSTANCE,
    class_atom: ATOM = 0,
    host_class_atom: ATOM = 0,
    palette_list_class_atom: ATOM = 0,
    tab_tooltip_class_atom: ATOM = 0,
    scrollbar_class_atom: ATOM = 0,
    quick_select_class_atom: ATOM = 0,
    hosts: std.ArrayListUnmanaged(*Host) = .empty,
    windows: std.ArrayListUnmanaged(*Surface) = .empty,
    /// Owned shell requests waiting for the top of the message loop;
    /// see `runDeferredOpens`.
    deferred_opens: std.ArrayListUnmanaged(DeferredOpen) = .empty,

    /// Internal test seam so action-path tests can drive real
    /// `performAction(.new_tab, ...)` logic without requiring HWND/GL
    /// surface bring-up.
    test_create_window_surface: ?*const fn (
        app: *App,
        config: *const configpkg.Config,
        title: LPCWSTR,
        opts: SurfaceInitOptions,
    ) anyerror!*Surface = null,
    /// Test-only seam that stands in for the GL context and the core surface
    /// in `Surface.init`, neither of which a unit test can create. The window,
    /// tab, shell and unwind steps around them run for real.
    test_surface_init_stage: ?*const fn (surface: *Surface, stage: Surface.InitStage) anyerror!void = null,
    /// Test-only seam for automation snapshots built without a live core
    /// surface. Returned strings are owned by the caller.
    test_automation_pwd: ?*const fn (Allocator, *Surface) anyerror!?[]const u8 = null,
    /// Test-only seam proving automation uses the protected paste encoder.
    test_automation_paste: ?*const fn (
        surface: *Surface,
        state: apprt.ClipboardRequest,
        text: [:0]const u8,
        confirmed: bool,
    ) anyerror!void = null,
    /// Test-only interleaving seam for the focus revision race between a
    /// structural prepare and commit (a split undone, a tab closed again).
    /// `pane` is one whose focus the test moves.
    test_before_structural_shell_commit: ?*const fn (
        app: *App,
        pane: win32_shell.model.PaneId,
    ) anyerror!void = null,
    /// Test-only stand-in for `ShellExecuteW` on a checked open target, so a
    /// unit test never launches a real handler.
    test_open_target: ?*const fn (app: *App, target: []const u8) anyerror!void = null,
    /// Stand-in for the remaining shell launchers; tests never launch OSK,
    /// elevated windows or installers.
    test_shell_request: ?*const fn (app: *App, request: *const DeferredOpen) anyerror!void = null,
    next_host_id: u32 = 1,
    launcher_profile_key: ?[:0]const u8 = null,
    launcher_profile_hint: ?[:0]const u8 = null,
    launcher_quick_slot_keys: [3]?[:0]const u8 = .{ null, null, null },
    launcher_profile_target: ProfileOpenTarget = .tab,
    startup_profile_picker: bool = false,
    /// True when argv explicitly selects a working directory. Such cold-start
    /// flows must create their requested window rather than restore a saved
    /// session and discard the CLI destination.
    explicit_startup_working_directory: bool = false,
    wheel_settings: SystemWheelSettings = .{},
    system_dynamic_scrollbars: bool = true,
    ipc_pipe_name: ?[:0]const u16 = null,
    /// Effective sanitized namespace captured when the IPC server starts.
    ipc_namespace: ?[]const u8 = null,
    ipc_thread: ?std.Thread = null,
    /// Set to end the IPC server thread's waits; owned while it runs.
    ipc_stop_event: ?windows.HANDLE = null,
    ipc_stop_requested: std.atomic.Value(bool) = .init(false),
    global_hotkeys: std.ArrayListUnmanaged(RegisteredGlobalHotkey) = .empty,
    global_hotkeys_dirty: bool = false,
    ui_thread_id: DWORD = 0,
    /// Published before any producer starts; retained until producers stop.
    /// Detached update workers hold their own reference, without borrowing App.
    delivery: ?*AppDelivery = null,
    /// Bumped whenever a Host's profiles are replaced or dropped, so a
    /// discovery that finishes off the UI thread can tell it went stale.
    profiles_generation: u64 = 0,
    /// A discovery result from `startProfileDiscovery`, waiting for the top
    /// of the outer pump.
    pending_profile_discovery: ?*ProfileDiscoveryCompletion = null,
    /// When the running discovery started (GetTickCount64), so one that never
    /// finishes does not block every later attempt.
    profile_discovery_started_ms: u64 = 0,
    /// Fires once after a worker starts, unless its result arrived, to start
    /// another attempt: nothing else re-arms the jump list's timer when a
    /// worker hangs or cannot deliver.
    profile_discovery_watchdog_id: ?UINT_PTR = null,
    /// The host inside `Host.requestProfiles`. With no worker the discovery
    /// runs synchronously within that call, and the host re-checks its list
    /// itself instead of being called back from inside its own chrome sync.
    profiles_requesting_host: ?*Host = null,
    /// Numbers each worker, so a late result from an abandoned one leaves the
    /// running state and watchdog of the attempt that replaced it alone.
    profile_discovery_attempt: u64 = 0,
    message_hwnd: ?HWND = null,
    core_ticking: bool = false,
    quit_timer_id: ?UINT_PTR = null,
    terminal_handoff_idle_timer_id: ?UINT_PTR = null,
    terminal_handoff_server: ?*win32_terminal_handoff.Server = null,
    undo_prune_timer_id: ?UINT_PTR = null,
    /// Thread timer that delivers program status notifications the rate
    /// limit held back. Only runs while one is waiting.
    program_status_notify_timer_id: ?UINT_PTR = null,
    recovery_retry_timer_id: ?UINT_PTR = null,
    /// Monotonic `GetTickCount64` deadline before which no tick may spend a
    /// ready-marker attempt. Cleared by the retry timer, which is the tick
    /// the deadline was waiting for.
    recovery_retry_not_before_ms: ?u64 = null,
    next_undo_sequence: u64 = 1,
    // App-scoped bindings from an empty host must retain their origin even
    // when pruning expires (and destroys) that host during dispatch.
    empty_host_key_id: ?u32 = null,
    running: bool = false,
    /// A normal last-host close destroys the native/session model before
    /// `terminate` runs. Preserve the successful pre-close snapshot instead
    /// of replacing it with an empty snapshot during final teardown.
    session_state_saved_before_last_host_close: bool = false,
    /// Set only in the process that restored the saved session, or was
    /// eligible to and started with its first window instead. Only that
    /// process saves or deletes `session-state.json`: a launch that forwarded
    /// to the primary, an Explorer "Open noctty here" window, an `-Embedding`
    /// handoff server or a second `single-instance = false` instance never
    /// loaded it, so writing their own windows (or none) over it destroys the
    /// user's workspace.
    session_owner: ?SessionOwnerLock = null,
    /// The saved session is not this build's to replace: a newer build wrote
    /// it, or it is larger than any session this build writes. This process
    /// neither restores it nor takes ownership, so it never saves over it or
    /// deletes it.
    session_state_left_alone: bool = false,
    /// Set once WM_ENDSESSION(TRUE) has saved for a sign-out, shutdown or
    /// reboot. That snapshot is final: shells the logoff kills afterwards
    /// close their panes, and the saves those closes would run must not
    /// shrink or delete it.
    session_ending: bool = false,
    /// `GetTickCount64` of the last `checkpointSessionState`.
    session_checkpoint_ms: ?u64 = null,
    /// Thread timer that saves the session once a burst of structural
    /// changes settles (`scheduleSessionCheckpoint`).
    session_checkpoint_timer_id: ?UINT_PTR = null,
    /// True only while the app is synchronously draining every host during
    /// shutdown. Child HWND teardown still repairs native split trees, but it
    /// must not diagnose the intentionally absent per-pane close preflight as
    /// an ordinary-close invariant failure.
    quitting: bool = false,
    /// Host currently undergoing allocation-free failed-restore teardown.
    /// Its child WM_DESTROY callbacks remove Surface ownership only; Host
    /// tree disposal happens once, after the native cascade completes.
    session_restore_rollback_host: ?*Host = null,
    windows_hidden: bool = false,
    quick_terminal_keyboard_diagnostic_logged: bool = false,
    update_notice: ?UpdateNotice = null,
    /// The host whose banner button started the running update action, so
    /// its feedback lands in the window the user is looking at. Set only for
    /// the length of that synchronous call (`Host.activateBannerButton`).
    update_action_host: ?*Host = null,
    update_auto_check_started: bool = false,
    /// Repeating thread timer that re-runs the automatic check in a process
    /// that stays open for days. See `update_recheck_interval_ms`.
    update_recheck_timer_id: ?UINT_PTR = null,
    /// Detected on first use: the install directory cannot change under a
    /// running process.
    install_kind: ?InstallKind = null,
    /// The last Install is looked at once per run, when a window can show the
    /// result (`reportFailedInstallerApply`).
    installer_apply_checked: bool = false,
    /// Set when Install starts applying, so a second press that gets in while
    /// `ShellExecuteW` pumps messages cannot start a second Setup.
    update_apply_in_flight: bool = false,
    /// Set from the confirm's answer until the loop takes the apply off the
    /// queue, so a second answer in between queues nothing.
    update_apply_queued: bool = false,
    update_startup_ready: bool = false,
    /// Most-recently-used command palette actions; newest first. Strings
    /// are owned by `core_app.alloc` and freed in `App.deinit`. Surfaced
    /// by `commandPaletteBannerText` when the query is empty so users
    /// see their own recent picks instead of the static onboarding hint.
    palette_mru: [5]?[:0]const u8 = .{null} ** 5,
    /// Singleton settings window. Lazily created by the `open_config`
    /// action; `App.terminate` destroys the HWND if still alive.
    settings_window: win32_settings.SettingsWindow = undefined,
    /// Stable core surface id that owned focus when Settings opened. Settings
    /// itself clears terminal focus flags, so close must not guess host zero.
    settings_restore_surface_id: ?u64 = null,
    /// Whether `OleInitialize` actually took responsibility for the
    /// apartment on this thread. `OleUninitialize` only pairs with a
    /// successful init (`S_OK` / `S_FALSE`) — `RPC_E_CHANGED_MODE`
    /// means another component already set up COM and we must not
    /// touch it on the way down.
    com_initialized: bool = false,
    /// Kernel build number from `RtlGetVersion`. 0 if probe failed.
    /// 22000 = Win11 21H2; 22621 = Win11 22H2 (the floor for
    /// `DWMWA_SYSTEMBACKDROP_TYPE`, which host windows always write as
    /// `DWMSBT_NONE` — see `applyDwmThemeWithBuild`).
    /// Future chrome gates read this directly; no runtime config flag,
    /// per §12 Q1.
    os_build: u32 = 0,
    /// Top-level switch for the integrated-titlebar path
    /// (`WM_NCCALCSIZE` / `WM_NCHITTEST` state machine). Derived
    /// from the Win11 build floor via `shouldUseIntegratedTitlebar`;
    /// false keeps the stock non-client caption path.
    use_integrated_titlebar: bool = false,
    /// Last applied `window-show-tab-bar` visibility. Only
    /// `reconfigureTheme` reads it, to notice a reload that turned the tab
    /// strip on or off: the chrome children that live in the strip are shown
    /// and hidden by `layoutChromeForRect`, which a reload otherwise reaches
    /// only when the frame mode flips too (never on Win10).
    tab_bar_visible: bool = true,
    // Live-resize state is tracked PER HOST (`Host.is_live_resize`),
    // not per App. Dragging window A must NOT freeze renderer
    // invalidations for unrelated background windows B/C.
    /// Whether the current core-app tick already spent its one synchronous
    /// renderer paint. See `rendererTickRepaintMode`.
    renderer_sync_paint_spent: bool = false,
    /// Hyperlink hover-dwell tracker, meant to be reset via `dismiss()`
    /// whenever focus leaves a surface or a click arrives.
    ///
    /// Not driven yet: initialized here and in a test, but nothing calls
    /// `onMouseMove`, `tick` or `dismiss` outside its own tests, and the
    /// core's `mouse_over_link` action is a no-op in `performAction`. There is
    /// no link-preview tooltip on Windows (docs/status.md, "Link previews");
    /// wiring one is the work this field waits for.
    link_hover_tracker: win32_link_preview.HoverTracker = undefined,
    /// Windows Action Center toast notifier. `null` when WinRT init
    /// fails (e.g. corporate lockdown, missing combase.dll), in which
    /// case `showDesktopNotification` falls back to the in-app banner
    /// path. One notifier per App, released in `App.terminate`.
    winrt_toast: ?win32_toast_winrt.WinrtToast = null,
    /// Taskbar progress COM object. `null` when the taskbar API is
    /// unavailable, in which case progress continues to render only in
    /// the window title/status text.
    taskbar_progress: ?win32_taskbar_progress.TaskbarProgress = null,
    /// Rate limit for program status (OSC 7501) notifications across all
    /// windows; each surface keeps its own last notification time too.
    program_status_notify: win32_program_status.NotifyLimiter = .{},
    /// Persisted taskbar destinations and their debounced shell COM commit.
    /// `null` when the app-state path cannot be resolved or initialized.
    jump_list: ?win32_jump_list.JumpList = null,
    /// Absolute path supplied via `--config-file=<path>` on the CLI.
    /// Resolved ONCE against the startup cwd during `App.init` — that's
    /// important because `run()` later calls `sanitizeCurrentDirectory()`,
    /// which can reset cwd to `%USERPROFILE%`. If we resolved the
    /// relative path at save time, we'd end up writing to a different
    /// file than the one `Config.load()` used at launch.
    cli_config_override_path: ?[]u8 = null,
    /// The file the last failed Settings save names in its status line.
    settings_failure_detail: win32_settings.FailureDetail = .{},
    /// The config keys the last Settings save wrote that a later layer
    /// overrides, comma separated, for its status line and notification.
    settings_masked_keys: win32_settings.FailureDetail = .{},
    /// What the config last loaded (startup, reload, Settings save) found
    /// wrong, and the fonts it names that no installed font matches. Copies:
    /// the config that held the diagnostics is gone after a reload.
    config_problems: win32_config_problems.Problems = .{},
    /// The text of the banner raised for `config_problems`, so a reload that
    /// finds none can take that banner down, and only that one.
    config_problems_banner: ?[]u8 = null,
    /// Startup-time cwd snapshot. `Config.load()` resolves relative
    /// `--config-file` argv entries via realpath-against-cwd, so any
    /// reload that happens after `sanitizeCurrentDirectory()` would
    /// resolve those entries against the sanitized cwd and end up
    /// reading a different file than launch did. We `std.fs.cwd()`
    /// chdir back to this value around `settingsSaveAndReload`'s
    /// reload so argv-relative paths re-resolve identically.
    startup_cwd: ?[]u8 = null,
    /// Parsed `wgh://activate?...` launch argument from a cold-start
    /// toast activation. `null` when no such argv entry is present.
    /// Consumed once after the first window spawns. We first try the
    /// requested surface/window identity and fall back to the newly
    /// created primary surface when the IDs came from a prior process.
    pending_toast_activation: ?win32_toast_activation.ActivationTarget = null,
    /// Ephemeral recovery launch: default config, no saved workspace restore.
    safe_mode: bool = false,
    /// COM SCM activation for the Windows default-terminal handoff server.
    /// This process owns adopted sessions directly; raw HANDLE values are
    /// never forwarded through the serialized single-instance IPC channel.
    embedding_mode: bool = false,
    recovery_startup: RecoveryStartup = .{},
    /// True once this launch is recorded on disk as resolved — either the
    /// ready marker landed or its bounded retries were exhausted.
    recovery_ready_resolved: bool = false,
    recovery_ready_retry: RecoveryReadyRetry = .{},
    recovery_safe_mode_notice: RecoverySafeModeNotice = .{},
    /// Top-level shell composition only. Terminal child HWNDs retain their
    /// existing WGL/SwapBuffers ownership regardless of this backend state.
    shell_compositor_driver: win32_compositor_native.NativeDriver = undefined,
    shell_compositor: win32_compositor.Backend = undefined,
    shell_compositor_initialized: bool = false,
    shell_runtime: win32_shell.runtime.Runtime = undefined,
    shell_runtime_initialized: bool = false,
    /// Release builds warn about a shell/native divergence at most once per
    /// `shell_audit_warn_interval_ms`.
    shell_audit_warning: RateLimitedWarning = .{},
    /// A tab or split was created in an existing window; the activation
    /// that shows it audits the shell/native mapping (`Surface.init`).
    shell_audit_after_activation: bool = false,

    const DeferredOpen = union(enum) {
        target: []u8,
        text_editor: struct { path: []u8, from_settings: bool },
        on_screen_keyboard,
        /// Install or Apply, once it is confirmed: `applyStagedUpdate` reaches
        /// `ShellExecuteW`, so it runs from the loop like the opens do.
        apply_staged_update,
        elevated_window: struct { parameters: [:0]u8, cwd: ?[]const u8 },

        fn deinit(self: DeferredOpen, alloc: Allocator) void {
            switch (self) {
                .target => |target| alloc.free(target),
                .text_editor => |request| alloc.free(request.path),
                .elevated_window => |launch| {
                    alloc.free(launch.parameters);
                    if (launch.cwd) |cwd| alloc.free(cwd);
                },
                .on_screen_keyboard, .apply_staged_update => {},
            }
        }
    };

    pub fn init(
        self: *App,
        core_app: *CoreApp,
        opts: struct { safe_mode: bool = false },
    ) !void {
        const embedding_mode = win32_terminal_handoff.isEmbeddingProcess(core_app.alloc);
        const is_elevated = win32_elevation.isProcessElevated() catch |err| elevated: {
            log.warn(
                "failed to query TokenElevation; treating process as elevated for title and IPC isolation err={}",
                .{err},
            );
            break :elevated true;
        };
        const session_state_excluded_for_elevation = if (is_elevated) excluded: {
            const elevation_type = win32_elevation.processTokenElevationType() catch |err| {
                log.warn(
                    "failed to query TokenElevationType; disabling session state because an elevated process with an unknown elevation type must fail closed err={}",
                    .{err},
                );
                break :excluded win32_elevation.excludesSessionState(is_elevated, null);
            };
            break :excluded win32_elevation.excludesSessionState(
                is_elevated,
                elevation_type,
            );
        } else false;
        const recovery_startup = if (embedding_mode)
            RecoveryStartup{}
        else
            beginRecoveryStartup(core_app.alloc, session_state_excluded_for_elevation);
        const safe_mode = opts.safe_mode or recovery_startup.decision != .normal;
        self.* = .{
            .core_app = core_app,
            .config = if (safe_mode) config: {
                var config = try configpkg.Config.default(core_app.alloc);
                errdefer config.deinit();
                // Recovery runs `cmd /D`, which loads no profile and skips AutoRun,
                // and so needs no PATH search.
                try config.useWindowsRecoveryCommand();
                try config.finalize();
                break :config config;
            } else try configpkg.Config.load(core_app.alloc),
            .is_elevated = is_elevated,
            .session_state_excluded_for_elevation = session_state_excluded_for_elevation,
            .safe_mode = safe_mode,
            .embedding_mode = embedding_mode,
            .recovery_startup = recovery_startup,
            .hinstance = sys.GetModuleHandleW(null),
            .launcher_profile_hint = detectDefaultProfileHint(core_app.alloc),
            .launcher_profile_target = detectDefaultProfileTarget(core_app.alloc),
            .startup_profile_picker = detectStartupProfilePicker(core_app.alloc),
            .explicit_startup_working_directory = detectExplicitStartupWorkingDirectory(core_app.alloc),
        };
        // Install before any host window exists, so the very first
        // SetWinEventHook registration already has somewhere to deliver.
        cloak_event_app = self;
        win32_power.setCloakEventHandler(&onHostCloakEvent);
        if (self.session_state_excluded_for_elevation and
            self.config.@"window-save-state" != .never)
        {
            log.info(
                "win32 session state disabled: elevated process whose token is TokenElevationTypeFull (split-token elevated) or whose elevation type could not be queried",
                .{},
            );
        }
        if (self.config.@"background-blur".win32BlurRequested()) logBackgroundBlurUnsupported();
        warnPortableIgnoredLocalData(core_app.alloc);
        // Snapshot the CLI --config-file override BEFORE any code has
        // a chance to chdir. See the field comment above.
        self.cli_config_override_path = cliConfigFileOverride(core_app.alloc) catch null;
        // Snapshot the startup cwd for reload-time restoration.
        self.startup_cwd = std.process.getCwdAlloc(core_app.alloc) catch null;
        // Scan argv for a cold-start toast activation arg. Silent on
        // absence or malformed input — activation is opt-in.
        self.pending_toast_activation = scanToastActivationArg(core_app.alloc);
        if (self.pending_toast_activation) |target| {
            log.info("toast activation received surface={?} tab={?} window={?} action={?}", .{
                target.surface_id,
                target.tab_id,
                target.window_id,
                target.action,
            });
        }
        // AUMID registration MUST precede any HWND creation so
        // taskbar-grouping / toast attribution picks up our identity
        // on the first window. Both swallow failures (warn +
        // continue) — toasts and taskbar grouping are non-essential
        // for basic terminal function.
        win32_aumid.setProcessAumid();
        {
            const state = localAppDataPathAlloc(core_app.alloc, win32_jump_list.state_filename);
            defer if (state) |path| core_app.alloc.free(path);
            // Not `isPortableModeActive`, which answers "installed" when
            // copying the root fails; this cached answer cannot fail.
            self.jump_list = claimSharedIdentity(
                core_app.alloc,
                internal_os.xdg.portableModeActive(),
                &win32_aumid.registerAumidDisplayName,
                state,
            );
        }

        // Be asked to end before the shells under it. Every process starts at
        // the default level 0x280, and Windows ends processes on one level
        // in no set order, so a sign-out could otherwise end the shells
        // first: each pane closes, the last window goes, and `terminate`
        // would delete the saved session before WM_ENDSESSION could save
        // it. A higher level is ended first.
        if (sys.SetProcessShutdownParameters(0x2FF, 0) == 0) {
            log.warn("win32 SetProcessShutdownParameters failed err={}", .{windows.GetLastError()});
        }

        // Boot the WinRT toast notifier. Failure falls back to the
        // host banner/log path in `showDesktopNotificationWithLaunch`.
        // MUST run AFTER `setProcessAumid` so `CreateToastNotifierWithId`
        // attributes toasts to our AUMID.
        const aumid_utf16 = std.unicode.utf8ToUtf16LeStringLiteral("io.github.amanthanvi.noctty");
        self.winrt_toast = win32_toast_winrt.WinrtToast.init(core_app.alloc, aumid_utf16) catch |err| blk: {
            std.log.warn("winrt toast init failed err={}; falling back to host notifications", .{err});
            break :blk null;
        };

        // Install the PowerShell shell-integration script into
        // %LOCALAPPDATA%\noctty\shell-integration\powershell\
        // if missing or the on-disk hash doesn't match the embedded
        // payload (forces updates when we ship a new version). This
        // keeps the manual `$PROFILE` fallback on a stable path even
        // though automatic injection now uses the resources-tree copy
        // for interactive PowerShell launches.
        //
        // Skipped in unit tests for the same reason `localAppDataPathAlloc`
        // is: a test that starts a real `App` would otherwise overwrite the
        // developer's own copy with whatever branch is under test, and that
        // copy is what a hand-written `$PROFILE` dot-source loads.
        if (!builtin.is_test) {
            if (win32_powershell_install.resolveInstallPath(core_app.alloc)) |ps1_path| {
                defer core_app.alloc.free(ps1_path);
                const result = win32_powershell_install.installIfStale(core_app.alloc, ps1_path);
                log.info("powershell integration install path={s} result={s}", .{ ps1_path, @tagName(result) });
            } else |err| {
                std.log.warn("powershell integration install path resolve failed err={}", .{err});
            }
        }

        // Install our compiled terminfo entry where Git for Windows' ncurses
        // tools find it, for TERM=xterm-ghostty (win32_terminfo.zig). Not in
        // portable mode, which leaves nothing on the host; not when `term`
        // names some other entry; and not in unit tests, which must not write
        // into the developer's profile.
        if (!builtin.is_test and !isPortableModeActive(core_app.alloc)) {
            installTerminfo(core_app.alloc, self.config.term);
        }

        // Windows version probe. Win11 build 22000+ enables the
        // integrated-titlebar path; older builds stay on the stock
        // non-client caption/buttons path.
        self.os_build = probeWindowsBuild();
        self.use_integrated_titlebar = shouldUseIntegratedTitlebar(
            self.os_build,
            self.config.@"window-show-tab-bar",
        );
        self.tab_bar_visible = tabBarVisibleForConfig(self.config.@"window-show-tab-bar");
        log.info("win32 os_build={d} integrated_titlebar={}", .{
            self.os_build,
            self.use_integrated_titlebar,
        });
        if (recovery_startup.decision != .normal and !opts.safe_mode) {
            log.warn("win32 recovery: repeated incomplete startups selected safe mode", .{});
        }

        self.initComApartment();
        self.taskbar_progress = win32_taskbar_progress.TaskbarProgress.init() catch |err| blk: {
            std.log.warn("taskbar progress init failed err={}; falling back to title-only progress", .{err});
            break :blk null;
        };
        self.refreshSystemWheelSettings();
        self.refreshSystemScrollbarPreference();
        self.resolved_theme = resolveTheme(&self.config);
        self.loadPaletteMru();
        self.settings_window = win32_settings.SettingsWindow.init(.{
            .ctx = @ptrCast(self),
            .alloc = core_app.alloc,
            .hinstance = self.hinstance,
            .ownerWindow = &settingsOwnerWindowThunk,
            .appIcon = &settingsAppIconThunk,
            .chromeBg = &settingsChromeBgThunk,
            .textPrimary = &settingsTextPrimaryThunk,
            .themeColors = &settingsThemeColorsThunk,
            .highContrast = &settingsHighContrastThunk,
            .openInEditor = &settingsOpenInEditorThunk,
            .currentConfig = &settingsCurrentConfigThunk,
            .saveAndReload = &settingsSaveAndReloadThunk,
            .configRevision = &settingsConfigRevisionThunk,
            .previewField = &settingsPreviewFieldThunk,
            .notifyConflict = &settingsNotifyConflictThunk,
            .reconcileDisk = &settingsReconcileDiskThunk,
            .failureDetail = &settingsFailureDetailThunk,
            .maskedKeys = &settingsMaskedKeysThunk,
            .saveTarget = &settingsSaveTargetThunk,
            .configProblems = &settingsConfigProblemsThunk,
            .notifySuccess = &settingsNotifySuccessThunk,
            .customUiaProvidersEnabled = &settingsCustomUiaProvidersEnabledThunk,
            .deferUiaDisconnect = &settingsDeferUiaDisconnectThunk,
            .onClosed = &settingsOnClosedThunk,
        });
        self.link_hover_tracker = win32_link_preview.HoverTracker.init();
        // The D3D11/DirectComposition/DirectWrite shell compositor is not
        // started: the backend gets no driver and no capability probe, so it
        // stays in its fallback state and the attach, resize and render
        // helpers below are no-ops. Building its device graph here put a
        // hardware D3D11 device on the UI thread before the first window,
        // and kept about 80 driver threads and tens of MB alive, for
        // explicit banner text only (PKG-33). The device-graph code stays
        // until the D3D11 renderer decision settles whether it is reused.
        self.shell_compositor_driver = win32_compositor_native.NativeDriver.init(core_app.alloc);
        self.shell_compositor = win32_compositor.Backend.init(.{}, null);
        self.shell_compositor_initialized = true;
        self.shell_runtime = win32_shell.runtime.Runtime.init(core_app.alloc);
        self.shell_runtime_initialized = true;

        // Core conditional configuration defaults to light. Synchronize it
        // with Windows before the first surface is created so conditional
        // themes and terminal color-scheme reports start on the right branch.
        // No surfaces or hosts exist yet: the resulting app config-change is
        // intentionally valid before `run`, and its topology loops are empty.
        self.syncSystemColorScheme() catch |err| {
            log.warn("initial win32 color scheme sync failed err={}", .{err});
        };
    }

    /// Bring OLE and its STA apartment online for in-process COM consumers
    /// (settings path picker via `IFileOpenDialog`, WinRT toast setup,
    /// OLE drag-drop). Pair each successful call with OleUninitialize —
    /// `S_FALSE` means "already initialised in this mode", and
    /// `RPC_E_CHANGED_MODE` means "already initialised in a different
    /// mode" and leaves STA-only consumers disabled.
    fn initComApartment(self: *App) void {
        const hr = sys.OleInitialize(null);
        switch (hr) {
            0, 1 => self.com_initialized = true, // S_OK, S_FALSE
            c.RPC_E_CHANGED_MODE => {
                std.log.warn("COM apartment: already MTA on this thread; STA consumers may fail", .{});
            },
            else => {
                std.log.warn("COM apartment: OleInitialize failed hr=0x{x:0>8}", .{@as(u32, @bitCast(hr))});
            },
        }
    }

    pub fn run(self: *App) !void {
        try self.sanitizeCurrentDirectory();
        const cwd = std.process.getCwdAlloc(self.core_app.alloc) catch null;
        defer if (cwd) |v| self.core_app.alloc.free(v);
        if (cwd) |v| {
            log.debug("win32 current directory cwd={s}", .{v});
        }

        try self.ensureWindowClass();

        const forwarded = if (self.embedding_mode or self.safe_mode)
            false
        else
            ipc_server.tryForwardStartupToExistingInstance(self) catch |err| switch (err) {
                // A busy or rejecting primary must not turn this launch into
                // false crash-loop evidence. Continue as a local instance.
                error.IPCFailed => failed: {
                    log.warn("win32 startup forwarding failed; continuing locally", .{});
                    break :failed false;
                },
                else => return err,
            };
        if (forwarded) {
            // Forwarding is a successful startup outcome for this process.
            // Mark it ready so repeated new-window launches cannot accumulate
            // false crash-loop evidence and trigger automatic safe mode.
            // This process exits immediately, so there is no later tick to
            // retry on; the failure is logged and the attempt stays unresolved.
            self.markRecoveryReady() catch |err| {
                log.warn("win32 recovery: forwarded launch ready marker failed err={}", .{err});
            };
            return;
        }

        self.running = true;
        const ui_thread_id = sys.GetCurrentThreadId();
        ensureMessageQueue();
        try self.createMessageWindow();
        @atomicStore(DWORD, &self.ui_thread_id, ui_thread_id, .release);
        defer {
            self.stopUndoPruneTimer();
            self.stopQuitTimer();
            self.stopTerminalHandoffIdleTimer();
            self.stopRecoveryRetryTimer();
            self.stopProgramStatusNotifyTimer();
            self.stopUpdateRecheckTimer();
            self.stopProfileDiscoveryWatchdog();
            @atomicStore(DWORD, &self.ui_thread_id, 0, .release);
            if (self.pending_profile_discovery) |pending| pending.deinit();
            self.pending_profile_discovery = null;
            self.closeMessageWindow();
            self.running = false;
        }

        var terminal_handoff_server: ?win32_terminal_handoff.Server = null;
        defer if (terminal_handoff_server) |*server| {
            self.terminal_handoff_server = null;
            _ = server.revoke();
            server.drainPending();
        };
        if (self.embedding_mode) {
            if (!self.com_initialized) return error.ComApartmentUnavailable;
            terminal_handoff_server = win32_terminal_handoff.Server.init(
                self.core_app.alloc,
                self,
                queueTerminalHandoff,
            );
            // Publish before registering: once the class object is live a
            // client can activate it, and the session queue has to be
            // reachable from the very first handoff.
            self.terminal_handoff_server = &terminal_handoff_server.?;
            try terminal_handoff_server.?.register();
            win32_terminal_handoff.appendHandoffMilestone(self.core_app.alloc, "server_registered");
            self.startTerminalHandoffIdleTimer();
        }

        // Safe mode is an isolated recovery process. It neither forwards into
        // the normal instance nor competes for that instance's IPC endpoint.
        if (!self.embedding_mode and !self.safe_mode and try ipc_server.startIpcServer(self)) {
            // Lost the first-instance race and the retry forward succeeded:
            // same successful-startup outcome as the forward above, and the
            // same reason the marker failure is only logged.
            self.markRecoveryReady() catch |err| {
                log.warn("win32 recovery: forwarded launch ready marker failed err={}", .{err});
            };
            return;
        }

        // A launch whose first window fails because OpenGL could not start is
        // not a crash, and safe mode starts the same renderer: three of them
        // must not strand the user there. Only this stretch: a later error
        // is no startup failure, and once the ready marker has merged other
        // instances' attempts, this one is no longer the last in memory.
        var initial_windows_created = false;
        errdefer if (!initial_windows_created) self.markRecoveryOpenGLUnavailable();
        if (!self.embedding_mode and self.config.@"launch-layout" != null) {
            const name = self.config.@"launch-layout".?;
            // An explicit CLI layout request is honored even when
            // `initial-window` is disabled, because the user asked for this
            // exact window. It is also one-shot: later ordinary new-window
            // actions must not inherit and replay it from the app config.
            const launched = self.launchNamedLayout(name, null);
            self.config.@"launch-layout" = null;
            // Clearing the field is not enough: `finalize` -> `loadTheme` and
            // `changeConditionalState` replay `_replay_steps` through
            // `loadIter`, and a per-window clone inherits that history, so a
            // surviving startup step would turn a later ordinary new window
            // into a layout launch.
            _ = self.config.dropLaunchLayoutReplaySteps(0);
            if (!launched) {
                // Handled, as for a skipped restore window.
                gl_startup.clearOpenGLStartupFailure();
                try self.createWindow(default_title);
                if (self.primarySurface()) |surface| if (surface.host) |host| {
                    host.setBanner(.err, "Layout could not be opened.") catch {};
                };
            }
        } else if (!self.embedding_mode and self.config.@"initial-window") {
            // Ownership starts only once the first window exists: a launch
            // that fails here must not delete, on its way out, the session
            // it could not bring back, and a save while restore is half done
            // would keep only the windows restored so far.
            const owner_lock = if (self.sessionRestoreEligible()) self.acquireSessionOwnerLock() else null;
            errdefer if (owner_lock) |lock| lock.release();
            const restored = if (owner_lock != null) try self.restoreSessionState() else false;
            if (!restored) try self.createWindow(default_title);
            self.adoptSessionOwner(owner_lock);
            if (!restored and self.startup_profile_picker) {
                if (self.primarySurface()) |surface| {
                    if (surface.host) |host| _ = host.toggleProfileOverlay();
                }
            }
        } else if (!self.embedding_mode) {
            log.info("initial-window is disabled; win32 runtime waiting without a window", .{});
        }
        initial_windows_created = true;

        // Keep the banner text even without an initial window: every later
        // host receives its own copy when it is created.
        _ = self.reportConfigProblems(&self.config);

        // Armed here, released by `resolveRecoveryStartup` once the ready
        // marker is on disk. Spawning it here would let thread scheduling put
        // the modal on screen while the ledger still holds an unresolved
        // attempt, so killing the process at the dialog would preserve the
        // failure streak.
        self.recovery_safe_mode_notice.arm(self.recovery_startup.decision);

        if (!self.embedding_mode) self.initializeJumpList();
        if (!self.embedding_mode) self.scheduleGlobalHotkeySync();
        if (!self.embedding_mode and self.global_hotkeys_dirty and self.windows.items.len == 0) {
            self.global_hotkeys_dirty = false;
            self.syncGlobalHotkeys() catch |err| {
                log.err("failed to sync win32 global hotkeys err={}", .{err});
            };
        }
        if (!self.embedding_mode and self.windows.items.len == 0) self.startQuitTimer();

        // Initial window creation must not start a check until the swapped
        // build is healthy and authoritative. Later windows retain the usual
        // scheduling path through update_startup_ready.
        //
        // Updater bookkeeping must not be able to stop the terminal from
        // opening. Every failure here is about the state file, the stage
        // directory, or a lock — none of it says the running build is
        // unusable, and returning would exit before the message loop with no
        // window ever shown. Log it and continue; staging and apply both
        // re-check the transaction phase and fail closed on their own.
        updatepkg.confirmPortableUpdateStartup(
            self.core_app.alloc,
            build_config.version_string,
        ) catch |err| {
            log.warn("portable update startup confirmation failed err={}", .{err});
        };
        self.update_startup_ready = true;
        // Before the check below: staging compares the state it started from
        // with the state it finishes in, and this clears a field in it.
        if (self.windows.items.len > 0) self.reportFailedInstallerApply();
        if (self.windows.items.len > 0) self.maybeScheduleAutomaticUpdateCheck();
        const portable_failure = updatepkg.takePortableUpdateFailure(self.core_app.alloc) catch |err| failure: {
            log.warn("failed to read portable update failure err={}", .{err});
            break :failure null;
        };
        if (portable_failure) |message| {
            defer self.core_app.alloc.free(message);
            self.showUpdateInfo(.err, message) catch |err| {
                log.warn("failed to surface portable update failure err={}", .{err});
            };
        }

        // Guarantee the loop reaches at least one tick. Resolving this launch
        // in the ledger and releasing the safe-mode notice both hang off
        // `tickCoreApp`, so neither may depend on some other subsystem
        // happening to post a wake first.
        self.wakeup();

        var msg: MSG = undefined;
        while (true) {
            // Opens queued while the previous message was handled run here,
            // with no window procedure on the stack.
            if (try self.drainDeferredOpens()) break;
            self.drainPendingHandoffs();
            self.applyPendingProfileDiscovery();

            const result = sys.GetMessageW(&msg, null, 0, 0);
            if (result == -1) return lastError();
            if (result == 0) break;
            self.showPendingConPtyFallbackBanner();

            if (msg.message == c.WM_TIMER) {
                if (self.recovery_retry_timer_id) |timer_id| {
                    if (msg.wParam == timer_id) {
                        self.onRecoveryRetryTimer();
                        continue;
                    }
                }
                if (self.terminal_handoff_idle_timer_id) |timer_id| {
                    if (msg.wParam == timer_id) {
                        self.stopTerminalHandoffIdleTimer();
                        self.drainPendingHandoffs();
                        if (self.embedding_mode and self.windows.items.len == 0) {
                            if (self.exitEmbeddingServerIfIdle()) {
                                log.info("terminal handoff server idle timeout", .{});
                                self.running = false;
                                sys.PostQuitMessage(0);
                            } else {
                                self.startTerminalHandoffIdleTimer();
                            }
                        }
                        continue;
                    }
                }
                // Our timer is a thread timer (`SetTimer(null, ...)`), which
                // posts with a null hwnd. Checking that keeps us from
                // swallowing a window timer whose numeric id happens to
                // collide.
                if (self.jump_list) |*jump_list| {
                    if (@intFromPtr(msg.hwnd) == 0 and jump_list.handleTimer(msg.wParam)) {
                        // Profile discovery is app-wide, so any host will do —
                        // `initial-window=false` starts without a primary
                        // surface. The request stays pending until one exists.
                        if (self.hosts.items.len > 0 and
                            jump_list.startupProfileDiscoveryPending())
                        {
                            const host = self.hosts.items[0];
                            if (host.profiles != null and host.profiles_complete) {
                                jump_list.completeStartupProfileDiscovery();
                            } else {
                                self.startProfileDiscovery();
                            }
                        }
                        continue;
                    }
                }
                if (self.quit_timer_id) |timer_id| {
                    if (msg.wParam == timer_id) {
                        self.stopQuitTimer();
                        if (self.running and !self.hasLiveUiWindows() and self.config.@"quit-after-last-window-closed") {
                            self.running = false;
                            sys.PostQuitMessage(0);
                        }
                        continue;
                    }
                }
                if (self.undo_prune_timer_id) |timer_id| {
                    if (msg.wParam == timer_id) {
                        self.stopUndoPruneTimer();
                        self.pruneUndoHistoryNow();
                        continue;
                    }
                }
                if (self.program_status_notify_timer_id) |timer_id| {
                    if (@intFromPtr(msg.hwnd) == 0 and msg.wParam == timer_id) {
                        self.flushProgramStatusNotifications();
                        continue;
                    }
                }
                if (self.session_checkpoint_timer_id) |timer_id| {
                    if (@intFromPtr(msg.hwnd) == 0 and msg.wParam == timer_id) {
                        self.onSessionCheckpointTimer();
                        continue;
                    }
                }
                if (self.update_recheck_timer_id) |timer_id| {
                    if (@intFromPtr(msg.hwnd) == 0 and msg.wParam == timer_id) {
                        self.onUpdateRecheckTimer();
                        continue;
                    }
                }
                if (self.profile_discovery_watchdog_id) |timer_id| {
                    if (@intFromPtr(msg.hwnd) == 0 and msg.wParam == timer_id) {
                        self.stopProfileDiscoveryWatchdog();
                        const pending = if (self.jump_list) |*jump_list| jump_list.startupProfileDiscoveryPending() else false;
                        if ((pending or self.anyHostRequestedProfiles()) and self.hosts.items.len > 0) self.startProfileDiscovery();
                        continue;
                    }
                }
            }

            if (msg.message == c.WM_HOTKEY) {
                self.handleGlobalHotkey(@intCast(msg.wParam));
                continue;
            }

            // The settings surface is a modeless native dialog. Route its
            // keyboard messages through the system dialog manager so Tab,
            // Shift+Tab, arrow-key radio navigation, and default buttons use
            // standard Win32 accessibility semantics.
            if (self.settings_window.hwnd) |settings_hwnd| {
                // The dialog manager consumes Tab and the arrow keys here and
                // never dispatches them to the control that gains focus, so
                // the settings window learns about keyboard navigation from
                // the pump, not from its controls.
                self.settings_window.noteInputMessage(msg.hwnd, msg.message, msg.wParam);
                // Ctrl+S is not a dialog-manager key; take it before the
                // manager sees it. Tab and the arrows still go to the manager.
                if (self.settings_window.handleAccelerator(msg.hwnd, msg.message, msg.wParam, msg.lParam)) {
                    try self.tickCoreApp();
                    continue;
                }
                if (sys.IsDialogMessageW(settings_hwnd, &msg) != 0) {
                    try self.tickCoreApp();
                    continue;
                }
            }

            _ = sys.TranslateMessage(&msg);
            _ = sys.DispatchMessageW(&msg);

            self.syncDirtyGlobalHotkeys();
            try self.tickCoreApp();

            if (!self.running and self.windows.items.len == 0) break;
        }
    }

    pub fn terminate(self: *App) void {
        self.stopUndoPruneTimer();
        self.stopQuitTimer();
        self.stopTerminalHandoffIdleTimer();
        self.stopRecoveryRetryTimer();
        self.stopProgramStatusNotifyTimer();
        self.stopUpdateRecheckTimer();
        self.stopSessionCheckpointTimer();
        if (self.update_notice) |*notice| {
            notice.deinit(self.core_app.alloc);
            self.update_notice = null;
        }
        self.unregisterGlobalHotkeys();
        ipc_server.stopIpcServer(self);
        if (!self.session_state_saved_before_last_host_close or self.hosts.items.len > 0) {
            _ = self.saveSessionState(.final);
        }
        self.releaseSessionOwnership();
        self.destroyAllWindows();
        if (self.shell_runtime_initialized) {
            self.shell_runtime.deinit();
            self.shell_runtime_initialized = false;
        }
        if (self.shell_compositor_initialized) {
            self.shell_compositor.deinit();
            self.shell_compositor_initialized = false;
        }
        // After destroyAllWindows: every Host has released its cloak-hook
        // reference by now, so no further callback can reach a freed App.
        win32_power.setCloakEventHandler(null);
        cloak_event_app = null;
        self.hosts.deinit(self.core_app.alloc);
        self.windows.deinit(self.core_app.alloc);
        self.discardDeferredOpens();
        self.global_hotkeys.deinit(self.core_app.alloc);
        if (self.launcher_profile_key) |value| self.core_app.alloc.free(value);
        if (self.launcher_profile_hint) |value| self.core_app.alloc.free(value);
        for (self.launcher_quick_slot_keys) |value| {
            if (value) |owned| self.core_app.alloc.free(owned);
        }
        self.savePaletteMru();
        for (&self.palette_mru) |*slot| {
            if (slot.*) |owned| self.core_app.alloc.free(owned);
            slot.* = null;
        }
        self.settings_window.deinit();
        const uia_disconnect_hr = win32_uia.disconnectAllProviders();
        if (uia_disconnect_hr != 0) {
            log.warn("win32 UIA disconnect-all failed hr=0x{x}", .{@as(u32, @bitCast(uia_disconnect_hr))});
        }
        if (self.winrt_toast) |*toast| {
            toast.deinit();
            self.winrt_toast = null;
        }
        if (self.taskbar_progress) |*taskbar| {
            taskbar.deinit();
            self.taskbar_progress = null;
        }
        if (self.jump_list) |*jump_list| {
            jump_list.deinit();
            self.jump_list = null;
        }
        if (self.cli_config_override_path) |path| {
            self.core_app.alloc.free(path);
            self.cli_config_override_path = null;
        }
        self.settings_failure_detail.clear(self.core_app.alloc);
        self.settings_masked_keys.clear(self.core_app.alloc);
        self.config_problems.deinit(self.core_app.alloc);
        if (self.config_problems_banner) |text| {
            self.core_app.alloc.free(text);
            self.config_problems_banner = null;
        }
        if (self.startup_cwd) |path| {
            self.core_app.alloc.free(path);
            self.startup_cwd = null;
        }
        deinitImeWindowFormsTracePath(self.core_app.alloc);
        self.config.deinit();
        if (self.com_initialized) {
            sys.OleUninitialize();
            self.com_initialized = false;
        }
        if (self.delivery) |delivery| {
            delivery.release();
            self.delivery = null;
        }
    }

    /// Resolve `%LOCALAPPDATA%\noctty\<name>`. Caller frees with
    /// `core_app.alloc`. Returns null if `LOCALAPPDATA` is unreadable
    /// or allocation fails.
    fn localAppDataPath(self: *const App, name: []const u8) ?[]u8 {
        return localAppDataPathAlloc(self.core_app.alloc, name);
    }

    fn initializeJumpList(self: *App) void {
        const jump_list = if (self.jump_list) |*value| value else return;
        if (self.delivery != null) jump_list.runner = .{ .ctx = self, .start = startJumpListRebuild };
        jump_list.startup();
    }

    /// The jump list's Shell commit, on a detached worker with an STA of
    /// its own. Like the profile discovery worker it borrows nothing from
    /// the App, so quitting never waits for it; the job comes back as
    /// WM_WINHOSTTY_JUMP_LIST.
    fn startJumpListRebuild(ctx: *anyopaque, job: *win32_jump_list.RebuildJob) bool {
        const self: *App = @ptrCast(@alignCast(ctx));
        const delivery = self.delivery orelse return false;
        delivery.retain();
        // Windows' default stack: Zig's 16 MiB default is committed, not
        // just reserved, and a wedged commit keeps its thread.
        const thread = std.Thread.spawn(.{ .stack_size = 1024 * 1024 }, jumpListRebuildThreadMain, .{ delivery, job }) catch |err| {
            delivery.release();
            log.warn("jump list rebuild thread unavailable err={}", .{err});
            return false;
        };
        thread.detach();
        return true;
    }

    /// Resolve `%LOCALAPPDATA%\noctty\palette-mru.txt`. Caller frees
    /// with `core_app.alloc`.
    fn paletteMruPath(self: *const App) ?[]u8 {
        return self.localAppDataPath("palette-mru.txt");
    }

    /// Resolve `%LOCALAPPDATA%\noctty\session-state.json`. Caller
    /// frees with `core_app.alloc`.
    fn sessionStatePath(self: *const App) ?[]u8 {
        return self.localAppDataPath("session-state.json");
    }

    fn namedLayoutPath(self: *const App, name: []const u8) ![]u8 {
        const relative = try win32_layouts.relativePathAlloc(self.core_app.alloc, name);
        defer self.core_app.alloc.free(relative);
        return self.localAppDataPath(relative) orelse error.LocalAppDataUnavailable;
    }

    fn namedLayoutsDirectoryPath(self: *const App) ?[]u8 {
        return self.localAppDataPath("layouts");
    }

    fn sessionStateEnabled(self: *const App) bool {
        // Only the owner, the process that was eligible to restore the saved
        // session and then got its first window, may replace or delete it.
        // The restore policy is re-checked so a config reload
        // (window-save-state = never) still stops it.
        return self.session_owner != null and self.sessionRestoreEligible();
    }

    /// Take the saved session for this process, on the restore-eligible
    /// startup path only. One live process owns it (decision D10): with
    /// `single-instance = false`, or when forwarding failed, a second
    /// instance starts with a fresh window instead of restoring the same
    /// workspace a second time, and never saves over it.
    fn acquireSessionOwnerLock(self: *App) ?SessionOwnerLock {
        if (self.session_state_excluded_for_elevation) return null;
        const path = self.sessionStatePath() orelse return null;
        defer self.core_app.alloc.free(path);
        return SessionOwnerLock.acquire(self.core_app.alloc, path) catch |err| {
            log.warn("win32 session: ownership lock unavailable; not restoring or saving err={}", .{err});
            return null;
        } orelse {
            log.info("win32 session: another instance owns the saved session; starting without it", .{});
            return null;
        };
    }

    /// Ownership is for a session this process may replace. One it left alone
    /// stays free, so the build that wrote it can still restore it.
    fn adoptSessionOwner(self: *App, lock: ?SessionOwnerLock) void {
        if (self.session_state_left_alone) {
            if (lock) |held| held.release();
            return;
        }
        self.session_owner = lock;
    }

    fn releaseSessionOwnership(self: *App) void {
        if (self.session_owner) |lock| lock.release();
        self.session_owner = null;
    }

    /// WM_ENDSESSION(TRUE): Windows may end the process once every window
    /// has returned, without `GetMessage` returning, so `terminate` never
    /// runs at sign-out, shutdown or reboot. Tear nothing down. A Restart
    /// Manager close (an installer replacing files) may leave noctty
    /// running, so only a real end of session latches the snapshot.
    fn saveForEndSession(self: *App, close_app: bool) void {
        if (self.session_ending) return;
        self.savePaletteMru();
        if (close_app) return self.checkpointSessionState();
        // A checkpoint, never `.final`: the sign-out also ends the shells, so
        // an empty window list here says nothing about what the user closed.
        // Latched even when the save fails: any later save would come from
        // panes closing as their shells die, and could only shrink the
        // previous snapshot or, from `terminate` with no hosts, delete it.
        _ = self.saveSessionState(.checkpoint);
        self.session_ending = true;
    }

    /// Crash insurance on a display-topology change, the moment a GPU
    /// driver is most likely to fault (#299), and the save for a Restart
    /// Manager close. Every host receives the same message, so one save per
    /// second is plenty.
    fn checkpointSessionState(self: *App) void {
        const now = sys.GetTickCount64();
        if (self.session_checkpoint_ms) |last| if (now -% last < 1000) return;
        self.session_checkpoint_ms = now;
        _ = self.saveSessionState(.checkpoint);
    }

    /// The shell model's `persist_session`: a window, tab or pane opened,
    /// closed or moved. Saved as crash insurance (Windows Terminal saves its
    /// layout automatically for the same reason) once the change settles,
    /// so a burst such as a layout launch or repeated undo writes once, and
    /// the last step of the burst is the one on disk. Re-arming the thread
    /// timer restarts its interval. Nothing is armed for a process that
    /// does not own the saved session, including one still restoring it.
    fn scheduleSessionCheckpoint(self: *App) void {
        if (!self.sessionStateEnabled()) return;
        const timer_id = sys.SetTimer(null, self.session_checkpoint_timer_id orelse 0, session_checkpoint_delay_ms, null);
        if (timer_id == 0) {
            log.warn("failed to start session checkpoint timer err={}", .{windows.kernel32.GetLastError()});
            return;
        }
        self.session_checkpoint_timer_id = timer_id;
    }

    fn stopSessionCheckpointTimer(self: *App) void {
        if (self.session_checkpoint_timer_id) |timer_id| {
            _ = sys.KillTimer(null, timer_id);
            self.session_checkpoint_timer_id = null;
        }
    }

    fn onSessionCheckpointTimer(self: *App) void {
        self.stopSessionCheckpointTimer();
        self.session_checkpoint_ms = sys.GetTickCount64();
        _ = self.saveSessionState(.checkpoint);
    }

    fn sessionRestoreEligible(self: *const App) bool {
        if (self.embedding_mode) return false;
        return sessionRestorePolicyAllows(
            self.safe_mode,
            self.config.@"window-save-state",
            self.config.@"initial-window",
            self.config.@"initial-command" != null,
            self.startup_profile_picker,
            self.explicit_startup_working_directory,
        );
    }

    /// Populate `palette_mru` from the on-disk file, one action per line
    /// (newest first). Missing file, I/O errors, and parse failures all
    /// degrade to "start empty" — the MRU is a UX nicety, not a
    /// correctness invariant.
    fn loadPaletteMru(self: *App) void {
        const path = self.paletteMruPath() orelse return;
        defer self.core_app.alloc.free(path);

        const file = std.fs.openFileAbsolute(path, .{}) catch return;
        defer file.close();

        // Cap read size at 64 KB — way more than the 5 × ~200-char
        // actions we expect, but bounded so a corrupted file can't OOM.
        const raw = file.readToEndAlloc(self.core_app.alloc, 64 * 1024) catch return;
        defer self.core_app.alloc.free(raw);

        var it = std.mem.tokenizeAny(u8, raw, "\r\n");
        var slot: usize = 0;
        while (it.next()) |line| {
            if (slot >= self.palette_mru.len) break;
            const trimmed = std.mem.trim(u8, line, " \t");
            if (trimmed.len == 0) continue;
            const duped = self.core_app.alloc.dupeZ(u8, trimmed) catch continue;
            self.palette_mru[slot] = duped;
            slot += 1;
        }
    }

    /// Write `palette_mru` to the on-disk file (newest first). Failure
    /// is silently logged — losing recent history is fine, blocking
    /// termination on file-system problems is not.
    fn savePaletteMru(self: *const App) void {
        // Fast path: nothing to persist.
        if (self.palette_mru[0] == null) return;

        const path = self.paletteMruPath() orelse return;
        defer self.core_app.alloc.free(path);

        if (std.fs.path.dirname(path)) |dir| {
            std.fs.makeDirAbsolute(dir) catch |err| switch (err) {
                error.PathAlreadyExists => {},
                else => {
                    std.log.warn("palette MRU: mkdir failed path={s} err={}", .{ dir, err });
                    return;
                },
            };
        }

        const file = std.fs.createFileAbsolute(path, .{ .truncate = true }) catch |err| {
            std.log.warn("palette MRU: create failed path={s} err={}", .{ path, err });
            return;
        };
        defer file.close();

        var fbuf: [1024]u8 = undefined;
        var fw = file.writer(&fbuf);
        for (self.palette_mru) |slot| {
            if (slot) |owned| {
                fw.interface.print("{s}\n", .{owned}) catch return;
            }
        }
        fw.interface.flush() catch {};
    }

    fn loadSessionState(self: *App) !?std.json.Parsed(win32_session_state.SessionState) {
        if (self.session_state_excluded_for_elevation) return null;
        if (!self.sessionRestoreEligible()) return null;
        const path = self.sessionStatePath() orelse return null;
        defer self.core_app.alloc.free(path);
        return self.loadSessionStateAt(path);
    }

    fn loadSessionStateAt(self: *App, path: []const u8) !?std.json.Parsed(win32_session_state.SessionState) {
        return switch (win32_session_persistence.loadAlloc(
            self.core_app.alloc,
            path,
            win32_session_persistence.default_max_state_bytes,
        )) {
            .missing => null,
            .oversized => oversized: {
                log.warn("win32 session restore: state exceeds size limit; leaving file untouched and not saving over it", .{});
                self.session_state_left_alone = true;
                break :oversized null;
            },
            .transient => |err| {
                // Unreadable now is not unwanted: a scanner may hold a newer
                // build's file for a moment, and the next checkpoint would
                // replace what this run never saw.
                self.session_state_left_alone = true;
                return err;
            },
            .newer_schema => newer: {
                log.warn("win32 session restore: state was written by a newer noctty; leaving file untouched and not saving over it", .{});
                self.session_state_left_alone = true;
                break :newer null;
            },
            .corrupt => |err| corrupt: {
                self.quarantineInvalidSessionState(path, err);
                break :corrupt null;
            },
            .loaded => |parsed| parsed,
        };
    }

    fn launchNamedLayout(self: *App, name: []const u8, preferred_banner_host: ?*Host) bool {
        const banner_host = preferred_banner_host orelse if (self.primarySurface()) |surface|
            surface.host
        else
            null;
        win32_layouts.validateName(name) catch |err| {
            log.warn("named layout launch rejected invalid name name={s} err={}", .{ name, err });
            if (banner_host) |host| host.setBanner(.err, "Invalid layout name.") catch {};
            return false;
        };
        const path = self.namedLayoutPath(name) catch |err| {
            log.warn("named layout launch path resolution failed name={s} err={}", .{ name, err });
            if (banner_host) |host| host.setBanner(.err, "Layout path is unavailable.") catch {};
            return false;
        };
        defer self.core_app.alloc.free(path);

        var loaded = win32_session_persistence.loadLayoutAlloc(
            self.core_app.alloc,
            path,
            win32_session_persistence.default_max_state_bytes,
        );
        defer loaded.deinit();
        switch (loaded) {
            .missing => {
                log.warn("named layout launch file not found name={s} path={s}", .{ name, path });
                if (banner_host) |host| host.setBanner(.err, "Layout was not found.") catch {};
                return false;
            },
            .oversized => {
                log.warn("named layout launch file exceeds size limit name={s} path={s}", .{ name, path });
                if (banner_host) |host| host.setBanner(.err, "Layout file is too large.") catch {};
                return false;
            },
            .transient => |err| {
                log.warn("named layout launch read failed name={s} path={s} err={}", .{ name, path, err });
                if (banner_host) |host| host.setBanner(.err, "Layout could not be read.") catch {};
                return false;
            },
            .newer_schema => {
                log.warn("named layout launch file was written by a newer noctty name={s} path={s}", .{ name, path });
                if (banner_host) |host| host.setBanner(.err, "Layout was saved by a newer noctty.") catch {};
                return false;
            },
            .corrupt => |err| {
                const quarantined = self.quarantineInvalidNamedLayout(path, name, err);
                if (banner_host) |host| host.setBanner(
                    .err,
                    if (quarantined)
                        "Invalid layout was quarantined."
                    else
                        "Invalid layout could not be quarantined.",
                ) catch {};
                return false;
            },
            .loaded => |parsed| {
                if (parsed.value.windows.len != 1) {
                    const quarantined = self.quarantineInvalidNamedLayout(
                        path,
                        name,
                        error.InvalidWindowCount,
                    );
                    if (banner_host) |host| host.setBanner(
                        .err,
                        if (quarantined)
                            "Invalid layout was quarantined."
                        else
                            "Invalid layout could not be quarantined.",
                    ) catch {};
                    return false;
                }
                // A layout file can come from a synced or shared directory, and
                // materializing one spawns a shell per pane. Refuse oversized
                // documents instead of quarantining them: the file may well be
                // the user's own, just too large for one window.
                win32_layouts.validateLaunchSize(parsed.value.windows[0]) catch |err| {
                    log.warn("named layout launch rejected oversized document name={s} err={}", .{ name, err });
                    if (banner_host) |host| host.setBanner(.err, "Layout has too many tabs or panes.") catch {};
                    return false;
                };
                // A layout is a shape, not a placement: the save path omits
                // window geometry deliberately. Strip any a hand-authored or
                // synced file carries so it cannot place the new window
                // off-screen, resize it, or maximize it.
                var shape = parsed.value.windows[0];
                shape.x = null;
                shape.y = null;
                shape.width = null;
                shape.height = null;
                shape.state = null;
                const surface = self.restoreSessionWindow(shape) catch |err| {
                    log.warn("named layout materialization failed name={s} err={}", .{ name, err });
                    if (banner_host) |host| host.setBanner(.err, "Layout could not be opened.") catch {};
                    return false;
                };
                self.activateSurface(surface);
                return true;
            },
        }
    }

    fn quarantineInvalidNamedLayout(
        self: *App,
        path: []const u8,
        name: []const u8,
        parse_error: anyerror,
    ) bool {
        const destination = win32_session_persistence.quarantineCorruptFileAlloc(
            self.core_app.alloc,
            path,
        ) catch |err| {
            log.warn("named layout quarantine failed name={s} path={s} parse_err={} move_err={}", .{ name, path, parse_error, err });
            return false;
        };
        defer self.core_app.alloc.free(destination);
        log.warn("named layout quarantined invalid file name={s} path={s} parse_err={}", .{ name, destination, parse_error });
        return true;
    }

    fn saveNamedLayout(self: *App, target: apprt.Target, name: []const u8) bool {
        const surface = self.findSurfaceForTarget(target) orelse {
            log.warn("named layout save has no target surface name={s}", .{name});
            return false;
        };
        const host = surface.host orelse {
            log.warn("named layout save target has no host name={s}", .{name});
            return false;
        };
        win32_layouts.validateName(name) catch |err| {
            log.warn("named layout save rejected invalid name name={s} err={}", .{ name, err });
            host.setBanner(.err, "Invalid layout name.") catch {};
            return false;
        };
        const path = self.namedLayoutPath(name) catch |err| {
            log.warn("named layout save path resolution failed name={s} err={}", .{ name, err });
            host.setBanner(.err, "Layout path is unavailable.") catch {};
            return false;
        };
        defer self.core_app.alloc.free(path);

        var arena = std.heap.ArenaAllocator.init(self.core_app.alloc);
        defer arena.deinit();
        // Layout files never carry terminal contents: request zero lines so
        // the `.layout` arm has nothing to capture even if it ever grows one.
        var no_scrollback_budget: usize = 0;
        const window = buildSessionWindow(
            arena.allocator(),
            host,
            .layout,
            0,
            &no_scrollback_budget,
        ) catch |err| {
            log.warn("named layout save snapshot failed name={s} err={}", .{ name, err });
            host.setBanner(.err, "Layout could not be saved.") catch {};
            return false;
        };
        // Launch refuses documents above this cap, so refuse to write one.
        // Saving must not report success for a layout that can never open.
        win32_layouts.validateLaunchSize(window) catch |err| {
            log.warn("named layout save rejected oversized window name={s} err={}", .{ name, err });
            host.setBanner(.err, "Layout has too many tabs or panes.") catch {};
            return false;
        };
        const layout_windows = [_]win32_session_state.Window{window};
        const encoded = win32_session_state.encodeAlloc(
            self.core_app.alloc,
            .{ .windows = &layout_windows },
        ) catch |err| {
            log.warn("named layout save encode failed name={s} err={}", .{ name, err });
            host.setBanner(.err, "Layout could not be saved.") catch {};
            return false;
        };
        defer self.core_app.alloc.free(encoded);
        if (!namedLayoutEncodingFitsReadLimit(encoded.len)) {
            log.warn(
                "named layout save rejected oversized encoding name={s} bytes={d}",
                .{ name, encoded.len },
            );
            host.setBanner(.err, "Layout data is too large.") catch {};
            return false;
        }
        writePersistentFileAlloc(self.core_app.alloc, path, encoded) catch |err| {
            log.warn("named layout save write failed name={s} path={s} err={}", .{ name, path, err });
            host.setBanner(.err, "Layout could not be saved.") catch {};
            return false;
        };
        host.setBanner(.info, "Layout saved.") catch {};
        return true;
    }

    fn namedLayoutEncodingFitsReadLimit(bytes: usize) bool {
        return bytes <= win32_session_persistence.default_max_state_bytes;
    }

    fn restoreSessionState(self: *App) !bool {
        var parsed = self.loadSessionState() catch |err| {
            log.warn("win32 session restore: state read failed; leaving file untouched err={}", .{err});
            return false;
        } orelse return false;
        defer parsed.deinit();

        const ledger_path = localAppDataPathAlloc(self.core_app.alloc, "startup-attempts.json");
        defer if (ledger_path) |value| self.core_app.alloc.free(value);
        if (ledger_path) |value| {
            markRecoveryAttemptAtPath(self.core_app.alloc, value, &self.recovery_startup, .{ .session_restore = unixMillis() });
        }
        defer if (ledger_path) |value| {
            markRecoveryAttemptAtPath(self.core_app.alloc, value, &self.recovery_startup, .session_restored);
        };
        // Debug-only fault for the restore crash-loop harness: the process
        // ends mid-restore, as a release abort does (ExitProcess(3)), without
        // the breakpoint a Debug panic raises.
        if (builtin.mode == .Debug and std.process.hasEnvVarConstant("NOCTTY_DEBUG_CRASH_SESSION_RESTORE")) {
            std.process.exit(3);
        }

        var restored = false;
        for (parsed.value.windows) |window| {
            if (self.restoreSessionWindow(window)) |surface| {
                restored = true;
                self.activateSurface(surface);
            } else |err| {
                log.warn("win32 session restore: skipped window err={}", .{err});
                // Handled: the dialog and the recovery ledger describe only
                // the failure that ends the launch.
                gl_startup.clearOpenGLStartupFailure();
            }
        }

        return restored;
    }

    fn quarantineInvalidSessionState(self: *App, path: []const u8, parse_error: anyerror) void {
        const destination = win32_session_persistence.quarantineCorruptFileAlloc(
            self.core_app.alloc,
            path,
        ) catch |err| {
            log.warn("win32 session restore: quarantine failed path={s} parse_err={} move_err={}", .{ path, parse_error, err });
            return;
        };
        defer self.core_app.alloc.free(destination);
        log.warn("win32 session restore: quarantined unreadable state path={s} parse_err={}", .{ destination, parse_error });
    }

    fn tickCoreApp(self: *App) !void {
        self.renderer_sync_paint_spent = false;
        try self.core_app.tick(self);
        self.resolveRecoveryStartup();
    }

    fn tickCoreAppModal(self: *App) void {
        if (self.core_ticking) return;
        self.core_ticking = true;
        defer self.core_ticking = false;
        self.renderer_sync_paint_spent = false;
        self.core_app.tickModal(self) catch |err| {
            log.warn("modal mailbox tick failed err={}", .{err});
        };
    }

    fn createMessageWindow(self: *App) !void {
        const name = std.unicode.utf8ToUtf16LeStringLiteral("noctty.win32.app");
        var wc: WNDCLASSEXW = .{
            .cbSize = @sizeOf(WNDCLASSEXW),
            .style = 0,
            .lpfnWndProc = &appMessageWindowProc,
            .cbClsExtra = 0,
            .cbWndExtra = 0,
            .hInstance = self.hinstance,
            .hIcon = null,
            .hCursor = null,
            .hbrBackground = null,
            .lpszMenuName = null,
            .lpszClassName = name,
            .hIconSm = null,
        };
        if (sys.RegisterClassExW(&wc) == 0 and windows.kernel32.GetLastError() != .CLASS_ALREADY_EXISTS)
            return lastError(); // ERROR_CLASS_ALREADY_EXISTS is expected in tests.
        const delivery = try AppDelivery.create();
        errdefer delivery.release();
        const hwnd = sys.CreateWindowExW(
            0,
            name,
            name,
            0,
            0,
            0,
            0,
            0,
            @ptrFromInt(@as(usize, @bitCast(@as(isize, -3)))), // HWND_MESSAGE
            null,
            self.hinstance,
            null,
        ) orelse return lastError();
        setWindowData(hwnd, self);
        self.message_hwnd = hwnd;
        self.delivery = delivery;
        if (self.winrt_toast) |*toast| {
            toast.setActivationCallback(delivery, winrtToastActivationCallback, .{
                .retain = retainToastDelivery,
                .release = releaseToastDelivery,
            });
        }
        delivery.publish(hwnd);
    }

    fn closeMessageWindow(self: *App) void {
        const delivery = self.delivery orelse return;
        delivery.close();
        while (delivery.pop()) |value| {
            var payload = value;
            switch (payload) {
                .uia_disconnect => |pending| processDeferredUiaDisconnect(null, pending),
                .jump_list => |job| {
                    // The Shell already reset its removed list for this
                    // commit; record the removals before the state is saved.
                    if (self.jump_list) |*jump_list| jump_list.completeRebuild(job);
                    payload.deinit();
                },
                else => payload.deinit(),
            }
        }
        delivery.update_running.store(false, .release);
        delivery.profiles_running.store(false, .release);
        delivery.toast_pending.store(false, .release);
        if (self.message_hwnd) |hwnd| {
            setWindowData(hwnd, null);
            _ = sys.DestroyWindow(hwnd);
            self.message_hwnd = null;
        }
    }

    /// Called only by the outer pump, never while an owner WndProc is under
    /// a native modal loop. Taking oldest also recovers a lost notification.
    fn drainPendingHandoffs(self: *App) void {
        const server = self.terminal_handoff_server orelse return;
        while (server.pending.takeOldest()) |pending| {
            defer {
                pending.deinit();
                self.core_app.alloc.destroy(pending);
            }
            self.createAdoptedWindow(pending) catch |err| {
                win32_terminal_handoff.appendHandoffMilestone(self.core_app.alloc, "adopted_window_failed");
                log.err("terminal handoff surface creation failed err={}", .{err});
            };
            if (self.windows.items.len == 0) self.startTerminalHandoffIdleTimer();
        }
    }

    fn syncDirtyGlobalHotkeys(self: *App) void {
        if (!self.global_hotkeys_dirty) return;
        self.global_hotkeys_dirty = false;
        self.syncGlobalHotkeys() catch |err| {
            log.err("failed to sync win32 global hotkeys err={}", .{err});
        };
    }

    fn rendererRepaintModeThisTick(self: *App, host: ?*const Host) SurfaceRepaintRequestMode {
        return rendererTickRepaintMode(
            rendererRepaintRequestMode(host, sys.GetTickCount64()),
            &self.renderer_sync_paint_spent,
        );
    }

    test "a failed new window request leaves the app running and the mailbox draining" {
        if (builtin.os.tag != .windows) return error.SkipZigTest;

        var core_app: CoreApp = undefined;
        var app: App = undefined;
        var host: Host = undefined;
        var surface: Surface = undefined;
        var session: TestSession = .{};
        try session.init(.{
            .core_app = &core_app,
            .app = &app,
            .hosts = &.{.{ .storage = &host, .register = true, .next_tab_id = 2 }},
            .surfaces = &.{.{ .storage = &surface, .host = &host, .register = true }},
            .tabs = &.{.{ .host = &host, .surface = &surface, .id = 1 }},
        });
        defer session.deinit();

        const Hook = struct {
            var calls: usize = 0;

            fn createSurface(_: *App, _: *const configpkg.Config, _: LPCWSTR, _: SurfaceInitOptions) anyerror!*Surface {
                calls += 1;
                return error.TestWindowCreateFailed;
            }
        };
        Hook.calls = 0;
        app.test_create_window_surface = &Hook.createSurface;

        // Two `+new-window` requests forwarded by other processes, and no
        // window can be created for either. Before the fix the first error
        // left `App.run`, and every existing window closed with it.
        for (0..2) |_| {
            try std.testing.expect(core_app.mailbox.push(.{ .new_window = .{} }, .instant) != 0);
        }
        try core_app.tick(&app);
        try std.testing.expectEqual(@as(usize, 2), Hook.calls);
        try std.testing.expectEqual(HostBannerKind.err, host.banner_kind);
        try std.testing.expectEqualStrings("New window could not be opened.", host.banner_text.?);

        // With its last tab detached for undo, the host stays open but has
        // no surface to resolve it through, and still takes the banner.
        try host.setBanner(.none, null);
        var detached = host.tabs.orderedRemove(0);
        detached.deinit();
        try std.testing.expect(core_app.mailbox.push(.{ .new_window = .{} }, .instant) != 0);
        try core_app.tick(&app);
        try std.testing.expectEqual(@as(usize, 3), Hook.calls);
        try std.testing.expectEqual(HostBannerKind.err, host.banner_kind);
    }

    /// Record this launch as resolved in the startup ledger.
    ///
    /// A launch is unresolved until the outer Win32 message loop completes its
    /// first core-app tick. Renderer and PTY work that continues on other
    /// threads after this boundary is outside recovery accounting.
    ///
    /// The write is attempted again on later ticks while the retry budget
    /// lasts: latching "handled" on the first attempt would let one transient
    /// sharing violation leave the launch unresolved for the whole session,
    /// which is exactly the crash-loop evidence that selects safe mode.
    fn resolveRecoveryStartup(self: *App) void {
        if (!self.recovery_ready_resolved) {
            // An unrelated tick that beat the retry timer must not spend an
            // attempt; the armed timer will bring the loop back on time.
            if (!recoveryRetryDue(self.recovery_retry_not_before_ms, sys.GetTickCount64())) return;

            if (self.markRecoveryReady()) {
                self.recovery_ready_resolved = true;
                self.stopRecoveryRetryTimer();
                self.recovery_retry_not_before_ms = null;
            } else |err| {
                const exhausted = self.recovery_ready_retry.recordFailure(err);
                const scheduled = !exhausted and self.scheduleRecoveryRetry();
                switch (recoveryFailurePolicy(exhausted, scheduled)) {
                    .retry_scheduled => log.warn(
                        "win32 recovery: ready marker attempt {d} failed err={}; retrying in {d}ms",
                        .{ self.recovery_ready_retry.failures, err, recovery_ready_retry_delay_ms },
                    ),
                    .give_up_unschedulable => {
                        log.warn(
                            "win32 recovery: ready marker attempt {d} failed err={} and no retry could be scheduled; leaving the launch unresolved",
                            .{ self.recovery_ready_retry.failures, err },
                        );
                        self.recovery_ready_resolved = true;
                        self.recovery_retry_not_before_ms = null;
                    },
                    .give_up_exhausted => {
                        log.warn(
                            "win32 recovery: ready marker unresolved after {d} attempt(s) err={}",
                            .{ self.recovery_ready_retry.failures, err },
                        );
                        self.recovery_ready_resolved = true;
                        self.stopRecoveryRetryTimer();
                        self.recovery_retry_not_before_ms = null;
                    },
                }
            }
        }

        // Only now may the safe-mode dialog appear: killing the process while
        // that modal is up must not preserve the failure streak.
        if (self.recovery_safe_mode_notice.release(self.recovery_ready_resolved)) {
            if (recoverySafeModeNotice(self.recovery_startup.decision, self.recovery_startup.session_set_aside)) |text| {
                self.showRecoverySafeModeNotice(text);
            }
        }
    }

    /// Record on this launch's attempt that it is ending because OpenGL could
    /// not start (the failure the startup dialog then reports), so the next
    /// launch does not count it toward safe mode. Best effort, like the
    /// restore markers. A crash, inside any renderer, never gets here.
    fn markRecoveryOpenGLUnavailable(self: *App) void {
        if (!gl_startup.openGLStartupFailed()) return;
        const path = localAppDataPathAlloc(self.core_app.alloc, "startup-attempts.json") orelse return;
        defer self.core_app.alloc.free(path);
        markRecoveryAttemptAtPath(self.core_app.alloc, path, &self.recovery_startup, .{ .opengl_unavailable = unixMillis() });
    }

    /// Errors are the retryable ones only: everything deterministic (no
    /// ledger, nothing to mark, an unmergeable record) returns normally so a
    /// caller's retry budget is not spent on a failure that cannot clear.
    fn markRecoveryReady(self: *App) !void {
        if (self.recovery_startup.count == 0) return;
        const memory_attempts = self.recovery_startup.attempts[0..self.recovery_startup.count];
        const target_started_at = memory_attempts[memory_attempts.len - 1].started_at_unix_ms;
        if (memory_attempts[memory_attempts.len - 1].ready_at_unix_ms != null) return;
        const path = localAppDataPathAlloc(self.core_app.alloc, "startup-attempts.json") orelse return;
        defer self.core_app.alloc.free(path);

        // The disk read and the replace below are one transaction against
        // other instances' startups and ready markers. A busy lock is
        // transient in the same way a handle hold is, so it spends a retry
        // rather than resolving the launch.
        var lock = (try RecoveryLedgerLock.acquire(
            self.core_app.alloc,
            path,
            recovery_ledger_lock_wait_ms,
        )) orelse return error.RecoveryLedgerBusy;
        defer lock.release();

        var disk_record: win32_recovery.StartupAttemptRecord = .{};
        var ledger = readRecoveryLedgerAlloc(self.core_app.alloc, path, "ready merge");
        defer ledger.deinit();
        // Deterministic, so not an error that spends the caller's retries.
        if (ledger == .left_alone) return;
        // A transient failure is what that retry budget is for: dropping the
        // marker would leave this launch unresolved on disk, which the next
        // launch counts as a failed start.
        if (ledger == .unreadable) return error.RecoveryLedgerUnreadable;
        if (ledger == .record) disk_record = ledger.record.value;

        var merged_attempts: [win32_recovery.max_attempts]win32_recovery.StartupAttempt = undefined;
        const merged = win32_recovery.mergeMarkReady(
            disk_record,
            .{ .attempts = memory_attempts },
            target_started_at,
            unixMillis(),
            &merged_attempts,
        ) catch |err| {
            log.warn("win32 recovery: ready marker merge failed err={}", .{err});
            return;
        };
        persistMergedRecoveryReadyAtPath(
            self.core_app.alloc,
            path,
            &self.recovery_startup,
            merged,
        ) catch |err| {
            log.warn("win32 recovery: ready marker persist failed err={}", .{err});
            return err;
        };
    }

    fn restoreSessionWindow(
        self: *App,
        window: win32_session_state.Window,
    ) !*Surface {
        var transaction = SessionRestoreTransaction.init(self);
        defer transaction.rollback();
        var host: ?*Host = null;
        var window_surface: ?*Surface = null;

        for (window.tabs, 0..) |saved_tab, tab_index| {
            const tab_surface = try self.restoreSessionTab(
                saved_tab,
                host,
                tab_index,
                &transaction,
            );
            if (host == null) {
                host = tab_surface.host;
                if (host) |created_host| {
                    applyRestoredWindowPlacement(created_host, window) catch |err| {
                        log.warn("win32 session restore: window placement failed err={}", .{err});
                    };
                }
            }
            if (window_surface == null or tab_index == window.selected_tab) {
                window_surface = tab_surface;
            }
        }

        const restored_host = host orelse return error.EmptyTabs;
        if (restored_host.tabs.items.len == 0) return error.EmptyTabs;
        restored_host.active_tab = @min(window.selected_tab, restored_host.tabs.items.len - 1);
        const active_tab = &restored_host.tabs.items[restored_host.active_tab];
        const selected = active_tab.focusedSurface() orelse window_surface orelse return error.EmptyTabs;
        transaction.commit();
        return selected;
    }

    fn restoreSessionTab(
        self: *App,
        saved_tab: win32_session_state.Tab,
        existing_host: ?*Host,
        tab_index: usize,
        transaction: *SessionRestoreTransaction,
    ) !*Surface {
        const layout = saved_tab.layout;
        if (layout.root >= layout.nodes.len) return error.EmptyLayout;
        const node_surfaces = try self.core_app.alloc.alloc(?*Surface, layout.nodes.len);
        defer self.core_app.alloc.free(node_surfaces);
        @memset(node_surfaces, null);

        // The panes are made in the saved tree's shape: each split's second
        // half is split off the pane standing for its first half, before that
        // pane is split further, so later splits nest inside the first half.
        // The shell model and the native tree then have the saved topology,
        // and closing a restored pane focuses the pane beside it on screen.
        // The native tree takes the saved ratios below.
        const Pending = struct { node: usize, leaf: *Surface };
        const pending = try self.core_app.alloc.alloc(Pending, layout.nodes.len);
        defer self.core_app.alloc.free(pending);
        const first_index = firstSessionLayoutPane(layout, layout.root) orelse return error.EmptyLayout;
        const first = try self.restoreSessionPane(
            layout.nodes[first_index].pane,
            existing_host,
            null,
            tab_index,
            .right,
            transaction,
        );
        pending[0] = .{ .node = layout.root, .leaf = first };
        var pending_len: usize = 1;
        while (pending_len > 0) {
            pending_len -= 1;
            const item = pending[pending_len];
            switch (layout.nodes[item.node]) {
                .pane => node_surfaces[item.node] = item.leaf,
                .split => |split| {
                    const second_index = firstSessionLayoutPane(layout, split.second) orelse return error.EmptyLayout;
                    const second = try self.restoreSessionPane(
                        layout.nodes[second_index].pane,
                        existing_host,
                        item.leaf,
                        tab_index,
                        switch (split.axis) {
                            .horizontal => .right,
                            .vertical => .down,
                        },
                        transaction,
                    );
                    if (pending_len + 2 > pending.len) return error.InvalidTreeShape;
                    pending[pending_len] = .{ .node = split.second, .leaf = second };
                    pending[pending_len + 1] = .{ .node = split.first, .leaf = item.leaf };
                    pending_len += 2;
                },
            }
        }

        // `selected_leaf` counts panes in the saved node order.
        var selected = first;
        var leaf_index: usize = 0;
        for (layout.nodes, node_surfaces) |node, surface| switch (node) {
            .pane => {
                if (leaf_index == saved_tab.selected_leaf) selected = surface orelse first;
                leaf_index += 1;
            },
            .split => {},
        };
        if (self.findTabForSurface(selected)) |found| {
            // No errdefer: nothing can fail before the tab takes the tree, and
            // from then on the tab frees it, also when `layout` fails.
            const restored_tree = try buildRestoredSessionSplitTree(
                self.core_app.alloc,
                saved_tab.layout,
                node_surfaces,
            );
            found.tab.tree.deinit();
            found.tab.tree = restored_tree;
            if (found.tab.findHandle(selected)) |handle| found.tab.focused = handle;
            // The model made each new pane its tab's focus; the saved
            // selection is this tab's.
            self.commitShellSurfaceActivation(selected);
            try found.host.layout();
        }
        return selected;
    }

    test "restoreSessionTab leaves the restored tree to the tab when layout fails" {
        if (builtin.os.tag != .windows) return error.SkipZigTest;

        var core_app: CoreApp = undefined;
        var app: App = undefined;
        var host: Host = undefined;
        var left: Surface = undefined;
        var right: Surface = undefined;
        var session: TestSession = .{};
        try session.init(.{
            .core_app = &core_app,
            .app = &app,
            .hosts = &.{.{ .storage = &host, .register = true }},
            .surfaces = &.{
                .{ .storage = &left, .host = &host },
                .{ .storage = &right, .host = &host },
            },
        });
        defer session.deinit();
        const host_hwnd = try createTestHostWindow();
        defer _ = sys.DestroyWindow(host_hwnd);
        host.hwnd = host_hwnd;

        // The saved ratio tells the restored tree from the one the panes
        // were created with.
        const nodes = [_]win32_session_state.Node{
            .{ .split = .{ .axis = .horizontal, .ratio = 0.25, .first = 1, .second = 2 } },
            .{ .pane = .{} },
            .{ .pane = .{} },
        };
        const layout: win32_session_state.LayoutTree = .{ .root = 0, .nodes = &nodes };
        var counting = std.testing.FailingAllocator.init(std.testing.allocator, .{});
        var dry_run = try buildRestoredSessionSplitTree(counting.allocator(), layout, &.{ null, &left, &right });
        dry_run.deinit();

        var failing = std.testing.FailingAllocator.init(std.testing.allocator, .{});
        core_app.alloc = failing.allocator();
        defer core_app.alloc = std.testing.allocator;

        const Hook = struct {
            var panes: [2]*Surface = undefined;
            var created: usize = 0;
            var failing_ref: *std.testing.FailingAllocator = undefined;
            var build_allocations: usize = 0;

            fn createSurface(
                hook_app: *App,
                _: *const configpkg.Config,
                _: LPCWSTR,
                opts: SurfaceInitOptions,
            ) anyerror!*Surface {
                const alloc = hook_app.core_app.alloc;
                const surface = panes[created];
                created += 1;
                const target = hook_app.findHostById(opts.host_id.?).?;
                const source = opts.clone_state_from orelse {
                    var tab = try Tab.init(alloc, target.nextTabId(), surface);
                    errdefer tab.deinit();
                    try target.tabs.append(alloc, tab);
                    return surface;
                };
                const found = hook_app.findTabForSurface(@constCast(source)).?;
                var inserted = try SplitTreeSurface.init(alloc, surface);
                defer inserted.deinit();
                const next = try found.tab.tree.split(alloc, found.tab.focused, opts.split_direction, 0.5, &inserted);
                found.tab.tree.deinit();
                found.tab.tree = next;
                // The last pane is in. Fail the first allocation after the
                // restored tree is built: the one `layout` makes once the
                // tab has taken that tree.
                failing_ref.fail_index = failing_ref.alloc_index + build_allocations;
                return surface;
            }
        };
        Hook.panes = .{ &left, &right };
        Hook.created = 0;
        Hook.failing_ref = &failing;
        Hook.build_allocations = counting.alloc_index;
        app.test_create_window_surface = &Hook.createSurface;

        var transaction = SessionRestoreTransaction.init(&app);
        // Before the fix the restore's own errdefer freed the restored tree
        // while the tab kept it, and the session teardown freed it again.
        try std.testing.expectError(error.OutOfMemory, app.restoreSessionTab(
            .{ .selected_leaf = 1, .layout = layout },
            &host,
            0,
            &transaction,
        ));
        try std.testing.expectEqual(@as(usize, 1), host.tabs.items.len);
        const tab = &host.tabs.items[0];
        try std.testing.expectEqual(@as(f16, 0.25), tab.tree.nodes[0].split.ratio);
        try std.testing.expectEqual(@as(usize, 2), tab.leafCount());
        try std.testing.expectEqual(&right, tab.focusedSurface().?);
    }

    fn restoreSessionPane(
        self: *App,
        pane: win32_session_state.Pane,
        existing_host: ?*Host,
        tab_surface: ?*Surface,
        tab_index: usize,
        split_direction: SplitTreeSurface.Split.Direction,
        transaction: *SessionRestoreTransaction,
    ) !*Surface {
        const host = existing_host orelse if (tab_surface) |source| source.host else null;
        const open_kind: apprt.surface.NewSurfaceContext = if (host == null)
            .window
        else if (tab_surface == null)
            .tab
        else
            .split;
        var config = try apprt.surface.newConfig(self.core_app, &self.config, open_kind);
        defer config.deinit();

        // `initial-command` (from `-e` or the config option) applies to the
        // ordinary first window. A restored pane's command comes from its
        // saved profile, so clear it: otherwise `Surface.init` prefers it
        // while `app.first` is set and the first pane of a restored session
        // or a launched layout runs the wrong command.
        config.@"initial-command" = null;

        // A refused profile (today: SSH) must not leave its key on the surface
        // either, or a later split of the restored pane would re-resolve it and
        // launch the connection this restore just declined.
        const profile_applied = if (pane.profile) |key|
            try self.applyRestoredProfileConfig(&config, host, key)
        else
            false;
        if (pane.cwd) |cwd| {
            const alloc = config._arena.?.allocator();
            config.@"working-directory" = .{ .path = try alloc.dupe(u8, cwd) };
        }

        const tab_id = if (tab_surface) |source|
            (self.findTabForSurface(source) orelse return error.NoActiveSurface).tab.id
        else
            null;
        const surface = try self.createWindowSurface(&config, default_title, .{
            .host_id = if (host) |existing| existing.id else null,
            .tab_id = tab_id,
            .tab_insert_index = if (host != null and tab_surface == null) tab_index else null,
            .clone_state_from = tab_surface,
            .split_direction = split_direction,
        });
        transaction.noteSurface(surface);

        if (profile_applied) {
            try appendOwnedString(self.core_app.alloc, &surface.launch_profile_key, pane.profile.?);
        }
        if (pane.title_override) |title| try surface.setTitleOverride(title);
        if (pane.tab_title_override) |title| try surface.setTabTitleOverride(title);
        if (pane.cwd) |cwd| try surface.setPwd(cwd);
        const scrollback_lines: usize = self.config.@"window-save-state-scrollback";
        if (scrollback_lines > 0) {
            if (pane.scrollback) |snapshot| {
                _ = surface.restoreSessionScrollback(
                    snapshot,
                    scrollback_lines,
                ) catch |err| {
                    log.warn("win32 session restore: pane snapshot omitted or partial err={}", .{err});
                    return surface;
                };
            }
        }
        return surface;
    }

    fn applyRestoredProfileConfig(
        self: *App,
        config: *configpkg.Config,
        host: ?*Host,
        key: []const u8,
    ) !bool {
        if (host) |existing| {
            const profile = (try existing.profileForKey(key)) orelse return false;
            if (!isSessionRestorableProfile(profile)) return false;
            try applyProfileSurfaceConfig(config, profile);
            return true;
        }

        const profiles = try windows_shell.listProfiles(
            self.core_app.alloc,
            self.config.@"ssh-config-hosts",
        );
        defer windows_shell.deinitProfiles(self.core_app.alloc, profiles);
        return try applyProfileConfigByKey(config, profiles, key);
    }

    fn applyRestoredWindowPlacement(
        host: *Host,
        window: win32_session_state.Window,
    ) !void {
        const hwnd = host.hwnd orelse return;
        if (try sessionStateWindowRect(window)) |saved| {
            // The saved rect is where the window was, not where there is room
            // for it now: its monitor may be gone.
            const works = WorkAreas.collect();
            const dpi_before = sys.GetDpiForWindow(hwnd);
            var target = restoredRectOnScreen(saved, works.slice(), restore_grab);
            // The rect is in the pixels of the monitor it was saved on, and is
            // where the window goes: a crossing from the monitor the host was
            // created on must not swap in the DPI suggestion's rescaled size.
            host.restore_placing = true;
            defer host.restore_placing = false;
            for (0..3) |attempt| {
                if (sys.SetWindowPos(
                    hwnd,
                    null,
                    target.left,
                    target.top,
                    target.right - target.left,
                    target.bottom - target.top,
                    c.SWP_NOZORDER | c.SWP_NOACTIVATE,
                ) == 0) return lastError();
                // Windows caps what it is given (a left edge to 16 bits, a
                // width to the largest window), so whether the title bar can
                // be reached is judged on the rect the window ended up with.
                var actual: RECT = undefined;
                if (sys.GetWindowRect(hwnd, &actual) == 0) return lastError();
                const moved = restoredRectOnScreen(actual, works.slice(), restore_grab);
                if (!rectEqual(moved, actual)) {
                    if (attempt == 2) {
                        log.warn("win32 session restore: window stayed off every monitor", .{});
                        break;
                    }
                    target = moved;
                    continue;
                }
                // The layout that follows a DPI change can resize it once
                // more: apply the same rect again once.
                if (sys.GetDpiForWindow(hwnd) == dpi_before or rectEqual(actual, target)) break;
            }
        }
        if ((window.state orelse .normal) == .maximized) {
            _ = sys.ShowWindow(hwnd, c.SW_MAXIMIZE);
        }
    }

    /// `.final` is the owner's save as its windows close: closing every
    /// one ends the session, so an empty snapshot deletes the file. A
    /// `.checkpoint` taken while the app keeps running never deletes, and
    /// leaves alone the snapshot a last-host close already took.
    fn saveSessionState(self: *const App, kind: SessionSaveKind) bool {
        if (self.session_state_excluded_for_elevation) return false;
        if (!self.sessionStateEnabled()) return false;
        // A sign-out's snapshot is final; see `session_ending`.
        if (self.session_ending) return false;
        if (kind == .checkpoint and self.session_state_saved_before_last_host_close) return false;
        const path = self.sessionStatePath() orelse return false;
        defer self.core_app.alloc.free(path);

        const scrollback_lines: usize = self.config.@"window-save-state-scrollback";
        for ([_]usize{ scrollback_lines, 0 }, 0..) |attempt_lines, attempt_index| {
            if (attempt_index == 1) {
                if (scrollback_lines == 0) break;
                log.warn("win32 session save: retrying without scrollback", .{});
            }

            var arena = std.heap.ArenaAllocator.init(self.core_app.alloc);
            defer arena.deinit();

            const state = self.buildSessionState(arena.allocator(), attempt_lines) catch |err| {
                log.warn("win32 session save: snapshot failed scrollback_lines={d} err={}", .{ attempt_lines, err });
                continue;
            };
            if (state.windows.len == 0) return removeEmptySessionState(path, kind);

            const encoded = win32_session_state.encodeAlloc(self.core_app.alloc, state) catch |err| {
                log.warn("win32 session save: encode failed scrollback_lines={d} err={}", .{ attempt_lines, err });
                continue;
            };
            defer self.core_app.alloc.free(encoded);
            const max_bytes = if (attempt_lines > 0)
                win32_session_persistence.default_max_state_bytes
            else
                win32_session_persistence.max_layout_state_bytes;
            if (encoded.len > max_bytes) {
                log.warn("win32 session save: state exceeds write limit bytes={d}", .{encoded.len});
                continue;
            }
            writePersistentFileAlloc(self.core_app.alloc, path, encoded) catch |err| {
                log.warn("win32 session save: write failed path={s} err={}", .{ path, err });
                return false;
            };
            return true;
        }
        return false;
    }

    fn buildSessionState(
        self: *const App,
        alloc: Allocator,
        scrollback_lines: usize,
    ) !win32_session_state.SessionState {
        var count: usize = 0;
        for (self.hosts.items) |host| {
            if (hostSessionTabs(host).len > 0) count += 1;
        }

        const windows_state = try alloc.alloc(win32_session_state.Window, count);
        var remaining_scrollback_budget = win32_session_state.max_total_scrollback_bytes;
        var built: usize = 0;
        for (self.hosts.items) |host| {
            if (hostSessionTabs(host).len == 0) continue;
            windows_state[built] = try buildSessionWindow(
                alloc,
                host,
                .session,
                scrollback_lines,
                &remaining_scrollback_budget,
            );
            built += 1;
        }

        return .{ .windows = windows_state };
    }

    /// What a window snapshot is for. `.session` is this process's own restore
    /// state; `.layout` is a user-visible named layout file, which carries only
    /// the shape fields and no window geometry.
    const SnapshotScope = enum { session, layout };

    fn buildSessionWindow(
        alloc: Allocator,
        host: *Host,
        scope: SnapshotScope,
        scrollback_lines: usize,
        remaining_scrollback_budget: *usize,
    ) !win32_session_state.Window {
        const session_tabs = hostSessionTabs(host);
        if (scope == .layout and session_tabs.len == 0) return error.EmptyTabs;
        const tabs = try alloc.alloc(win32_session_state.Tab, session_tabs.len);
        var selected_tab: usize = 0;
        for (session_tabs, 0..) |*tab, i| {
            if (i <= host.active_tab) selected_tab = i;
            tabs[i] = try buildSessionTab(
                alloc,
                tab,
                scope,
                scrollback_lines,
                remaining_scrollback_budget,
            );
        }

        var window: win32_session_state.Window = .{
            .selected_tab = selected_tab,
            .tabs = tabs,
        };
        // Geometry is restore state, not layout shape.
        if (scope == .layout) return window;
        if (sessionWindowPlacement(host)) |placed| {
            if (placed.rect) |rect| {
                window.x = rect.left;
                window.y = rect.top;
                window.width = rect.right - rect.left;
                window.height = rect.bottom - rect.top;
            }
            window.state = if (placed.maximized) .maximized else .normal;
        }
        return window;
    }

    fn buildSessionTab(
        alloc: Allocator,
        tab: *const Tab,
        scope: SnapshotScope,
        scrollback_lines: usize,
        remaining_scrollback_budget: *usize,
    ) !win32_session_state.Tab {
        var selected_leaf: usize = 0;
        var leaf_index: usize = 0;
        for (tab.tree.nodes, 0..) |node, node_index| {
            switch (node) {
                .leaf => {},
                .split => continue,
            }
            if (tab.focused.idx() == node_index) selected_leaf = leaf_index;
            leaf_index += 1;
        }

        return .{
            .selected_leaf = selected_leaf,
            .layout = try buildSessionLayout(
                alloc,
                tab,
                scope,
                scrollback_lines,
                remaining_scrollback_budget,
            ),
        };
    }

    fn buildSessionLayout(
        alloc: Allocator,
        tab: *const Tab,
        scope: SnapshotScope,
        scrollback_lines: usize,
        remaining_scrollback_budget: *usize,
    ) !win32_session_state.LayoutTree {
        if (tab.tree.nodes.len > std.math.maxInt(u16)) return error.TooManySessionLayoutNodes;
        const nodes = try alloc.alloc(win32_session_state.Node, tab.tree.nodes.len);
        for (tab.tree.nodes, 0..) |node, i| {
            nodes[i] = switch (node) {
                // The two pane literals are deliberately separate. Anything
                // added to the session pane below (terminal contents, process
                // state) must stay out of user-visible layout files unless it
                // is also added to the layout literal on purpose. Neither
                // snapshot may persist an SSH launch for unattended restore.
                .leaf => |surface| switch (scope) {
                    .session => .{ .pane = .{
                        .cwd = sessionSnapshotPaneText(
                            "cwd",
                            if (surface.launched_ssh) null else surface.pwd,
                        ),
                        .profile = sessionSnapshotPaneText(
                            "profile",
                            if (surface.launched_ssh) null else surface.launch_profile_key,
                        ),
                        .title_override = sessionSnapshotPaneText(
                            "title_override",
                            surface.title_override,
                        ),
                        .tab_title_override = sessionSnapshotPaneText(
                            "tab_title_override",
                            if (surface.launched_ssh) null else surface.tab_title_override,
                        ),
                        .scrollback = surface.captureSessionScrollback(
                            alloc,
                            scrollback_lines,
                            remaining_scrollback_budget,
                        ) catch |err| snapshot: {
                            log.warn("win32 session save: pane snapshot omitted err={}", .{err});
                            break :snapshot null;
                        },
                    } },
                    .layout => .{ .pane = .{
                        .cwd = sessionSnapshotPaneText(
                            "cwd",
                            if (surface.launched_ssh) null else surface.pwd,
                        ),
                        .profile = sessionSnapshotPaneText(
                            "profile",
                            if (surface.launched_ssh) null else surface.launch_profile_key,
                        ),
                        .title_override = sessionSnapshotPaneText(
                            "title_override",
                            surface.title_override,
                        ),
                        .tab_title_override = sessionSnapshotPaneText(
                            "tab_title_override",
                            if (surface.launched_ssh) null else surface.tab_title_override,
                        ),
                    } },
                },
                .split => |split| .{ .split = .{
                    .axis = switch (split.layout) {
                        .horizontal => .horizontal,
                        .vertical => .vertical,
                    },
                    .ratio = @floatCast(split.ratio),
                    .first = @intFromEnum(split.left),
                    .second = @intFromEnum(split.right),
                } },
            };
        }
        return .{ .root = 0, .nodes = nodes };
    }

    /// Drop a single pane field that a hostile source (OSC 7 pwd, OSC 0/2
    /// title) made unsafe, rather than failing the whole save. The load path
    /// stays strict: `win32_session_state.validatePane` rejects the file.
    fn sessionSnapshotPaneText(field: []const u8, value: ?[]const u8) ?[]const u8 {
        const text = value orelse return null;
        // A working directory on a network share or device is never written:
        // spawn would replace it with the home folder anyway, and a file that
        // names one invites the next reader to touch it. This also drops one
        // restored from a session saved before such pwds were refused.
        if (std.mem.eql(u8, field, "cwd") and internal_os.path.isNetworkOrDevicePath(text)) {
            log.warn("win32 session save: dropping network or device cwd", .{});
            return null;
        }
        if (win32_session_state.isValidPaneText(text)) return text;
        log.warn("win32 session save: dropping unsafe pane field field={s} len={}", .{ field, text.len });
        return null;
    }

    /// The tabs of `host` a session or layout file records: none for the
    /// quick terminal, which is never restored.
    fn hostSessionTabs(host: *const Host) []const Tab {
        return if (host.quick_terminal) &.{} else host.tabs.items;
    }

    /// The node index of the first pane under `index`, following each
    /// split's first half. Null for an index or chain the layout does not
    /// hold, which validation rejects before a restore.
    fn firstSessionLayoutPane(layout: win32_session_state.LayoutTree, index: usize) ?usize {
        var current = index;
        var steps: usize = 0;
        while (current < layout.nodes.len and steps < layout.nodes.len) : (steps += 1) {
            switch (layout.nodes[current]) {
                .pane => return current,
                .split => |split| current = split.first,
            }
        }
        return null;
    }

    fn buildRestoredSessionSplitTree(
        alloc: Allocator,
        layout: win32_session_state.LayoutTree,
        node_surfaces: []const ?*Surface,
    ) (Allocator.Error || error{ InvalidTreeShape, TooManySessionLayoutNodes })!SplitTreeSurface {
        if (layout.nodes.len == 0 or layout.nodes.len != node_surfaces.len) {
            return error.InvalidTreeShape;
        }
        if (layout.root >= layout.nodes.len) return error.InvalidTreeShape;
        if (layout.nodes.len > std.math.maxInt(SplitTreeSurface.Node.Handle.Backing)) {
            return error.TooManySessionLayoutNodes;
        }

        const invalid_index = std.math.maxInt(usize);
        const remap = try alloc.alloc(usize, layout.nodes.len);
        defer alloc.free(remap);
        @memset(remap, invalid_index);

        if (layout.root == 0) {
            for (remap, 0..) |*slot, i| slot.* = i;
        } else {
            const stack = try alloc.alloc(usize, layout.nodes.len);
            defer alloc.free(stack);

            remap[layout.root] = 0;
            stack[0] = layout.root;
            var stack_len: usize = 1;
            var next_index: usize = 1;
            while (stack_len > 0) {
                stack_len -= 1;
                const saved_index = stack[stack_len];
                switch (layout.nodes[saved_index]) {
                    .pane => {},
                    .split => |split| {
                        const children = [_]u16{ split.first, split.second };
                        for (children) |child| {
                            const child_index: usize = child;
                            if (child_index >= layout.nodes.len) return error.InvalidTreeShape;
                            if (remap[child_index] == invalid_index) {
                                remap[child_index] = next_index;
                                next_index += 1;
                                stack[stack_len] = child_index;
                                stack_len += 1;
                            }
                        }
                    },
                }
            }
            if (next_index != layout.nodes.len) return error.InvalidTreeShape;
        }

        var arena = std.heap.ArenaAllocator.init(alloc);
        errdefer arena.deinit();
        const tree_nodes = try arena.allocator().alloc(SplitTreeSurface.Node, layout.nodes.len);

        for (layout.nodes, 0..) |node, saved_index| {
            const restored_index = remap[saved_index];
            if (restored_index == invalid_index) return error.InvalidTreeShape;
            tree_nodes[restored_index] = switch (node) {
                .pane => .{ .leaf = node_surfaces[saved_index] orelse return error.InvalidTreeShape },
                .split => |split| .{ .split = .{
                    .layout = switch (split.axis) {
                        .horizontal => .horizontal,
                        .vertical => .vertical,
                    },
                    .ratio = @floatCast(split.ratio),
                    .left = @enumFromInt(remap[split.first]),
                    .right = @enumFromInt(remap[split.second]),
                } },
            };
        }

        return .{
            .arena = arena,
            .nodes = tree_nodes,
            .zoomed = null,
        };
    }

    fn sessionStateWindowRect(window: win32_session_state.Window) !?RECT {
        const x = window.x orelse {
            if (window.y == null and window.width == null and window.height == null) return null;
            return error.InvalidWindowRect;
        };
        const y = window.y orelse return error.InvalidWindowRect;
        const width = window.width orelse return error.InvalidWindowRect;
        const height = window.height orelse return error.InvalidWindowRect;
        if (width <= 0 or height <= 0) return error.InvalidWindowRect;
        const right = std.math.add(i32, x, width) catch return error.InvalidWindowRect;
        const bottom = std.math.add(i32, y, height) catch return error.InvalidWindowRect;
        return .{
            .left = x,
            .top = y,
            .right = right,
            .bottom = bottom,
        };
    }

    const SessionWindowPlacement = struct {
        /// The window's normal rect in screen coordinates.
        rect: ?RECT,
        /// It is, or restores to, maximized.
        maximized: bool,
    };

    fn sessionWindowPlacement(host: *Host) ?SessionWindowPlacement {
        return sessionWindowPlacementOn(host, null);
    }

    /// `monitor` stands in for the window's monitor, so a test can give it
    /// the taskbar this machine lacks.
    fn sessionWindowPlacementOn(host: *Host, monitor: ?MONITORINFO) ?SessionWindowPlacement {
        const hwnd = host.hwnd orelse return null;
        var maximized = sys.IsZoomed(hwnd) != 0;
        var rect: RECT = undefined;
        if (maximized or sys.IsIconic(hwnd) != 0) {
            var placement: WINDOWPLACEMENT = std.mem.zeroes(WINDOWPLACEMENT);
            placement.length = @sizeOf(WINDOWPLACEMENT);
            if (sys.GetWindowPlacement(hwnd, &placement) != 0) {
                maximized = restoresMaximized(hwnd, &placement);
                // Workspace coordinates, offset from the screen's by a taskbar
                // on the top or left. Every other state saves screen
                // coordinates, and restore applies them as such.
                rect = placement.rcNormalPosition;
                if (monitor) |info| {
                    rect = workspaceRectToScreen(rect, info);
                } else if (sys.MonitorFromWindow(hwnd, c.MONITOR_DEFAULTTONEAREST)) |nearest| {
                    var info: MONITORINFO = std.mem.zeroes(MONITORINFO);
                    info.cbSize = @sizeOf(MONITORINFO);
                    if (sys.GetMonitorInfoW(nearest, &info) != 0) rect = workspaceRectToScreen(rect, info);
                }
            } else if (sys.GetWindowRect(hwnd, &rect) == 0) {
                return .{ .rect = null, .maximized = maximized };
            }
        } else if (sys.GetWindowRect(hwnd, &rect) == 0) {
            return .{ .rect = null, .maximized = maximized };
        }

        if (rect.right <= rect.left or rect.bottom <= rect.top) return .{ .rect = null, .maximized = maximized };
        return .{ .rect = rect, .maximized = maximized };
    }

    /// Push an action string onto the palette MRU list, dedup'd by
    /// exact match, rotating the oldest slot out. `action` is not owned
    /// by the caller; this dups it into the app allocator. Safe to call
    /// with an action that may be the same as an existing MRU entry —
    /// that entry is moved to the front without reallocating.
    fn pushPaletteMru(self: *App, action: []const u8) !void {
        // If action already exists, move it to slot 0.
        var existing_index: ?usize = null;
        for (self.palette_mru, 0..) |slot, i| {
            if (slot) |owned| {
                if (std.mem.eql(u8, owned, action)) {
                    existing_index = i;
                    break;
                }
            }
        }
        if (existing_index) |i| {
            if (i == 0) return;
            const top = self.palette_mru[i];
            var j: usize = i;
            while (j > 0) : (j -= 1) self.palette_mru[j] = self.palette_mru[j - 1];
            self.palette_mru[0] = top;
            return;
        }
        // Insert as new head. Free whatever falls off the end.
        const duped = try self.core_app.alloc.dupeZ(u8, action);
        errdefer self.core_app.alloc.free(duped);
        if (self.palette_mru[self.palette_mru.len - 1]) |oldest| {
            self.core_app.alloc.free(oldest);
        }
        var j: usize = self.palette_mru.len - 1;
        while (j > 0) : (j -= 1) self.palette_mru[j] = self.palette_mru[j - 1];
        self.palette_mru[0] = duped;
    }

    /// View of the MRU list as a slice of non-null entries, newest first.
    /// Shared storage; caller must not free or retain past the next
    /// `pushPaletteMru` call.
    fn paletteMruSlice(self: *const App, buf: *[5][]const u8) []const []const u8 {
        var n: usize = 0;
        for (self.palette_mru) |slot| {
            if (slot) |owned| {
                buf[n] = owned;
                n += 1;
            }
        }
        return buf[0..n];
    }

    fn unregisterGlobalHotkeys(self: *App) void {
        for (self.global_hotkeys.items) |hotkey| {
            _ = sys.UnregisterHotKey(null, hotkey.id);
        }
        self.global_hotkeys.clearRetainingCapacity();
    }

    fn syncGlobalHotkeys(self: *App) !void {
        self.unregisterGlobalHotkeys();

        var next_id: i32 = 1;
        var it = self.config.keybind.set.bindings.iterator();
        while (it.next()) |entry| {
            const generic = switch (entry.value_ptr.*) {
                .leader => continue,
                .leaf => |*leaf| leaf.generic(),
                .leaf_chained => |*leaf| leaf.generic(),
            };
            if (!generic.flags.global) continue;

            const spec = hotkeySpecForTrigger(entry.key_ptr.*) orelse {
                log.warn("skipping unsupported win32 global hotkey trigger={f}", .{entry.key_ptr.*});
                continue;
            };

            if (self.registeredGlobalHotkeyForSpec(spec)) |existing| {
                log.warn("skipping duplicate win32 global hotkey trigger={f} conflicts_with={f} mods=0x{x} vk=0x{x}", .{
                    entry.key_ptr.*,
                    existing.trigger,
                    spec.modifiers,
                    spec.vk,
                });
                continue;
            }

            if (sys.RegisterHotKey(null, next_id, spec.modifiers, spec.vk) == 0) {
                const err = windows.kernel32.GetLastError();
                log.warn("failed to register win32 global hotkey trigger={f} id={} mods=0x{x} vk=0x{x} err={} reason={s}", .{
                    entry.key_ptr.*,
                    next_id,
                    spec.modifiers,
                    spec.vk,
                    err,
                    hotkeyRegistrationFailureReason(err),
                });
                continue;
            }

            try self.global_hotkeys.append(self.core_app.alloc, .{
                .id = next_id,
                .trigger = entry.key_ptr.*,
                .spec = spec,
                .binding = entry.value_ptr,
            });
            next_id += 1;
        }
    }

    fn registeredGlobalHotkeyForSpec(self: *const App, spec: GlobalHotkeySpec) ?RegisteredGlobalHotkey {
        for (self.global_hotkeys.items) |hotkey| {
            if (hotkeySpecEql(hotkey.spec, spec)) return hotkey;
        }
        return null;
    }

    fn scheduleGlobalHotkeySync(self: *App) void {
        self.global_hotkeys_dirty = true;
        self.wakeup();
    }

    fn handleGlobalHotkey(self: *App, id: i32) void {
        for (self.global_hotkeys.items) |hotkey| {
            if (hotkey.id != id) continue;

            switch (hotkey.binding.*) {
                .leader => unreachable,
                .leaf => |*leaf| self.core_app.performAllChainedAction(self, leaf.generic().actionsSlice()),
                .leaf_chained => |*leaf| self.core_app.performAllChainedAction(self, leaf.generic().actionsSlice()),
            }
            return;
        }
    }

    pub fn wakeup(self: *App) void {
        if (@atomicLoad(DWORD, &self.ui_thread_id, .acquire) == 0) return;
        const delivery = self.delivery orelse return;
        _ = delivery.wake(c.WM_WINHOSTTY_WAKE);
    }

    fn automaticUpdateChecksEnabled(self: *const App) bool {
        return self.config.@"auto-update" != .off and
            self.config.@"auto-update-channel" == .stable and
            self.ui_thread_id != 0;
    }

    fn maybeScheduleAutomaticUpdateCheck(self: *App) void {
        if (self.update_auto_check_started) return;
        if (!self.automaticUpdateChecksEnabled()) return;

        self.update_auto_check_started = true;
        self.runAutomaticUpdateCheck();
        self.startUpdateRecheckTimer();
    }

    fn runAutomaticUpdateCheck(self: *App) void {
        self.scheduleUpdateCheck(.{
            .force = false,
            .manual = false,
            .respect_dismissal = true,
        }) catch |err| {
            log.warn("failed to start automatic update check err={}", .{err});
        };
    }

    /// A terminal that stays open for weeks would otherwise learn about a
    /// release only after a restart. The tick is cheap: the check's own
    /// 24 hour throttle answers from the saved state (no request, no
    /// download) until a day has passed, and a dismissed version stays
    /// dismissed because the check respects it. With no window open the tick
    /// does nothing, so an idle background process makes no request.
    fn startUpdateRecheckTimer(self: *App) void {
        if (self.update_recheck_timer_id != null) return;
        const timer_id = sys.SetTimer(null, 0, update_recheck_interval_ms, null);
        if (timer_id == 0) {
            log.warn("failed to start win32 update recheck timer err={}", .{windows.kernel32.GetLastError()});
            return;
        }
        self.update_recheck_timer_id = timer_id;
    }

    fn stopUpdateRecheckTimer(self: *App) void {
        if (self.update_recheck_timer_id) |timer_id| {
            _ = sys.KillTimer(null, timer_id);
            self.update_recheck_timer_id = null;
        }
    }

    /// Applying a staged update sets `running = false` first; nothing is left
    /// to tell about a release then. A staged notice that is already up is
    /// left alone: the check would only re-verify it (and for a portable ZIP
    /// re-extract it) while the user may be about to press Install.
    fn updateRecheckWanted(self: *const App) bool {
        if (self.update_notice) |notice| if (notice.staged) return false;
        return self.running and self.windows.items.len > 0 and self.automaticUpdateChecksEnabled();
    }

    test "the update recheck timer is armed once, stopped on request, and ticks only with a window" {
        if (builtin.os.tag != .windows) return error.SkipZigTest;

        var core_app: CoreApp = undefined;
        var app: App = undefined;
        var surface: Surface = undefined;
        var session: TestSession = .{};
        try session.init(.{
            .core_app = &core_app,
            .app = &app,
            .surfaces = &.{.{ .storage = &surface }},
        });
        defer session.deinit();

        app.startUpdateRecheckTimer();
        defer app.stopUpdateRecheckTimer();
        const timer_id = app.update_recheck_timer_id.?;
        app.startUpdateRecheckTimer();
        try std.testing.expectEqual(timer_id, app.update_recheck_timer_id.?);
        app.stopUpdateRecheckTimer();
        try std.testing.expectEqual(@as(?UINT_PTR, null), app.update_recheck_timer_id);

        // A tick asks for a check only while the app runs with a window and
        // automatic checks are on for the stable channel.
        app.config.@"auto-update" = .check;
        app.config.@"auto-update-channel" = .stable;
        app.ui_thread_id = 1;
        defer app.ui_thread_id = 0;
        app.running = true;
        try std.testing.expect(!app.updateRecheckWanted());
        try app.windows.append(std.testing.allocator, &surface);
        defer app.windows.clearAndFree(std.testing.allocator);
        try std.testing.expect(app.updateRecheckWanted());
        // A staged notice that is already up is left alone; an unstaged one
        // is not, since a newer release should replace it.
        app.update_notice = try UpdateNotice.init(std.testing.allocator, "1.3.200", "https://example.invalid/release", true);
        try std.testing.expect(!app.updateRecheckWanted());
        app.update_notice.?.staged = false;
        try std.testing.expect(app.updateRecheckWanted());
        app.update_notice.?.deinit(std.testing.allocator);
        app.update_notice = null;
        app.config.@"auto-update" = .off;
        try std.testing.expect(!app.updateRecheckWanted());
        app.config.@"auto-update" = .check;
        app.config.@"auto-update-channel" = .tip;
        try std.testing.expect(!app.updateRecheckWanted());
        app.config.@"auto-update-channel" = .stable;
        app.running = false;
        try std.testing.expect(!app.updateRecheckWanted());
    }

    fn onUpdateRecheckTimer(self: *App) void {
        if (self.updateRecheckWanted()) self.runAutomaticUpdateCheck();
    }

    fn installKind(self: *App) InstallKind {
        if (self.install_kind) |kind| return kind;
        const kind = InstallKind.detect(self.core_app.alloc);
        self.install_kind = kind;
        return kind;
    }

    /// What a check should download and stage, or null for a notice only:
    /// `auto-update = download` on a copy that can apply what it stages.
    fn updateStageKind(self: *App) ?updatepkg.portable_apply.StagedKind {
        if (self.config.@"auto-update" != .download) return null;
        return self.installKind().stagedKind();
    }

    test "a check stages only when auto-update is download and this copy can apply the result" {
        if (builtin.os.tag != .windows) return error.SkipZigTest;

        var core_app: CoreApp = undefined;
        var app: App = undefined;
        var session: TestSession = .{};
        try session.init(.{ .core_app = &core_app, .app = &app });
        defer session.deinit();

        const Staged = updatepkg.portable_apply.StagedKind;
        const cases = [_]struct { mode: configpkg.Config.AutoUpdate, kind: InstallKind, stages: ?Staged }{
            .{ .mode = .download, .kind = .installer, .stages = .installer },
            .{ .mode = .download, .kind = .portable, .stages = .portable },
            .{ .mode = .download, .kind = .other, .stages = null },
            .{ .mode = .check, .kind = .installer, .stages = null },
            .{ .mode = .off, .kind = .portable, .stages = null },
        };
        for (cases) |case| {
            app.config.@"auto-update" = case.mode;
            app.install_kind = case.kind;
            try std.testing.expectEqual(case.stages, app.updateStageKind());
        }
    }

    test "the first automatic check arms the recheck timer once" {
        if (builtin.os.tag != .windows) return error.SkipZigTest;

        var core_app: CoreApp = undefined;
        var app: App = undefined;
        var session: TestSession = .{};
        try session.init(.{ .core_app = &core_app, .app = &app });
        defer session.deinit();

        // The session has no delivery channel, so no check thread starts.
        app.config.@"auto-update" = .check;
        app.config.@"auto-update-channel" = .stable;
        app.ui_thread_id = 1;
        defer app.ui_thread_id = 0;
        defer app.stopUpdateRecheckTimer();
        app.maybeScheduleAutomaticUpdateCheck();
        try std.testing.expect(app.update_auto_check_started);
        const timer_id = app.update_recheck_timer_id.?;
        app.maybeScheduleAutomaticUpdateCheck();
        try std.testing.expectEqual(timer_id, app.update_recheck_timer_id.?);

        // Automatic checks off: no timer for a process that never checks.
        app.stopUpdateRecheckTimer();
        app.update_auto_check_started = false;
        app.config.@"auto-update" = .off;
        app.maybeScheduleAutomaticUpdateCheck();
        try std.testing.expect(!app.update_auto_check_started);
        try std.testing.expectEqual(@as(?UINT_PTR, null), app.update_recheck_timer_id);
    }

    fn scheduleUpdateCheck(
        self: *App,
        opts: struct {
            force: bool,
            manual: bool,
            respect_dismissal: bool,
        },
    ) !void {
        if (self.ui_thread_id == 0) return;

        const delivery = self.delivery orelse return;
        const current = delivery.update_running.cmpxchgStrong(false, true, .acq_rel, .acquire);
        if (current != null) {
            if (opts.manual) try self.showUpdateInfo(.info, "Update check already running.");
            return;
        }
        errdefer delivery.update_running.store(false, .release);

        const request = try std.heap.page_allocator.create(UpdateCheckRequest);
        errdefer std.heap.page_allocator.destroy(request);

        // The ignored-feed note has to come from the resolver, not from the
        // config value alone: NOCTTY_UPDATE_FEED_URL is also a feed source
        // and it is also dropped when it is not HTTPS.
        const resolved_feed = try updatepkg.resolveReleaseFeed(
            self.core_app.alloc,
            self.config.@"auto-update-feed-url",
        );
        const release_feed_url = resolved_feed.url;
        defer self.core_app.alloc.free(release_feed_url);
        // Only a copy that can apply a staged update gets one downloaded.
        // The notice for any other falls back to "Open Release".
        const stage_kind = self.updateStageKind();

        // The detached worker must not borrow the core allocator's lifetime.
        // Page allocator storage and a retained channel remain valid after UI exit.
        const state_path = try updatepkg.defaultStatePath(std.heap.page_allocator);
        errdefer std.heap.page_allocator.free(state_path);
        const current_version_string = try std.heap.page_allocator.dupe(u8, build_config.version_string);
        errdefer std.heap.page_allocator.free(current_version_string);
        const worker_feed = try std.heap.page_allocator.dupe(u8, release_feed_url);
        errdefer std.heap.page_allocator.free(worker_feed);

        request.* = .{
            .alloc = std.heap.page_allocator,
            .delivery = delivery,
            .state_path = state_path,
            .current_version = build_config.version,
            .current_version_string = current_version_string,
            .release_feed_url = worker_feed,
            .force = opts.force,
            .manual = opts.manual,
            .ignored_feed_source = resolved_feed.ignored_non_https,
            .respect_dismissal = opts.respect_dismissal,
            .download = stage_kind != null,
            .staged_kind = stage_kind orelse .installer,
        };

        delivery.retain();
        errdefer delivery.release();
        const thread = try std.Thread.spawn(.{}, updateCheckThreadMain, .{request});
        thread.detach();
    }

    /// Run the jump list's deferred startup profile discovery off the UI
    /// thread. Discovery starts `wsl.exe --status` and `wsl.exe -l -q` and
    /// waits for each (up to 1.5 s apiece), which held the UI thread about
    /// 90 ms half a second after start-up here. Like the update check, the
    /// worker is detached and borrows nothing from the App, so quitting never
    /// waits for it; its result arrives as WM_WINHOSTTY_PROFILES.
    fn startProfileDiscovery(self: *App) void {
        const delivery = self.delivery orelse return self.discoverStartupProfilesNow();
        const now_ms = sys.GetTickCount64();
        if (delivery.profiles_running.cmpxchgStrong(false, true, .acq_rel, .acquire) != null) {
            // Running, or its result is still queued. A worker can hang for
            // good: a shell spawned at the same moment can inherit the write
            // end of `wsl.exe -l -q`'s stdout pipe, and its drain then never
            // ends. Give up on it then; the generation keeps a late result
            // from doing harm.
            if (now_ms -| self.profile_discovery_started_ms < profile_discovery_abandon_ms) return;
            log.warn("profile discovery worker unfinished after {d} ms; starting another", .{profile_discovery_abandon_ms});
        }
        self.profile_discovery_started_ms = now_ms;
        self.profile_discovery_attempt +%= 1;
        delivery.retain();
        const thread = std.Thread.spawn(.{}, profileDiscoveryThreadMain, .{
            delivery,
            self.config.@"ssh-config-hosts",
            self.profiles_generation,
            self.profile_discovery_attempt,
        }) catch |err| {
            delivery.release();
            delivery.profiles_running.store(false, .release);
            log.warn("profile discovery thread unavailable; discovering on the UI thread err={}", .{err});
            return self.discoverStartupProfilesNow();
        };
        thread.detach();
        self.stopProfileDiscoveryWatchdog();
        const timer_id = sys.SetTimer(null, 0, @intCast(profile_discovery_abandon_ms + std.time.ms_per_s), null);
        if (timer_id != 0) self.profile_discovery_watchdog_id = timer_id;
    }

    fn stopProfileDiscoveryWatchdog(self: *App) void {
        if (self.profile_discovery_watchdog_id) |timer_id| {
            _ = sys.KillTimer(null, timer_id);
            self.profile_discovery_watchdog_id = null;
        }
    }

    fn applyPendingProfileDiscovery(self: *App) void {
        const pending = self.pending_profile_discovery orelse return;
        self.pending_profile_discovery = null;
        defer pending.deinit();
        if (pending.attempt == self.profile_discovery_attempt) {
            if (self.delivery) |delivery| delivery.profiles_running.store(false, .release);
            self.stopProfileDiscoveryWatchdog();
        }
        self.handleProfileDiscovery(pending);
    }

    /// A discovery's list goes to every host that asked for one (the
    /// picker, the palette) and, for the jump list, to the first host while
    /// its startup discovery is pending and that host has no complete list.
    fn handleProfileDiscovery(self: *App, completion: *const ProfileDiscoveryCompletion) void {
        // With no host, `scheduleIfStartupPending` re-arms when one appears.
        if (self.hosts.items.len == 0) return;
        const primary = self.hosts.items[0];
        const jump_list: ?*win32_jump_list.JumpList = if (self.jump_list) |*value|
            if (value.startupProfileDiscoveryPending()) value else null
        else
            null;
        defer if (jump_list) |list| {
            if (primary.profiles != null and primary.profiles_complete) {
                list.completeStartupProfileDiscovery();
            } else {
                list.retryStartupProfileDiscovery();
            }
        };
        const primary_wants = jump_list != null and !(primary.profiles != null and primary.profiles_complete);

        if (completion.generation != self.profiles_generation) {
            // A list was applied or dropped since this one started. The
            // jump list re-arms its timer; a host that asked starts over.
            if (self.anyHostRequestedProfiles()) self.startProfileDiscovery();
            return;
        }
        const discovery = completion.result catch |err| {
            log.warn("deferred profile discovery failed err={}", .{err});
            for (self.hosts.items) |host| {
                if (!host.profiles_requested) continue;
                host.profiles_requested = false;
                if (host != self.profiles_requesting_host) host.profilesArrived(host.profiles != null);
            }
            return;
        };
        for (self.hosts.items) |host| {
            if (!host.profiles_requested and !(host == primary and primary_wants)) continue;
            host.profiles_requested = false;
            const had_profiles = host.profiles != null;
            // An incomplete list (a probe timed out, the SSH config was
            // busy) does not replace a complete one.
            if (!discovery.complete and host.profiles_complete) {
                if (host != self.profiles_requesting_host) host.profilesArrived(had_profiles);
                continue;
            }
            const profiles = windows_shell.cloneProfiles(self.core_app.alloc, discovery.profiles) catch |err| {
                log.warn("deferred profile discovery failed err={}", .{err});
                continue;
            };
            _ = host.applyProfileDiscovery(.{ .profiles = profiles, .complete = discovery.complete }) catch |err| {
                log.warn("deferred profile discovery failed err={}", .{err});
            };
            if (host != self.profiles_requesting_host) host.profilesArrived(had_profiles);
        }
    }

    fn anyHostRequestedProfiles(self: *const App) bool {
        for (self.hosts.items) |host| {
            if (host.profiles_requested) return true;
        }
        return false;
    }

    /// The synchronous path, for when no thread can run it.
    fn discoverStartupProfilesNow(self: *App) void {
        var completion: ProfileDiscoveryCompletion = .{
            .arena = .init(self.core_app.alloc),
            .generation = self.profiles_generation,
        };
        defer completion.deinit();
        completion.result = windows_shell.discoverProfiles(completion.arena.allocator(), self.config.@"ssh-config-hosts");
        self.handleProfileDiscovery(&completion);
    }

    fn handleUpdateCheckCompletion(self: *App, completion: *UpdateCheckCompletion) void {
        if (self.delivery) |delivery| delivery.update_running.store(false, .release);

        // The old notice offers Install (staged installer from the old feed)
        // or Open Release (release URL from the old feed). Once the check
        // discarded that feed's state, neither action is still valid, so drop
        // the notice before anything below can raise a replacement.
        if (completion.clear_stale_notice) self.clearUpdateNotice();

        if (completion.release) |release| {
            self.setUpdateNotice(release.version_text, release.release_url, completion.staged) catch |err| {
                log.warn("failed to surface update notice err={}", .{err});
            };
            if (completion.manual_message) |message| {
                self.showUpdateInfo(.info, message) catch |err| {
                    log.warn("failed to show updater status message err={}", .{err});
                };
            }
            return;
        }

        if (completion.manual_message) |message| {
            self.showUpdateInfo(.info, message) catch |err| {
                log.warn("failed to show updater status message err={}", .{err});
            };
        }
    }

    fn setUpdateNotice(self: *App, version_text: []const u8, release_url: []const u8, staged: bool) !void {
        if (self.update_notice) |*notice| {
            if (ownedBytesEquals(notice.version_text, version_text) and
                ownedBytesEquals(notice.release_url, release_url) and
                notice.staged == staged)
            {
                return;
            }
            notice.deinit(self.core_app.alloc);
            self.update_notice = null;
        }

        self.update_notice = try UpdateNotice.init(self.core_app.alloc, version_text, release_url, staged);
        // Announce it once: in the window the user is in, else the first.
        const foreground = sys.GetForegroundWindow();
        var announcer: ?*Host = if (self.hosts.items.len > 0) self.hosts.items[0] else null;
        for (self.hosts.items) |host| {
            if (host.hwnd != null and host.hwnd == foreground) announcer = host;
        }
        for (self.hosts.items) |host| host.updateNoticeChanged(host == announcer);
    }

    fn clearUpdateNotice(self: *App) void {
        if (self.update_notice) |*notice| {
            notice.deinit(self.core_app.alloc);
            self.update_notice = null;
            for (self.hosts.items) |host| host.updateNoticeChanged(false);
        }
    }

    fn openUpdateNotice(self: *App) !void {
        const notice = self.update_notice orelse return;
        if (notice.staged) {
            if (!self.canApplyStagedUpdate()) {
                if (isPortableModeActive(self.core_app.alloc)) {
                    try self.showUpdateInfo(.err, updateApplyFailureMessage(error.NoStagedPortableInstall));
                    return;
                }
                if (notice.release_url) |url| {
                    try self.openUrl(url);
                    return;
                }
            }
            try self.requestApplyStagedUpdate();
            return;
        }
        try self.openUrl(notice.release_url.?);
    }

    /// A staged notice is recorded too, or it would come back at every launch.
    /// Only the dismissal is written: the staged install stays on disk, so a
    /// manual check can offer it again without downloading.
    fn dismissUpdateNotice(self: *App) void {
        if (self.update_notice == null) return;
        const state_path = updatepkg.defaultStatePath(self.core_app.alloc) catch |err| {
            log.warn("failed to resolve updater state path err={}", .{err});
            self.clearUpdateNotice();
            return;
        };
        defer self.core_app.alloc.free(state_path);
        self.dismissUpdateNoticeAt(state_path);
    }

    fn dismissUpdateNoticeAt(self: *App, state_path: []const u8) void {
        const notice = self.update_notice orelse return;
        if (notice.version_text) |version_text| {
            updatepkg.recordDismissal(self.core_app.alloc, state_path, version_text) catch |err| {
                log.warn("failed to record updater dismissal err={}", .{err});
            };
        }
        self.clearUpdateNotice();
    }

    test "dismissing a staged update notice records the dismissal and keeps the staged install" {
        if (builtin.os.tag != .windows) return error.SkipZigTest;

        var core_app: CoreApp = undefined;
        var app: App = undefined;
        var session: TestSession = .{};
        try session.init(.{ .core_app = &core_app, .app = &app });
        defer session.deinit();

        const alloc = std.testing.allocator;
        var tmp = std.testing.tmpDir(.{});
        defer tmp.cleanup();
        const root = try tmp.dir.realpathAlloc(alloc, ".");
        defer alloc.free(root);
        const state_path = try std.fs.path.join(alloc, &.{ root, "update-state.json" });
        defer alloc.free(state_path);
        var staged: updatepkg.State = .{
            .staged_version = try alloc.dupe(u8, "1.3.200"),
            .staged_kind = .installer,
            .staged_installer_path = try alloc.dupe(u8, "setup.exe"),
            .staged_sha256 = try alloc.dupe(u8, "00"),
        };
        defer staged.deinit(alloc);
        try updatepkg.saveState(state_path, &staged);

        for ([_]bool{ true, false }) |is_staged| {
            app.update_notice = try UpdateNotice.init(alloc, "1.3.200", "https://example.invalid/release", is_staged);
            app.dismissUpdateNoticeAt(state_path);
            try std.testing.expectEqual(@as(?UpdateNotice, null), app.update_notice);

            var after = try updatepkg.loadState(alloc, state_path);
            defer after.deinit(alloc);
            try std.testing.expectEqualStrings("1.3.200", after.dismissed_version.?);
            try std.testing.expectEqualStrings("1.3.200", after.staged_version.?);
            try updatepkg.clearDismissal(alloc, state_path);
        }
    }

    fn applyStagedUpdate(self: *App) !void {
        if (self.update_apply_in_flight) return;
        self.update_apply_in_flight = true;
        errdefer self.update_apply_in_flight = false;
        const state_path = try updatepkg.defaultStatePath(self.core_app.alloc);
        defer self.core_app.alloc.free(state_path);

        // Re-resolve the feed rather than trusting the staged metadata: a
        // staged installer only stays applicable while the feed that
        // produced it is still the effective one.
        const release_feed_url = try updatepkg.resolveReleaseFeedUrl(
            self.core_app.alloc,
            self.config.@"auto-update-feed-url",
        );
        defer self.core_app.alloc.free(release_feed_url);

        const expected_kind: updatepkg.portable_apply.StagedKind =
            if (isPortableModeActive(self.core_app.alloc)) .portable else .installer;

        var staged = updatepkg.verifyStagedWindowsInstall(
            self.core_app.alloc,
            state_path,
            release_feed_url,
            expected_kind,
        ) catch |err| {
            self.showUpdateInfo(.err, updateApplyFailureMessage(err)) catch |banner_err| {
                log.warn("failed to show updater apply failure err={}", .{banner_err});
            };
            return err;
        };
        defer staged.deinit(self.core_app.alloc);

        const install_dir = currentInstallDir(self.core_app.alloc) catch |err| {
            self.showUpdateInfo(.err, updateApplyFailureMessage(err)) catch |banner_err| {
                log.warn("failed to show updater apply failure err={}", .{banner_err});
            };
            return err;
        };
        defer self.core_app.alloc.free(install_dir);

        if (staged.kind == .portable) {
            updatepkg.recordPortableApplyPending(self.core_app.alloc, state_path, 0) catch |err| {
                self.showUpdateInfo(.err, updateApplyFailureMessage(err)) catch |banner_err| {
                    log.warn("failed to show updater apply failure err={}", .{banner_err});
                };
                return err;
            };
            self.stopQuitTimer();
            self.running = false;
            self.destroyAllWindows();
            if (self.windows.items.len == 0) sys.PostQuitMessage(0);
            return;
        }

        if (!internal_os.windows.isInstallerManagedInstallDir(install_dir)) {
            self.showUpdateInfo(.err, updateApplyFailureMessage(error.InvalidInstallPath)) catch |banner_err| {
                log.warn("failed to show updater apply failure err={}", .{banner_err});
            };
            return error.InvalidInstallPath;
        }

        const stage_dir = std.fs.path.dirname(staged.artifact_path) orelse return error.InvalidStagedInstallerPath;
        const log_path = try updatepkg.applyLogPathAlloc(self.core_app.alloc, staged.artifact_path);
        defer self.core_app.alloc.free(log_path);
        try std.fs.cwd().makePath(std.fs.path.dirname(log_path).?);

        const params = try buildInstallerApplyArgs(self.core_app.alloc, install_dir, log_path);
        defer self.core_app.alloc.free(params);

        const installer_w = try std.unicode.utf8ToUtf16LeAllocZ(self.core_app.alloc, staged.artifact_path);
        defer self.core_app.alloc.free(installer_w);
        const params_w = try std.unicode.utf8ToUtf16LeAllocZ(self.core_app.alloc, params);
        defer self.core_app.alloc.free(params_w);
        const stage_dir_w = try std.unicode.utf8ToUtf16LeAllocZ(self.core_app.alloc, stage_dir);
        defer self.core_app.alloc.free(stage_dir_w);

        // Only App-owned state follows this call; the click handler returns without touching Host.
        const result = sys.ShellExecuteW(
            null,
            shell_runas,
            installer_w.ptr,
            params_w.ptr,
            stage_dir_w.ptr,
            c.SW_SHOW,
        );
        if (@intFromPtr(result) <= 32) {
            self.showUpdateInfo(.err, updateApplyFailureMessage(error.UpdateApplyLaunchFailed)) catch |banner_err| {
                log.warn("failed to show updater apply failure err={}", .{banner_err});
            };
            return error.UpdateApplyLaunchFailed;
        }

        updatepkg.recordStagedApplyRequested(self.core_app.alloc, state_path, 0) catch |err| {
            log.warn("failed to record updater apply request after launch err={}", .{err});
        };

        self.stopQuitTimer();
        self.running = false;
        self.destroyAllWindows();
        if (self.windows.items.len == 0) sys.PostQuitMessage(0);
    }

    /// Install quits the app and nothing watches Setup, so the next start is
    /// where a setup that did not replace this build is found. Only a
    /// setup-managed copy can have started one: the update state is shared by
    /// every copy of the user's, and an older Scoop or dev build starting after
    /// a successful install must not report (and consume) the request. Needs
    /// a window for the banner; without one the request stays for the next
    /// start.
    fn reportFailedInstallerApply(self: *App) void {
        if (self.installer_apply_checked) return;
        self.installer_apply_checked = true;
        if (self.installKind() != .installer) return;
        const state_path = updatepkg.defaultStatePath(self.core_app.alloc) catch return;
        defer self.core_app.alloc.free(state_path);
        const message = updatepkg.takeFailedInstallerApply(
            self.core_app.alloc,
            state_path,
            build_config.version,
        ) catch |err| {
            log.warn("failed to check the last installer apply err={}", .{err});
            return;
        } orelse return;
        defer self.core_app.alloc.free(message);
        log.warn("{s}", .{message});
        self.showUpdateInfo(.err, message) catch |err| {
            log.warn("failed to surface installer apply failure err={}", .{err});
        };
    }

    fn canApplyStagedUpdate(self: *App) bool {
        const state_path = updatepkg.defaultStatePath(self.core_app.alloc) catch return false;
        defer self.core_app.alloc.free(state_path);
        if (isPortableModeActive(self.core_app.alloc)) {
            return updatepkg.hasStagedWindowsInstall(self.core_app.alloc, state_path, .portable);
        }
        const install_dir = currentInstallDir(self.core_app.alloc) catch return false;
        defer self.core_app.alloc.free(install_dir);
        return internal_os.windows.isInstallerManagedInstallDir(install_dir) and
            updatepkg.hasStagedWindowsInstall(self.core_app.alloc, state_path, .installer);
    }

    /// Updater feedback in the banner. A failure is `.err`, so it stays
    /// until dismissed instead of counting down like an `.info` message.
    fn showUpdateInfo(self: *App, kind: HostBannerKind, message: []const u8) !void {
        // The window whose button was pressed, else the primary one. A host
        // with no tab (its last one detached for undo) still shows a banner.
        // Opening the release can pump messages, so check that the pressing
        // window is still open before using it.
        const pressed_in: ?*Host = if (self.update_action_host) |pressed| for (self.hosts.items) |live| {
            if (live == pressed) break pressed;
        } else null else null;
        const host: ?*Host = pressed_in orelse blk: {
            if (self.primarySurface()) |surface| if (surface.host) |value| break :blk value;
            break :blk if (self.hosts.items.len > 0) self.hosts.items[0] else null;
        };
        if (host) |value| return value.setBanner(kind, message);
        try showInfoMessage(.app, "noctty", message);
    }

    test "showUpdateInfo answers in the window whose banner button was pressed" {
        if (builtin.os.tag != .windows) return error.SkipZigTest;

        var core_app: CoreApp = undefined;
        var app: App = undefined;
        var first: Host = undefined;
        var second: Host = undefined;
        var session: TestSession = .{};
        try session.init(.{
            .core_app = &core_app,
            .app = &app,
            .hosts = &.{
                .{ .storage = &first, .id = 1, .register = true },
                .{ .storage = &second, .id = 2, .register = true },
            },
        });
        defer session.deinit();

        app.update_action_host = &second;
        try app.showUpdateInfo(.err, "Install failed.");
        try std.testing.expectEqual(@as(?[:0]const u8, null), first.banner_text);
        try std.testing.expectEqualStrings("Install failed.", second.banner_text.?);

        // A pressing window that has since closed is not used.
        _ = app.hosts.swapRemove(1);
        try app.showUpdateInfo(.err, "Still failed.");
        try std.testing.expectEqualStrings("Still failed.", first.banner_text.?);

        // With no pressed window and no surface to find the primary window
        // by, the first window answers rather than only the log.
        app.update_action_host = null;
        try app.showUpdateInfo(.info, "Up to date.");
        try std.testing.expectEqualStrings("Up to date.", first.banner_text.?);
    }

    fn showRecoverySafeModeNotice(_: *App, text: [:0]const u16) void {
        var thread = std.Thread.spawn(.{}, recoverySafeModeNoticeThread, .{text.ptr}) catch |err| {
            log.warn("win32 recovery: safe-mode notice thread failed err={}", .{err});
            return;
        };
        thread.detach();
    }

    /// True when any user-facing top-level UI window is still alive —
    /// either a terminal Host or the settings window. The quit timer
    /// and message-loop exit check both use this so the app doesn't
    /// tear down while the settings window holds an unsaved pending
    /// draft. Palette / confirm overlays are owned by their Host and
    /// therefore don't need their own count.
    fn hasLiveUiWindows(self: *const App) bool {
        if (self.windows.items.len != 0) return true;
        if (self.settings_window.hwnd != null) return true;
        return false;
    }

    pub fn startQuitTimer(self: *App) void {
        if (!self.running) return;
        if (self.hasLiveUiWindows()) {
            self.stopQuitTimer();
            return;
        }
        if (!self.config.@"quit-after-last-window-closed") {
            self.stopQuitTimer();
            return;
        }

        const delay = self.config.@"quit-after-last-window-closed-delay" orelse {
            self.stopQuitTimer();
            self.running = false;
            sys.PostQuitMessage(0);
            return;
        };

        self.stopQuitTimer();
        const delay_ms = quitTimerDelayMs(delay);
        const timer_id = sys.SetTimer(null, 0, delay_ms, null);
        if (timer_id == 0) {
            log.err("failed to start win32 quit timer delay_ms={} err={}", .{
                delay_ms,
                windows.kernel32.GetLastError(),
            });
            return;
        }
        self.quit_timer_id = timer_id;
    }

    fn stopQuitTimer(self: *App) void {
        if (self.quit_timer_id) |timer_id| {
            _ = sys.KillTimer(null, timer_id);
            self.quit_timer_id = null;
        }
    }

    fn startTerminalHandoffIdleTimer(self: *App) void {
        self.stopTerminalHandoffIdleTimer();
        const timer_id = sys.SetTimer(null, 0, 5000, null);
        if (timer_id == 0) {
            log.err("failed to start terminal handoff idle timer err={}", .{windows.kernel32.GetLastError()});
            return;
        }
        self.terminal_handoff_idle_timer_id = timer_id;
    }

    fn stopTerminalHandoffIdleTimer(self: *App) void {
        if (self.terminal_handoff_idle_timer_id) |timer_id| {
            _ = sys.KillTimer(null, timer_id);
            self.terminal_handoff_idle_timer_id = null;
        }
    }

    /// Decide whether the embedding-mode server may exit, and close the race
    /// against an in-flight activation while deciding.
    ///
    /// Returning true means the class object has been revoked and no client
    /// can still be mid-activation, so the caller may quit. Returning false
    /// means a client holds the class object or a handoff is already queued;
    /// the class object is left registered (or re-registered) and the caller
    /// must keep running.
    fn exitEmbeddingServerIfIdle(self: *App) bool {
        const server = self.terminal_handoff_server orelse return true;

        // A client between CoGetClassObject and CreateInstance holds a
        // LockServer reference, and a client that created an ITerminalHandoff3
        // without locking still owns a live object. Exiting under either one
        // would fail its activation.
        if (server.isBusy()) return false;

        // Revoke first, then re-check. After the revoke no new activation can
        // arrive, so anything observed now is everything that can exist.
        if (!server.revoke()) return false;
        if (!server.isBusy()) return true;

        // Something landed in the gap between the check and the revoke. Take
        // the class object back and keep serving.
        server.register() catch |err| {
            log.err("failed to re-register terminal handoff class object err={}", .{err});
        };
        return false;
    }

    /// Schedule the next ready-marker attempt.
    ///
    /// `GetMessageW` blocks, so an idle app generates no further ticks and the
    /// retry budget would never be spent — an `initial-window = false` launch
    /// in particular can reach its quit timer without another tick at all,
    /// leaving the attempt unresolved on disk and the safe-mode notice
    /// unreleased. The timer both guarantees the attempt and spaces it out;
    /// a bare wake would busy-retry and could not outlast a handle hold.
    ///
    /// Bounded by `RecoveryReadyRetry`: only a failure that has not exhausted
    /// the budget reaches here, so at most
    /// `recovery_ready_persist_attempts - 1` timers are ever armed.
    /// Returns false when no retry could be armed. There is deliberately no
    /// wake fallback: a wake re-ticks immediately, so the remaining attempts
    /// would run back to back and the delay that lets a handle hold clear
    /// would be gone exactly when `SetTimer` failing says the session is
    /// already degraded. The caller stops instead.
    fn scheduleRecoveryRetry(self: *App) bool {
        self.stopRecoveryRetryTimer();
        const timer_id = sys.SetTimer(null, 0, recovery_ready_retry_delay_ms, null);
        if (timer_id == 0) {
            log.warn("failed to start win32 recovery retry timer err={}", .{windows.kernel32.GetLastError()});
            return false;
        }
        self.recovery_retry_timer_id = timer_id;
        self.recovery_retry_not_before_ms = sys.GetTickCount64() +| recovery_ready_retry_delay_ms;
        return true;
    }

    fn stopRecoveryRetryTimer(self: *App) void {
        if (self.recovery_retry_timer_id) |timer_id| {
            _ = sys.KillTimer(null, timer_id);
            self.recovery_retry_timer_id = null;
        }
    }

    /// The retry timer fired: this is the tick the deadline was holding out
    /// for, so clear it rather than re-checking the clock. `SetTimer` may
    /// deliver marginally early, and refusing its own tick would leave nothing
    /// armed to come back.
    fn onRecoveryRetryTimer(self: *App) void {
        self.stopRecoveryRetryTimer();
        self.recovery_retry_not_before_ms = null;
        self.resolveRecoveryStartup();
    }

    fn stopUndoPruneTimer(self: *App) void {
        if (self.undo_prune_timer_id) |timer_id| {
            _ = sys.KillTimer(null, timer_id);
            self.undo_prune_timer_id = null;
        }
    }

    fn undoTimeoutMs(self: *const App) u64 {
        return std.math.divCeil(
            u64,
            self.config.@"undo-timeout".duration,
            std.time.ns_per_ms,
        ) catch std.math.maxInt(u64);
    }

    /// `undo-timeout = 0`: the prune timer takes every entry the moment it
    /// fires, so nothing can be restored. Only exactly 0 counts; a nonzero
    /// timeout leaves a window, however short.
    fn undoOff(self: *const App) bool {
        return self.undoTimeoutMs() == 0;
    }

    fn nextUndoSequence(self: *App) u64 {
        const sequence = self.next_undo_sequence;
        self.next_undo_sequence +%= 1;
        if (self.next_undo_sequence == 0) self.next_undo_sequence = 1;
        return sequence;
    }

    fn oldestUndoTimestamp(self: *const App) ?u64 {
        var oldest: ?u64 = null;
        for (self.windows.items) |surface| {
            if (surface.undo_stack.oldestTimestamp()) |timestamp| {
                if (oldest == null or timestamp < oldest.?) oldest = timestamp;
            }
        }
        for (self.hosts.items) |host| {
            if (host.oldestStructuralTimestamp()) |timestamp| {
                if (oldest == null or timestamp < oldest.?) oldest = timestamp;
            }
        }
        return oldest;
    }

    fn scheduleUndoPruneTimer(self: *App) void {
        self.scheduleUndoPruneTimerWithMinimum(1);
    }

    fn scheduleUndoPruneTimerWithMinimum(self: *App, minimum_delay_ms: u64) void {
        if (!self.running) return;
        self.stopUndoPruneTimer();

        const oldest = self.oldestUndoTimestamp() orelse return;
        const now = sys.GetTickCount64();
        const expires_at = oldest +| self.undoTimeoutMs() +| 1;
        const delay_ms = @max(minimum_delay_ms, if (expires_at <= now) 1 else expires_at - now);
        const timer_id = sys.SetTimer(
            null,
            0,
            @intCast(@min(delay_ms, std.math.maxInt(UINT))),
            null,
        );
        if (timer_id == 0) {
            log.warn("failed to start win32 undo prune timer err={}", .{
                windows.kernel32.GetLastError(),
            });
            return;
        }
        self.undo_prune_timer_id = timer_id;
    }

    fn pruneUndoHistoryBefore(self: *App, min_timestamp_ms: u64) bool {
        var complete = true;
        for (self.windows.items) |surface| {
            surface.undo_stack.discardExpired(min_timestamp_ms);
        }

        var i: usize = 0;
        while (i < self.hosts.items.len) {
            const host = self.hosts.items[i];
            if (!host.pruneStructuralHistoryBefore(min_timestamp_ms)) complete = false;
            if (host.destroy_after_structural_dispose and host.tabs.items.len == 0 and !host.hasStructuralHistory()) {
                if (host.hwnd) |hwnd| {
                    _ = sys.DestroyWindow(hwnd);
                    self.removeHost(host);
                    continue;
                }
                host.destroy_after_structural_dispose = false;
            }
            if (i < self.hosts.items.len and self.hosts.items[i] == host) {
                i += 1;
            }
        }
        return complete;
    }

    fn pruneUndoHistoryNow(self: *App) void {
        const complete = self.pruneUndoHistoryBefore(self.undoCutoffTimestampMs());
        if (complete)
            self.scheduleUndoPruneTimer()
        else
            self.scheduleUndoPruneTimerWithMinimum(1000);
        if (self.running and !self.hasLiveUiWindows()) self.startQuitTimer();
    }

    fn ensureMessageQueue() void {
        var msg: MSG = undefined;
        _ = sys.PeekMessageW(&msg, null, 0, 0, c.PM_NOREMOVE);
    }

    pub fn performAction(
        self: *App,
        target: apprt.Target,
        comptime action: apprt.Action.Key,
        value: apprt.Action.Value(action),
    ) !bool {
        switch (action) {
            .quit => {
                self.postQuit(target);
                return true;
            },

            .new_window => {
                var forwarded_arguments = value.arguments;
                switch (scanForwardedToastActivation(value.arguments)) {
                    .none => {},
                    .malformed => {
                        std.log.warn("dropping malformed forwarded toast activation argv", .{});
                        return true;
                    },
                    .activation => |activation| {
                        const dropped_args = forwardedActivationExtraArgCount(value.arguments);
                        if (dropped_args > 0) {
                            std.log.warn("dropping {d} forwarded argv item(s) bundled with toast activation", .{dropped_args});
                        }
                        if (self.handleToastActivation(activation)) return true;
                        self.pending_toast_activation = activation;
                        forwarded_arguments = null;
                    },
                }
                var config = try apprt.surface.newConfig(
                    self.core_app,
                    &self.config,
                    .window,
                );
                defer config.deinit();
                // The forwarded argv reaches us over the single-instance IPC
                // pipe, so it is only as trusted as any process running as
                // this user. Refuse the whole request unless every key is on
                // the presentation allowlist.
                if (forwarded_arguments) |argv| {
                    if (forwardedArgvRejection(argv)) |rejection| {
                        logForwardedArgvRejection(rejection);
                        return true;
                    }
                }
                applyNewWindowArguments(
                    self.core_app.alloc,
                    &config,
                    forwarded_arguments,
                ) catch |err| switch (err) {
                    // Defense in depth: `applyNewWindowArguments` enforces
                    // the same filter independently. Treat a rejection as
                    // handled so it cannot abort the app tick. Logged here
                    // too so the rejection can never become silent if the
                    // pre-check above is ever refactored away.
                    error.ForbiddenForwardedArgument => {
                        log.err(
                            "refusing forwarded new-window argv: rejected by applyNewWindowArguments",
                            .{},
                        );
                        return true;
                    },
                    else => return err,
                };
                if (config.@"launch-layout") |name| {
                    const banner_host = if (self.findSurfaceForTarget(target)) |source| source.host else null;
                    _ = self.launchNamedLayout(name, banner_host);
                    return true;
                }
                const source = self.newWindowSource(target);
                _ = self.createWindowSurface(&config, default_title, .{
                    .clone_state_from = source,
                }) catch |err| {
                    // A request forwarded by another process was acknowledged
                    // when it was queued, so say here that nothing opened.
                    // The first host still shows a banner while its last tab
                    // is detached for undo, when it has no surface.
                    const banner_host: ?*Host = if (source) |surface|
                        surface.host
                    else if (self.hosts.items.len > 0) self.hosts.items[0] else null;
                    if (banner_host) |host| host.setBanner(.err, "New window could not be opened.") catch {};
                    return err;
                };
                return true;
            },

            .launch_layout => {
                const banner_host = if (self.findSurfaceForTarget(target)) |source| source.host else null;
                return layoutActionResult(self.launchNamedLayout(value.name, banner_host));
            },

            .save_layout => {
                return layoutActionResult(self.saveNamedLayout(target, value.name));
            },

            .new_window_elevated => {
                const alloc = self.core_app.alloc;
                const source = self.findSurfaceForTarget(target);

                const cwd = cwd: {
                    if (source) |surface| {
                        if (surface.core().pwd(alloc) catch null) |live_pwd| {
                            if (live_pwd.len > 0) break :cwd live_pwd;
                            alloc.free(live_pwd);
                        }
                        if (surface.pwd) |cached_pwd| {
                            if (cached_pwd.len > 0) break :cwd try alloc.dupe(u8, cached_pwd);
                        }
                    }
                    if (self.startup_cwd) |startup_cwd| {
                        if (startup_cwd.len > 0) break :cwd try alloc.dupe(u8, startup_cwd);
                    }
                    break :cwd try std.process.getCwdAlloc(alloc);
                };
                defer alloc.free(cwd);

                var command: ?configpkg.Command = null;
                var temporary_profiles: ?[]windows_shell.Profile = null;
                defer if (temporary_profiles) |profiles| {
                    windows_shell.deinitProfiles(alloc, profiles);
                };
                const profile_key: ?[]const u8 = if (value.profile_key.len > 0)
                    value.profile_key
                else if (source) |surface|
                    surface.launch_profile_key
                else
                    null;
                if (profile_key) |key| {
                    const source_host: ?*Host = if (source) |surface|
                        surface.host
                    else
                        null;
                    const profile: ?*const windows_shell.Profile = if (source_host) |host|
                        try host.profileForKey(key)
                    else profile: {
                        const profiles = try windows_shell.listProfiles(
                            alloc,
                            self.config.@"ssh-config-hosts",
                        );
                        temporary_profiles = profiles;
                        const index = profileIndexByKey(profiles, key) orelse break :profile null;
                        break :profile &profiles[index];
                    };
                    command = (profile orelse {
                        log.warn("elevated window profile not found key={s}", .{key});
                        return false;
                    }).command;
                }

                const process_argv = try std.process.argsAlloc(alloc);
                defer std.process.argsFree(alloc, process_argv);
                const argv = try alloc.alloc([]const u8, process_argv.len);
                defer alloc.free(argv);
                for (process_argv, 0..) |arg, i| argv[i] = arg;

                const parameters = try win32_elevation.buildRelaunchParameters(
                    alloc,
                    argv,
                    self.config.class,
                    cwd,
                    self.startup_cwd orelse cwd,
                    command,
                );
                errdefer alloc.free(parameters);

                // The terminal keeps its pwd in --working-directory; the
                // elevated host must not search that directory for programs.
                const host_cwd = try win32_elevation.elevatedHostDirectory(alloc);
                errdefer alloc.free(host_cwd);

                try self.deferShellRequest(.{ .elevated_window = .{
                    .parameters = parameters,
                    .cwd = host_cwd,
                } });
                return true;
            },

            .new_tab => {
                const source = self.findSurfaceForTarget(target);
                _ = try self.createNewTab(source, null, false, false);
                return true;
            },

            .new_split => {
                const source = self.findSurfaceForTarget(target) orelse return false;
                _ = try self.createNewSplit(source, splitDirectionFromAction(value), null, false);
                return true;
            },

            .close_tab => {
                return try self.closeTab(target, value);
            },

            .close_all_windows => {
                // Closing every window quits, as `quit` does.
                self.postQuit(target);
                return true;
            },

            .close_window => {
                if (self.findSurfaceForTarget(target)) |surface| {
                    if (surface.host) |host| host.close();
                    return true;
                }

                return false;
            },

            .config_change => {
                switch (target) {
                    .app => {
                        var config = try value.config.clone(self.core_app.alloc);
                        const ssh_config_hosts_changed =
                            self.config.@"ssh-config-hosts" != config.@"ssh-config-hosts";
                        // Warn on the transition, not on every reload: the
                        // Settings checkbox and an edited config file both
                        // arrive here, and that is the only notice a user who
                        // turns blur on after startup would ever get.
                        const background_blur_newly_requested =
                            config.@"background-blur".win32BlurRequested() and
                            !self.config.@"background-blur".win32BlurRequested();
                        // CLI launch-layout is a one-shot startup/new-window
                        // request. Config reload reparses the original argv, so
                        // strip it before installing the long-lived app config
                        // -- both the parsed field and the replay step, since
                        // a later theme or conditional-state reload would
                        // otherwise put it back.
                        config.@"launch-layout" = null;
                        _ = config.dropLaunchLayoutReplaySteps(0);
                        // Palette theme preview owns a reversible baseline
                        // around the app-global config. An external/settings
                        // config change supersedes that transaction: dismiss
                        // the palette first so it reverts and resets every
                        // borrowed catalog before the incoming config replaces
                        // the baseline. A later Escape can never resurrect the
                        // stale pre-reload config.
                        for (self.hosts.items) |host| {
                            if (host.overlay_mode == .command_palette) host.hideOverlay();
                        }
                        self.unregisterGlobalHotkeys();
                        self.config.deinit();
                        self.config = config;
                        if (background_blur_newly_requested) logBackgroundBlurUnsupported();
                        self.config_revision +%= 1;
                        if (self.config_revision == 0) self.config_revision = 1;
                        // Also with no Host open: a discovery still running
                        // used the old setting.
                        if (ssh_config_hosts_changed) self.profiles_generation +%= 1;
                        const jump_list_profiles_pending = ssh_config_hosts_changed and self.jump_list != null;
                        if (jump_list_profiles_pending) self.jump_list.?.updateProfiles(&.{});
                        // Drop every list before asking for a new one: each drop
                        // bumps the generation, which would make a discovery
                        // started in between stale.
                        if (ssh_config_hosts_changed) {
                            for (self.hosts.items) |host| host.invalidateProfiles();
                        }
                        for (self.hosts.items) |host| {
                            if (ssh_config_hosts_changed and host.overlay_mode == .profile) {
                                host.requestProfiles();
                                host.refreshProfileChrome();
                            }
                            if (host.overlay_mode == .command_palette) host.rebuildPaletteList();
                        }
                        if (jump_list_profiles_pending) {
                            self.jump_list.?.requestProfileDiscovery();
                        }
                        self.scheduleGlobalHotkeySync();
                        self.reconfigureTheme();
                        for (self.windows.items) |surface| {
                            try surface.applyRuntimeConfig(&self.config);
                        }
                        // A reload that turns automatic checks on in a process
                        // that started with them off (or on another channel).
                        if (self.windows.items.len > 0 and self.update_startup_ready) self.maybeScheduleAutomaticUpdateCheck();
                        self.settings_window.externalConfigChanged(&self.config, self.config_revision);
                        self.refreshConfigProblems();
                        if (self.windows.items.len == 0) {
                            self.startQuitTimer();
                        } else {
                            self.stopQuitTimer();
                        }
                    },
                    .surface => |core_surface| {
                        const surface = self.findSurfaceByCore(core_surface) orelse return false;
                        try surface.applyRuntimeConfig(value.config);
                        try self.syncHostWindowState(surface);
                    },
                }
                return true;
            },

            .reload_config => {
                // Recovery keeps its default config and cmd /D until restart.
                // In particular, a hard reload must not run default discovery
                // or load the startup files that safe mode bypassed.
                if (self.safe_mode) return true;
                if (value.soft) {
                    switch (target) {
                        .app => try self.core_app.updateConfig(self, &self.config),
                        .surface => |core_surface| try core_surface.updateConfig(&self.config),
                    }
                    return true;
                }

                if (target != .app) return false;

                // Same startup-cwd restoration dance as
                // `settingsSaveAndReload`: `Config.load` calls
                // `loadCliArgs`, which realpaths `--config-file
                // <relative>` against current cwd. After
                // `sanitizeCurrentDirectory()` ran, relative overrides
                // would resolve to a different file than launch used,
                // silently swapping the config source on every manual
                // reload. Scoped to this path — non-reload code keeps
                // seeing the sanitized cwd.
                const cwd_before: ?[]u8 = std.process.getCwdAlloc(self.core_app.alloc) catch null;
                defer if (cwd_before) |p| self.core_app.alloc.free(p);

                // `defer` + flag so the restore fires even when
                // `Config.load` returns an error — otherwise a
                // broken include leaves the process pinned to
                // `startup_cwd` (same class of bug as the one
                // fixed in `settingsSaveAndReload`). Relative-path
                // lookups + child processes spawned after a failed
                // reload would inherit the wrong cwd.
                var did_chdir_to_startup: bool = false;
                if (self.startup_cwd) |cwd| {
                    if (std.process.changeCurDir(cwd)) |_| {
                        did_chdir_to_startup = true;
                    } else |err| {
                        std.log.warn("reload_config: couldn't restore startup cwd path={s} err={}", .{ cwd, err });
                    }
                }
                defer {
                    if (did_chdir_to_startup) {
                        if (cwd_before) |cwd| {
                            std.process.changeCurDir(cwd) catch |err| {
                                std.log.warn("reload_config: couldn't restore sanitized cwd path={s} err={}", .{ cwd, err });
                            };
                        }
                    }
                }

                var config = try configpkg.Config.load(self.core_app.alloc);
                defer config.deinit();
                try self.core_app.updateConfig(self, &config);
                // A reload that found problems says so, whatever
                // `app-notifications` allows: "reloaded" would be false.
                // The config in effect, not the one just read: the app
                // applies its conditional state (dark system, `theme =
                // light:A,dark:B`) before it installs it.
                // config_change already recorded this load, including its
                // font checks; explicitly re-announce without scanning twice.
                if (self.reportRecordedConfigProblems()) return true;
                if (self.config.@"app-notifications".@"config-reload") {
                    try self.showDesktopNotification(.app, "noctty", "Configuration reloaded");
                }
                return true;
            },

            .present_terminal, .color_change, .mouse_over_link => {
                if (action == .present_terminal) {
                    if (self.findSurfaceForTarget(target)) |surface| {
                        surface.present();
                        return true;
                    }
                    return false;
                }
                return true;
            },

            .renderer_health => {
                const surface = self.findSurfaceForTarget(target) orelse return false;
                return surface.handleRendererHealth(value);
            },

            .quit_timer => {
                if (target != .app) return false;
                switch (value) {
                    .start => self.startQuitTimer(),
                    .stop => self.stopQuitTimer(),
                }
                return true;
            },

            .toggle_visibility => {
                self.windows_hidden = !self.windows_hidden;
                if (self.windows_hidden) {
                    for (self.hosts.items) |host| host.hideForToggle();
                } else {
                    for (self.hosts.items) |host| try host.showAfterToggle();
                    // Focus goes to a window that is on screen: a quick
                    // terminal dismissed before the hide stays dismissed.
                    if (self.shownSurfaceForTarget(target)) |surface| self.activateSurface(surface);
                }
                return true;
            },

            .toggle_background_opacity => {
                if (self.findSurfaceForTarget(target)) |surface| {
                    const changed = try surface.toggleBackgroundOpacity();
                    if (!changed) return false;
                    try self.syncHostWindowState(surface);
                    return true;
                }
                return false;
            },

            .goto_window => {
                return try self.gotoWindow(target, value);
            },

            .goto_split => {
                return try self.gotoSplitFallback(target, value);
            },

            .resize_split => {
                return try self.resizeSplitFallback(target, value);
            },

            .equalize_splits => {
                return try self.equalizeSplitsFallback(target);
            },

            .move_tab => {
                return try self.moveTab(target, value);
            },

            .goto_tab => {
                return try self.gotoTab(target, value);
            },

            .toggle_tab_overview => {
                if (self.findSurfaceForTarget(target)) |surface| {
                    return try surface.toggleTabOverview();
                }
                return false;
            },

            .cycle_focus_region => {
                const surface = self.findSurfaceForTarget(target) orelse return false;
                const host = surface.host orelse return false;
                return host.cycleFocusRegionFromCurrentFocus(switch (value) {
                    .previous => .previous,
                    .next => .next,
                });
            },

            .toggle_quick_terminal => {
                try self.toggleQuickTerminal();
                return true;
            },

            .toggle_maximize => {
                if (self.findSurfaceForTarget(target)) |surface| {
                    surface.toggleMaximize();
                    try self.syncHostWindowState(surface);
                    return true;
                }
                return false;
            },

            .toggle_fullscreen => {
                if (self.findSurfaceForTarget(target)) |surface| {
                    try surface.toggleFullscreen(value);
                    try self.syncHostWindowState(surface);
                    return true;
                }
                return false;
            },

            .toggle_window_decorations => {
                if (self.findSurfaceForTarget(target)) |surface| {
                    try surface.toggleDecorations();
                    try self.syncHostWindowState(surface);
                    return true;
                }
                return false;
            },

            .float_window => {
                if (self.findSurfaceForTarget(target)) |surface| {
                    try surface.setFloatWindow(value);
                    try self.syncHostWindowState(surface);
                    return true;
                }
                return false;
            },

            .initial_size => {
                if (self.findSurfaceForTarget(target)) |surface| {
                    try surface.setInitialSize(value);
                    try self.syncHostWindowState(surface);
                    return true;
                }
                return false;
            },

            .reset_window_size => {
                if (self.findSurfaceForTarget(target)) |surface| {
                    try surface.resetWindowSize();
                    try self.syncHostWindowState(surface);
                    return true;
                }
                return false;
            },

            .size_limit => {
                if (self.findSurfaceForTarget(target)) |surface| {
                    surface.setSizeLimit(value);
                    try self.syncHostWindowState(surface);
                    return true;
                }
                return false;
            },

            .cell_size => {
                if (self.findSurfaceForTarget(target)) |surface| {
                    surface.setCellSize(value);
                    try self.syncHostWindowState(surface);
                    return true;
                }
                return false;
            },

            .toggle_split_zoom => {
                if (self.findSurfaceForTarget(target)) |surface| {
                    const found = self.findTabForSurface(surface) orelse return false;
                    const handle = found.tab.findHandle(surface) orelse found.tab.focused;
                    found.tab.tree.zoom(if (found.tab.tree.zoomed != null) null else handle);
                    surface.invalidateRedoForUnsupportedTabStructuralAction();
                    try found.host.layout();
                    return true;
                }
                return false;
            },

            .render => {
                return switch (target) {
                    .app => blk: {
                        for (self.windows.items) |surface| {
                            try surface.requestRepaintWithMode(self.rendererRepaintModeThisTick(surface.host));
                            surface.drainTerminalAccessibilityOutput();
                            if (surface.terminal_accessibility) |session| session.rendererUpdated();
                        }
                        break :blk true;
                    },
                    .surface => if (self.findSurfaceForTarget(target)) |surface| blk: {
                        try surface.requestRepaintWithMode(self.rendererRepaintModeThisTick(surface.host));
                        surface.drainTerminalAccessibilityOutput();
                        if (surface.terminal_accessibility) |session| session.rendererUpdated();
                        break :blk true;
                    } else false,
                };
            },

            .render_inspector => {
                if (self.findSurfaceForTarget(target)) |surface| {
                    surface.redrawInspector();
                    return true;
                }

                return false;
            },

            .inspector => {
                if (self.findSurfaceForTarget(target)) |surface| {
                    return try self.setInspectorActionForSurface(surface, value);
                }
                return false;
            },

            .show_gtk_inspector => {
                if (self.findSurfaceForTarget(target)) |surface| {
                    return try self.setInspectorActionForSurface(surface, .show);
                }
                return false;
            },

            .set_title => {
                if (self.findSurfaceForTarget(target)) |surface| {
                    try surface.setTitle(value.title);
                    return true;
                }

                return false;
            },

            .set_tab_title => {
                if (self.findSurfaceForTarget(target)) |surface| {
                    try surface.setTabTitleOverride(if (value.title.len == 0) null else value.title);
                    return true;
                }

                return false;
            },

            .prompt_title => {
                if (self.findSurfaceForTarget(target)) |surface| {
                    try surface.promptTitle(value);
                    return true;
                }

                return false;
            },

            .toggle_command_palette => {
                if (self.findSurfaceForTarget(target)) |surface| {
                    return try surface.toggleCommandPalette();
                }
                return false;
            },

            .toggle_quick_select => {
                if (self.findSurfaceForTarget(target)) |surface| {
                    return try surface.toggleQuickSelect();
                }
                return false;
            },

            .pwd => {
                if (self.findSurfaceForTarget(target)) |surface| {
                    try surface.setPwd(value.pwd);
                    if (self.jump_list) |*jump_list| jump_list.noteRecent(value.pwd);
                    return true;
                }

                return false;
            },

            .mouse_shape => {
                if (self.findSurfaceForTarget(target)) |surface| {
                    surface.setMouseShape(value);
                    return true;
                }
                return false;
            },

            .mouse_visibility => {
                if (self.findSurfaceForTarget(target)) |surface| {
                    surface.setMouseVisibility(value);
                    return true;
                }
                return false;
            },

            .progress_report => {
                if (self.findSurfaceForTarget(target)) |surface| {
                    try surface.setProgressReport(value);
                    return true;
                }
                return false;
            },

            .program_status => {
                if (self.findSurfaceForTarget(target)) |surface| {
                    try self.applyProgramStatus(surface, value);
                    return true;
                }
                return false;
            },

            .goto_attention => return try self.gotoAttention(target),

            .command_finished => {
                try self.showCommandFinished(target, value);
                return true;
            },

            .start_search => {
                if (self.findSurfaceForTarget(target)) |surface| {
                    try surface.showSearchOverlay(value.needle);
                    return true;
                }
                return false;
            },

            .end_search => {
                if (self.findSurfaceForTarget(target)) |surface| {
                    try surface.closeDockedSearchBar(false, false);
                    return true;
                }
                return false;
            },

            .search_total => {
                if (self.findSurfaceForTarget(target)) |surface| {
                    try surface.setSearchTotal(value.total, value.invalid);
                    return true;
                }
                return false;
            },

            .search_selected => {
                if (self.findSurfaceForTarget(target)) |surface| {
                    try surface.setSearchSelected(value.selected);
                    return true;
                }
                return false;
            },

            .search_match_rows => {
                if (self.findSurfaceForTarget(target)) |surface| {
                    try surface.setSearchMatchRows(value.rows);
                    return true;
                }
                return false;
            },

            .secure_input => {
                if (self.findSurfaceForTarget(target)) |surface| {
                    try surface.setSecureInput(value);
                    return true;
                }
                return false;
            },

            // The core enforces read-only input. There is no separate chrome
            // indicator now that the dormant status bar has been removed.
            .readonly => return self.findSurfaceForTarget(target) != null,

            .key_sequence => {
                if (self.findSurfaceForTarget(target)) |surface| {
                    try surface.setKeySequenceActive(switch (value) {
                        .trigger => true,
                        .end => false,
                    });
                    return true;
                }
                return false;
            },

            .key_table => {
                if (self.findSurfaceForTarget(target)) |surface| {
                    try surface.setKeyTable(value);
                    return true;
                }
                return false;
            },

            .scrollbar => {
                if (self.findSurfaceForTarget(target)) |surface| {
                    try surface.setScrollbar(value);
                    return true;
                }
                return false;
            },

            .undo => {
                self.pruneUndoHistoryNow();
                const surface = self.undoRedoSurfaceForTarget(target) orelse {
                    const host = self.structuralUndoHostForTarget(target) orelse return false;
                    while (host.peekStructuralUndo() != null) {
                        const message = try host.applyLatestStructuralUndo() orelse continue;
                        try host.setBanner(.info, message);
                        return true;
                    }
                    try host.setBanner(.info, "Nothing to undo.");
                    return true;
                };

                while (true) {
                    const host_entry = if (surface.host) |host| host.peekStructuralUndo() else null;
                    const local_entry = surface.undo_stack.peekUndo();

                    if (host_entry == null and local_entry == null) break;
                    const use_host = host_entry != null and
                        (local_entry == null or win32_structural_history.sortsAfter(
                            host_entry.?.timestamp_ms,
                            host_entry.?.sequence_id,
                            local_entry.?.timestamp_ms,
                            local_entry.?.sequence_id,
                        ));

                    if (use_host) {
                        const host = surface.host orelse break;
                        const message = try host.applyLatestStructuralUndo() orelse continue;
                        _ = try self.showHostBanner(.{ .surface = surface.core() }, .info, message);
                        return true;
                    }

                    const message = try surface.applyLatestLocalUndo() orelse continue;
                    _ = try self.showHostBanner(.{ .surface = surface.core() }, .info, message);
                    return true;
                }

                // A key press on the pane and the palette both target the
                // surface. The default binding is performable, so report that
                // nothing was undone and the chord goes on to the program in
                // the pane (the palette says so itself, see invokePaletteRow).
                // An app-level request gets the banner.
                if (target == .surface) return false;
                _ = try self.showHostBanner(.{ .surface = surface.core() }, .info, "Nothing to undo.");
                return true;
            },

            .redo => {
                self.pruneUndoHistoryNow();
                const surface = self.undoRedoSurfaceForTarget(target) orelse {
                    const host = self.structuralRedoHostForTarget(target) orelse return false;
                    while (host.peekStructuralRedo() != null) {
                        const message = try host.applyLatestStructuralRedo() orelse continue;
                        try host.setBanner(.info, message);
                        return true;
                    }
                    try host.setBanner(.info, "Nothing to redo.");
                    return true;
                };

                while (true) {
                    const host_entry = if (surface.host) |host| host.peekStructuralRedo() else null;
                    const local_entry = surface.undo_stack.peekRedo();

                    if (host_entry == null and local_entry == null) break;
                    const use_host = host_entry != null and
                        (local_entry == null or win32_structural_history.sortsAfter(
                            host_entry.?.timestamp_ms,
                            host_entry.?.sequence_id,
                            local_entry.?.timestamp_ms,
                            local_entry.?.sequence_id,
                        ));

                    if (use_host) {
                        const host = surface.host orelse break;
                        const message = try host.applyLatestStructuralRedo() orelse continue;
                        _ = try self.showHostBanner(.{ .surface = surface.core() }, .info, message);
                        return true;
                    }

                    const message = try surface.applyLatestLocalRedo() orelse continue;
                    _ = try self.showHostBanner(.{ .surface = surface.core() }, .info, message);
                    return true;
                }

                // See undo: a surface-targeted request with nothing to redo
                // is not performed, so a performable binding lets the key through.
                if (target == .surface) return false;
                _ = try self.showHostBanner(.{ .surface = surface.core() }, .info, "Nothing to redo.");
                return true;
            },

            .check_for_updates => {
                if (self.config.@"auto-update-channel" != .stable) {
                    _ = try self.showHostBanner(target, .info, "Automatic prerelease update checks are not supported yet. Opening releases.");
                    try self.openUrl(releases_url);
                    return true;
                }

                try self.scheduleUpdateCheck(.{
                    .force = true,
                    .manual = true,
                    .respect_dismissal = false,
                });
                return true;
            },

            .open_url => {
                self.openUrl(value.url) catch |err| {
                    // A click that does nothing reads as a broken terminal.
                    if (err == error.OpenUrlRejected) {
                        _ = self.showHostBanner(target, .info, labels.open_refused_banner) catch false;
                    }
                    return err;
                };
                return true;
            },

            .show_on_screen_keyboard => {
                try self.showOnScreenKeyboard();
                return true;
            },

            .open_config => {
                try self.openConfig();
                return true;
            },

            .copy_title_to_clipboard => {
                if (self.findSurfaceForTarget(target)) |surface| {
                    const title = surface.getTitle() orelse return false;
                    try surface.writeClipboardText(title);
                    return true;
                }
                return false;
            },

            .ring_bell => {
                self.ringBell(target);
                return true;
            },

            .desktop_notification => {
                try self.showDesktopNotification(target, value.title, value.body);
                return true;
            },

            .show_child_exited => {
                try self.showChildExited(target, value);
                return true;
            },
        }
    }

    pub fn performIpc(
        alloc: Allocator,
        target: apprt.ipc.Target,
        comptime action: apprt.ipc.Action.Key,
        value: apprt.ipc.Action.Value(action),
        response_timeout_ms: u64,
    ) !bool {
        switch (action) {
            .new_window => {
                const launch_layout = scanLaunchLayoutIpcArgument(value.arguments) catch |err| {
                    log.err("--launch-layout must be the only +new-window argument", .{});
                    return err;
                };

                const elevated = try win32_elevation.isProcessElevated();
                const pipe_name = try resolveIpcPipeNameForTarget(
                    alloc,
                    target,
                    elevated,
                );
                defer alloc.free(pipe_name);
                const forwarded = switch (launch_layout) {
                    .none => try sendNewWindowIpc(alloc, pipe_name, elevated, value.arguments, response_timeout_ms),
                    .name => |name| try sendLaunchLayoutIpc(alloc, pipe_name, elevated, name, response_timeout_ms),
                };
                if (forwarded) return true;
                return try spawnWindowProcess(alloc, target, value);
            },
        }
    }

    pub fn queryAutomationWindowList(
        alloc: Allocator,
        target: apprt.ipc.Target,
        response_timeout_ms: u64,
    ) !?[]u8 {
        const elevated = try win32_elevation.isProcessElevated();
        const pipe_name = try resolveIpcPipeNameForTarget(alloc, target, elevated);
        defer alloc.free(pipe_name);
        return try sendListWindowsIpc(alloc, pipe_name, elevated, response_timeout_ms);
    }

    pub fn performAutomationAction(
        alloc: Allocator,
