fn settingsNotifySuccessThunk(ctx: *anyopaque, title: []const u8, body: []const u8) void {
    const app: *App = @ptrCast(@alignCast(ctx));
    const saved_title = if (app.safe_mode) "Settings saved; restart noctty to apply them" else title;
    // Always show local chrome feedback for the Save button, even
    // when system/reload notifications are disabled.
    const alloc = app.core_app.alloc;
    // Problems the save's reload found are an error that stays until
    // dismissed. An info banner would replace it and then expire, and so
    // would the banner a refused system toast falls back to, so neither is
    // raised: the Settings status line already says the save went through.
    if (app.config_problems.count() > 0 and app.showConfigProblemsBanner()) return;
    const banner_text = std.fmt.allocPrint(alloc, "{s}{s}{s}", .{
        saved_title,
        if (body.len > 0) ": " else "",
        body,
    }) catch null;
    const banner_shown: bool = if (banner_text) |msg| blk: {
        defer alloc.free(msg);
        // `showHostBanner(.app, …)` routes through `primarySurface()`
        // and returns false when no terminal host is open (e.g.
        // settings window is the only UI window after the last tab
        // closed). Capture that so we know to fall back to the
        // always-visible in-settings confirm strip below.
        break :blk app.showHostBanner(.app, .info, msg) catch false;
    } else false;

    // System-level WinRT toast + local fallback. Gated on
    // `app-notifications.config-reload` because Settings save also
    // reloads config; users who disabled reload notifications should
    // not get a system toast on every Save. If no host banner can
    // render, force the fallback so settings-only saves still show
    // visible confirmation.
    if (!app.config.@"app-notifications".@"config-reload" and banner_shown) return;

    // WinRT notification strings must be sentinel-terminated. On
    // allocation failure, keep any banner already shown and skip the
    // system path.
    const title_z = alloc.dupeZ(u8, saved_title) catch return;
    defer alloc.free(title_z);
    const body_z = alloc.dupeZ(u8, body) catch return;
    defer alloc.free(body_z);
    app.showDesktopNotification(.app, title_z, body_z) catch |err| {
        std.log.warn("settings: desktop notification failed err={}", .{err});
    };
}

fn buildToastLaunchForSurface(
    alloc: Allocator,
    surface: *Surface,
) Allocator.Error![]u8 {
    const tab_id = if (surface.host) |host| blk: {
        for (host.tabs.items) |*tab| {
            if (tab.findHandle(surface) != null) break :blk tab.id;
        }
        break :blk null;
    } else null;

    return try win32_toast_activation.buildLaunchArg(alloc, .{
        .surface_id = surface.core().id,
        .tab_id = tab_id,
        .window_id = surface.host_id,
        .action = .focus,
    });
}

/// The active tab's index once tab `removed` is gone and `remaining` tabs
/// are left: the same tab when another one closed; when the active tab
/// itself closed, the tab now at its place, or the last one. The shell
/// model's `closeTab` and `detachTab` choose the same way.
fn activeTabAfterRemoval(active: usize, removed: usize, remaining: usize) usize {
    if (remaining == 0) return 0;
    if (removed < active) return @min(active - 1, remaining - 1);
    return @min(active, remaining - 1);
}

test "win32 closing a tab keeps the active tab active" {
    // [A, B, C] with B active.
    try std.testing.expectEqual(@as(usize, 0), activeTabAfterRemoval(1, 0, 2)); // A closes: B
    try std.testing.expectEqual(@as(usize, 1), activeTabAfterRemoval(1, 2, 2)); // C closes: B
    try std.testing.expectEqual(@as(usize, 1), activeTabAfterRemoval(1, 1, 2)); // B closes: C
    try std.testing.expectEqual(@as(usize, 1), activeTabAfterRemoval(2, 2, 2)); // last closes: new last
    try std.testing.expectEqual(@as(usize, 0), activeTabAfterRemoval(0, 0, 0));
}

/// Whether the user can see tab `index` of `host` right now: it is the
/// window's active tab, and the window is the foreground window and not
/// minimized.
fn tabSeenByUser(host: *const Host, index: usize) bool {
    return tabSeenWithForeground(host, index, sys.GetForegroundWindow());
}

fn tabSeenWithForeground(host: *const Host, index: usize, foreground: ?HWND) bool {
    if (index != host.active_tab) return false;
    const hwnd = host.hwnd orelse return false;
    return foreground == hwnd and sys.IsIconic(hwnd) == 0;
}

test "win32 only a close in the window in front takes focus" {
    if (builtin.os.tag != .windows) return error.SkipZigTest;
    var host: Host = undefined;
    host.active_tab = 1;
    host.hwnd = null;
    try std.testing.expect(!tabSeenWithForeground(&host, 1, null));
    const hwnd = try createTestHostWindow();
    defer _ = sys.DestroyWindow(hwnd);
    host.hwnd = hwnd;
    try std.testing.expect(tabSeenWithForeground(&host, 1, hwnd));
    // A background tab, or a window that is not in front.
    try std.testing.expect(!tabSeenWithForeground(&host, 0, hwnd));
    try std.testing.expect(!tabSeenWithForeground(&host, 1, null));
    // A minimized window, even one Windows still calls the foreground
    // (the style bit is what IsIconic reads; the window is never shown).
    _ = sys.SetWindowLongPtrW(hwnd, c.GWL_STYLE, @bitCast(@as(usize, c.WS_POPUP | c.WS_MINIMIZE)));
    try std.testing.expect(!tabSeenWithForeground(&host, 1, hwnd));
}

const TabProgramStatus = struct {
    surface: *Surface,
    record: *const win32_program_status.Record,
};

/// The program status record a tab shows: the most urgent headline among
/// its surfaces, the first one in the split tree on a tie.
fn tabStatusHeadline(tab: *const Tab) ?TabProgramStatus {
    var best: ?TabProgramStatus = null;
    var it = tab.tree.iterator();
    while (it.next()) |entry| {
        const record = entry.view.program_status.headline() orelse continue;
        if (best) |current| {
            const rank = win32_program_status.Indicator.of(record).rank();
            if (rank <= win32_program_status.Indicator.of(current.record).rank()) continue;
        }
        best = .{ .surface = entry.view, .record = record };
    }
    return best;
}

/// An even status key cannot collide with a program status's odd hash.
const tab_bell_status_key: u64 = 2;

/// What a screen reader is told about a tab's status, as a hash that
/// progress alone doesn't change; never 0, which stands for no status.
fn tabStatusKey(status: TabProgramStatus) u64 {
    var hasher = std.hash.Wyhash.init(0);
    win32_program_status.hashAnnounced(&hasher, &status.surface.program_status, status.record);
    return hasher.final() | 1;
}

/// Accept callback for the `confirm-close-surface` overlay. Fires
/// from the Host's overlay machinery once the user picks Accept /
/// presses Enter. `userdata` is the `*Surface` pointer passed into
/// `showConfirm`. The Surface's HWND may already be gone (defensive
/// null-check) — if so this is a no-op.
fn surfaceConfirmCloseAccept(userdata: ?*anyopaque) void {
    const ud = userdata orelse return;
    const surface: *Surface = @ptrCast(@alignCast(ud));
    _ = surface.requestClose();
}

/// Close for the window-close prompt. `userdata` is the Host that shows
/// the prompt, so it is alive whenever the prompt can be answered.
fn hostCloseConfirmAccept(userdata: ?*anyopaque) void {
    const host: *Host = @ptrCast(@alignCast(userdata orelse return));
    host.closeConfirmed();
}

/// Quit for the quit prompt. `userdata` is the App, which outlives every
/// window the quit destroys, including the one showing the prompt.
fn appQuitConfirmAccept(userdata: ?*anyopaque) void {
    const app: *App = @ptrCast(@alignCast(userdata orelse return));
    // Settings may have gained unsaved edits while this prompt waited.
    if (app.settings_window.holdQuitForUnsavedChanges()) return;
    app.quitConfirmed();
}

/// Install for the update prompt. `userdata` is the App, which outlives every
/// window the install destroys, including the one showing the prompt. This
/// runs inside the overlay's handlers, so it only queues the install: the
/// message loop applies it once this has returned, and checks for unsaved
/// Settings edits then.
fn updateApplyConfirmAccept(userdata: ?*anyopaque) void {
    const app: *App = @ptrCast(@alignCast(userdata orelse return));
    app.queueApplyStagedUpdate() catch |err| {
        log.warn("failed to queue the staged update apply after confirm err={}", .{err});
    };
}

/// Close tabs for the other-tabs prompt. `userdata` is the Surface the
/// tabs are kept beside: its destruction cancels the prompt
/// (`cancelConfirmIfOwnedBy`), and the tabs are found again here because
/// they may have changed while the prompt was open.
fn closeOtherTabsConfirmAccept(userdata: ?*anyopaque) void {
    const surface: *Surface = @ptrCast(@alignCast(userdata orelse return));
    _ = surface.app.closeTabsBeside(surface, .other) catch |err| {
        log.warn("close other tabs after confirm failed err={}", .{err});
    };
}

/// Close the tab for the undo-is-off prompt. `userdata` is the Surface the
/// close was asked on: its destruction cancels the prompt
/// (`cancelConfirmIfOwnedBy`), and its tab is found again here because it
/// may have moved while the prompt was open.
fn closeThisTabConfirmAccept(userdata: ?*anyopaque) void {
    const surface: *Surface = @ptrCast(@alignCast(userdata orelse return));
    const app = surface.app;
    const found = app.findTabForSurface(surface) orelse return;
    _ = app.closeTabUndoable(found.host, found.index) catch |err| {
        log.warn("close tab after confirm failed err={}", .{err});
    };
}

/// Close tabs for the tabs-to-the-right prompt; see `closeOtherTabsConfirmAccept`.
fn closeRightTabsConfirmAccept(userdata: ?*anyopaque) void {
    const surface: *Surface = @ptrCast(@alignCast(userdata orelse return));
    _ = surface.app.closeTabsBeside(surface, .right) catch |err| {
        log.warn("close tabs to the right after confirm failed err={}", .{err});
    };
}

/// Accept callback for a deferred paste confirm. Ownership of the
/// duplicated payload passes here and is released after synchronous
/// core ingestion.
fn surfaceConfirmPasteAccept(userdata: ?*anyopaque) void {
    const ud = userdata orelse return;
    const surface: *Surface = @ptrCast(@alignCast(ud));
    const op = surface.pending_clipboard_op orelse return;
    if (op != .paste) return;
    const pending = op.paste;
    // Snapshot the allocator by value BEFORE dispatching. If
    // `completeClipboardRequest` synchronously destroys the surface
    // (for example via close_surface), `surface.app` at defer
    // time is a dangling read. `std.mem.Allocator` is a pod value
    // (vtable + ctx ptr); the ctx is owned by the app arena which
    // outlives the surface, so the snapshot stays valid.
    const alloc = surface.app.core_app.alloc;
    surface.pending_clipboard_op = null;
    defer alloc.free(pending.data);
    surface.core_surface.completeClipboardRequest(
        pending.request,
        pending.data,
        true, // confirmed
    ) catch |err| {
        std.log.warn("pending clipboard paste accept failed err={}", .{err});
    };
}

fn surfaceConfirmPasteCancel(userdata: ?*anyopaque, reason: ConfirmCancelReason) void {
    const ud = userdata orelse return;
    const surface: *Surface = @ptrCast(@alignCast(ud));
    var op = surface.pending_clipboard_op orelse return;
    const alloc = surface.app.core_app.alloc;
    surface.pending_clipboard_op = null;
    defer op.deinit(alloc);
    if (reason != .explicit or op != .paste or
        op.paste.request != .osc_52_read or !surface.core_initialized or
        surface.core_surface.config.clipboard_read == .deny) return;

    // Finish this read without revealing clipboard contents. Reuse the
    // OSC 52 serializer so the reply echoes the requested selection.
    surface.core_surface.completeClipboardRequest(op.paste.request, "", true) catch |err| {
        log.warn("pending clipboard read cancel reply failed err={}", .{err});
    };
}

/// Accept callback for a deferred clipboard-write confirm. Mirrors
/// the body of `Surface.setClipboard` (html-first, then plain text)
/// because the confirm-write path only fires from the standard
/// clipboard — OSC 52 writes use a different code path.
fn surfaceConfirmWriteAccept(userdata: ?*anyopaque) void {
    const ud = userdata orelse return;
    const surface: *Surface = @ptrCast(@alignCast(ud));
    const op = surface.pending_clipboard_op orelse return;
    if (op != .write) return;
    const pending = op.write;
    const alloc = surface.app.core_app.alloc;
    surface.pending_clipboard_op = null;
    defer {
        for (pending.contents) |*content| {
            alloc.free(content.mime);
            alloc.free(content.data);
        }
        alloc.free(pending.contents);
    }
    if (pending.clipboard != .standard) return;
    var html_content: ?[]const u8 = null;
    var plain_content: ?[]const u8 = null;
    for (pending.contents) |content| {
        if (std.mem.eql(u8, content.mime, "text/html")) {
            html_content = content.data;
        } else if (std.mem.eql(u8, content.mime, "text/plain")) {
            plain_content = content.data;
        }
    }
    if (html_content) |html| {
        surface.writeClipboardHtml(html, plain_content) catch |err| {
            std.log.warn("pending clipboard html write failed err={}", .{err});
        };
        return;
    }
    if (plain_content) |plain| {
        surface.writeClipboardText(plain) catch |err| {
            std.log.warn("pending clipboard text write failed err={}", .{err});
        };
    }
}

fn surfaceConfirmWriteCancel(userdata: ?*anyopaque, _: ConfirmCancelReason) void {
    const ud = userdata orelse return;
    const surface: *Surface = @ptrCast(@alignCast(ud));
    if (surface.pending_clipboard_op) |*op| op.deinit(surface.app.core_app.alloc);
    surface.pending_clipboard_op = null;
}

/// IDropTarget payload callback. Runs on the STA UI thread (COM
/// guarantees). `payload` is owned by the module and lives only for
/// the duration of this callback — the apprt must not retain it.
///
/// Route through `completeClipboardRequest(.paste, …, confirmed=false)`
/// rather than `textCallback` so `clipboard-paste-protection`
/// actually applies. `textCallback` hard-codes `allow_unsafe=true`
/// (it's the terminal-typed path, where newlines ARE the user's
/// intent), which would defeat paste protection for dropped content.
fn surfaceDropPayloadCallback(ctx: *anyopaque, payload: []const u8) void {
    const surface: *Surface = @ptrCast(@alignCast(ctx));
    if (payload.len == 0) return;
    const alloc = surface.app.core_app.alloc;
    const payload_z = alloc.dupeZ(u8, payload) catch |err| {
        std.log.warn("drop payload dupe failed err={}", .{err});
        return;
    };
    defer alloc.free(payload_z);

    // Defense-in-depth classifier pass.
    //
    // Core's `isSafe` only flags newlines + bracketed-paste-end
    // sequences. That's correct for generic clipboard pastes but
    // insufficient for drop payloads where a crafted filename like
    // `%USERPROFILE%\x.txt` (cmd `%VAR%`), `$HOME.txt` (PowerShell),
    // or a filename containing control bytes / a URL embedded in
    // other text would bypass confirmation. Consult the full
    // `win32_paste_protection.inspect` verdict — which covers
    // control_chars, shell_metachar, AND mixed_content — not just
    // `hasShellMetachar`. When the verdict isn't `.safe`, fire the
    // same confirm path as the core `.UnsafePaste` branch.
    if (surface.app.config.@"clipboard-paste-protection") {
        const verdict = win32_paste_protection.inspect(payload_z);
        if (verdict.severity != .safe) {
            std.log.info("drop payload flagged severity={s} reason={s}", .{
                @tagName(verdict.severity),
                verdict.reason,
            });
            // Non-modal confirm overlay; dupes payload so it survives
            // the callback teardown. Paste completes asynchronously
            // on accept via `surfaceConfirmPasteAccept`.
            surface.requestPasteConfirm(.paste, payload_z) catch |err| {
                std.log.warn("drop payload paste-protection confirm failed err={}", .{err});
            };
            return;
        }
    }

    surface.core_surface.completeClipboardRequest(.paste, payload_z, false) catch |err| switch (err) {
        error.UnsafePaste, error.UnauthorizedPaste => {
            // Unsafe content (newlines, control sequences, etc.).
            // Defer to the non-modal confirm overlay; the Accept
            // callback re-submits with `confirmed = true`.
            surface.requestPasteConfirm(.paste, payload_z) catch |inner| {
                std.log.warn("drop payload protected paste confirm failed err={}", .{inner});
            };
        },
        else => {
            std.log.warn("drop payload paste failed err={}", .{err});
        },
    };
}

const QuickTerminalGeometrySize = struct {
    primary: win32_quick_terminal.SizePercent,
    secondary: ?win32_quick_terminal.SizePercent,
};

fn quickTerminalSizeForGeometry(
    qts: configpkg.Config.QuickTerminalSize,
    position: configpkg.Config.QuickTerminalPosition,
    dims: configpkg.Config.QuickTerminalSize.Dimensions,
) QuickTerminalGeometrySize {
    if (position == .center and dims.width < dims.height) {
        return .{
            .primary = if (qts.secondary) |value| sizeToGeometry(value) else .{ .pixels = 400 },
            .secondary = if (qts.primary) |value| sizeToGeometry(value) else .{ .pixels = 800 },
        };
    }

    return .{
        .primary = if (qts.primary) |value|
            sizeToGeometry(value)
        else
            .{ .pixels = if (position == .center) 800 else 400 },
        .secondary = if (qts.secondary) |value|
            sizeToGeometry(value)
        else if (position == .center)
            .{ .pixels = 400 }
        else
            null,
    };
}

fn sizeToGeometry(sz: configpkg.Config.QuickTerminalSize.Size) win32_quick_terminal.SizePercent {
    return switch (sz) {
        .percentage => |v| .{ .percent = v },
        .pixels => |v| .{ .pixels = v },
    };
}

fn rectEqual(a: RECT, b: RECT) bool {
    return a.left == b.left and
        a.top == b.top and
        a.right == b.right and
        a.bottom == b.bottom;
}

/// A QT rect is computed in physical pixels. WM_DPICHANGED still updates
/// fonts/layout during this call, but must not substitute its suggested size.
fn setQuickTerminalRect(hwnd: HWND, rect: RECT) void {
    const host = getHost(hwnd);
    const was_placing = if (host) |v| v.quick_terminal_placing else false;
    if (host) |v| v.quick_terminal_placing = true;
    defer if (host) |v| {
        v.quick_terminal_placing = was_placing;
    };
    const dpi_before = sys.GetDpiForWindow(hwnd);
    _ = sys.SetWindowPos(hwnd, HWND_TOPMOST, rect.left, rect.top, rect.right - rect.left, rect.bottom - rect.top, c.SWP_NOACTIVATE);
    // Settle the computed rectangle after nested DPI scale/layout updates.
    if (sys.GetDpiForWindow(hwnd) != dpi_before) {
        _ = sys.SetWindowPos(hwnd, HWND_TOPMOST, rect.left, rect.top, rect.right - rect.left, rect.bottom - rect.top, c.SWP_NOACTIVATE);
    }
}

test "win32 DPI suggestions preserve a quick terminal tween but resize ordinary moves" {
    if (builtin.os.tag != .windows) return error.SkipZigTest;
    const previous_dpi_context = sys.SetThreadDpiAwarenessContext(-4);
    defer _ = sys.SetThreadDpiAwarenessContext(previous_dpi_context);
    const core = try CoreApp.create(std.testing.allocator);
    defer core.destroy();
    var app: App = undefined;
    try app.init(core, .{ .safe_mode = true });
    const hinstance = app.hinstance;
    defer {
        app.terminate();
        _ = sys.UnregisterClassW(host_class_name, hinstance);
        _ = sys.UnregisterClassW(palette_list_class_name, hinstance);
        _ = sys.UnregisterClassW(scrollbar_class_name, hinstance);
    }
    const host = try app.createHost(std.unicode.utf8ToUtf16LeStringLiteral(""), null, true);
    const hwnd = host.hwnd.?;
    var before: RECT = undefined;
    try std.testing.expect(sys.GetWindowRect(hwnd, &before) != 0);
    const suggested: RECT = .{ .left = before.left + 40, .top = before.top + 30, .right = before.left + 40 + 1600, .bottom = before.top + 30 + 1000 };
    // DefWindowProc caps the tracking size on small/headless displays. Use
    // a direct native placement as the ordinary-move oracle, rather than
    // assuming this monitor permits the requested physical dimensions.
    try std.testing.expect(sys.SetWindowPos(hwnd, null, suggested.left, suggested.top, suggested.right - suggested.left, suggested.bottom - suggested.top, c.SWP_NOZORDER | c.SWP_NOACTIVATE) != 0);
    var ordinary: RECT = undefined;
    try std.testing.expect(sys.GetWindowRect(hwnd, &ordinary) != 0);
    // Creation can also permit an oversized rect that a subsequent move
    // would cap. Establish and read back a smaller native starting rect.
    try std.testing.expect(sys.SetWindowPos(hwnd, null, before.left, before.top, @divTrunc(ordinary.right - ordinary.left, 2), @divTrunc(ordinary.bottom - ordinary.top, 2), c.SWP_NOZORDER | c.SWP_NOACTIVATE) != 0);
    try std.testing.expect(sys.GetWindowRect(hwnd, &before) != 0);
    try std.testing.expect(!rectEqual(before, ordinary));
    const param: LPARAM = @bitCast(@intFromPtr(&suggested));
    // A delivered DPI message between tween frames must not override the
    // physical dimensions. This reaches the native handler even when the
    // OS disables animation on a hidden desktop.
    host.quick_terminal_animation = .{ .id = 1, .start = before, .end = before };
    _ = hostWindowProc(hwnd, c.WM_DPICHANGED, 0, param);
    var actual: RECT = undefined;
    try std.testing.expect(sys.GetWindowRect(hwnd, &actual) != 0);
    try std.testing.expectEqualDeep(before, actual);
    host.quick_terminal_animation = null;
    // A user move of that same QT still follows the ordinary DPI policy.
    _ = hostWindowProc(hwnd, c.WM_DPICHANGED, 0, param);
    try std.testing.expect(sys.GetWindowRect(hwnd, &actual) != 0);
    try std.testing.expectEqualDeep(ordinary, actual);
    // So does a restored window's saved rect while it is being applied.
    try std.testing.expect(sys.SetWindowPos(hwnd, null, before.left, before.top, before.right - before.left, before.bottom - before.top, c.SWP_NOZORDER | c.SWP_NOACTIVATE) != 0);
    host.restore_placing = true;
    _ = hostWindowProc(hwnd, c.WM_DPICHANGED, 0, param);
    try std.testing.expect(sys.GetWindowRect(hwnd, &actual) != 0);
    try std.testing.expectEqualDeep(before, actual);
    host.restore_placing = false;
    try std.testing.expect(!host.quick_terminal_placing);
    try std.testing.expect(sys.IsWindowVisible(hwnd) == 0);
}

test "win32 a DPI change holds the terminal grid from WM_GETDPISCALEDSIZE to WM_DPICHANGED" {
    if (builtin.os.tag != .windows) return error.SkipZigTest;
    const core = try CoreApp.create(std.testing.allocator);
    defer core.destroy();
    var app: App = undefined;
    try app.init(core, .{ .safe_mode = true });
    const hinstance = app.hinstance;
    defer {
        app.terminate();
        _ = sys.UnregisterClassW(host_class_name, hinstance);
        _ = sys.UnregisterClassW(palette_list_class_name, hinstance);
        _ = sys.UnregisterClassW(scrollbar_class_name, hinstance);
    }
    const host = try app.createHost(std.unicode.utf8ToUtf16LeStringLiteral(""), null, true);
    const hwnd = host.hwnd.?;
    var size: extern struct { cx: i32, cy: i32 } = .{ .cx = 900, .cy = 600 };
    const size_param: LPARAM = @bitCast(@intFromPtr(&size));

    // FALSE keeps Windows' linear scaling and leaves the proposed size alone.
    try std.testing.expect(!host.dpi_change_pending);
    try std.testing.expectEqual(@as(LRESULT, 0), hostWindowProc(hwnd, c.WM_GETDPISCALEDSIZE, 144, size_param));
    try std.testing.expect(host.dpi_change_pending);
    try std.testing.expectEqual(@as(i32, 900), size.cx);

    // WM_DPICHANGED releases the hold once it has run.
    var rect: RECT = undefined;
    try std.testing.expect(sys.GetWindowRect(hwnd, &rect) != 0);
    _ = hostWindowProc(hwnd, c.WM_DPICHANGED, 0, @bitCast(@intFromPtr(&rect)));
    try std.testing.expect(!host.dpi_change_pending);

    // So does the end of a drag that never delivered one.
    _ = hostWindowProc(hwnd, c.WM_GETDPISCALEDSIZE, 144, size_param);
    _ = hostWindowProc(hwnd, c.WM_EXITSIZEMOVE, 0, 0);
    try std.testing.expect(!host.dpi_change_pending);
}

/// Runs `body` on a thread attached to a desktop of its own, so a test can
/// show, hide and minimize windows without touching the user's desktop.
/// `SetThreadDesktop` fails on a thread that owns a window, so the runner's
/// own thread cannot do it (AGENTS.md 2026-10-06).
fn runOnHiddenDesktop(comptime body: anytype) !void {
    const Desktop = struct {
        extern "user32" fn CreateDesktopW(name: [*:0]const u16, device: ?*anyopaque, mode: ?*anyopaque, flags: u32, access: u32, attributes: ?*anyopaque) callconv(.winapi) ?*anyopaque;
        extern "user32" fn SetThreadDesktop(desktop: *anyopaque) callconv(.winapi) BOOL;
        extern "user32" fn CloseDesktop(desktop: *anyopaque) callconv(.winapi) BOOL;

        fn run(desktop: *anyopaque, result: *anyerror!void) void {
            if (SetThreadDesktop(desktop) == 0) {
                result.* = lastError();
                return;
            }
            body() catch |err| {
                // The test fails at `return result` on the runner's thread;
                // this trace shows which check failed.
                if (@errorReturnTrace()) |trace| std.debug.dumpStackTrace(trace.*);
                result.* = err;
            };
        }
    };
    var name_buf: [80]u8 = undefined;
    const name = try std.fmt.bufPrint(&name_buf, "noctty-pkg43-test-{x}-{d}", .{ @intFromPtr(&name_buf), sys.GetTickCount64() });
    const wide_name = try std.unicode.utf8ToUtf16LeAllocZ(std.testing.allocator, name);
    defer std.testing.allocator.free(wide_name);
    const desktop = Desktop.CreateDesktopW(wide_name.ptr, null, null, 0, 0x10000000, null) orelse return error.SkipZigTest;
    defer _ = Desktop.CloseDesktop(desktop);
    var result: anyerror!void = {};
    const thread = try std.Thread.spawn(.{}, Desktop.run, .{ desktop, &result });
    thread.join();
    return result;
}

/// A quick terminal host that a test has put on screen, with the pieces a
/// toggle needs: a registered host, one tab, and the surface that tab shows.
/// `other` is a second host with a window and no tab, not registered until a
/// test appends it to `app.hosts`.
const QuickTerminalToggleFixture = struct {
    core_app: CoreApp = undefined,
    app: App = undefined,
    host: Host = undefined,
    other: Host = undefined,
    surface: Surface = undefined,
    /// What `QuickTerminalFreshTab` hands back as a tab created later.
    fresh: Surface = undefined,
    session: TestSession = .{},

    fn init(self: *QuickTerminalToggleFixture) !void {
        try self.session.init(.{
            .core_app = &self.core_app,
            .app = &self.app,
            .hosts = &.{
                .{ .storage = &self.host, .register = true, .next_tab_id = 2 },
                .{ .storage = &self.other, .id = 2 },
            },
            .surfaces = &.{
                .{ .storage = &self.surface, .host = &self.host, .register = true },
                .{ .storage = &self.fresh, .host = &self.host, .window_visible = false },
            },
            .tabs = &.{.{ .host = &self.host, .surface = &self.surface, .id = 1 }},
        });
        errdefer self.session.deinit();
        // `none` shows the window without the activation machinery, which
        // needs a real chrome the fixture does not have.
        self.app.config.@"quick-terminal-keyboard-interactivity" = .none;
        self.host.quick_terminal = true;
        self.host.hwnd = try createTestHostWindow();
        errdefer _ = sys.DestroyWindow(self.host.hwnd.?);
        // Showing a tab refreshes the chrome, which creates the tab-strip
        // container as a layered child; this manifest-less test binary
        // cannot (AGENTS.md 2026-10-01), so a plain one takes its slot.
        self.host.tab_container_hwnd = try createTestChromeChild(self.host.hwnd.?, prompt_label_class);
        self.other.hwnd = try createTestHostWindow();
        _ = sys.ShowWindow(self.host.hwnd.?, c.SW_SHOWNOACTIVATE);
        _ = sys.ShowWindow(self.other.hwnd.?, c.SW_SHOWNOACTIVATE);
    }

    fn deinit(self: *QuickTerminalToggleFixture) void {
        _ = sys.DestroyWindow(self.other.hwnd.?);
        _ = sys.DestroyWindow(self.host.hwnd.?);
        self.session.deinit();
    }

    fn visible(self: *const QuickTerminalToggleFixture) bool {
        return sys.IsWindowVisible(self.host.hwnd.?) != 0;
    }

    fn otherVisible(self: *const QuickTerminalToggleFixture) bool {
        return sys.IsWindowVisible(self.other.hwnd.?) != 0;
    }
};

const QuickTerminalCreateCounter = struct {
    var calls: usize = 0;
    var host_id: ?u32 = null;

    fn createSurface(_: *App, _: *const configpkg.Config, _: LPCWSTR, opts: SurfaceInitOptions) anyerror!*Surface {
        calls += 1;
        host_id = opts.host_id;
        return error.TestWindowCreateFailed;
    }
};

test "win32 toggle_quick_terminal follows its host after the first pane is gone" {
    if (builtin.os.tag != .windows) return error.SkipZigTest;
    try runOnHiddenDesktop(struct {
        fn body() !void {
            var fixture: QuickTerminalToggleFixture = .{};
            try fixture.init();
            defer fixture.deinit();
            // Only the pane the window was created with ever carried the
            // per-surface flag. This tab was opened in the quick terminal
            // later, so its surface is not flagged, but its host is.
            QuickTerminalCreateCounter.calls = 0;
            fixture.app.test_create_window_surface = &QuickTerminalCreateCounter.createSurface;

            try std.testing.expect(fixture.visible());
            try fixture.app.toggleQuickTerminal();
            try std.testing.expect(!fixture.visible());
            try std.testing.expect(!fixture.surface.window_visible);
            try fixture.app.toggleQuickTerminal();
            try std.testing.expect(fixture.visible());
            try std.testing.expect(fixture.surface.window_visible);
            // A second quick terminal was never made.
            try std.testing.expectEqual(@as(usize, 0), QuickTerminalCreateCounter.calls);
            try std.testing.expectEqual(@as(usize, 1), fixture.app.hosts.items.len);
        }
    }.body);
}

/// Stands in for the tab `toggleQuickTerminal` opens in an empty quick
/// terminal host: `fixture.fresh`, inserted as the host's only tab.
const QuickTerminalFreshTab = struct {
    var fixture: *QuickTerminalToggleFixture = undefined;
    var calls: usize = 0;
    var host_id: ?u32 = null;

    fn createSurface(app: *App, _: *const configpkg.Config, _: LPCWSTR, opts: SurfaceInitOptions) anyerror!*Surface {
        calls += 1;
        host_id = opts.host_id;
        const surface = &fixture.fresh;
        var prepared = (try app.prepareShellSurfaceCreate(&fixture.host, opts)).?;
        defer prepared.deinit();
        try app.windows.append(app.core_app.alloc, surface);
        try fixture.host.tabs.insert(
            app.core_app.alloc,
            0,
            try Tab.init(app.core_app.alloc, fixture.host.nextTabId(), surface),
        );
        try prepared.commit(&app.shell_runtime);
        surface.shell_id = prepared.created.pane;
        surface.shell_committed = true;
        fixture.host.tabs.items[0].shell_id = prepared.created.tab;
        // Surface.init leaves the audit to the caller that shows the tab.
        app.shell_audit_after_activation = true;
        return surface;
    }
};

test "win32 toggle_quick_terminal opens a fresh floating tab instead of showing one detached for undo" {
    if (builtin.os.tag != .windows) return error.SkipZigTest;
    try runOnHiddenDesktop(struct {
        fn body() !void {
            var fixture: QuickTerminalToggleFixture = .{};
            try fixture.init();
            defer fixture.deinit();
            // `close_tab:this` on the only tab keeps the host and the
            // surface for undo, and nothing in the host shows it.
            fixture.app.shell_runtime_initialized = true;
            var window = try fixture.app.shell_runtime.prepare(.create_window);
            defer window.deinit();
            try window.commit(&fixture.app.shell_runtime);
            fixture.host.shell_id = window.created.window;
            var close = try fixture.app.shell_runtime.prepare(.{ .detach_tab = window.created.tab.? });
            defer close.deinit();
            try close.commit(&fixture.app.shell_runtime);
            var detached = fixture.host.tabs.orderedRemove(0);
            defer detached.deinit();
            fixture.surface.window_visible = false;

            QuickTerminalFreshTab.fixture = &fixture;
            QuickTerminalFreshTab.calls = 0;
            QuickTerminalFreshTab.host_id = null;
            fixture.app.test_create_window_surface = &QuickTerminalFreshTab.createSurface;

            // On screen and empty, the toggle dismisses it.
            try fixture.app.toggleQuickTerminal();
            try std.testing.expect(!fixture.visible());
            try std.testing.expectEqual(@as(usize, 0), QuickTerminalFreshTab.calls);

            // Dismissed, it opens a fresh tab and shows that, never the
            // surface that was detached.
            defer appendOwnedString(std.testing.allocator, &fixture.host.cached_window_title, null) catch unreachable;
            try fixture.app.toggleQuickTerminal();
            try std.testing.expectEqual(@as(usize, 1), QuickTerminalFreshTab.calls);
            try std.testing.expectEqual(@as(?u32, fixture.host.id), QuickTerminalFreshTab.host_id);
            try std.testing.expect(!fixture.surface.window_visible);
            try std.testing.expect(fixture.visible());
            try std.testing.expect(fixture.fresh.window_visible);
            try std.testing.expect(fixture.host.activeSurface() == &fixture.fresh);
            // Passive showing bypasses activateSurface, but must complete
            // the pending structural audit before returning to the pump.
            try std.testing.expect(!fixture.app.shell_audit_after_activation);
            try fixture.app.validateShellNativeMapping();
            // The window floats with the tab it shows, so a tab switch or
            // undo does not drop it below other windows.
            try std.testing.expect(fixture.fresh.topmost);
        }
    }.body);
}

test "win32 toggle_quick_terminal keeps a pane a zoom hides out of view" {
    if (builtin.os.tag != .windows) return error.SkipZigTest;
