fn getHost(hwnd: HWND) ?*Host {
    return windowData(Host, hwnd);
}

/// Target of the DWM cloak/uncloak WinEvent hook. Set for the lifetime of the
/// App so the callback can resolve an HWND without a global `getHost`, which
/// would be unsafe here: other window classes in this apprt store unrelated
/// payloads in `GWLP_USERDATA`, and the hook sees every window on this thread.
var cloak_event_app: ?*App = null;

/// Runs on the UI thread (WINEVENT_OUTOFCONTEXT delivers through our own
/// message pump), so it may touch host state directly.
///
/// A cloak transition has no window message, so without this a virtual-desktop
/// switch that uncloaks a background window would leave `surfaces_visible`
/// false; hidden surfaces skip rendering entirely, so nothing would repair it
/// until an unrelated message arrived.
///
/// `cloaked` is the transition the event carried. It must reach the refresh:
/// if it were dropped and the refresh's `DwmGetWindowAttribute` query then
/// failed, the previous `cloaked = true` would be preserved and this very
/// recovery path would be the thing that fails to recover.
fn onHostCloakEvent(hwnd: HWND, cloaked: bool) void {
    const app = cloak_event_app orelse return;
    for (app.hosts.items) |host| {
        const host_hwnd = host.hwnd orelse continue;
        if (host_hwnd != hwnd) continue;
        host.refreshSurfaceVisibilityObserving(cloaked);
        return;
    }
}

/// A child window that can take keyboard focus right now. Hidden chrome
/// is not a focus target: focusing it would move focus somewhere the user
/// cannot see and make a screen reader announce an off-screen element.
fn focusableHwnd(hwnd: ?HWND) ?HWND {
    const value = hwnd orelse return null;
    if (sys.IsWindowVisible(value) == 0) return null;
    return value;
}

fn refocusActiveSurface(host: *Host) void {
    if (host.activeSurface()) |surface| {
        if (surface.hwnd) |surface_hwnd| _ = sys.SetFocus(surface_hwnd);
    }
}

fn hostActivationFocusTarget(
    mode: HostOverlayMode,
    edit: ?HWND,
    accept: ?HWND,
    cancel: ?HWND,
    surface: ?HWND,
) ?HWND {
    return switch (mode) {
        .none => surface,
        .command_palette,
        .profile,
        .search,
        .surface_title,
        .tab_title,
        .tab_overview,
        => edit orelse surface,
        .confirm => accept orelse cancel orelse surface,
    };
}

fn refocusHostAfterActivation(host: *Host) void {
    const surface_hwnd = if (host.activeSurface()) |surface| surface.hwnd else null;
    if (hostActivationFocusTarget(
        host.overlay_mode,
        host.overlay_edit_hwnd,
        host.overlay_accept_hwnd,
        host.overlay_cancel_hwnd,
        surface_hwnd,
    )) |target| {
        _ = sys.SetFocus(target);
    }
}

/// Window messages are dispatched by native menu/size/dialog pumps too. The
/// only receiver with completion authority is this message-only App window.
fn appMessageWindowProc(hwnd: HWND, message: UINT, wparam: WPARAM, lparam: LPARAM) callconv(.winapi) LRESULT {
    const app = windowData(App, hwnd) orelse return sys.DefWindowProcW(hwnd, message, wparam, lparam);
    const delivery = app.delivery orelse return 0;
    switch (message) {
        c.WM_WINHOSTTY_WAKE => {
            app.tickCoreAppModal();
            return 0;
        },
        c.WM_WINHOSTTY_UPDATE,
        c.WM_WINHOSTTY_TOAST_ACTIVATION,
        c.WM_WINHOSTTY_UIA_DISCONNECT,
        c.WM_WINHOSTTY_PROFILES,
        c.WM_WINHOSTTY_JUMP_LIST,
        => {
            var payload = delivery.take(message, @bitCast(lparam)) orelse return 0;
            switch (payload) {
                .update => |completion| {
                    defer payload.deinit();
                    app.handleUpdateCheckCompletion(completion);
                },
                .profiles => |completion| {
                    // Applied at the top of the outer pump: this can run
                    // inside a modal loop, with a menu built from the
                    // profiles being replaced still open.
                    if (app.pending_profile_discovery) |pending| pending.deinit();
                    app.pending_profile_discovery = completion;
                },
                .jump_list => |job| {
                    defer payload.deinit();
                    if (app.jump_list) |*jump_list| jump_list.completeRebuild(job);
                },
                .toast => |activation| {
                    defer delivery.toast_pending.store(false, .release);
                    if (!app.handleToastActivation(activation)) app.pending_toast_activation = activation;
                },
                .uia_disconnect => |pending| processDeferredUiaDisconnect(delivery, pending),
            }
            app.tickCoreAppModal();
            return 0;
        },
        c.WM_WINHOSTTY_TERMINAL_HANDOFF => {
            // Adoption is done at the top of the outer pump, where no owner
            // window procedure or COM call has a borrowed Host on its stack.
            return 0;
        },
        else => return sys.DefWindowProcW(hwnd, message, wparam, lparam),
    }
}

/// Native modal delivery tests run on a private desktop without a shell,
/// renderer, clipboard operation, or COM initialization.
const Pkg19NativeDeliveryTest = struct {
    extern "user32" fn CreateDesktopW(name: [*:0]const u16, device: ?*anyopaque, mode: ?*anyopaque, flags: u32, access: u32, attributes: ?*anyopaque) callconv(.winapi) ?*anyopaque;
    extern "user32" fn SetThreadDesktop(desktop: *anyopaque) callconv(.winapi) BOOL;
    extern "user32" fn CloseDesktop(desktop: *anyopaque) callconv(.winapi) BOOL;
    extern "user32" fn EndMenu() callconv(.winapi) BOOL;

    const FakeUia = struct {
        disconnects: usize = 0,
        releases: usize = 0,
        fn disconnect(raw: *anyopaque) win32_uia.HRESULT {
            const self: *@This() = @ptrCast(@alignCast(raw));
            self.disconnects += 1;
            return win32_uia.S_OK;
        }
        fn release(raw: *anyopaque) void {
            const self: *@This() = @ptrCast(@alignCast(raw));
            self.releases += 1;
        }
    };

    const Popup = struct {
        app: *App,
        title_surface: *Surface,
        closing_surface: *Surface,
        fake: *FakeUia,
        entered: bool = false,
        open: bool = false,
        exited: bool = false,
        observed_inside: bool = false,
        timed_out: bool = false,
        completions_posted: bool = false,
        ticks: usize = 0,

        fn proc(hwnd: HWND, message: UINT, wparam: WPARAM, lparam: LPARAM) callconv(.winapi) LRESULT {
            if (windowData(@This(), hwnd)) |self| switch (message) {
                0x0211 => { // WM_ENTERMENULOOP
                    self.entered = true;
                    self.open = true;
                },
                0x0212 => { // WM_EXITMENULOOP
                    self.open = false;
                    self.exited = true;
                },
                else => {},
            };
            return sys.DefWindowProcW(hwnd, message, wparam, lparam);
        }

        fn timer(hwnd: ?HWND, _: UINT, _: UINT_PTR, _: DWORD) callconv(.winapi) void {
            const self = windowData(@This(), hwnd orelse return) orelse return;
            self.ticks += 1;
            // First require wake alone to apply the title. Only then post
            // completions, whose own modal tick cannot mask a broken wake.
            // Never tick the core, dispatch delivery, or remove messages here.
            if (!self.completions_posted and self.open and
                self.title_surface.title != null and
                std.mem.eql(u8, self.title_surface.title.?, "modal-delivered"))
            {
                self.completions_posted = true;
                self.app.delivery.?.update_running.store(true, .release);
                postUpdate(self.app.delivery.?) catch {
                    self.timed_out = true;
                    _ = EndMenu();
                    return;
                };
                postUia(self.app.delivery.?, self.fake) catch {
                    self.timed_out = true;
                    _ = EndMenu();
                    return;
                };
            }
            if (self.open and self.title_surface.title != null and
                std.mem.eql(u8, self.title_surface.title.?, "modal-delivered") and
                self.fake.disconnects == 1 and self.fake.releases == 1 and
                !self.app.delivery.?.update_running.load(.acquire) and
                self.app.running and sys.IsWindow(self.closing_surface.hwnd.?) != 0)
            {
                self.observed_inside = true;
                _ = EndMenu();
            } else if (self.ticks >= 100) {
                self.timed_out = true;
                _ = EndMenu();
            }
        }
    };

    fn run(comptime body: anytype) !void {
        const Thread = struct {
            fn entry(desktop: *anyopaque, result: *anyerror!void) void {
                result.* = if (SetThreadDesktop(desktop) == 0) lastError() else body();
            }
        };
        var name_buf: [80]u8 = undefined;
        const name = try std.fmt.bufPrint(&name_buf, "noctty-pkg19-test-{x}-{d}", .{ @intFromPtr(&name_buf), sys.GetTickCount64() });
        const wide_name = try std.unicode.utf8ToUtf16LeAllocZ(std.testing.allocator, name);
        defer std.testing.allocator.free(wide_name);
        const desktop = CreateDesktopW(wide_name.ptr, null, null, 0, 0x10000000, null) orelse return error.SkipZigTest;
        defer _ = CloseDesktop(desktop);
        var result: anyerror!void = {};
        const thread = try std.Thread.spawn(.{}, Thread.entry, .{ desktop, &result });
        thread.join();
        try result;
    }

    fn pending(fake: *FakeUia) !*DeferredUiaDisconnect {
        const value = try std.heap.page_allocator.create(DeferredUiaDisconnect);
        value.* = .{ .ctx = fake, .disconnect = &FakeUia.disconnect, .release = &FakeUia.release };
        return value;
    }

    fn postUia(delivery: *AppDelivery, fake: *FakeUia) !void {
        const value = try pending(fake);
        if (!postDeferredUiaDisconnect(delivery, value)) {
            std.heap.page_allocator.destroy(value);
            return error.TestPostFailed;
        }
    }

    fn postUpdate(delivery: *AppDelivery) !void {
        const value = try std.testing.allocator.create(UpdateCheckCompletion);
        value.* = .{ .alloc = std.testing.allocator };
        if (!delivery.post(c.WM_WINHOSTTY_UPDATE, .{ .update = value })) {
            std.testing.allocator.destroy(value);
            return error.TestPostFailed;
        }
    }

    fn closeAppWindow(app: *App) void {
        const delivery = app.delivery orelse return;
        app.closeMessageWindow();
        app.delivery = null;
        delivery.release();
    }

    fn popupBody() !void {
        var core_app: CoreApp = undefined;
        var app: App = undefined;
        var host: Host = undefined;
        var title_surface: Surface = undefined;
        var closing_surface: Surface = undefined;
        var session: TestSession = .{};
        try session.init(.{
            .core_app = &core_app,
            .app = &app,
            // Host is deliberately not in App.hosts: this dummy native owner
            // does not run the production Host destruction procedure.
            .hosts = &.{.{ .storage = &host }},
            .surfaces = &.{
                .{ .storage = &title_surface, .register = true },
                .{ .storage = &closing_surface, .host = &host, .register = true },
            },
            .tabs = &.{.{ .host = &host, .surface = &closing_surface, .id = 1 }},
        });
        defer session.deinit();
        try app.createMessageWindow();
        defer closeAppWindow(&app);
        app.running = true;
        @atomicStore(DWORD, &app.ui_thread_id, sys.GetCurrentThreadId(), .release);

        // A partial CoreSurface fixture, never initialized/deinitialized as a
        // complete CoreSurface. These are exactly the fields read by the two
        // dispatched core methods: set_title and close/needsConfirmQuit.
        title_surface.core_surface.rt_app = &app;
        title_surface.core_surface.config.title = null;
        closing_surface.core_surface.rt_surface = &closing_surface;
        closing_surface.core_surface.readonly = false;
        closing_surface.core_surface.child_exited = true;
        try core_app.surfaces.append(std.testing.allocator, &title_surface);
        // TestSession owns the runtime fixtures; CoreApp must never call
        // Surface.deinit on these partial core fixtures at teardown.
        defer core_app.surfaces.clearRetainingCapacity();
        try core_app.surfaces.append(std.testing.allocator, &closing_surface);
        defer if (title_surface.title) |value| std.testing.allocator.free(value);

        var fake: FakeUia = .{};
        var popup: Popup = .{ .app = &app, .title_surface = &title_surface, .closing_surface = &closing_surface, .fake = &fake };
        const popup_class_name = std.unicode.utf8ToUtf16LeStringLiteral("noctty.pkg19.popup-test");
        var wc: WNDCLASSEXW = .{
            .cbSize = @sizeOf(WNDCLASSEXW),
            .style = 0,
            .lpfnWndProc = &Popup.proc,
            .cbClsExtra = 0,
            .cbWndExtra = 0,
            .hInstance = app.hinstance,
            .hIcon = null,
            .hCursor = null,
            .hbrBackground = null,
            .lpszMenuName = null,
            .lpszClassName = popup_class_name,
            .hIconSm = null,
        };
        if (sys.RegisterClassExW(&wc) == 0 and windows.kernel32.GetLastError() != .CLASS_ALREADY_EXISTS) return lastError();
        const owner = sys.CreateWindowExW(0, popup_class_name, popup_class_name, WS_OVERLAPPEDWINDOW, 100, 100, 300, 200, null, null, app.hinstance, null) orelse return lastError();
        defer _ = sys.DestroyWindow(owner);
        setWindowData(owner, &popup);
        defer setWindowData(owner, null);
        _ = sys.ShowWindow(owner, c.SW_SHOWNOACTIVATE);
        const closing_hwnd = sys.CreateWindowExW(0, prompt_label_class, default_title, c.WS_CHILD, 0, 0, 10, 10, owner, null, app.hinstance, null) orelse return lastError();
        closing_surface.hwnd = closing_hwnd;
        defer if (sys.IsWindow(closing_hwnd) != 0) {
            _ = sys.DestroyWindow(closing_hwnd);
        };

        // Unsafe work precedes safe work, so failing to defer it would close
        // the child / quit before the observable title reaches the fixture.
        try std.testing.expect(core_app.mailbox.push(.{ .close = &closing_surface.core_surface }, .instant) != 0);
        try std.testing.expect(core_app.mailbox.push(.quit, .instant) != 0);
        var title: [256]u8 = @splat(0);
        @memcpy(title[0.."modal-delivered".len], "modal-delivered");
        try std.testing.expect(core_app.mailbox.push(.{ .surface_message = .{ .surface = &title_surface.core_surface, .message = .{ .set_title = title } } }, .instant) != 0);
        try std.testing.expect(app.delivery.?.wake(c.WM_WINHOSTTY_WAKE));
        try std.testing.expect(title_surface.title == null);
        try std.testing.expectEqual(@as(usize, 0), fake.disconnects);

        const menu = sys.CreatePopupMenu();
        defer _ = sys.DestroyMenu(menu);
        try std.testing.expect(sys.AppendMenuW(menu, c.MF_STRING, 1, default_title) != 0);
        const timer = sys.SetTimer(owner, 0x1919, 20, @ptrCast(&Popup.timer));
        if (timer == 0) return lastError();
        defer _ = sys.KillTimer(owner, timer);
        _ = sys.TrackPopupMenu(menu, c.TPM_RETURNCMD | c.TPM_RIGHTBUTTON, 120, 120, 0, owner, null);
        try std.testing.expect(popup.entered and popup.exited and !popup.open);
        try std.testing.expect(!popup.timed_out);
        try std.testing.expect(popup.observed_inside);
        try std.testing.expect(app.running);
        try std.testing.expect(sys.IsWindow(closing_hwnd) != 0);

        // Only the outer tick may execute lifetime operations.
        try core_app.tick(&app);
        try std.testing.expect(sys.IsWindow(closing_hwnd) == 0);
        try std.testing.expect(!app.running);
    }

    fn queued(hwnd: HWND, message: UINT) !MSG {
        var msg: MSG = undefined;
        if (sys.PeekMessageW(&msg, hwnd, message, message, c.PM_REMOVE) == 0) return error.TestMissingDeliveryMessage;
        return msg;
    }

    fn capabilitiesBody() !void {
        var core_a: CoreApp = undefined;
        var app_a: App = undefined;
        var core_b: CoreApp = undefined;
        var app_b: App = undefined;
        var session_a: TestSession = .{};
        var session_b: TestSession = .{};
        try session_a.init(.{ .core_app = &core_a, .app = &app_a });
        defer session_a.deinit();
        try session_b.init(.{ .core_app = &core_b, .app = &app_b });
        defer session_b.deinit();
        try app_a.createMessageWindow();
        defer closeAppWindow(&app_a);
        try app_b.createMessageWindow();
        defer closeAppWindow(&app_b);
        const a = app_a.message_hwnd.?;
        const b = app_b.message_hwnd.?;
        var fake: FakeUia = .{};
        try postUia(app_a.delivery.?, &fake);
        const uia = try queued(a, c.WM_WINHOSTTY_UIA_DISCONNECT);
        // Null, arbitrary pointer-shaped input, a real token at another App
        // HWND, and a real token with another message kind do nothing.
        _ = sys.SendMessageW(a, c.WM_WINHOSTTY_UIA_DISCONNECT, 0, 0);
        _ = sys.SendMessageW(a, c.WM_WINHOSTTY_UIA_DISCONNECT, 0, @bitCast(@intFromPtr(&fake)));
        _ = sys.SendMessageW(b, uia.message, uia.wParam, uia.lParam);
        _ = sys.SendMessageW(a, c.WM_WINHOSTTY_UPDATE, 0, uia.lParam);
        try std.testing.expectEqual(@as(usize, 0), fake.disconnects);
        try std.testing.expectEqual(@as(usize, 0), fake.releases);
        _ = sys.SendMessageW(a, uia.message, uia.wParam, uia.lParam);
        try std.testing.expectEqual(@as(usize, 1), fake.disconnects);
        try std.testing.expectEqual(@as(usize, 1), fake.releases);
        _ = sys.SendMessageW(a, uia.message, uia.wParam, uia.lParam);
        try std.testing.expectEqual(@as(usize, 1), fake.disconnects);
        try std.testing.expectEqual(@as(usize, 1), fake.releases);

        app_a.delivery.?.update_running.store(true, .release);
        try postUpdate(app_a.delivery.?);
        const update = try queued(a, c.WM_WINHOSTTY_UPDATE);
        _ = sys.SendMessageW(a, c.WM_WINHOSTTY_UPDATE, 0, 0);
        _ = sys.SendMessageW(b, update.message, 0, update.lParam);
        try std.testing.expect(app_a.delivery.?.update_running.load(.acquire));
        _ = sys.SendMessageW(a, update.message, 0, update.lParam);
        try std.testing.expect(!app_a.delivery.?.update_running.load(.acquire));
        // Replaying a consumed update must not clear a subsequent check.
        app_a.delivery.?.update_running.store(true, .release);
        _ = sys.SendMessageW(a, update.message, 0, update.lParam);
        try std.testing.expect(app_a.delivery.?.update_running.load(.acquire));

        const activation: win32_toast_activation.ActivationTarget = .{ .window_id = 19, .tab_id = 7 };
        app_a.delivery.?.toast_pending.store(true, .release);
        try std.testing.expect(app_a.delivery.?.post(c.WM_WINHOSTTY_TOAST_ACTIVATION, .{ .toast = activation }));
        const toast = try queued(a, c.WM_WINHOSTTY_TOAST_ACTIVATION);
        _ = sys.SendMessageW(a, toast.message, 0, 0);
        _ = sys.SendMessageW(b, toast.message, 0, toast.lParam);
        try std.testing.expect(app_a.pending_toast_activation == null);
        try std.testing.expect(app_b.pending_toast_activation == null);
        try std.testing.expect(app_a.delivery.?.toast_pending.load(.acquire));
        _ = sys.SendMessageW(a, toast.message, 0, toast.lParam);
        try std.testing.expect(activation.eql(app_a.pending_toast_activation.?));
        try std.testing.expect(!app_a.delivery.?.toast_pending.load(.acquire));
        app_a.pending_toast_activation = null;
        app_a.delivery.?.toast_pending.store(true, .release);
        _ = sys.SendMessageW(a, toast.message, 0, toast.lParam);
        try std.testing.expect(app_a.pending_toast_activation == null);
        try std.testing.expect(app_a.delivery.?.toast_pending.load(.acquire));
    }
};

test "win32 App delivery drains title and UIA in native popup while close and quit wait" {
    if (builtin.os.tag != .windows) return error.SkipZigTest;
    try Pkg19NativeDeliveryTest.run(Pkg19NativeDeliveryTest.popupBody);
}

test "win32 App delivery validates owned tokens by kind HWND and single consumption" {
    if (builtin.os.tag != .windows) return error.SkipZigTest;
    try Pkg19NativeDeliveryTest.run(Pkg19NativeDeliveryTest.capabilitiesBody);
}

fn postDeferredUiaDisconnect(delivery: ?*AppDelivery, pending: *DeferredUiaDisconnect) bool {
    const target = delivery orelse return false;
    return target.post(c.WM_WINHOSTTY_UIA_DISCONNECT, .{ .uia_disconnect = pending });
}

fn processDeferredUiaDisconnect(delivery: ?*AppDelivery, pending: *DeferredUiaDisconnect) void {
    const hr = pending.disconnect(pending.ctx);
    if (hr == win32_uia.RPC_E_CANTCALLOUT_ININPUTSYNCCALL and pending.retries < 3) {
        pending.retries += 1;
        if (postDeferredUiaDisconnect(delivery, pending)) return;
        // During shutdown no message target remains. Finish bounded retries
        // in place before releasing the provider's final reference.
        if (delivery == null) return processDeferredUiaDisconnect(null, pending);
    }
    if (hr != win32_uia.S_OK) {
        log.warn("win32 UIA deferred disconnect failed hr=0x{x} retries={d}", .{
            @as(u32, @bitCast(hr)),
            pending.retries,
        });
    }
    pending.release(pending.ctx);
    std.heap.page_allocator.destroy(pending);
}

fn scheduleDeferredUiaDisconnect(
    app: *App,
    ctx: *anyopaque,
    disconnect: *const fn (*anyopaque) win32_uia.HRESULT,
    release: *const fn (*anyopaque) void,
) void {
    const pending = std.heap.page_allocator.create(DeferredUiaDisconnect) catch {
        log.warn("win32 UIA deferred disconnect allocation failed", .{});
        const hr = disconnect(ctx);
        if (hr != win32_uia.S_OK) {
            log.warn("win32 UIA immediate disconnect fallback failed hr=0x{x}", .{@as(u32, @bitCast(hr))});
        }
        release(ctx);
        return;
    };
    pending.* = .{ .ctx = ctx, .disconnect = disconnect, .release = release };
    if (!postDeferredUiaDisconnect(app.delivery, pending)) {
        log.warn("win32 UIA deferred disconnect post failed", .{});
        processDeferredUiaDisconnect(null, pending);
    }
}

test "win32 deferred UIA disconnect drain retries and releases once" {
    const Fake = struct {
        disconnects: usize = 0,
        releases: usize = 0,
        always_rpc: bool = false,

        fn disconnect(raw: *anyopaque) win32_uia.HRESULT {
            const self: *@This() = @ptrCast(@alignCast(raw));
            self.disconnects += 1;
            return if (self.always_rpc or self.disconnects == 1)
                win32_uia.RPC_E_CANTCALLOUT_ININPUTSYNCCALL
            else
                win32_uia.S_OK;
        }

        fn release(raw: *anyopaque) void {
            const self: *@This() = @ptrCast(@alignCast(raw));
            self.releases += 1;
        }
    };

    var fake: Fake = .{};
    const pending = try std.heap.page_allocator.create(DeferredUiaDisconnect);
    pending.* = .{ .ctx = @ptrCast(&fake), .disconnect = &Fake.disconnect, .release = &Fake.release };
    processDeferredUiaDisconnect(null, pending);
    try std.testing.expectEqual(@as(usize, 2), fake.disconnects);
    try std.testing.expectEqual(@as(usize, 1), fake.releases);

    var exhausted: Fake = .{ .always_rpc = true };
    const retry_pending = try std.heap.page_allocator.create(DeferredUiaDisconnect);
    retry_pending.* = .{ .ctx = @ptrCast(&exhausted), .disconnect = &Fake.disconnect, .release = &Fake.release };
    processDeferredUiaDisconnect(null, retry_pending);
    try std.testing.expectEqual(@as(usize, 4), exhausted.disconnects);
    try std.testing.expectEqual(@as(usize, 1), exhausted.releases);
}

/// The integrated titlebar is the only thing that paints caption
/// buttons; without it the window has a stock DWM caption that the host
/// provider already describes.
///
/// A minimized or hidden window paints nothing either. Leaving the
/// buttons in the tree there would hand a reader a full-size rect at the
/// minimized window's off-screen origin, with `IsOffscreen = false`
/// alongside it.
fn captionButtonsPainted(integrated: bool, window_visible: bool, iconic: bool) bool {
    return integrated and window_visible and !iconic;
}

fn captionButtonsPaintedThunk(ctx: *anyopaque) bool {
    const host: *Host = @ptrCast(@alignCast(ctx));
    const hwnd = host.hwnd orelse return false;
    return captionButtonsPainted(
        host.usingIntegratedTitlebar(),
        sys.IsWindowVisible(hwnd) != 0,
        sys.IsIconic(hwnd) != 0,
    );
}

fn captionButtonZoomedThunk(ctx: *anyopaque) bool {
    const host: *Host = @ptrCast(@alignCast(ctx));
    const hwnd = host.hwnd orelse return false;
    return sys.IsZoomed(hwnd) != 0;
}

fn captionButtonBoundsThunk(
    ctx: *anyopaque,
    kind: win32_uia.CaptionButtonKind,
) ?win32_uia.UiaRect {
    const host: *Host = @ptrCast(@alignCast(ctx));
    const hwnd = host.hwnd orelse return null;
    var client: RECT = undefined;
    if (sys.GetClientRect(hwnd, &client) == 0) return null;
    const rect = (host.captionButtonRects(client) orelse return null).get(kind);
    var origin: POINT = .{ .x = rect.left, .y = rect.top };
    if (sys.ClientToScreen(hwnd, &origin) == 0) return null;
    const width = rect.right - rect.left;
    const height = rect.bottom - rect.top;
    if (width <= 0 or height <= 0) return null;
    return .{
        .left = @floatFromInt(origin.x),
        .top = @floatFromInt(origin.y),
        .width = @floatFromInt(width),
        .height = @floatFromInt(height),
    };
}

/// Posts the command the mouse path sends. Posting rather than sending
/// keeps the UIA caller off the modal loop `SC_MAXIMIZE` / `SC_CLOSE`
/// can enter on the window's own thread.
fn captionButtonInvokeThunk(ctx: *anyopaque, kind: win32_uia.CaptionButtonKind) bool {
    const host: *Host = @ptrCast(@alignCast(ctx));
    const hwnd = host.hwnd orelse return false;
    if (!host.usingIntegratedTitlebar()) return false;
    const command = captionButtonCommand(kind, sys.IsZoomed(hwnd) != 0) orelse return false;
    return sys.PostMessageW(hwnd, c.WM_SYSCOMMAND, command, 0) != 0;
}

fn rootDisconnectThunk(ctx: *anyopaque) win32_uia.HRESULT {
    return (@as(*win32_uia.RootProvider, @ptrCast(@alignCast(ctx)))).disconnect();
}
fn rootReleaseThunk(ctx: *anyopaque) void {
    const provider: *win32_uia.RootProvider = @ptrCast(@alignCast(ctx));
    _ = win32_uia.RootProvider.Release(&provider.base);
}
fn paletteDisconnectThunk(ctx: *anyopaque) win32_uia.HRESULT {
    return (@as(*win32_uia.PaletteListProvider, @ptrCast(@alignCast(ctx)))).disconnect();
}
fn paletteReleaseThunk(ctx: *anyopaque) void {
    const provider: *win32_uia.PaletteListProvider = @ptrCast(@alignCast(ctx));
    _ = win32_uia.PaletteListProvider.Release(&provider.base);
}
fn terminalDisconnectThunk(ctx: *anyopaque) win32_uia.HRESULT {
    return (@as(*win32_uia.TerminalProvider, @ptrCast(@alignCast(ctx)))).disconnect();
}
fn terminalReleaseThunk(ctx: *anyopaque) void {
    const provider: *win32_uia.TerminalProvider = @ptrCast(@alignCast(ctx));
    _ = win32_uia.TerminalProvider.Release(&provider.base);
}
fn chromeDisconnectThunk(ctx: *anyopaque) win32_uia.HRESULT {
    return (@as(*win32_uia.ChromeControlProvider, @ptrCast(@alignCast(ctx)))).disconnect();
}
fn chromeReleaseThunk(ctx: *anyopaque) void {
    const provider: *win32_uia.ChromeControlProvider = @ptrCast(@alignCast(ctx));
    _ = win32_uia.ChromeControlProvider.Release(&provider.base);
}
fn detachChromeControlProvider(
    app: *App,
    slot: *?*win32_uia.ChromeControlProvider,
) void {
    const provider = slot.* orelse return;
    slot.* = null;
    provider.detach();
    scheduleDeferredUiaDisconnect(
        app,
        @ptrCast(provider),
        &chromeDisconnectThunk,
        &chromeReleaseThunk,
    );
}

fn overlayButtonDisconnectThunk(ctx: *anyopaque) win32_uia.HRESULT {
    return (@as(*win32_uia.SettingsControlProvider, @ptrCast(@alignCast(ctx)))).disconnect();
}

fn overlayButtonReleaseThunk(ctx: *anyopaque) void {
    const provider: *win32_uia.SettingsControlProvider = @ptrCast(@alignCast(ctx));
    _ = win32_uia.SettingsControlProvider.Release(&provider.base);
}

const OverlayButtonUiaProviders = struct {
    accept: ?*win32_uia.SettingsControlProvider,
    cancel: ?*win32_uia.SettingsControlProvider,
};

fn overlayButtonUiaProviderForHwnd(
    hwnd: HWND,
    accept_hwnd: ?HWND,
    cancel_hwnd: ?HWND,
    accept_provider: ?*win32_uia.SettingsControlProvider,
    cancel_provider: ?*win32_uia.SettingsControlProvider,
) ?*win32_uia.SettingsControlProvider {
    if (accept_hwnd) |accept| {
        if (hwnd == accept) return accept_provider;
    }
    if (cancel_hwnd) |cancel| {
        if (hwnd == cancel) return cancel_provider;
    }
    return null;
}

fn takeOverlayButtonUiaProviders(
    accept: *?*win32_uia.SettingsControlProvider,
    cancel: *?*win32_uia.SettingsControlProvider,
) OverlayButtonUiaProviders {
    const result: OverlayButtonUiaProviders = .{
        .accept = accept.*,
        .cancel = cancel.*,
    };
    accept.* = null;
    cancel.* = null;
    return result;
}

fn shouldRefocusAfterOverlayHide(
    focused: ?HWND,
    edit: ?HWND,
    accept: ?HWND,
    cancel: ?HWND,
    list: ?HWND,
) bool {
    const hwnd = focused orelse return false;
    return (edit != null and hwnd == edit.?) or
        (accept != null and hwnd == accept.?) or
        (cancel != null and hwnd == cancel.?) or
        (list != null and hwnd == list.?);
}

fn logUiActionError(comptime context: []const u8, err: anyerror) void {
    log.warn(context ++ " err={}", .{err});
}

fn runUiActionOrLog(comptime context: []const u8, action: anytype) void {
    _ = action catch |err| logUiActionError(context, err);
}

/// Run a chrome sync that reports "this changed", treating a failure as "no
/// change". The sync helpers work on terminal-controlled data and can fail on
/// it, and every `refreshChrome` call site already logs instead of
/// propagating. Paths reached from `App.tick` need the same containment: the
/// Win32 message loop calls `tick` with `try`, so an escaping error unwinds
/// `App.run` and exits the process rather than dropping one chrome update.
fn chromeSyncOrLog(comptime context: []const u8, sync: anytype) bool {
    return sync catch |err| {
        logUiActionError(context, err);
        return false;
    };
}

fn tabContainerProc(hwnd: HWND, msg: UINT, wParam: WPARAM, lParam: LPARAM) callconv(.winapi) LRESULT {
    if (getHost(hwnd)) |host| {
        if (msg == c.WM_GETOBJECT) {
            if (host.tab_container_uia_provider) |provider| {
                if (win32_uia.returnChromeControlProvider(hwnd, wParam, lParam, provider)) |lr| return lr;
            }
        }
        if (msg == c.WM_NCHITTEST) return c.HTTRANSPARENT;
        if (host.tab_container_prev_proc) |previous| return sys.CallWindowProcW(previous, hwnd, msg, wParam, lParam);
    }
    return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
}

const BannerKey = enum { ignore, press, dismiss, other_button };

/// What a key does on a focused banner button, or null when the button
/// leaves it to the focus-region keys (F6, and Escape on the update notice,
/// which goes back to the terminal: Dismiss records that version as
/// dismissed, so it takes a deliberate press). Space is the BUTTON's own:
/// it clicks on release. A held Enter or Escape repeats, and a repeat must
/// not press whatever button the first press left focused.
fn bannerButtonKey(has_message: bool, vk: WPARAM, repeat: bool) ?BannerKey {
    return switch (vk) {
        c.VK_RETURN => if (repeat) .ignore else .press,
        c.VK_ESCAPE => if (!has_message) null else if (repeat) .ignore else .dismiss,
        c.VK_TAB, c.VK_LEFT, c.VK_RIGHT => .other_button,
        else => null,
    };
}

test "bannerButtonKey presses once, closes a message on Escape and leaves the notice's Escape alone" {
    try std.testing.expectEqual(@as(?BannerKey, .press), bannerButtonKey(true, c.VK_RETURN, false));
    try std.testing.expectEqual(@as(?BannerKey, .press), bannerButtonKey(false, c.VK_RETURN, false));
    try std.testing.expectEqual(@as(?BannerKey, .ignore), bannerButtonKey(false, c.VK_RETURN, true));
    try std.testing.expectEqual(@as(?BannerKey, .dismiss), bannerButtonKey(true, c.VK_ESCAPE, false));
    try std.testing.expectEqual(@as(?BannerKey, .ignore), bannerButtonKey(true, c.VK_ESCAPE, true));
    try std.testing.expectEqual(@as(?BannerKey, null), bannerButtonKey(false, c.VK_ESCAPE, false));
    for ([_]WPARAM{ c.VK_TAB, c.VK_LEFT, c.VK_RIGHT }) |vk| {
        try std.testing.expectEqual(@as(?BannerKey, .other_button), bannerButtonKey(false, vk, false));
    }
    try std.testing.expectEqual(@as(?BannerKey, null), bannerButtonKey(true, c.VK_SPACE, false));
    try std.testing.expectEqual(@as(?BannerKey, null), bannerButtonKey(true, c.VK_F6, false));
}

const ConfirmKey = enum { accept, cancel, other_button, ignore };

/// What a key does on a confirm prompt's Allow or Cancel button, or null to
/// leave it to the button. Enter presses the focused button and Escape
/// cancels from either. Space only cancels: it is the key someone typing in
/// the terminal most often has on its way when a prompt takes focus, and it
/// is swallowed on Allow so the BUTTON cannot click on its release either.
/// A held key repeats into the prompt that just took focus, so a repeat
/// presses nothing.
fn confirmButtonKey(vk: WPARAM, repeat: bool, on_accept: bool) ?ConfirmKey {
    return switch (vk) {
        c.VK_ESCAPE => .cancel,
        c.VK_TAB, c.VK_LEFT, c.VK_RIGHT => .other_button,
        c.VK_RETURN => if (repeat) .ignore else if (on_accept) .accept else .cancel,
        c.VK_SPACE => if (repeat or on_accept) .ignore else .cancel,
        else => null,
    };
}

test "confirmButtonKey accepts only a fresh Enter on Allow" {
    try std.testing.expectEqual(@as(?ConfirmKey, .accept), confirmButtonKey(c.VK_RETURN, false, true));
    try std.testing.expectEqual(@as(?ConfirmKey, .ignore), confirmButtonKey(c.VK_RETURN, true, true));
    try std.testing.expectEqual(@as(?ConfirmKey, .ignore), confirmButtonKey(c.VK_SPACE, false, true));
    try std.testing.expectEqual(@as(?ConfirmKey, .ignore), confirmButtonKey(c.VK_SPACE, true, true));
    try std.testing.expectEqual(@as(?ConfirmKey, .cancel), confirmButtonKey(c.VK_RETURN, false, false));
    try std.testing.expectEqual(@as(?ConfirmKey, .cancel), confirmButtonKey(c.VK_SPACE, false, false));
    try std.testing.expectEqual(@as(?ConfirmKey, .ignore), confirmButtonKey(c.VK_SPACE, true, false));
    for ([_]bool{ false, true }) |on_accept| {
        try std.testing.expectEqual(@as(?ConfirmKey, .cancel), confirmButtonKey(c.VK_ESCAPE, true, on_accept));
        try std.testing.expectEqual(@as(?ConfirmKey, .other_button), confirmButtonKey(c.VK_TAB, false, on_accept));
        try std.testing.expectEqual(@as(?ConfirmKey, null), confirmButtonKey('A', false, on_accept));
    }
}

/// How long an `.info` banner stays up, in milliseconds: the system's
/// notification time (`SPI_GETMESSAGEDURATION`), which Settings offers from
/// 5 seconds to 5 minutes and defaults to 5.
fn bannerMessageDurationMs() UINT {
    var seconds: u32 = 0;
    if (sys.SystemParametersInfoW(c.SPI_GETMESSAGEDURATION, 0, @ptrCast(&seconds), 0) == 0) seconds = 0;
    return std.math.clamp(seconds, 5, 300) * std.time.ms_per_s;
}

/// Mouse on a banner button, or null for a message it leaves alone. The
/// BUTTON class takes keyboard focus on a press. A banner button must not:
/// every click would pull focus, and the focus reports a program asked for,
/// off the terminal, and a press dragged off before the release would leave
/// focus on the button. So the press, capture and click are done here.
fn bannerButtonMouse(host: *Host, hwnd: HWND, button: BannerButton, msg: UINT, lParam: LPARAM) ?LRESULT {
    switch (msg) {
        c.WM_LBUTTONDOWN, c.WM_LBUTTONDBLCLK => {
            _ = sys.SetCapture(hwnd);
            _ = sys.SendMessageW(hwnd, c.BM_SETSTATE, 1, 0);
            return 0;
        },
        c.WM_LBUTTONUP => {
            if (sys.GetCapture() != hwnd) return 0;
            var client: RECT = undefined;
            const inside = sys.GetClientRect(hwnd, &client) != 0 and pointInRect(.{
                .x = signedLowWord(lParamBits(lParam)),
                .y = signedHighWord(lParamBits(lParam)),
            }, client);
            // `WM_CAPTURECHANGED` clears the pressed look.
            _ = sys.ReleaseCapture();
            // May destroy every window (Install): touch nothing after.
            if (inside) host.activateBannerButton(button);
            return 0;
        },
        c.WM_CAPTURECHANGED => {
            _ = sys.SendMessageW(hwnd, c.BM_SETSTATE, 0, 0);
            return 0;
        },
        else => return null,
    }
}

fn hostBannerProc(hwnd: HWND, msg: UINT, wParam: WPARAM, lParam: LPARAM) callconv(.winapi) LRESULT {
    if (getHost(hwnd)) |host| {
        switch (msg) {
            c.WM_GETOBJECT => {
                if (host.banner_uia_provider) |provider| {
                    if (win32_uia.returnChromeControlProvider(hwnd, wParam, lParam, provider)) |lr| return lr;
                }
            },
            // Opaque, so it answers for its own rect, except where the
            // resize edges of a frameless window reach into it, as the
            // terminal pane does.
            c.WM_NCHITTEST => return if (host.resizesFrom(lParam)) c.HTTRANSPARENT else c.HTCLIENT,
            c.WM_SETCURSOR => {
                if ((lParamBits(lParam) & 0xFFFF) == c.HTCLIENT) {
                    _ = sys.SetCursor(sys.LoadCursorW(null, c.IDC_ARROW));
                    return 1;
                }
            },
            c.WM_ERASEBKGND => return 1,
            c.WM_PAINT => {
                var ps: PAINTSTRUCT = undefined;
                const hdc = sys.BeginPaint(hwnd, &ps) orelse return 0;
                defer _ = sys.EndPaint(hwnd, &ps);
                var client: RECT = undefined;
                if (sys.GetClientRect(hwnd, &client) != 0) host.paintBanner(hdc, client, isHighContrastActive());
                return 0;
            },
            c.WM_PRINTCLIENT => {
                const hdc: HDC = @ptrFromInt(wParam);
                var client: RECT = undefined;
                if (sys.GetClientRect(hwnd, &client) != 0) host.paintBanner(hdc, client, isHighContrastActive());
                return 0;
            },
            c.WM_MOUSEMOVE => {
                host.bannerPointerMoved();
                return 0;
            },
            c.WM_MOUSELEAVE => {
                host.bannerPointerLeft();
                return 0;
            },
            // The banner's buttons are its own children, so their owner
            // draw and their clicks (and UIA Invoke, which posts the same
            // command) come here.
            c.WM_DRAWITEM => {
                const draw: *const DRAWITEMSTRUCT = @ptrFromInt(@as(usize, @bitCast(lParam)));
                if (host.drawBannerButton(draw)) return 1;
            },
            c.WM_COMMAND => {
                const child: ?HWND = @ptrFromInt(@as(usize, @bitCast(lParam)));
                if (((wParam >> 16) & 0xFFFF) == c.BN_CLICKED) {
                    if (host.bannerButtonOf(child)) |button| {
                        host.activateBannerButton(button);
                        return 0;
                    }
                }
            },
            else => {},
        }
        if (host.banner_prev_proc) |previous| return sys.CallWindowProcW(previous, hwnd, msg, wParam, lParam);
    }
    return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
}

/// The UIA name for one confirm prompt line, from the text its control
/// was last given.
///
/// Reporting the control's own cached text rather than re-deriving it is
/// what keeps the spoken name and the drawn line the same string. Two
/// rules ride along, and both matter enough to be testable without a
/// live `Host`:
///
///   * Outside `.confirm` the control is hidden and still holds the
///     previous overlay's text. That is not a name any client should
///     read, so the answer is empty.
///   * A name that does not fit the caller's buffer is shortened on a
///     UTF-8 boundary, never dropped. `bufPrint` returns an error there
///     and the obvious `catch ""` would report nothing at the moment a
///     live region is about to be announced. The body can carry banner
///     text, which is arbitrary, so this is reachable.
fn confirmPromptUiaName(
    mode: HostOverlayMode,
    cached: ?[:0]const u8,
    buf: []u8,
    fallback: []const u8,
) []const u8 {
    if (mode != .confirm) return "";
    const text = cached orelse return "";
    return std.fmt.bufPrint(buf, "{s}", .{utf8BoundedPrefix(text, buf.len)}) catch fallback;
}

/// Whether a confirm prompt line is rendered by its own child window
/// rather than by chrome paint.
///
/// Per line, never for the pair: the title's rect is bounded by the query
/// frame and collapses on a narrow window while the body's still has
/// room, so a shared gate would answer that by taking the body out of the
/// UI Automation tree as well. The HWND is checked alongside the
/// placement because reading the placement alone is correct only for as
/// long as `layout` keeps touching it exclusively inside its null check.
fn confirmPromptLineOwnedByChild(
    mode: HostOverlayMode,
    hwnd: ?HWND,
    placement: ChildPlacement,
) bool {
    if (mode != .confirm) return false;
    return hwnd != null and placement.visible;
}

/// Foreground for one confirm prompt line: the overlay label colour for
/// the title, and the banner-kind-sensitive secondary colour for the
/// body, which is what keeps an error raised while a prompt is open
/// reading as an error. Mirrors the colours the chrome paint fallback
/// picks for the same two lines.
fn confirmPromptLineColor(
    theme: *const ThemeColors,
    title: bool,
    banner_kind: HostBannerKind,
    has_banner: bool,
) u32 {
    if (title) return theme.overlay_label_fg;
    return switch (if (has_banner) banner_kind else .none) {
        .none => theme.text_secondary,
        .info => theme.info_fg,
        .err => theme.error_fg,
    };
}

/// Subclass for the confirm prompt's title and body STATICs.
///
/// Exists for `WM_GETOBJECT`: a stock STATIC hands UIA only the default
/// HWND provider, which reports ControlType Text but no live-region
/// setting, so the prompt would appear in the tree without ever being
/// announced. `HTTRANSPARENT` keeps the two lines from eating clicks
/// aimed at the overlay band underneath them.
fn overlayPromptTextProc(hwnd: HWND, msg: UINT, wParam: WPARAM, lParam: LPARAM) callconv(.winapi) LRESULT {
    if (getHost(hwnd)) |host| {
        if (msg == c.WM_GETOBJECT) {
            if (host.overlayPromptTextProvider(hwnd)) |provider| {
                if (win32_uia.returnChromeControlProvider(hwnd, wParam, lParam, provider)) |lr| return lr;
            }
        }
        if (msg == c.WM_NCHITTEST) return c.HTTRANSPARENT;
        if (host.overlayPromptTextPrevProc(hwnd)) |previous| {
            return sys.CallWindowProcW(previous, hwnd, msg, wParam, lParam);
        }
    }
    return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
}

const ButtonTooltipAction = enum {
    none,
    show,
    /// Hide, and keep hidden until a `.hide` for the same button: the pointer
    /// leaving it, or the button being hidden or destroyed.
    dismiss,
    hide,
};

/// What a message to a `hostButtonProc` button does to the search buttons'
/// hover tooltip. Only a search button arms the hover that shows one, and a
/// hide is a no-op for a button whose tooltip is not up, so the proc's other
/// buttons need no case of their own.
fn buttonTooltipAction(msg: UINT, wParam: WPARAM) ButtonTooltipAction {
    return switch (msg) {
        c.WM_MOUSEHOVER => .show,
        // A click answers the question the tooltip was there for. Hiding it
        // is not enough: the BUTTON class releases a left click's capture on
        // the button-up, the system follows that with a WM_MOUSEMOVE even
        // when the pointer has not moved, and that re-arms the hover, which
        // would bring the tooltip back under a still pointer.
        c.WM_LBUTTONDOWN, c.WM_RBUTTONDOWN, c.WM_MBUTTONDOWN => .dismiss,
        c.WM_MOUSELEAVE => .hide,
        // A button hidden under a resting pointer (Escape closing the search
        // bar, a tab switch) sends no WM_MOUSELEAVE, so its tooltip would
        // outlive it. `ShowWindow(SW_HIDE)` does send this, whatever hid the
        // button.
        c.WM_SHOWWINDOW => if (wParam == 0) .hide else .none,
        // A pane closing while its window stays open destroys its search
        // buttons (`Surface.destroy` -> `destroySearchBarControls`) without
        // hiding them first. `windowDestroyed` clears the hovered button
        // afterwards, which takes the popup down too, since the popup is only
        // up for the hovered button; this drops it with the button instead.
        // Closing the window reaches here as well: each button's own window
        // data still names the Host, which outlives the buttons, and the
        // Host's WM_DESTROY has already destroyed the popup
        // (`destroyChildControls`), so hiding finds no popup to hide.
        c.WM_DESTROY => .hide,
        else => .none,
    };
}

/// Which `hostButtonProc` button the shared tooltip popup is up for, and which
/// one a click keeps it down for. It holds no windows, so the order of hovers,
/// clicks and leaves that decides whether a tooltip comes back can be tested
/// without the popup or the real cursor.
const ButtonTooltip = struct {
    /// The button the popup describes. At most one of this and
    /// `Host.tab_tooltip_tab_id` is set.
    shown: ?HWND = null,
    /// The last clicked button, whether or not its tooltip was up, until the
    /// pointer leaves it or it is hidden or destroyed. Its tooltip stays down
    /// meanwhile, as a stock Windows tooltip stays down after a click until
    /// the pointer leaves the tool.
    dismissed: ?HWND = null,

    const Effect = enum { none, present, hide };

    /// Record `action` on `button` and say what it does to the popup. The
    /// caller makes `shown` follow: presenting sets it, hiding clears it.
    fn apply(self: *ButtonTooltip, action: ButtonTooltipAction, button: HWND) Effect {
        switch (action) {
            .none => return .none,
            .show => {
                if (self.dismissed == button) return .none;
                // The hover timer re-arms on every pointer move inside the
                // button, so this fires repeatedly while the tooltip is up.
                if (self.shown == button) return .none;
                return .present;
            },
            .dismiss => self.dismissed = button,
            .hide => {
                if (self.dismissed == button) self.dismissed = null;
            },
        }
        return if (self.shown == button) .hide else .none;
    }
};

fn hostButtonProc(hwnd: HWND, msg: UINT, wParam: WPARAM, lParam: LPARAM) callconv(.winapi) LRESULT {
    const host = getHost(hwnd);
    if (host) |v| {
        if (msg == c.WM_NCHITTEST and v.resizesFromTop(lParam)) return c.HTTRANSPARENT;
        if (msg == c.WM_GETOBJECT) {
            if (v.chromeUiaProviderForHwnd(hwnd)) |provider| {
                if (win32_uia.returnChromeControlProvider(hwnd, wParam, lParam, provider)) |lr| return lr;
            }
            // The overlay accept / cancel pair. Their providers were
            // built in `ensureOverlayControls` and torn down with the
            // rest, but `overlayButtonUiaProviderForHwnd` had no caller,
            // so UIA only ever saw the default HWND provider: measured
            // with `AutomationElement.FindAll` on a live clipboard-paste
            // prompt, "Allow" and "Cancel" came back as ControlType Pane
            // with no Invoke pattern. Returning the provider makes them
            // announce as buttons and gives assistive technology a way
            // to press them.
            if (overlayButtonUiaProviderForHwnd(
                hwnd,
                v.overlay_accept_hwnd,
                v.overlay_cancel_hwnd,
                v.overlay_accept_uia_provider,
                v.overlay_cancel_uia_provider,
            )) |provider| {
                if (win32_uia.returnSettingsControlProvider(hwnd, wParam, lParam, provider)) |lr| return lr;
            }
        }
        if (msg == c.WM_KEYDOWN) v.noteChromeKeyInput(wParam);
        if (msg == c.WM_LBUTTONDOWN or msg == c.WM_RBUTTONDOWN or msg == c.WM_MBUTTONDOWN) {
            v.noteChromePointerInput();
        }
        if (v.bannerButtonOf(hwnd)) |button| {
            // May destroy every window (Install): touch nothing after.
            if (bannerButtonMouse(v, hwnd, button, msg, lParam)) |result| return result;
        }
        switch (v.button_tooltip.apply(buttonTooltipAction(msg, wParam), hwnd)) {
            .none => {},
            .present => v.showSearchButtonTooltip(hwnd),
            .hide => v.hideTabTooltip(),
        }
        // Focus-region keys for the tab-strip action buttons and the
        // docked search controls. Overlay buttons are deliberately
        // excluded: they belong to a modal overlay, not to the window's
        // focus-region cycle.
        if (msg == c.WM_KEYDOWN) {
            if (v.bannerButtonOf(hwnd)) |button| {
                // May destroy every window (Install): touch nothing after.
                if (v.handleBannerButtonKey(hwnd, button, wParam, lParam)) return 0;
            }
        }
        if (msg == c.WM_KEYDOWN and !v.isOverlayButton(hwnd)) {
            // The docked search buttons already own Escape (it dismisses
            // the search), so only Ctrl+F6 is taken from them here.
            const allow_escape = v.searchControlSurface(hwnd) == null;
            if (v.handleFocusRegionKey(hwnd, wParam, allow_escape)) return 0;
        }
        // Keyboard routing for the overlay accept/cancel pair. In
        // confirm mode the EDIT control is hidden and focus lands on
        // the accept button; without this path Esc has no effect
        // because `overlayEditProc`'s Esc handler only runs when the
        // (hidden) EDIT has focus. Tab/Shift+Tab cycle between the
        // two buttons; arrow keys also cycle for screen-reader
        // users who navigate via arrows.
        if (msg == c.WM_KEYDOWN and v.isOverlayButton(hwnd)) {
            const reverse = if (wParam == c.VK_TAB) keyPressed(c.VK_SHIFT) else wParam == c.VK_LEFT;
            if (v.overlay_mode == .confirm) {
                const repeat = (lParamBits(lParam) & c.KF_REPEAT) != 0;
                const action = confirmButtonKey(wParam, repeat, hwnd == v.overlay_accept_hwnd);
                if (action != ConfirmKey.accept) v.holdProgramConfirmForKey(wParam);
                if (action) |key| {
                    switch (key) {
                        .accept => v.invokeConfirmAccept(),
                        .cancel => v.invokeConfirmCancel(),
                        .other_button => _ = v.focusRelativeOverlayControl(hwnd, reverse),
                        .ignore => {},
                    }
                    return 0;
                }
            } else switch (wParam) {
                c.VK_ESCAPE => {
                    v.hideOverlay();
                    return 0;
                },
                c.VK_TAB, c.VK_LEFT, c.VK_RIGHT => {
                    _ = v.focusRelativeOverlayControl(hwnd, reverse);
                    return 0;
                },
                else => {},
            }
        }
        if (msg == c.WM_KEYDOWN and v.isSearchBarButton(hwnd)) {
            if (v.searchControlSurface(hwnd)) |surface| {
                if (searchButtonKeyAction(wParam, keyPressed(c.VK_SHIFT))) |action| {
                    if (dockedSearchCoreDirectionFromKeyAction(action)) |dir| {
                        _ = surface.navigateDockedSearch(dir) catch |err| {
                            logUiActionError("docked search button navigation failed", err);
                        };
                        return 0;
                    }
                    switch (action) {
                        .dismiss => {
                            _ = v.dismissActiveSearch();
                            return 0;
                        },
                        else => {},
                    }
                }
            }
        }
        switch (msg) {
            c.WM_SETFOCUS => {
                if (v.bannerButtonOf(hwnd) != null) {
                    v.banner_focused = true;
                    v.syncBannerExpiry();
                }
                if (v.searchControlSurface(hwnd)) |surface| {
                    v.app.activateSurfaceNoFocus(surface);
                }
                if (v.chromeUiaProviderForHwnd(hwnd)) |provider| {
                    provider.raiseFocusChanged();
                }
            },
            c.WM_KILLFOCUS => {
                if (v.bannerButtonOf(hwnd) != null) {
                    v.banner_focused = false;
                    v.syncBannerExpiry();
                }
            },
            c.WM_MOUSEMOVE => {
                // The search bar's icon buttons also arm TME_HOVER, as the tab
                // buttons do for their title tooltip, so a dwell names them.
                const search_button = v.isSearchBarButton(hwnd);
                var track: TRACKMOUSEEVENT = .{
                    .cbSize = @sizeOf(TRACKMOUSEEVENT),
                    .dwFlags = if (search_button) c.TME_LEAVE | c.TME_HOVER else c.TME_LEAVE,
                    .hwndTrack = hwnd,
                    .dwHoverTime = if (search_button) c.HOVER_DEFAULT else 0,
                };
                _ = sys.TrackMouseEvent(&track);
                v.setHoveredButton(hwnd);
            },
            c.WM_MOUSELEAVE => {
                if (v.isHoveredButton(hwnd)) v.setHoveredButton(null);
            },
            c.WM_RBUTTONUP => {
                if (v.new_tab_hwnd != null and hwnd == v.new_tab_hwnd.?) {
                    if (v.openSelectedProfileOrFallback(.window)) return 0;
                }
            },
            c.WM_MBUTTONUP => {
                if (v.new_tab_hwnd != null and hwnd == v.new_tab_hwnd.?) {
                    if (v.openSelectedProfileOrFallback(.split)) return 0;
                }
            },
            else => {},
        }

        const prev = if (v.isOverlayButton(hwnd))
            v.overlay_button_prev_proc
        else if (v.searchControlSurface(hwnd)) |surface|
            surface.searchBarButtonPrevProc(hwnd)
        else
            v.chrome_button_prev_proc;
        if (prev) |proc| {
            return sys.CallWindowProcW(proc, hwnd, msg, wParam, lParam);
        }
    }
    return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
}

fn tabButtonProc(hwnd: HWND, msg: UINT, wParam: WPARAM, lParam: LPARAM) callconv(.winapi) LRESULT {
    const host = getHost(hwnd);
    if (host) |v| {
        if (msg == c.WM_NCHITTEST and v.resizesFromTop(lParam)) return c.HTTRANSPARENT;
        if (v.tabIndexForButton(hwnd)) |index| {
            if (msg == c.WM_GETOBJECT) {
                if (v.tabs.items[index].uia_provider) |provider| {
                    if (win32_uia.returnChromeControlProvider(hwnd, wParam, lParam, provider)) |lr| return lr;
                }
            }
            switch (msg) {
                win32_uia.widgets.tab_close_message => {
                    // Revalidate closability after Invoke waited in the queue:
                    // the tab may have moved, scrolled out, or become hidden.
                    if (tabCloseAction(v.tabs.items.len) != .none and v.tabs.items[index].id == wParam and
                        v.shouldShowTabBar() and sys.IsWindowVisible(hwnd) != 0)
                    {
                        _ = v.closeTabFromStrip(index);
                    }
                    return 0;
                },
                c.WM_SETFOCUS => {
                    if (v.tabs.items[index].uia_provider) |provider| {
                        provider.raiseFocusChanged();
                    }
                },
                c.WM_LBUTTONDOWN => {
                    v.noteChromePointerInput();
                    // A click answers the question the tooltip was there to
                    // answer, and the strip is about to relayout under it.
                    v.hideTabTooltip();
                    const down_x = signedLowWord(lParamBits(lParam));
                    var btn_rect: RECT = undefined;
                    _ = sys.GetClientRect(hwnd, &btn_rect);
                    const close_left = btn_rect.right - v.scaled(host_tab_close_zone_width);
                    if (down_x >= close_left and tabCloseAction(v.tabs.items.len) != .none) {
                        // Click in close zone — capture for mouseup but don't start drag
                        _ = sys.SetCapture(hwnd);
                    } else {
                        // Start potential drag: record origin
                        v.tab_drag_index = index;
                        v.tab_drag_start_x = down_x;
                        v.tab_drag_start_y = signedHighWord(lParamBits(lParam));
                        v.tab_drag_active = false;
                        _ = sys.SetCapture(hwnd);
                    }
                    return 0;
                },
                c.WM_LBUTTONUP => {
                    const drag_index = v.tab_drag_index;
                    const was_drag = v.tab_drag_active;
                    const drop_operation = v.tab_drop_operation;
                    const drop_target_surface = v.tab_drop_target_surface;
                    v.tab_drag_index = null;
                    v.tab_drag_active = false;
                    _ = sys.ReleaseCapture();
                    if (was_drag) {
                        if (drag_index) |source_index| {
                            v.tab_drop_operation = drop_operation;
                            v.tab_drop_target_surface = drop_target_surface;
                            const transferred = v.commitTabDropSplit(source_index);
                            v.hideTabDropPreview();
                            if (transferred) return 0;
                        }
                    }
                    v.hideTabDropPreview();
                    const click_x = signedLowWord(lParamBits(lParam));
                    var btn_rect: RECT = undefined;
                    _ = sys.GetClientRect(hwnd, &btn_rect);
                    const close_left = btn_rect.right - v.scaled(host_tab_close_zone_width);
                    switch (tabButtonMouseUpAction(
                        drag_index,
                        was_drag,
                        click_x,
                        close_left,
                        v.tabs.items.len,
                    )) {
                        .activate => {
                            _ = v.activateTabIndex(index);
                        },
                        .close => _ = v.closeTabFromStrip(index),
                        .none => {},
                    }
                    return 0;
                },
                c.WM_CAPTURECHANGED => {
                    v.tab_drag_index = null;
                    v.tab_drag_active = false;
                    v.hideTabDropPreview();
                },
                c.WM_MOUSEMOVE => {
                    // TME_HOVER arms WM_MOUSEHOVER for the title tooltip. The
                    // timer restarts on every move, so it only fires once the
                    // pointer has actually settled on the tab.
                    var track: TRACKMOUSEEVENT = .{
                        .cbSize = @sizeOf(TRACKMOUSEEVENT),
                        .dwFlags = c.TME_LEAVE | c.TME_HOVER,
                        .hwndTrack = hwnd,
                        .dwHoverTime = c.HOVER_DEFAULT,
                    };
                    _ = sys.TrackMouseEvent(&track);
                    v.setHoveredButton(hwnd);

                    // Handle tab drag reorder
                    if (v.tab_drag_index) |drag_idx| {
                        const mouse_x = signedLowWord(lParamBits(lParam));
                        const mouse_y = signedHighWord(lParamBits(lParam));
                        const dx = if (mouse_x > v.tab_drag_start_x)
                            mouse_x - v.tab_drag_start_x
                        else
                            v.tab_drag_start_x - mouse_x;
                        const dy = if (mouse_y > v.tab_drag_start_y)
                            mouse_y - v.tab_drag_start_y
                        else
                            v.tab_drag_start_y - mouse_y;

                        // Activate drag after 5px threshold
                        if (!v.tab_drag_active and dx + dy > 5) {
                            v.tab_drag_active = true;
                            v.hideTabTooltip();
                        }

                        if (v.tab_drag_active) {
                            // A vertical excursion resolves an exact pane and
                            // labeled split operation. Staying in the tab row
                            // keeps the established ordered-reorder gesture.
                            var pt: POINT = .{ .x = mouse_x, .y = mouse_y };
                            _ = sys.ClientToScreen(hwnd, &pt);
                            v.updateTabDropPreview(drag_idx, pt);
                            if (v.tab_drop_operation == .none) {
                                if (v.tabIndexAtScreenX(pt.x)) |target_idx| {
                                    if (target_idx != drag_idx and v.tabs.items.len > 1) {
                                        v.swapTabs(drag_idx, target_idx);
                                        v.tab_drag_index = target_idx;
                                        v.tab_drag_start_x = mouse_x;
                                        v.tab_drag_start_y = mouse_y;
                                    }
                                }
                            }
                        }
                    }
                },
                c.WM_MOUSEHOVER => {
                    v.showTabTooltip(hwnd);
                },
                c.WM_MOUSELEAVE => {
                    v.hideTabTooltip();
                    if (v.isHoveredButton(hwnd)) v.setHoveredButton(null);
                },
                c.WM_KEYDOWN => {
                    v.noteChromeKeyInput(wParam);
                    if (v.handleFocusRegionKey(hwnd, wParam, true)) return 0;
                    if (tabButtonKeyAction(wParam, keyPressed(c.VK_CONTROL))) |action| {
                        switch (action) {
                            // Activating a tab moves focus into its
                            // terminal, which is what Enter on a tab
                            // should do. Arrow/Home/End navigation must
                            // not: it activates as it moves, so focus is
                            // pulled back to the strip afterwards or the
                            // next arrow press would go to the PTY.
                            .activate => {
                                _ = v.activateTabIndex(index);
                                return 0;
                            },
                            .previous => {
                                _ = v.activateTabByDirection(.previous);
                                v.restoreTabStripFocus();
                                return 0;
                            },
                            .next => {
                                _ = v.activateTabByDirection(.next);
                                v.restoreTabStripFocus();
                                return 0;
                            },
                            .first => {
                                _ = v.activateTabByDirection(@enumFromInt(1));
                                v.restoreTabStripFocus();
                                return 0;
                            },
                            .last => {
                                _ = v.activateTabByDirection(.last);
                                v.restoreTabStripFocus();
                                return 0;
                            },
                            .move_previous => {
                                if (v.activateTabIndex(index)) {
                                    if (v.activeSurface()) |surface| {
                                        runUiActionOrLog("tab key move previous failed", v.app.moveTab(.{ .surface = surface.core() }, .{ .amount = -1 }));
                                        return 0;
                                    }
                                }
                            },
                            .move_next => {
                                if (v.activateTabIndex(index)) {
                                    if (v.activeSurface()) |surface| {
                                        runUiActionOrLog("tab key move next failed", v.app.moveTab(.{ .surface = surface.core() }, .{ .amount = 1 }));
                                        return 0;
                                    }
                                }
                            },
                            .move_first => {
                                if (v.activateTabIndex(index)) {
                                    if (v.activeSurface()) |surface| {
                                        const amount = moveTabAmountToEdge(v.tabs.items.len, index, true);
                                        if (amount != 0) {
                                            runUiActionOrLog("tab key move first failed", v.app.moveTab(.{ .surface = surface.core() }, .{ .amount = amount }));
                                        }
                                        return 0;
                                    }
                                }
                            },
                            .move_last => {
                                if (v.activateTabIndex(index)) {
                                    if (v.activeSurface()) |surface| {
                                        const amount = moveTabAmountToEdge(v.tabs.items.len, index, false);
                                        if (amount != 0) {
                                            runUiActionOrLog("tab key move last failed", v.app.moveTab(.{ .surface = surface.core() }, .{ .amount = amount }));
                                        }
                                        return 0;
                                    }
                                }
                            },
                            .rename => {
                                if (v.activateTabIndex(index)) {
                                    if (v.activeSurface()) |surface| {
                                        runUiActionOrLog("tab key rename failed", surface.promptTitle(.tab));
                                        return 0;
                                    }
                                }
                            },
                            .close => {
                                if (v.closeTabFromStrip(index)) return 0;
                            },
                            .overview => {
                                if (v.activateTabIndex(index)) {
                                    if (v.activeSurface()) |surface| {
                                        runUiActionOrLog("tab key overview failed", surface.toggleTabOverview());
                                        return 0;
                                    }
                                }
                            },
                        }
                    }
                },
                c.WM_MBUTTONUP => {
                    if (v.closeTabFromStrip(index)) return 0;
                },
                c.WM_LBUTTONDBLCLK => {
                    if (v.activateTabIndex(index)) {
                        if (v.activeSurface()) |surface| {
                            runUiActionOrLog("tab double-click rename failed", surface.promptTitle(.tab));
                            return 0;
                        }
                    }
                },
                c.WM_RBUTTONUP => {
                    if (v.activateTabIndex(index)) {
                        v.showTabContextMenu(hwnd, index);
                        return 0;
                    }
                },
                else => {},
            }

            if (v.tabs.items[index].button_prev_proc) |proc| {
                return sys.CallWindowProcW(proc, hwnd, msg, wParam, lParam);
            }
        }
    }
    return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
}

fn searchLabelProc(hwnd: HWND, msg: UINT, wParam: WPARAM, lParam: LPARAM) callconv(.winapi) LRESULT {
    if (getSurface(hwnd)) |surface| {
        if (msg == c.WM_GETOBJECT) {
            if (surface.searchLabelUiaProvider(hwnd)) |provider| {
                if (win32_uia.returnChromeControlProvider(hwnd, wParam, lParam, provider)) |lr| return lr;
            }
        }
        if (surface.searchLabelPrevProc(hwnd)) |previous| return sys.CallWindowProcW(previous, hwnd, msg, wParam, lParam);
    }
    return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
}

fn searchEditProc(hwnd: HWND, msg: UINT, wParam: WPARAM, lParam: LPARAM) callconv(.winapi) LRESULT {
    const host = getHost(hwnd);
    if (msg == c.WM_GETOBJECT) {
        if (host) |v| {
            if (v.searchControlSurface(hwnd)) |surface| {
                if (surface.search_bar_edit_uia_provider) |provider| {
                    if (win32_uia.returnTerminalProvider(hwnd, wParam, lParam, provider)) |lr| return lr;
                }
            }
        }
    }
    if (host) |v| {
        if (v.searchControlSurface(hwnd)) |surface| switch (msg) {
            c.WM_SETFOCUS => {
                v.app.activateSurfaceNoFocus(surface);
                surface.invalidateSearchBarChildPaint();
            },
            c.WM_KILLFOCUS => {
                surface.invalidateSearchBarChildPaint();
            },
            c.WM_LBUTTONDOWN => v.noteChromePointerInput(),
            c.WM_CHAR => {
                if (wParam == c.VK_RETURN or wParam == c.VK_ESCAPE) return 0;
            },
            c.WM_KEYDOWN, c.WM_SYSKEYDOWN => {
                v.noteChromeKeyInput(wParam);
                // Escape stays with the search bar, which dismisses
                // itself and returns focus to the terminal; only Ctrl+F6
                // is taken for the focus-region cycle.
                if (v.handleFocusRegionKey(hwnd, wParam, false)) return 0;
                if (wParam == c.VK_RETURN) {
                    _ = surface.navigateDockedSearch(dockedSearchEnterDirection(keyPressed(c.VK_SHIFT))) catch |err| {
                        logUiActionError("docked search enter navigation failed", err);
                    };
                    return 0;
                }
                if (dockedSearchArrowDirection(wParam)) |dir| {
                    _ = surface.navigateDockedSearch(dir) catch |err| {
                        logUiActionError("docked search arrow navigation failed", err);
                    };
                    return 0;
                }
                if (searchButtonKeyAction(wParam, keyPressed(c.VK_SHIFT))) |action| {
                    if (dockedSearchCoreDirectionFromKeyAction(action)) |dir| {
                        _ = surface.navigateDockedSearch(dir) catch |err| {
                            logUiActionError("docked search key navigation failed", err);
                        };
                        return 0;
                    }
                    switch (action) {
                        .dismiss => {
                            surface.closeDockedSearchBar(true, true) catch |err| {
                                logUiActionError("docked search key close failed", err);
                            };
                            return 0;
                        },
                        else => {},
                    }
                }
            },
            else => {},
        };
    }

    const result = if (host) |v| blk: {
        if (v.searchControlSurface(hwnd)) |surface| {
            if (surface.search_bar_edit_prev_proc) |proc| {
                break :blk sys.CallWindowProcW(proc, hwnd, msg, wParam, lParam);
            }
        }
        break :blk sys.DefWindowProcW(hwnd, msg, wParam, lParam);
    } else sys.DefWindowProcW(hwnd, msg, wParam, lParam);
    if (host) |v| {
        if (v.searchControlSurface(hwnd)) |surface| {
            if (surface.search_bar_edit_uia_provider) |provider| switch (msg) {
                c.WM_SETFOCUS => win32_uia.events.raiseFocusChanged(&provider.base),
                c.WM_KEYUP, c.WM_LBUTTONUP, c.EM_SETSEL => surface.raiseSearchEditSelectionChangedIfNeeded(),
                else => {},
            };
        }
    }
    return result;
}

fn overlayEditProc(hwnd: HWND, msg: UINT, wParam: WPARAM, lParam: LPARAM) callconv(.winapi) LRESULT {
    const host = getHost(hwnd);
    // This proc is shared with the confirm preview pane, which is the
    // same EDIT class but a different control. The UIA provider below
    // belongs to the query field alone; handing it out for the preview
    // would report one control's name and selection for the other.
    const is_query_edit = if (host) |v|
        v.overlay_edit_hwnd != null and hwnd == v.overlay_edit_hwnd.?
    else
        false;
    if (msg == c.WM_GETOBJECT) {
        if (host) |v| {
            if (is_query_edit) {
                if (v.overlay_edit_uia_provider) |provider| {
                    if (win32_uia.returnTerminalProvider(hwnd, wParam, lParam, provider)) |lr| return lr;
                }
            } else if (v.overlay_preview_uia_provider) |provider| {
                if (win32_uia.returnSettingsControlProvider(hwnd, wParam, lParam, provider)) |lr| return lr;
            }
        }
    }
    if (host) |v| switch (msg) {
        c.WM_LBUTTONDOWN => v.noteChromePointerInput(),
        c.WM_CHAR => {
            if (wParam == c.VK_ESCAPE) return 0;
            if (wParam == c.VK_RETURN) {
                // The confirm preview pane accepts on Enter too, but not on
                // a held one (see `confirmButtonKey`), and never a
                // program's prompt: Tab from its Cancel lands here, and
                // Tab then Enter is how someone finishes typing a command.
                const repeat = (lParamBits(lParam) & c.KF_REPEAT) != 0;
                if (v.overlay_mode == .confirm and (repeat or v.programConfirmOpen())) return 0;
                if (v.overlay_mode != .profile) {
                    runUiActionOrLog("overlay submit failed", v.submitOverlay());
                }
                return 0;
            }
        },

        c.WM_KEYDOWN, c.WM_SYSKEYDOWN => {
            // Tab out of the query is how the keyboard reaches the Close
            // button; it has to show its ring when it gets there.
            v.noteChromeKeyInput(wParam);
            if (v.overlay_mode == .confirm) v.holdProgramConfirmForKey(wParam);
            if (v.commandPaletteToggleKeyMessage(msg, wParam, lParam)) {
                _ = v.dismissCommandPalette();
                return 0;
            }
            if (v.overlay_mode == .command_palette) {
                if (wParam == c.VK_UP or wParam == c.VK_DOWN) {
                    // Up/Down move through the live result list instead of
                    // editing the query text.
                    if (v.moveListSelection(wParam == c.VK_UP)) return 0;
                }
                if (wParam == c.VK_TAB) {
                    const reverse = keyPressed(c.VK_SHIFT);
                    if ((v.completeCommandPalette(reverse) catch false)) return 0;
                }
            }
            if (wParam == c.VK_TAB and v.focusRelativeOverlayControl(hwnd, keyPressed(c.VK_SHIFT))) return 0;
            if (v.overlay_mode == .tab_overview) {
                if (wParam == c.VK_UP or wParam == c.VK_DOWN) {
                    if ((v.stepTabOverviewSelection(wParam == c.VK_UP) catch false)) return 0;
                }
            }
            if (v.overlay_mode == .profile) {
                const profiles_ready = v.profilesForChrome();
                if (profiles_ready) {
                    if (clearQuickSlotPinsRequested(wParam, keyPressed(c.VK_MENU), keyPressed(c.VK_SHIFT))) {
                        if (v.clearQuickSlotPins()) return 0;
                    }
                    if (quickSlotPinOrdinalFromKey(wParam, keyPressed(c.VK_MENU), keyPressed(c.VK_SHIFT))) |slot_ordinal| {
                        if (v.assignSelectedProfileToQuickSlot(slot_ordinal)) return 0;
                    }
                    if (quickSlotShortcutProfileIndex(v.profiles.?.len, v.selectedProfileIndex(), wParam, keyPressed(c.VK_MENU))) |index| {
                        if (v.quickOpenProfileIndex(index, v.app.launcher_profile_target)) return 0;
                    }
                }
                if (keyPressed(c.VK_CONTROL)) {
                    if (profileShortcutIndexFromKey(wParam)) |index| {
                        if (v.quickOpenProfileIndex(index, v.app.launcher_profile_target)) return 0;
                    }
                }
                if (wParam == c.VK_RETURN) {
                    runUiActionOrLog(
                        "profile overlay submit failed",
                        v.submitProfileOverlay(resolveProfileOpenTarget(
                            v.app.launcher_profile_target,
                            keyPressed(c.VK_SHIFT),
                            keyPressed(c.VK_CONTROL),
                        )),
                    );
                    return 0;
                }
                if (wParam == c.VK_UP or wParam == c.VK_DOWN) {
                    if ((v.stepProfileSelection(wParam == c.VK_UP) catch false)) return 0;
                }
            }
            if (wParam == c.VK_ESCAPE) {
                if (v.overlay_mode == .confirm) {
                    // Same no-access-after-dispatch discipline as
                    // the mouse-click confirm paths — cancel
                    // callbacks may tear down the Host.
                    v.invokeConfirmCancel();
                    return 0;
                }
                v.hideOverlay();
                runUiActionOrLog("overlay escape layout failed", v.layout());
                refocusActiveSurface(v);
                return 0;
            }
        },

        else => {},
    };

    const result = if (host) |v| blk: {
        const saved = if (is_query_edit) v.overlay_edit_prev_proc else v.overlay_preview_prev_proc;
        if (saved) |proc| {
            break :blk sys.CallWindowProcW(proc, hwnd, msg, wParam, lParam);
        }
        break :blk sys.DefWindowProcW(hwnd, msg, wParam, lParam);
    } else sys.DefWindowProcW(hwnd, msg, wParam, lParam);
    if (is_query_edit) {
        if (host) |v| {
            if (v.overlay_edit_uia_provider) |provider| switch (msg) {
                c.WM_SETFOCUS => win32_uia.events.raiseFocusChanged(&provider.base),
                c.WM_KEYUP, c.WM_LBUTTONUP, c.EM_SETSEL => v.raiseOverlayEditSelectionChangedIfNeeded(),
                else => {},
            };
        }
    }
    return result;
}

fn applyConsoleWindowVisibility(hwnd: HWND, visible: bool) void {
    if (visible) {
        if (sys.IsIconic(hwnd) == 0) return;
        _ = sys.DefWindowProcW(hwnd, c.WM_SYSCOMMAND, c.SC_RESTORE, 0);
    } else {
        if (sys.IsIconic(hwnd) != 0) return;
        _ = sys.DefWindowProcW(hwnd, c.WM_SYSCOMMAND, c.SC_MINIMIZE, 0);
    }
}

fn hostWindowProc(hwnd: HWND, msg: UINT, wParam: WPARAM, lParam: LPARAM) callconv(.winapi) LRESULT {
    if (msg == c.WM_NCCREATE) {
        const cs: *const CREATESTRUCTW = @ptrFromInt(@as(usize, @bitCast(lParam)));
        if (cs.lpCreateParams) |ptr| {
            setWindowData(hwnd, ptr);
        }
    }

    const host = getHost(hwnd);
    switch (msg) {
        c.WM_WINHOSTTY_CONSOLE_VISIBILITY => {
            if (host != null) applyConsoleWindowVisibility(hwnd, wParam != 0);
            return 0;
        },
        c.WM_WINHOSTTY_HOST_NEW_TAB => {
            if (host) |v| v.dispatchDeferredNewTab(if (wParam == 0) null else @as(u64, @intCast(wParam)));
            return 0;
        },
        c.WM_NCACTIVATE => {
            if (host) |v| {
                v.setWindowActive(wParam != 0);
            }
            return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
        },
        c.WM_ACTIVATE => {
            // Cloak/uncloak (virtual-desktop switches, shell animations)
            // has NO window message -- the documented signal is the
            // EVENT_OBJECT_CLOAKED/UNCLOAKED WinEvent, which
            // `win32_power.Notifications` now hooks. This refresh is the
            // belt-and-braces path for a missed or unavailable hook: a
            // cloaked host renders nothing, so a stale `surfaces_visible`
            // would otherwise mean a permanently frozen window.
            if (host) |v| v.refreshSurfaceVisibility();
            if ((wParam & 0xFFFF) != c.WA_INACTIVE) {
                // The user brought this window forward: its active tab is
                // seen even if focus lands on the chrome, not a terminal.
                if (host) |v| v.app.acknowledgeTab(v, v.active_tab);
            }
            if ((wParam & 0xFFFF) == c.WA_INACTIVE) {
                if (host) |v| {
                    // The tab tooltip is a top-level popup, so losing the
                    // window is not enough to take it down: a pointer that
                    // never left the tab sends no WM_MOUSELEAVE, and the popup
                    // would sit over whatever the user switched to.
                    v.hideTabTooltip();
                    if (v.quick_terminal and v.app.config.@"quick-terminal-autohide") {
                        if (sys.IsWindowVisible(hwnd) != 0) App.hideQuickTerminalHost(v);
                    }
                }
            }
            return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
        },
        // Per-host tween heartbeat. Runs at ~16 ms while any chrome
        // animation is active; stops as soon as the scheduler empties.
        // Separate from the App-level quit timer, which uses
        // `sys.SetTimer(null, …)` on the thread queue.
        c.WM_TIMER => {
            if (wParam == c.TWEEN_TIMER_ID) {
                if (host) |v| v.tickTweens();
                return 0;
            }
            if (wParam == c.SEARCH_TIMER_ID) {
                if (host) |v| v.tickSearchBars();
                return 0;
            }
            if (wParam == c.SCROLLBAR_TIMER_ID) {
                if (host) |v| v.tickScrollbars();
                return 0;
            }
            if (wParam == c.RESIZE_SETTLE_TIMER_ID) {
                if (host) |v| v.tickResizeSettleRepaint();
                return 0;
            }
            if (wParam == c.BANNER_TIMER_ID) {
                if (host) |v| v.bannerExpiryTick();
                return 0;
            }
            return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
        },
        c.WM_DRAWITEM => {
            if (host) |v| {
                const draw: *const DRAWITEMSTRUCT = @ptrFromInt(@as(usize, @bitCast(lParam)));
                if (v.drawConfirmPromptText(draw)) return 1;
                if (v.drawSearchBarBackground(draw)) return 1;
                v.drawButton(draw);
                return 1;
            }
            return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
        },
        c.WM_ERASEBKGND => return 1,
        // Integrated-titlebar non-client handlers. All gated on the
        // host actively using the integrated titlebar (Win11 build /
        // config gate + visible tab/caption row); otherwise they fall
        // through to DefWindowProcW and the system paints its default
        // caption.
        c.WM_NCCALCSIZE => {
            if (host) |v| {
                if (v.handleNcCalcSize(hwnd, wParam, lParam)) |lr| return lr;
            }
            return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
        },
        c.WM_NCHITTEST => {
            if (host) |v| {
                if (v.usingIntegratedTitlebar()) {
                    if (dispatchDwmNcMessage(hwnd, msg, wParam, lParam)) |lr| return lr;
                }
                if (v.handleNcHitTest(hwnd, lParam)) |lr| return lr;
            }
            return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
        },
        c.WM_NCMOUSEMOVE => {
            if (host) |v| {
                if (v.handleNcMouseMove(hwnd, wParam)) |lr| return lr;
            }
            return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
        },
        c.WM_NCMOUSELEAVE => {
            if (host) |v| {
                const dwm_result = if (v.usingIntegratedTitlebar())
                    dispatchDwmNcMessage(hwnd, msg, wParam, lParam)
                else
                    null;
                v.handleNcMouseLeave();
                if (dwm_result) |lr| return lr;
            }
            return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
        },
        // Integrated-titlebar caption-button click dispatch. The
        // custom NC frame still returns HTMINBUTTON / HTMAXBUTTON for
        // shell affordances such as Snap Layout hover, but it cannot
        // rely on DefWindowProc owning the full caption-button mouse
        // loop once WM_NCCALCSIZE has removed the top NC margin.
        c.WM_NCLBUTTONDOWN => {
            if (host) |v| {
                if (v.usingIntegratedTitlebar()) {
                    const ht: i32 = @intCast(@as(i64, @bitCast(wParam)));
                    v.caption_pressed = titlebarCaptionFromHitTest(ht);
                    if (v.caption_pressed != .none) v.repaintTopChrome();
                    if (captionButtonSysCommand(ht, sys.IsZoomed(hwnd) != 0)) |cmd| {
                        v.clearCaptionPressed();
                        _ = sys.SendMessageW(hwnd, c.WM_SYSCOMMAND, cmd, lParam);
                        return 0;
                    }
                    if (ht == c.HTCLOSE) return 0;
                }
            }
            return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
        },
        c.WM_NCLBUTTONUP => {
            if (host) |v| {
                if (v.usingIntegratedTitlebar()) {
                    if (dispatchDwmNcMessage(hwnd, msg, wParam, lParam)) |lr| return lr;
                    const ht: i32 = @intCast(@as(i64, @bitCast(wParam)));
                    if (captionButtonSysCommand(ht, sys.IsZoomed(hwnd) != 0) != null) {
                        v.clearCaptionPressed();
                        return 0;
                    }
                    switch (ht) {
                        c.HTCLOSE => {
                            v.clearCaptionPressed();
                            _ = sys.SendMessageW(hwnd, c.WM_SYSCOMMAND, c.SC_CLOSE, lParam);
                            return 0;
                        },
                        else => v.clearCaptionPressed(),
                    }
                }
            }
            return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
        },
        // Right-click on the integrated titlebar's empty strip or on an
        // undecorated window's tab strip: the window menu, as on a stock
        // caption. See `captionRightClick`. No DwmDefWindowProc first:
        // only HTCAPTION is handled here, and every other code, the
        // caption buttons included, goes to DefWindowProc as before.
        c.WM_NCRBUTTONDOWN, c.WM_NCRBUTTONDBLCLK, c.WM_NCRBUTTONUP => {
            if (host) |v| {
                const ht: i32 = @intCast(@as(i64, @bitCast(wParam)));
                if (captionRightClick(msg, ht, v.clientCaptionHeight())) |action| {
                    if (action == .open_menu) openWindowMenuAt(hwnd, lParam);
                    return 0;
                }
            }
            return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
        },
        c.WM_WINHOSTTY_UIA_CAPTION_SYNC => {
            if (host) |v| v.syncCaptionUiaState();
            return 0;
        },
        // UIA root object request. Screen readers (Narrator, NVDA) call
        // `AccessibleObjectFromWindow` which turns into WM_GETOBJECT on
        // the target HWND. We only handle the UIA root-object ID; MSAA
        // and other IDs fall through to the default proc.
        c.WM_GETOBJECT => {
            if (host) |v| {
                const provider = v.root_uia_provider orelse provider: {
                    const created = win32_uia.RootProvider.create(
                        std.heap.page_allocator,
                        hwnd,
                    ) catch |err| {
                        log.warn("uia: root provider init failed err={}", .{err});
                        return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
                    };
                    created.setCaptionButtons(v.captionButtonsUiaState());
                    v.root_uia_provider = created;
                    break :provider created;
                };
                if (win32_uia.returnRootProvider(hwnd, wParam, lParam, provider)) |lr| return lr;
            }
            return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
        },
        c.WM_SETTINGCHANGE => {
            if (host) |v| {
                v.app.refreshSystemWheelSettings();
                v.app.refreshSystemScrollbarPreference();
                if (settingChangeAffectsTheme(lParam)) v.app.reconfigureSystemTheme();
                if (settingChangeIsImmersiveColorSet(lParam)) {
                    v.app.syncSystemColorScheme() catch |err| {
                        log.warn("win32 color scheme sync failed err={}", .{err});
                    };
                }
            }
            return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
        },
        c.WM_THEMECHANGED, c.WM_SYSCOLORCHANGE => {
            if (host) |v| {
                v.app.reconfigureSystemTheme();
            }
            return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
        },
        // Fired by DWM when the user's accent color changes. Re-resolve
        // the theme so any accent-derived tokens pick up the new value
        // without requiring a config reload.
        c.WM_DWMCOLORIZATIONCOLORCHANGED => {
            if (host) |v| {
                v.app.reconfigureSystemTheme();
            }
            return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
        },
        c.WM_GETDPISCALEDSIZE => {
            // Sent before the resize Windows makes for a DPI change, which
            // then reaches us ahead of `WM_DPICHANGED` (measured in real
            // drags). Hold the terminals' grid from here; see
            // `dpi_change_pending`. FALSE keeps Windows' linear scaling.
            if (host) |v| v.dpi_change_pending = true;
            return 0;
        },
        c.WM_DPICHANGED => {
            if (host) |v| {
                // Also held when no `WM_GETDPISCALEDSIZE` came first.
                v.dpi_change_pending = true;
                const new_dpi = sys.GetDpiForWindow(hwnd);
                if (new_dpi > 0) v.current_dpi = new_dpi;
                v.recreateChromeFont();

                // QT placement/tween frames own their physical-pixel rect.
                // Keep scale and layout updates even when the OS's resized
                // suggestion would override that rect on a DPI crossing.
                // SWP_FRAMECHANGED either way: in a drag across monitors
                // Windows resizes the window before this message, so
                // `WM_NCCALCSIZE` laid the frame out at the old DPI (22x11 px,
                // 144 DPI's, on a 96 DPI monitor whose frame is 16x8), and the
                // suggestion is that same rect. Without a fresh layout the
                // client stayed that far off, and the configured grid size
                // resized from the stale frame.
                const flags = c.SWP_NOZORDER | c.SWP_NOACTIVATE | c.SWP_FRAMECHANGED;
                if (!v.quick_terminal_placing and !v.restore_placing and v.quick_terminal_animation == null) {
                    const suggested: *const RECT = @ptrFromInt(@as(usize, @bitCast(lParam)));
                    _ = sys.SetWindowPos(hwnd, null, suggested.left, suggested.top, suggested.right - suggested.left, suggested.bottom - suggested.top, flags);
                } else {
                    _ = sys.SetWindowPos(hwnd, null, 0, 0, 0, 0, flags | c.SWP_NOMOVE | c.SWP_NOSIZE);
                }

                // Lay the children out while still held (a frame change
                // need not send WM_SIZE), then each terminal takes its new
                // font and settled size as one resize. Building a font can
                // outlast termio's 25 ms resize coalescing, so a size sent
                // ahead of it was laid out in the old font.
                runUiActionOrLog("DPI update layout failed", v.layout());
                v.applyDpiChangeToVisibleSurfaces();
                v.dpi_change_pending = false;
                v.syncVisibleSurfaceCoreSizesFromClientRects();
                v.app.resizeShellCompositorWindow(hwnd);
                v.invalidateTopChromeText();
            }
            return 0;
        },
        c.WM_CTLCOLOREDIT, c.WM_CTLCOLORSTATIC, c.WM_CTLCOLORBTN => {
            if (host) |v| {
                v.ensureThemeBrushes() catch return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
                const hdc: HDC = @ptrFromInt(@as(usize, @intCast(wParam)));
                const child: HWND = @ptrFromInt(@as(usize, @intCast(lParam)));
                switch (msg) {
                    c.WM_CTLCOLOREDIT => {
                        _ = sys.SetBkMode(hdc, c.OPAQUE);
                        _ = sys.SetBkColor(hdc, v.app.resolved_theme.edit_bg);
                        _ = sys.SetTextColor(hdc, v.app.resolved_theme.edit_fg);
                        return @as(LRESULT, @bitCast(@as(usize, @intFromPtr(v.edit_brush.?))));
                    },
                    c.WM_CTLCOLORSTATIC => {
                        _ = sys.SetBkMode(hdc, c.TRANSPARENT);
                        _ = sys.SetTextColor(hdc, if (v.isSearchBarResultsLabel(child))
                            if (v.searchControlSurface(child)) |surface|
                                searchBarResultsVisual(&v.app.resolved_theme, &surface.search_bar).fg
                            else
                                v.app.resolved_theme.text_secondary
                        else if (v.overlay_hint_hwnd != null and child == v.overlay_hint_hwnd.?)
                            v.app.resolved_theme.text_secondary
                        else
                            v.app.resolved_theme.text_primary);
                        return @as(LRESULT, @bitCast(@as(usize, @intFromPtr(v.overlay_brush.?))));
                    },
                    c.WM_CTLCOLORBTN => {
                        _ = sys.SetBkMode(hdc, c.TRANSPARENT);
                        if (v.isOverlayStyledButton(child)) {
                            _ = sys.SetTextColor(hdc, v.app.resolved_theme.button_overlay_fg);
                            return @as(LRESULT, @bitCast(@as(usize, @intFromPtr(v.overlay_brush.?))));
                        }
                        _ = sys.SetTextColor(hdc, if (v.isActiveChromeButton(child))
                            v.app.resolved_theme.button_active_fg
                        else
                            v.app.resolved_theme.button_chrome_fg);
                        return @as(LRESULT, @bitCast(@as(usize, @intFromPtr(v.chrome_brush.?))));
                    },
                    else => {},
                }
            }
            return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
        },
        c.WM_COMMAND => {
            if (host) |v| {
                const command_id = lowWord(wParam);
                const notify_code = highWord(wParam);
                const child_hwnd = wmCommandChildHwnd(lParam);
                switch (command_id) {
                    2002 => {
                        if (notify_code == c.EN_CHANGE) {
                            // Skip re-entry from our own programmatic
                            // `SetWindowTextW` on the edit HWND. The
                            // caller already wraps the write in
                            // `suppress_edit_events` and drives its
                            // own sync pass afterward; letting this
                            // handler run would invalidate
                            // `cached_overlay_edit` mid-write and
                            // racing borrows across the sync cascade
                            // caused palette edit re-entry crashes.
                            if (v.suppress_edit_events) return 0;
                            runUiActionOrLog(
                                "overlay edit cache clear failed",
                                appendOwnedString(v.app.core_app.alloc, &v.cached_overlay_edit, null),
                            );
                            if (v.overlay_edit_uia_provider) |provider| {
                                provider.raiseTextChanged();
                                provider.raiseValueChanged();
                            }
                            v.raiseOverlayEditSelectionChangedIfNeeded();
                            if (v.overlay_mode == .command_palette) {
                                runUiActionOrLog("overlay completion sync failed", v.syncOverlayCompletionState());
                                runUiActionOrLog("command palette banner sync failed", v.syncCommandPaletteBanner());
                            } else {
                                _ = v.syncOverlayLabel() catch false;
                                _ = v.syncOverlayHint() catch false;
                                _ = v.syncOverlayButtons() catch false;
                            }
                            return 0;
                        }
                    },
                    c.SEARCH_EDIT_ID => {
                        if (notify_code == c.EN_CHANGE) {
                            if (v.suppress_edit_events) return 0;
                            if (child_hwnd) |child| {
                                if (v.searchControlSurface(child)) |surface| {
                                    if (surface.search_bar_edit_uia_provider) |provider| {
                                        provider.raiseTextChanged();
                                        provider.raiseValueChanged();
                                    }
                                    surface.raiseSearchEditSelectionChangedIfNeeded();
                                    _ = surface.handleSearchBarEditChanged() catch |err| {
                                        logUiActionError("docked search edit update failed", err);
                                    };
                                    return 0;
                                }
                            }
                        }
                    },
                    2003 => if (expectedButtonClick(notify_code, child_hwnd, v.overlay_accept_hwnd)) {
                        if (v.overlay_mode == .confirm) {
                            // MUST NOT touch `v` after the callback
                            // — a destructive accept (close-surface)
                            // fires `DestroyWindow`, which triggers
                            // the Host's WM_DESTROY path + frees the
                            // Host struct. `invokeConfirmAccept`
                            // itself documents this ordering invariant.
                            v.invokeConfirmAccept();
                            return 0;
                        }
                        if (v.overlay_mode == .profile) {
                            runUiActionOrLog("profile overlay submit failed", v.submitProfileOverlay(resolveProfileOpenTarget(
                                v.app.launcher_profile_target,
                                keyPressed(c.VK_SHIFT),
                                keyPressed(c.VK_CONTROL),
                            )));
                        } else {
                            runUiActionOrLog("overlay submit failed", v.submitOverlay());
                        }
                        return 0;
                    },
                    2004 => if (expectedButtonClick(notify_code, child_hwnd, v.overlay_cancel_hwnd)) {
                        if (v.overlay_mode == .confirm) {
                            // Cancel callbacks can mutate or destroy
                            // the Host. Use the same no-access-after
                            // discipline as the accept path for safety.
                            v.invokeConfirmCancel();
                            return 0;
                        }
                        v.hideOverlay();
                        runUiActionOrLog("overlay dismiss layout refresh failed", v.layout());
                        refocusActiveSurface(v);
                        return 0;
                    },
                    c.SEARCH_PREV_ID => {
                        if (notify_code == c.BN_CLICKED) {
                            if (child_hwnd) |child| {
                                if (v.searchControlSurface(child)) |surface| {
                                    if (dockedSearchButtonDirection(command_id)) |dir| {
                                        _ = surface.navigateDockedSearch(dir) catch |err| {
                                            logUiActionError("docked search previous failed", err);
                                        };
                                    }
                                    return 0;
                                }
                            }
                        }
                    },
                    c.SEARCH_NEXT_ID => {
                        if (notify_code == c.BN_CLICKED) {
                            if (child_hwnd) |child| {
                                if (v.searchControlSurface(child)) |surface| {
                                    if (dockedSearchButtonDirection(command_id)) |dir| {
                                        _ = surface.navigateDockedSearch(dir) catch |err| {
                                            logUiActionError("docked search next failed", err);
                                        };
                                    }
                                    return 0;
                                }
                            }
                        }
                    },
                    c.SEARCH_REGEX_ID, c.SEARCH_CASE_ID, c.SEARCH_WORD_ID => {
                        if (notify_code == c.BN_CLICKED) {
                            if (child_hwnd) |child| {
                                if (v.searchControlSurface(child)) |surface| {
                                    _ = surface.handleSearchToggleClick(command_id) catch |err| {
                                        logUiActionError("docked search toggle failed", err);
                                    };
                                    return 0;
                                }
                            }
                        }
                    },
                    c.SEARCH_CLOSE_ID => {
                        if (notify_code == c.BN_CLICKED) {
                            if (child_hwnd) |child| {
                                if (v.searchControlSurface(child)) |surface| {
                                    surface.closeDockedSearchBar(true, true) catch |err| {
                                        logUiActionError("docked search close failed", err);
                                    };
                                    return 0;
                                }
                            }
                        }
                    },
                    // Foreground-free harness hooks also used by interactive
                    // verification; these have no visible toolbar controls.
                    1901 => {
                        if (v.activeSurface()) |surface| {
                            runUiActionOrLog("toolbar command palette failed", surface.toggleCommandPalette());
                        }
                        return 0;
                    },
                    1907 => {
                        _ = v.activateTabByDirection(.previous);
                        return 0;
                    },
                    1908 => {
                        _ = v.activateTabByDirection(.next);
                        return 0;
                    },
                    1904 => {
                        v.postDeferredNewTab();
                        return 0;
                    },
                    1911 => {
                        v.showOverflowMenu();
                        return 0;
                    },
                    else => {},
                }
                for (v.tabs.items, 0..) |*tab, i| {
                    if (child_hwnd) |child| {
                        if (tab.button_hwnd == child) {
                            _ = v.activateTabIndex(i);
                            return 0;
                        }
                    }
                }
            }
            return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
        },

        c.WM_SETFOCUS => {
            if (host) |v| {
                refocusHostAfterActivation(v);
            }
            return 0;
        },

        c.WM_KEYDOWN, c.WM_SYSKEYDOWN, c.WM_KEYUP, c.WM_SYSKEYUP => {
            if (host) |v| {
                if (v.handleEmptyHostKeyMessage(msg, wParam, lParam)) return 0;
            }
            return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
        },

        c.WM_MENUCHAR => {
            // An Alt chord typed into a chrome control (a tab button, the
            // search field) reaches DefWindowProc as WM_SYSCHAR, becomes
            // SC_KEYMENU, and lands here with MF_POPUP clear: no menu is
            // open, nothing can match, and the default answer is the shell's
            // beep. Close that phantom loop silently. With a menu actually
            // open (MF_POPUP: the window menu after Alt+Space, or one of
            // this window's own TrackPopupMenu menus) the default reply
            // stays. The terminal surface consumes its own WM_SYSCHAR
            // (#250) except for Alt+Space, whose menu is a real popup.
            const menu_flags: u32 = @intCast((wParam >> 16) & 0xFFFF);
            if (win32_input.menuCharClosesPhantomMenu(menu_flags)) {
                return @as(LRESULT, c.MNC_CLOSE) << 16;
            }
            return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
        },

        c.WM_GETMINMAXINFO => {
            if (host) |v| {
                if (v.activeSurface()) |surface| {
                    surface.updateMinMaxInfo(lParam);
                    return 0;
                }
            }
            return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
        },

        c.WM_SIZE => {
            if (host) |v| {
                // Defensive: maximize / minimize jumps don't always
                // route through WM_ENTERSIZEMOVE → WM_EXITSIZEMOVE, so
                // a flag set on an earlier interactive drag might be
                // left stuck `true` after a window-button size change.
                // Clear it here so the renderer doesn't stay in
                // coarse-mode after the user clicks maximize.
                const size_kind: u32 = @truncate(wParam);
                if (size_kind == c.SIZE_MAXIMIZED or size_kind == c.SIZE_MINIMIZED) {
                    v.is_live_resize.store(false, .release);
                    // Win32 silently cancels NC mouse tracking when
                    // the window minimises or its maximised state
                    // flips — WM_NCMOUSELEAVE is NOT guaranteed to
                    // fire in those paths. Force-clear the caption
                    // state here so the next NC re-entry re-arms
                    // `TrackMouseEvent` and hover paint stays correct.
                    v.caption_track_armed = false;
                    if (v.caption_hover != .none or v.caption_pressed != .none) {
                        v.caption_hover = .none;
                        v.caption_pressed = .none;
                        v.repaintTopChrome();
                    }
                }
                runUiActionOrLog("window resize layout failed", v.layout());
                v.scheduleCaptionUiaSync();
                v.app.resizeShellCompositorWindow(hwnd);
                if (size_kind == c.SIZE_MAXIMIZED or
                    (size_kind == c.SIZE_RESTORED and !v.is_live_resize.load(.acquire)))
                {
                    v.startResizeSettleRepaints();
                }
                return 0;
            }
            return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
        },

        win32_power.WM_POWERBROADCAST => {
            // Only the power-setting notifications we registered for are
            // ours. Suspend/resume and the legacy APM query messages must
            // keep reaching DefWindowProcW.
            if (wParam != win32_power.PBT_POWERSETTINGCHANGE) {
                return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
            }
            _ = win32_power.handlePowerSettingChange(lParam);
            return 1;
        },

        // Sign-out, shutdown, reboot and Restart Manager closes. The save
        // waits for WM_ENDSESSION, after which the process may be ended
        // without `terminate` running; WM_QUERYENDSESSION is left to
        // DefWindowProcW, which answers TRUE.
        c.WM_ENDSESSION => {
            if (wParam != 0) if (host) |v| v.app.saveForEndSession((@as(usize, @bitCast(lParam)) & c.ENDSESSION_CLOSEAPP) != 0);
            return 0;
        },
        // Saved from the message loop rather than inside this sent message,
        // which can arrive while the thread waits in the middle of other
        // work.
        c.WM_DISPLAYCHANGE => {
            _ = sys.PostMessageW(hwnd, c.WM_WINHOSTTY_SESSION_CHECKPOINT, 0, 0);
            return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
        },
        c.WM_WINHOSTTY_SESSION_CHECKPOINT => {
            if (host) |v| v.app.checkpointSessionState();
            return 0;
        },
        c.WM_WINHOSTTY_QUIT => {
            // wParam: whether the quit came from this window. May destroy
            // this window: nothing after the call reads `v`.
            if (host) |v| v.app.requestQuit(if (wParam != 0) v.activeSurface() else null);
            return 0;
        },

        c.WM_SHOWWINDOW => {
            const result = sys.DefWindowProcW(hwnd, msg, wParam, lParam);
            if (host) |v| {
                if (wParam != 0) v.hidden_by_toggle = false;
                v.refreshSurfaceVisibility();
                // Hiding or showing a window changes no size, so WM_SIZE
                // never fires and this is the only notice that the caption
                // children just appeared or disappeared.
                v.scheduleCaptionUiaSync();
            }
            return result;
        },

        c.WM_WINDOWPOSCHANGED => {
            const result = sys.DefWindowProcW(hwnd, msg, wParam, lParam);
            // This fires once per mouse-move during a drag-move/resize and
            // the visibility query costs a DWM round-trip, so skip it while
            // a drag is in flight -- a window being dragged is by definition
            // visible. The drag loop emits its last WM_WINDOWPOSCHANGED just
            // BEFORE WM_EXITSIZEMOVE, so that one is skipped too and the
            // WM_EXITSIZEMOVE arm does the catch-up refresh.
            if (host) |v| {
                if (!v.is_live_resize.load(.acquire)) {
                    v.refreshSurfaceVisibility();
                    // Covers the SetWindowPos show/hide flags, which do not
                    // always produce a WM_SHOWWINDOW. The post coalesces.
                    v.scheduleCaptionUiaSync();
                }
            }
            return result;
        },

        c.WM_ENTERSIZEMOVE => {
            // User started a drag-resize or drag-move. We don't know
            // which yet, but setting the flag on both is harmless —
            // pure move generates no WM_SIZE so the throttle has
            // nothing to coalesce. WM_EXITSIZEMOVE clears it either
            // way.
            if (host) |v| v.is_live_resize.store(true, .release);
            return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
        },

        c.WM_EXITSIZEMOVE => {
            if (host) |v| {
                // A drag that ends without the `WM_DPICHANGED` its
                // `WM_GETDPISCALEDSIZE` announced must not hold the grid; the
                // forced sync below catches it up.
                v.dpi_change_pending = false;
                v.is_live_resize.store(false, .release);
                v.defer_surface_repaints_until_flush = true;
                runUiActionOrLog("resize completion layout failed", v.layout());
                v.defer_surface_repaints_until_flush = false;
                v.flushDeferredVisibleSurfaceRepaints();
                v.startResizeSettleRepaints();
                v.forceVisibleSurfaceRepaintsNow();
                v.forceHostCompositionPaint();
                // The last WM_WINDOWPOSCHANGED of the drag was skipped by
                // the live-resize guard, so re-check here.
                v.refreshSurfaceVisibility();
            }
            return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
        },

        c.WM_MOUSEWHEEL, c.WM_MOUSEHWHEEL, c.WM_POINTERWHEEL, c.WM_POINTERHWHEEL => {
            if (host) |v| {
                var point = POINT{
                    .x = signedLowWord(lParamBits(lParam)),
                    .y = signedHighWord(lParamBits(lParam)),
                };
                if (sys.ScreenToClient(hwnd, &point) != 0 and point.y >= 0 and point.y < v.tabBarHeight()) {
                    _ = v.activateTabByDirection(tabDirectionFromWheelDelta(signedHighWord(wParam)));
                    return 0;
                }
            }
            return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
        },

        c.WM_PAINT => {
            if (host) |v| {
                v.chrome_paint_pending = false;
                v.chrome_paint_mask = .{};
                v.paintChrome();
                return 0;
            }
            return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
        },

        c.WM_CLOSE => {
            if (host) |v| {
                v.close();
                return 0;
            }
            _ = sys.DestroyWindow(hwnd);
            return 0;
        },

        c.WM_DESTROY => {
            if (host) |v| {
                v.destroyChildControls();
                v.app.detachShellCompositorWindow(hwnd);
                v.power_notifications.deinit();
                v.hwnd = null;
            }
            return 0;
        },

        else => return sys.DefWindowProcW(hwnd, msg, wParam, lParam),
    }
}

fn desiredTabIndex(total: usize, current: usize, goto: apprt.action.GotoTab) ?usize {
    if (total == 0 or current >= total) return null;

    return switch (goto) {
        .previous => if (current == 0) total - 1 else current - 1,
        .next => (current + 1) % total,
        .last => total - 1,
        // `goto_tab:N` is 1-based, as the GTK and macOS apprts read it.
        _ => blk: {
            const raw: c_int = @intFromEnum(goto);
            if (raw < 1) return null;
            const idx: usize = @intCast(raw - 1);
            break :blk @min(idx, total - 1);
        },
    };
}

const TabButtonMouseUpAction = enum {
    none,
    activate,
    close,
};

fn tabButtonMouseUpAction(
    drag_index: ?usize,
    was_drag: bool,
    click_x: i32,
    close_left: i32,
    tab_count: usize,
) TabButtonMouseUpAction {
    if (drag_index != null) {
        return if (was_drag) .none else .activate;
    }
    if (tabCloseAction(tab_count) != .none and click_x >= close_left) return .close;
    return .none;
}

const TabCloseAction = enum {
    /// There is no tab to close.
    none,
    /// Close that tab and leave the window to the others.
    close_tab,
    /// The tab is the window's only one: close the window.
    close_window,
};

/// What a window with `tab_count` tabs does when its tab strip closes a tab:
/// the X, a middle click, Delete on a focused tab, the context menu's
/// "Close Tab" and a UIA Invoke of the close element. Every tab has the
/// close X, the only one included, since an undecorated window has no caption
/// button to close it with. The only tab closes the window the way the window's
/// own close button does, because `close_tab:this` on it keeps an empty frame
/// on screen for `undo-timeout` (measured, TABX).
fn tabCloseAction(tab_count: usize) TabCloseAction {
    return switch (tab_count) {
        0 => .none,
        1 => .close_window,
        else => .close_tab,
    };
}

fn desiredMoveIndex(total: usize, current: usize, amount: isize) ?usize {
    if (total <= 1 or current >= total or amount == 0) return null;
    const total_i: isize = @intCast(total);
    const current_i: isize = @intCast(current);
    const normalized = @mod(current_i + amount, total_i);
    return @intCast(normalized);
}

fn movedIndexAfterReorder(active: usize, from: usize, to: usize) usize {
    if (active == from) return to;
    if (from < to and active > from and active <= to) return active - 1;
    if (from > to and active >= to and active < from) return active + 1;
    return active;
}

fn applyQuickSlotPreferenceOrder(
    profiles: []windows_shell.Profile,
    slot_keys: [3]?[]const u8,
) void {
    var insert_at: usize = 0;
    for (slot_keys) |key_opt| {
        const key = key_opt orelse continue;
        var found: ?usize = null;
        for (profiles, 0..) |profile, index| {
            if (profileKeyEquals(profile, key)) {
                found = index;
                break;
            }
        }
        const found_index = found orelse continue;
        if (found_index == insert_at) {
            insert_at += 1;
            continue;
        }
        const chosen = profiles[found_index];
        var move_index = found_index;
        while (move_index > insert_at) : (move_index -= 1) {
            profiles[move_index] = profiles[move_index - 1];
        }
        profiles[insert_at] = chosen;
        insert_at += 1;
    }
}

const findLauncherQuickSlotOrdinal = labels.findLauncherQuickSlotOrdinal;

fn launcherQuickSlotAssignmentNeedsChange(
    slot_keys: [3]?[:0]const u8,
    slot_ordinal: usize,
    key: []const u8,
) bool {
    if (slot_ordinal >= slot_keys.len) return false;
    return findLauncherQuickSlotOrdinal(slot_keys, key) != slot_ordinal;
}

fn launcherQuickSlotPinsAlreadyClear(slot_keys: [3]?[:0]const u8) bool {
    for (slot_keys) |slot_key| {
        if (slot_key != null) return false;
    }
    return true;
}

fn selectedProfileSelectionNeedsChange(
    current_index: usize,
    next_index: usize,
    selected_profile_key: ?[:0]const u8,
    launcher_profile_key: ?[:0]const u8,
    next_key: []const u8,
) bool {
    return current_index != next_index or
        !ownedStringEquals(selected_profile_key, next_key) or
        !ownedStringEquals(launcher_profile_key, next_key);
}

fn startupProfilePickerEnabled(raw: []const u8) bool {
    return std.mem.eql(u8, raw, "1") or
        std.ascii.eqlIgnoreCase(raw, "true") or
        std.ascii.eqlIgnoreCase(raw, "yes") or
        std.ascii.eqlIgnoreCase(raw, "on");
}

fn detectStartupProfilePicker(alloc: Allocator) bool {
    const raw = std.process.getEnvVarOwned(alloc, "NOCTTY_WIN32_STARTUP_PROFILE_PICKER") catch
        return false;
    defer alloc.free(raw);
    return startupProfilePickerEnabled(raw);
}

fn detectDefaultProfileHint(alloc: Allocator) ?[:0]const u8 {
    const raw = std.process.getEnvVarOwned(alloc, "NOCTTY_WIN32_DEFAULT_PROFILE") catch
        return null;
    if (raw.len == 0) {
        alloc.free(raw);
        return null;
    }
    const value = alloc.dupeZ(u8, raw) catch {
        alloc.free(raw);
        return null;
    };
    alloc.free(raw);
    return value;
}

fn detectDefaultProfileTarget(alloc: Allocator) ProfileOpenTarget {
    const raw = std.process.getEnvVarOwned(alloc, "NOCTTY_WIN32_DEFAULT_PROFILE_TARGET") catch
        return .tab;
    defer alloc.free(raw);
    return parseProfileOpenTarget(raw) orelse .tab;
}

fn isSafeStartupCwd(path: []const u8) bool {
    return path.len >= 3 and
        std.ascii.isAlphabetic(path[0]) and
        path[1] == ':' and
        (path[2] == '\\' or path[2] == '/');
}

fn pointInRect(point: POINT, rect: RECT) bool {
    return point.x >= rect.left and
        point.x < rect.right and
        point.y >= rect.top and
        point.y < rect.bottom;
}

const lParamBits = win32_input.lParamBits;

fn lowWord(value: usize) u16 {
    return @truncate(value & 0xFFFF);
}

const highWord = win32_input.highWord;

fn signedLowWord(value: usize) i16 {
    return @bitCast(lowWord(value));
}

fn signedHighWord(value: usize) i16 {
    return @bitCast(highWord(value));
}

fn cursorPosFromLParam(lParam: LPARAM) apprt.CursorPos {
    const bits = lParamBits(lParam);
    return .{
        .x = @floatFromInt(signedLowWord(bits)),
        .y = @floatFromInt(signedHighWord(bits)),
    };
}

const ImeWindowForms = struct {
    composition: COMPOSITIONFORM,
    candidate: CANDIDATEFORM,
};

var ime_window_forms_trace_path_loaded = false;
var ime_window_forms_trace_path: ?[]const u8 = null;

fn scaledImeCoord(value: f64, scale: f32) i32 {
    const scale_f64: f64 = @floatCast(scale);
    return @intFromFloat(value * scale_f64);
}

fn imeWindowForms(ime_pos: apprt.IMEPos, content_scale: apprt.ContentScale) ImeWindowForms {
    const point: POINT = .{
        .x = scaledImeCoord(ime_pos.x, content_scale.x),
        .y = scaledImeCoord(ime_pos.y, content_scale.y),
    };
    const caret_height = @max(@as(i32, 1), scaledImeCoord(ime_pos.height, content_scale.y));

    return .{
        .composition = .{
            .dwStyle = c.CFS_POINT,
            .ptCurrentPos = point,
            .rcArea = .{ .left = 0, .top = 0, .right = 0, .bottom = 0 },
        },
        .candidate = .{
            .dwIndex = 0,
            .dwStyle = c.CFS_EXCLUDE,
            .ptCurrentPos = point,
            .rcArea = .{
                .left = point.x,
                .top = point.y - caret_height,
                .right = point.x + 1,
                .bottom = point.y,
            },
        },
    };
}

fn imeWindowFormsTracePath(alloc: Allocator) ?[]const u8 {
    if (!ime_window_forms_trace_path_loaded) {
        ime_window_forms_trace_path_loaded = true;
        ime_window_forms_trace_path = internal_os.getEnvVarOwnedTrimmedNotEmpty(
            alloc,
            "NOCTTY_WIN32_IME_FORM_TRACE_FILE",
        ) catch null;
    }

    return ime_window_forms_trace_path;
}

fn deinitImeWindowFormsTracePath(alloc: Allocator) void {
    if (ime_window_forms_trace_path) |path| alloc.free(path);
    ime_window_forms_trace_path = null;
    ime_window_forms_trace_path_loaded = false;
}

fn writeImeWindowFormsTrace(
    alloc: Allocator,
    ime_pos: apprt.IMEPos,
    content_scale: apprt.ContentScale,
    forms: ImeWindowForms,
) void {
    const trace_path = imeWindowFormsTracePath(alloc) orelse return;

    const file = std.fs.createFileAbsolute(trace_path, .{ .truncate = true }) catch |err| {
        log.warn("win32 IME form trace create failed path={s} err={}", .{ trace_path, err });
        return;
    };
    defer file.close();

    var buffer: [1024]u8 = undefined;
    var writer = file.writer(&buffer);
    const stream = &writer.interface;
    stream.print("{f}", .{std.json.fmt(.{
        .ime_pos = .{
            .x = ime_pos.x,
            .y = ime_pos.y,
            .width = ime_pos.width,
            .height = ime_pos.height,
        },
        .content_scale = .{
            .x = content_scale.x,
            .y = content_scale.y,
        },
        .composition = .{
            .dwStyle = forms.composition.dwStyle,
            .ptCurrentPos = .{
                .X = forms.composition.ptCurrentPos.x,
                .Y = forms.composition.ptCurrentPos.y,
            },
            .rcArea = .{
                .Left = forms.composition.rcArea.left,
                .Top = forms.composition.rcArea.top,
                .Right = forms.composition.rcArea.right,
                .Bottom = forms.composition.rcArea.bottom,
            },
        },
        .candidate = .{
            .dwIndex = forms.candidate.dwIndex,
            .dwStyle = forms.candidate.dwStyle,
            .ptCurrentPos = .{
                .X = forms.candidate.ptCurrentPos.x,
                .Y = forms.candidate.ptCurrentPos.y,
            },
            .rcArea = .{
                .Left = forms.candidate.rcArea.left,
                .Top = forms.candidate.rcArea.top,
                .Right = forms.candidate.rcArea.right,
                .Bottom = forms.candidate.rcArea.bottom,
            },
        },
    }, .{})}) catch |err| {
        log.warn("win32 IME form trace write failed path={s} err={}", .{ trace_path, err });
        return;
    };
    stream.flush() catch |err| {
        log.warn("win32 IME form trace flush failed path={s} err={}", .{ trace_path, err });
        return;
    };
}

const readSystemWheelSetting = win32_input.readSystemWheelSetting;

const wheelDeltaFromWParam = win32_input.wheelDeltaFromWParam;

const normalizeWheelDelta = win32_input.normalizeWheelDelta;

const keyPressed = win32_input.keyPressed;

const currentMods = win32_input.currentMods;

const hotkeySpecForTrigger = win32_input.hotkeySpecForTrigger;

const hotkeySpecEql = win32_input.hotkeySpecEql;

const hotkeyRegistrationFailureReason = win32_input.hotkeyRegistrationFailureReason;
const quickSelectAsciiFromKey = win32_input.quickSelectAsciiFromKey;

fn quitTimerDelayMs(delay: configpkg.Config.Duration) UINT {
    const clamped_ns = @max(delay.duration, std.time.ns_per_s);
    const delay_ms_u64 = @max(1, std.math.divCeil(u64, clamped_ns, std.time.ns_per_ms) catch std.math.maxInt(u64));
    return @intCast(@min(delay_ms_u64, std.math.maxInt(UINT)));
}

fn mouseButtonFromMessage(msg: UINT) ?input.MouseButton {
    return switch (msg) {
        c.WM_LBUTTONDOWN, c.WM_LBUTTONUP => .left,
        c.WM_RBUTTONDOWN, c.WM_RBUTTONUP => .right,
        c.WM_MBUTTONDOWN, c.WM_MBUTTONUP => .middle,
        else => null,
    };
}

fn mouseButtonStateFromMessage(msg: UINT) ?input.MouseButtonState {
    return switch (msg) {
        c.WM_LBUTTONDOWN, c.WM_RBUTTONDOWN, c.WM_MBUTTONDOWN => .press,
        c.WM_LBUTTONUP, c.WM_RBUTTONUP, c.WM_MBUTTONUP => .release,
        else => null,
    };
}

fn rightClickShowsMenu(action: configpkg.Config.RightClickAction, press_consumed: bool) bool {
    return action == .@"context-menu" and !press_consumed;
}

test "win32 right click menu honors consumed presses and every configured action" {
    const expect = std.testing.expect;
    try expect(rightClickShowsMenu(.@"context-menu", false));
    try expect(!rightClickShowsMenu(.@"context-menu", true));
    inline for (.{ .ignore, .paste, .copy, .@"copy-or-paste" }) |action| {
        try expect(!rightClickShowsMenu(action, false));
        try expect(!rightClickShowsMenu(action, true));
    }
}

fn mouseModsFromWParam(wParam: WPARAM) input.Mods {
    const bits = @as(usize, @intCast(wParam));
    var mods = currentMods();
    if ((bits & c.MK_SHIFT) != 0) mods.shift = true;
    if ((bits & c.MK_CONTROL) != 0) mods.ctrl = true;
    _ = bits & (c.MK_LBUTTON | c.MK_RBUTTON | c.MK_MBUTTON);
    return mods;
}

const ScrollbarProxyPoint = struct {
    local_x: f32,
    local_y: f32,
    over_band: bool,
};

fn scrollbarProxyPointFromSurfaceCoords(
    pane_rect: RECT,
    hover_width: i32,
    surface_x: i32,
    surface_y: i32,
) ScrollbarProxyPoint {
    const pane_width: i32 = @max(@as(i32, 1), pane_rect.right - pane_rect.left);
    const pane_height: i32 = @max(@as(i32, 1), pane_rect.bottom - pane_rect.top);
    const band_left: i32 = @max(@as(i32, 0), pane_width - @max(@as(i32, 1), hover_width));
    return .{
        .local_x = @floatFromInt(surface_x - band_left),
        .local_y = @floatFromInt(surface_y),
        .over_band = surface_x >= band_left and surface_x <= pane_width and
            surface_y >= 0 and surface_y <= pane_height,
    };
}

fn scrollbarProxyPointFromSurfaceCursor(
    pane_rect: RECT,
    hover_width: i32,
    lParam: LPARAM,
) ScrollbarProxyPoint {
    return scrollbarProxyPointFromSurfaceCoords(
        pane_rect,
        hover_width,
        signedLowWord(lParamBits(lParam)),
        signedHighWord(lParamBits(lParam)),
    );
}

const DeferredCharState = win32_input.DeferredCharState;

const keyEventFromWin32Message = win32_input.keyEventFromWin32Message;

fn windowProc(hwnd: HWND, msg: UINT, wParam: WPARAM, lParam: LPARAM) callconv(.winapi) LRESULT {
    if (msg == c.WM_NCCREATE) {
        const cs: *const CREATESTRUCTW = @ptrFromInt(@as(usize, @bitCast(lParam)));
        if (cs.lpCreateParams) |ptr| {
            setWindowData(hwnd, ptr);
        }
    }

    const surface = getSurface(hwnd);

    switch (msg) {
        c.WM_WINHOSTTY_WAKE => return 0,

        c.WM_NCHITTEST => {
            if (surface) |v| if (v.host) |host| if (host.resizesFrom(lParam)) return c.HTTRANSPARENT;
            return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
        },

        c.WM_WINHOSTTY_RENDER_TRACE_SNAPSHOT => {
            if (surface) |v| v.render_trace.requestSnapshot();
            return 0;
        },

        c.WM_WINHOSTTY_RENDER_TRACE_TARGET => {
            if (surface) |v| v.render_trace.setTargetOutputBytes(@intCast(wParam));
            return 0;
        },

        c.WM_WINHOSTTY_UIA_QUERY_REFRESH => {
            if (surface) |v| {
                v.drainTerminalAccessibilityOutput();
                if (v.terminal_accessibility) |session| {
                    if (wParam == 2) {
                        session.handleScroll();
                        return 1;
                    }
                    if (wParam == 3) {
                        session.handleViewportRefresh();
                        return 1;
                    }
                    session.handleQueryRefresh(wParam != 0);
                }
            }
            return 0;
        },

        c.WM_SETFOCUS => {
            if (surface) |v| v.focusChanged(true);
            return 0;
        },

        c.WM_KILLFOCUS => {
            if (surface) |v| {
                v.deferred_char.clear();
                v.focusChanged(false);
            }
            return 0;
        },

        c.WM_SIZE => {
            if (surface) |v| v.windowSizeChanged();
            return 0;
        },

        c.WM_TIMER => {
            if (wParam == c.TERMINAL_UIA_TIMER_ID) {
                if (surface) |v| {
                    v.drainTerminalAccessibilityOutput();
                    if (v.terminal_accessibility) |session| session.handleTimer();
                }
                return 0;
            }
            return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
        },

        c.WM_GETOBJECT => {
            if (surface) |v| {
                // UIA may query the child HWND reentrantly while DestroyWindow
                // is unwinding. Surface.destroy clears this flag before it
                // releases the owner context, so never recreate that context
                // once teardown has begun (or before init completes).
                if (!v.destroy_on_wm_destroy) return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
                const provider = v.terminalUiaProvider() catch |err| {
                    log.warn("uia: terminal provider init failed err={}", .{err});
                    return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
                };
                if (win32_uia.returnTerminalProvider(
                    hwnd,
                    wParam,
                    lParam,
                    provider,
                )) |lr| return lr;
            }
            return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
        },

        c.WM_GETMINMAXINFO => {
            if (surface) |v| {
                v.updateMinMaxInfo(lParam);
                return 0;
            }
            return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
        },

        c.WM_KEYDOWN, c.WM_SYSKEYDOWN, c.WM_KEYUP, c.WM_SYSKEYUP => {
            // The pump has already run TranslateMessage, so the characters
            // this key typed are queued. Take them before the surface is
            // resolved: PeekMessage runs cross-thread sent messages.
            const typed: win32_input.TypedChars = if (msg == c.WM_KEYDOWN or msg == c.WM_SYSKEYDOWN)
                win32_input.takeTypedChars(hwnd)
            else
                .{};
            if (getSurface(hwnd)) |v| {
                // VK_APPS (Menu key) -> show context menu when not mouse reporting
                const vk: UINT = @intCast(wParam & 0xFFFF);
                if (vk == c.VK_APPS and (msg == c.WM_KEYDOWN or msg == c.WM_SYSKEYDOWN)) {
                    if (!v.core_initialized or v.core_surface.io.terminal.flags.mouse_event == .none) {
                        if (v.host) |h| {
                            // Keyboard invoke: use center of surface
                            var rect: RECT = undefined;
                            if (sys.GetClientRect(hwnd, &rect) != 0) {
                                var pt: POINT = .{
                                    .x = @divTrunc(rect.right, 2),
                                    .y = @divTrunc(rect.bottom, 2),
                                };
                                _ = sys.ClientToScreen(hwnd, &pt);
                                h.showContextMenu(pt.x, pt.y);
                            }
                        }
                        return 0;
                    }
                }
                v.handleKeyMessage(msg, wParam, lParam, &typed);
                return 0;
            }
            return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
        },

        c.WM_IME_STARTCOMPOSITION => {
            if (surface) |v| {
                v.deferred_char.clear();
                v.ime_composing = true;
                v.positionImeWindow();
            }
            return 0;
        },

        c.WM_IME_COMPOSITION => {
            if (surface) |v| {
                v.deferred_char.clear();
                const parts: u32 = @intCast(lParam);
                if ((parts & c.GCS_RESULTSTR) != 0) {
                    // Committing into a pane whose child has exited closes
                    // the pane, which frees the surface before this returns.
                    if (v.handleImeResult() == .closed) return 0;
                }
                if ((parts & c.GCS_COMPSTR) != 0) {
                    v.handleImeComposition();
                }
                return 0;
            }
            return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
        },

        c.WM_IME_ENDCOMPOSITION => {
            if (surface) |v| {
                v.deferred_char.clear();
                v.ime_composing = false;
                v.core_surface.preeditCallback(null) catch {};
            }
            return 0;
        },

        c.WM_IME_SETCONTEXT => {
            // We handle preedit via the core renderer.
            const masked_lParam = lParam & ~c.ISC_SHOWUICOMPOSITIONWINDOW;
            return sys.DefWindowProcW(hwnd, msg, wParam, masked_lParam);
        },

        c.WM_CHAR, c.WM_DEADCHAR, c.WM_SYSDEADCHAR => {
            if (surface) |v| v.handleCharMessage(msg, wParam, lParam);
            return 0;
        },

        c.WM_SYSCHAR => {
            // `TranslateMessage` turns an Alt chord's WM_SYSKEYDOWN into
            // this. The chord was already encoded from the key message (an
            // Alt chord never defers its text to a character message), so
            // the character carries nothing the terminal still needs, and
            // handed to DefWindowProc it becomes SC_KEYMENU: a window with
            // no menu bar answers that with a menu loop that matches nothing
            // and the shell's default beep (#250). Swallowed outright, and
            // left out of `takeTypedChars`: committing it would type the
            // chord's character a second time after the chord. Alt+Space
            // alone still opens the window menu, which
            // Windows reserves for moving and resizing from the keyboard,
            // and only on a window that has one.
            if (surface) |v| {
                if (!win32_input.sysCharOpensWindowMenu(@intCast(wParam & 0xFFFF))) return 0;
                if (!v.hasWindowMenu()) return 0;
            }
            return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
        },

        c.WM_MOUSEMOVE => {
            if (surface) |v| {
                v.armScrollbarLeaveTracking(hwnd);
                if (v.handleScrollbarProxyMouseMove(hwnd, lParam)) return 0;
                v.handleMouseMove(lParam, mouseModsFromWParam(wParam));
                return 0;
            }
            return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
        },

        c.WM_MOUSELEAVE => {
            if (surface) |v| {
                v.handleMouseLeave();
                return 0;
            }
            return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
        },

        c.WM_RBUTTONUP => {
            if (surface) |v| {
                // Balance the core's press even when the click opens a menu.
                // Snapshot and clear before releasing capture, which can send
                // synchronous window messages. A reporting TUI consumes the
                // press; Shift bypasses it unless the TUI captures Shift too.
                const show_menu = v.core_initialized and rightClickShowsMenu(
                    v.core_surface.config.right_click_action,
                    v.right_press_consumed,
                );
                v.right_press_consumed = false;
                _ = v.handleMouseButton(msg, wParam, lParam);
                if (!show_menu) return 0;
                if (v.host) |h| {
                    var pt: POINT = .{
                        .x = signedLowWord(lParamBits(lParam)),
                        .y = signedHighWord(lParamBits(lParam)),
                    };
                    _ = sys.ClientToScreen(hwnd, &pt);
                    h.showContextMenu(pt.x, pt.y);
                }
                return 0;
            }
            return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
        },

        c.WM_LBUTTONDOWN, c.WM_LBUTTONUP => {
            if (surface) |v| {
                if (v.handleScrollbarProxyButton(hwnd, msg, lParam)) return 0;
                _ = v.handleMouseButton(msg, wParam, lParam);
                return 0;
            }
            return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
        },

        c.WM_RBUTTONDOWN => {
            if (surface) |v| {
                v.right_press_consumed = v.handleMouseButton(msg, wParam, lParam);
                return 0;
            }
            return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
        },

        c.WM_MBUTTONDOWN, c.WM_MBUTTONUP => {
            if (surface) |v| {
                _ = v.handleMouseButton(msg, wParam, lParam);
                return 0;
            }
            return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
        },

        c.WM_XBUTTONDOWN, c.WM_XBUTTONUP => {
            if (surface) |v| {
                v.handleXMouseButton(msg, wParam, lParam);
            }
            // Windows requires TRUE for XButton messages
            return 1;
        },

        c.WM_DROPFILES => {
            if (surface) |v| {
                v.handleDropFiles(wParam);
            }
            return 0;
        },

        c.WM_MOUSEWHEEL, c.WM_POINTERWHEEL => {
            if (surface) |v| {
                v.updateWheelCursorPos(hwnd, lParam);
                v.handleMouseWheel(normalizeWheelDelta(
                    v.wheelNormalizationContext(),
                    .vertical,
                    wheelDeltaFromWParam(wParam),
                ));
                return 0;
            }
            return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
        },

        c.WM_MOUSEHWHEEL, c.WM_POINTERHWHEEL => {
            if (surface) |v| {
                v.updateWheelCursorPos(hwnd, lParam);
                v.handleMouseWheel(normalizeWheelDelta(
                    v.wheelNormalizationContext(),
                    .horizontal,
                    wheelDeltaFromWParam(wParam),
                ));
                return 0;
            }
            return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
        },

        c.WM_ERASEBKGND => return 1,

        c.WM_SETTINGCHANGE => {
            if (surface) |v| v.app.refreshSystemWheelSettings();
            return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
        },

        c.WM_SETCURSOR => {
            if (surface) |v| {
                if (lowWord(@as(usize, @intCast(lParam))) == c.HTCLIENT) {
                    const now_ms = sys.GetTickCount64();
                    const was_hovered = v.scrollbar_state.hovered;
                    const was_visibility = v.scrollbar_state.visibility;
                    const over_scrollbar = v.updateScrollbarHoverFromScreenCursor(hwnd, now_ms);
                    if (over_scrollbar or
                        v.scrollbar_state.hovered != was_hovered or
                        v.scrollbar_state.visibility != was_visibility)
                    {
                        v.syncScrollbarWindowNow(now_ms) catch |err| {
                            log.warn("win32 scrollbar cursor refresh failed err={}", .{err});
                        };
                    }
                    if (over_scrollbar or v.scrollbar_state.dragging) {
                        _ = sys.SetCursor(sys.LoadCursorW(null, c.IDC_ARROW));
                        return 1;
                    }
                    if (v.applyCursor()) {
                        return 1;
                    }
                }
            }
            return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
        },

        c.WM_CAPTURECHANGED => {
            if (surface) |v| v.handleScrollbarCaptureChanged();
            return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
        },

        0x8050, 0x8051, 0x8052, 0x8053, 0x8054, 0x8058 => { // Test-only renderer lifecycle actions.
            if (build_config.renderer_test_tools and build_config.d3d11) {
                if (surface) |v| {
                    if (!v.core_initialized) return 0;
                    if (msg == 0x8052 or msg == 0x8053 or msg == 0x8058) {
                        if (!v.core_surface.renderer.setTestFailures(msg == 0x8052, msg == 0x8053)) return 0;
                    }
                    if (msg == 0x8054) {
                        if (!v.core_surface.renderer.failNextPresent()) return 0;
                    } else if (msg != 0x8051 and !v.core_surface.renderer.requestDeviceLoss()) return 0;
                    v.redraw() catch return 0;
                    return 1;
                }
            }
            return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
        },
        0x8056 => { // Test-only actions through the production binding path.
            if (build_config.renderer_test_tools) {
                if (surface) |v| {
                    if (!v.core_initialized) return 0;
                    const action: input.Binding.Action = switch (wParam) {
                        1 => .new_tab,
                        2 => .{ .new_split = .right },
                        3 => .{ .new_split = .down },
                        4 => .previous_tab,
                        5 => .next_tab,
                        6 => .close_surface,
                        7 => .reload_config,
                        else => return 0,
                    };
                    return @intFromBool(v.core_surface.performBindingAction(action) catch false);
                }
            }
            return 0;
        },
        0x8057 => { // Test-only DPI scale notification, without moving monitors.
            if (build_config.renderer_test_tools) {
                if (surface) |v| {
                    // Down to half of 96, so a 96 DPI host can scale down too.
                    if (!v.core_initialized or wParam < 48 or wParam > 384) return 0;
                    const scale: f32 = @as(f32, @floatFromInt(wParam)) / 96;
                    v.content_scale = .{ .x = scale, .y = scale };
                    v.core_surface.contentScaleCallback(v.content_scale) catch return 0;
                    return 1;
                }
            }
            return 0;
        },
        0x0317, 0x0318 => { // Test-only in-app GPU readback (no DWM evidence).
            if (build_config.renderer_test_tools and build_config.d3d11) {
                if (surface) |v| {
                    if (v.core_initialized and wParam != 0) {
                        v.core_surface.renderer.capture(@ptrFromInt(wParam)) catch return 0;
                        return 1;
                    }
                }
            }
            return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
        },
        c.WM_PAINT => {
            var ps: PAINTSTRUCT = undefined;
            _ = sys.BeginPaint(hwnd, &ps) orelse return 0;
            defer _ = sys.EndPaint(hwnd, &ps);

            if (surface) |v| {
                const draw_content = v.shouldDrawRendererPaintContent();
                v.paint_pending = false;
                if (draw_content) {
                    const paint_start_ms = if (v.render_trace.enabled()) sys.GetTickCount64() else 0;
                    v.render_trace.notePaintDraw();
                    defer v.finishRendererRepaintRequest();
                    defer if (paint_start_ms != 0) {
                        const paint_end_ms = sys.GetTickCount64();
                        if (paint_end_ms > paint_start_ms) {
                            v.render_trace.notePaintDrawDuration(paint_end_ms - paint_start_ms);
                        }
                    };
                    v.redraw() catch |err| {
                        log.err("win32 paint redraw failed err={}", .{err});
                    };
                } else {
                    v.render_trace.notePaintRetry();
                    v.requestRendererFrameNow(.apprt_paint_retry);
                    // The OS asked for pixels and the renderer had none
                    // reserved. `.apprt_paint_retry` above only wakes the
                    // renderer; it cannot help if the renderer still thinks
                    // this surface is occluded, and it does not re-arm the
                    // update region. See `win32/first_frame.zig` (#224).
                    v.noteFirstFrame(.paint_without_content);
                }
            }

            return 0;
        },

        c.WM_CLOSE => {
            if (surface) |v| _ = v.requestClose();
            return 0;
        },

        c.WM_DESTROY => {
            if (surface) |v| {
                if (v.destroy_on_wm_destroy) {
                    v.destroy();
                } else if (v.hwnd == hwnd) {
                    // The chrome children die with this window. Detach their
                    // providers here rather than leaving them to decide
                    // availability from `IsWindow`, which can answer yes again
                    // once the system recycles the handle value.
                    detachChromeControlProvider(v.app, &v.scrollbar_uia_provider);
                    v.destroySearchBarControls();
                    v.hwnd = null;
                }
            }
            return 0;
        },

        else => return sys.DefWindowProcW(hwnd, msg, wParam, lParam),
    }
}

fn getSurface(hwnd: HWND) ?*Surface {
    return windowData(Surface, hwnd);
}

fn terminalAccessibilityHwnd(ctx: *anyopaque) ?HWND {
    const surface: *Surface = @ptrCast(@alignCast(ctx));
    return surface.hwnd;
}

fn terminalAccessibilityName(ctx: *anyopaque, buf: []u8) []const u8 {
    const surface: *Surface = @ptrCast(@alignCast(ctx));
    const title = surface.effectiveTitle() orelse "Terminal";
    return std.fmt.bufPrint(buf, "Terminal: {s}", .{title}) catch "Terminal";
}

fn terminalAccessibilityFocused(ctx: *anyopaque) bool {
    const surface: *Surface = @ptrCast(@alignCast(ctx));
    return surface.app.isSurfaceFocused(surface);
}

fn terminalAccessibilityCapture(
    ctx: *anyopaque,
    alloc: Allocator,
) !win32_terminal_accessibility.Capture {
    const surface: *Surface = @ptrCast(@alignCast(ctx));
    if (!surface.core_initialized) return error.SurfaceNotInitialized;

    // This runs on the UI thread, reached from `windowProc` via WM_GETOBJECT,
    // and UIA can re-enter `windowProc` while the UI thread already holds the
    // renderer lock. Blocking here stops the message loop for as long as the
    // lock is held -- indefinitely in the re-entrant case. Take the lock only
    // if it is free and let the caller keep its cached snapshot otherwise.
    if (!surface.core_surface.renderer_state.mutex.tryLock()) return error.WouldBlock;
    const snapshot = win32_uia.snapshotTerminalAccessiblePlainText(
        alloc,
        surface.core_surface.renderer_state.terminal,
    ) catch |err| {
        surface.core_surface.renderer_state.mutex.unlock();
        return err;
    };
    const renderer_size = surface.core_surface.size;
    surface.core_surface.renderer_state.mutex.unlock();
    return .{
        .snapshot = snapshot,
        .cell_width = @floatFromInt(renderer_size.cell.width),
        .cell_height = @floatFromInt(renderer_size.cell.height),
        .origin_x = @floatFromInt(renderer_size.padding.left),
        .origin_y = @floatFromInt(renderer_size.padding.top),
    };
}

fn terminalAccessibilityViewport(ctx: *anyopaque) !win32_uia.widgets.TerminalViewportGeometry {
    const surface: *Surface = @ptrCast(@alignCast(ctx));
    if (!surface.core_initialized) return error.ElementNotAvailable;
    const core = &surface.core_surface;
    if (!core.renderer_state.mutex.tryLock()) return error.WouldBlock;
    defer core.renderer_state.mutex.unlock();
    const state = core.renderer_state.terminal;
    const pages = &state.screens.active.pages;
    const viewport = pages.pointFromPin(.screen, pages.getTopLeft(.viewport)) orelse return error.UnknownPoint;
    return .{
        .row_numbering = @import("win32_uia/text.zig").rowNumbering(state),
        .viewport_y = viewport.screen.y,
        .cell_width = @floatFromInt(core.size.cell.width),
        .cell_height = @floatFromInt(core.size.cell.height),
        .origin_x = @floatFromInt(core.size.padding.left),
        .origin_y = @floatFromInt(core.size.padding.top),
    };
}

fn terminalAccessibilityDeferProviderRelease(
    ctx: *anyopaque,
    provider: *win32_uia.TerminalProvider,
) void {
    const surface: *Surface = @ptrCast(@alignCast(ctx));
    scheduleDeferredUiaDisconnect(
        surface.app,
        @ptrCast(provider),
        &terminalDisconnectThunk,
        &terminalReleaseThunk,
    );
}

fn terminalAccessibilityScroll(ctx: *anyopaque, request: win32_uia.widgets.ScrollRequest) !void {
    const surface: *Surface = @ptrCast(@alignCast(ctx));
    if (!surface.core_initialized) return error.ElementNotAvailable;
    const core = &surface.core_surface;
    if (!core.renderer_state.mutex.tryLock()) return error.WouldBlock;
    const scrolled = @import("win32_uia/text.zig").scrollFrozenRange(
        core.alloc,
        core.renderer_state.terminal,
        request.token,
        request.document_window,
        request.absolute_row,
        request.align_to_top,
    ) catch |err| {
        core.renderer_state.mutex.unlock();
        return err;
    };
    core.renderer_state.mutex.unlock();
    if (scrolled) try core.refreshCallback();
}

fn terminalAccessibilityOutputCallback(
    ctx: *anyopaque,
    item: apprt.surface.TerminalOutputTransport.Item,
) void {
    const session: *win32_terminal_accessibility.TerminalAccessibilitySession =
        @ptrCast(@alignCast(ctx));
    switch (item) {
        .reset => session.resetSemanticOutputContinuity(),
        .data => |output| session.noteSemanticOutput(output),
        .omitted => session.noteOutputOmitted(),
    }
}

const QuickSelectSession = struct {
    const PendingAction = struct {
        trigger_vk: UINT,
        index: ?usize,
        ctrl: bool,
        alt: bool,
    };

    scan: win32_hints.Scan,
    labels: win32_hints.LabelSet,
    prefix: win32_hints.PrefixState = .{},
    pending_action: ?PendingAction = null,
    awaiting_composed_char: bool = false,
    suppress_until_opening_keys_released: bool = false,
    suppress_opening_left_button_up: bool = false,
    cell_width: i32,
    cell_height: i32,
    padding_left: i32,
    padding_top: i32,
    placed_rects: []RECT,
    placed_slots: []?usize,
    placed_count: usize = 0,
    placement_client: ?RECT = null,
    placement_metrics: ?win32_theme.ThemeMetrics = null,
    placement_dpi: UINT = 0,
    placement_complete: bool = false,

    fn deinit(self: *QuickSelectSession, alloc: Allocator) void {
        alloc.free(self.placed_slots);
        alloc.free(self.placed_rects);
        self.labels.deinit(alloc);
        self.scan.deinit(alloc);
        self.* = undefined;
    }
};

test "quick select label placement checks final positioned chips" {
    const client: RECT = .{ .left = 0, .top = 0, .right = 100, .bottom = 100 };
    var comparisons_remaining: usize = Surface.quick_select_placement_comparison_budget;
    const occupied = [_]RECT{
        .{ .left = 0, .top = 0, .right = 20, .bottom = 10 },
        .{ .left = 10, .top = 10, .right = 30, .bottom = 20 },
    };
    const placed = Surface.quickSelectPositionLabel(
        .{ .left = 10, .top = 10, .right = 20, .bottom = 20 },
        client,
        &occupied,
        &comparisons_remaining,
    ).?;
    try std.testing.expectEqual(@as(i32, 20), placed.top);
    try std.testing.expectEqual(@as(i32, 30), placed.bottom);
}

test "quick select label placement uses the free global grid" {
    const client: RECT = .{ .left = 0, .top = 0, .right = 30, .bottom = 20 };
    var comparisons_remaining: usize = Surface.quick_select_placement_comparison_budget;
    const occupied = [_]RECT{
        .{ .left = 10, .top = 0, .right = 20, .bottom = 10 },
        .{ .left = 10, .top = 10, .right = 20, .bottom = 20 },
    };
    const placed = Surface.quickSelectPositionLabel(
        .{ .left = 10, .top = 0, .right = 20, .bottom = 10 },
        client,
        &occupied,
        &comparisons_remaining,
    ).?;
    try std.testing.expectEqual(@as(i32, 0), placed.left);
    try std.testing.expectEqual(@as(i32, 10), placed.right);
}

test "quick select label placement reports an exhausted viewport" {
    const client: RECT = .{ .left = 0, .top = 0, .right = 20, .bottom = 20 };
    var comparisons_remaining: usize = Surface.quick_select_placement_comparison_budget;
    const occupied = [_]RECT{
        .{ .left = 0, .top = 0, .right = 10, .bottom = 10 },
        .{ .left = 10, .top = 0, .right = 20, .bottom = 10 },
        .{ .left = 0, .top = 10, .right = 10, .bottom = 20 },
        .{ .left = 10, .top = 10, .right = 20, .bottom = 20 },
    };
    try std.testing.expect(Surface.quickSelectPositionLabel(
        .{ .left = 0, .top = 0, .right = 10, .bottom = 10 },
        client,
        &occupied,
        &comparisons_remaining,
    ) == null);
}

test "quick select label placement stops at its comparison budget" {
    const client: RECT = .{ .left = 0, .top = 0, .right = 20, .bottom = 20 };
    const occupied = [_]RECT{.{ .left = 0, .top = 0, .right = 10, .bottom = 10 }};
    var comparisons_remaining: usize = 0;
    try std.testing.expect(Surface.quickSelectPositionLabel(
        .{ .left = 0, .top = 0, .right = 10, .bottom = 10 },
        client,
        &occupied,
        &comparisons_remaining,
    ) == null);
}

fn quickSelectLabelDisplayUnit(byte: u8) u16 {
    return if (byte == ' ') 0x2423 else byte;
}

/// Opening a modal overlay transfers focus while its shortcut is still held.
/// Snapshotting this as a boolean is sufficient because the overlay ignores
/// every label input until a key-up observes that no virtual key remains down.
fn anyVirtualKeyPressed() bool {
    for (0..256) |vk| {
        if (win32_input.keyPressed(@intCast(vk))) return true;
    }
    return false;
}

test "quick select label renders spaces visibly" {
    try std.testing.expectEqual(@as(u16, 0x2423), quickSelectLabelDisplayUnit(' '));
    try std.testing.expectEqual(@as(u16, 'a'), quickSelectLabelDisplayUnit('a'));
}

fn quickSelectCanActivate(window_visible: bool, hwnd_visible: bool) bool {
    return window_visible and hwnd_visible;
}

test "quick select activates only for a visible surface" {
    try std.testing.expect(quickSelectCanActivate(true, true));
    try std.testing.expect(!quickSelectCanActivate(false, true));
    try std.testing.expect(!quickSelectCanActivate(true, false));
}

fn consumeQuickSelectOpeningLeftButtonUp(
    suppress_button_up: *bool,
    suppress_keys: *bool,
    any_key_pressed: bool,
) bool {
    if (!suppress_button_up.*) return false;
    suppress_button_up.* = false;
    suppress_keys.* = any_key_pressed;
    return true;
}

test "quick select consumes only the opening left button release" {
    var suppress_button_up = true;
    var suppress_keys = true;
    try std.testing.expect(consumeQuickSelectOpeningLeftButtonUp(
        &suppress_button_up,
        &suppress_keys,
        false,
    ));
    try std.testing.expect(!suppress_button_up);
    try std.testing.expect(!suppress_keys);
    try std.testing.expect(!consumeQuickSelectOpeningLeftButtonUp(
        &suppress_button_up,
        &suppress_keys,
        false,
    ));

    suppress_button_up = true;
    try std.testing.expect(consumeQuickSelectOpeningLeftButtonUp(
        &suppress_button_up,
        &suppress_keys,
        true,
    ));
    try std.testing.expect(suppress_keys);
}

pub const Surface = struct {
    app: *App,
    shell_id: ?win32_shell.model.PaneId = null,
    shell_committed: bool = false,
    host: ?*Host = null,
    host_id: u32 = 0,
    host_active: bool = true,
    window_visible: bool = false,
    occlusion_visible: ?bool = null,
    hwnd: ?HWND = null,
    placement: ChildPlacement = .{},
    hdc: HDC = null,
    hglrc: HGLRC = null,
    /// The pixel format this window took, once `SetPixelFormat` succeeded.
    /// A window keeps its format for good, so a later OpenGL attempt (a
    /// fallback from D3D11 after an earlier one failed) must reuse it.
    gl_pixel_format: ?pixel_format.WglPixelFormatProvenance = null,
    core_surface: CoreSurface = undefined,
    core_initialized: bool = false,
    adopted_session: ?ptypkg.AdoptedSession = null,
    adopted_console: bool = false,
    /// Set once the core has asked for the pty's hosting window
    /// (`consoleOwner`); until then there is no console window to keep in step.
    console_window_attached: bool = false,
    console_window_visible: ?bool = null,
    destroy_on_wm_destroy: bool = false,
    content_scale: apprt.ContentScale = .{ .x = 1, .y = 1 },
    size: apprt.SurfaceSize = .{ .width = 800, .height = 600 },
    cursor_pos: apprt.CursorPos = .{ .x = -1, .y = -1 },
    right_press_consumed: bool = false,
    title: ?[:0]const u8 = null,
    title_override: ?[:0]const u8 = null,
    tab_title_override: ?[:0]const u8 = null,
    launch_profile_key: ?[:0]const u8 = null,
    /// Recorded from the resolved profile kind at launch, so nothing downstream
    /// has to re-derive "is this SSH?" from the key text.
    launched_ssh: bool = false,
    launch_command: ?configpkg.Command = null,
    mouse_shape: terminal.MouseShape = .text,
    mouse_visible: bool = true,
    hovered_link: ?[:0]const u8 = null,
    window_focused: bool = false,
    /// The bell rang here while the user was not looking; the tab label and
    /// the window caption carry the glyph until `clearBell`.
    bell_ringing: bool = false,
    decorations_visible: bool = true,
    decorations_visible_overridden: bool = false,
    fullscreen: bool = false,
    topmost: bool = false,
    /// What `leaveFullscreen` returns the window to, captured by
    /// `enterFullscreen`: the window rect, and the placement for a window
    /// that was maximized.
    restore_rect: RECT = .{ .left = 0, .top = 0, .right = 0, .bottom = 0 },
    restore_placement: WINDOWPLACEMENT = std.mem.zeroes(WINDOWPLACEMENT),
    restore_monitor: ?FullscreenMonitor = null,
    default_client_size: ?apprt.SurfaceSize = null,
    cell_size_pixels: apprt.action.CellSize = .{ .width = 0, .height = 0 },
    background_opacity_default: f64 = 1.0,
    background_opacity_force_opaque: bool = false,
    scrollbar_config: configpkg.Config.Scrollbar = .system,
    size_limit: apprt.action.SizeLimit = .{
        .min_width = 0,
        .min_height = 0,
        .max_width = 0,
        .max_height = 0,
    },
    secure_input: bool = false,
    secure_input_ever_engaged: bool = false,
    key_sequence_active: bool = false,
    key_table_name: ?[:0]const u8 = null,
    search_active: bool = false,
    search_needle: ?[:0]const u8 = null,
    search_total: ?usize = null,
    search_selected_raw: ?usize = null,
    search_selected: ?usize = null,
    search_match_rows: []const u32 = &.{},
    scrollbar: terminal.Scrollbar = .zero,
    scrollbar_state: win32_scrollbar_geometry.ScrollbarState = .{},
    scrollbar_hwnd: ?HWND = null,
    scrollbar_uia_provider: ?*win32_uia.ChromeControlProvider = null,
    scrollbar_placement: ChildPlacement = .{},
    scrollbar_leave_armed: bool = false,
    scrollbar_leave_hwnd: ?HWND = null,
    scrollbar_drag_anchor_offset: f32 = 0,
    scrollbar_alpha_cache: BYTE = 0,
    scrollbar_markers: []const f32 = &.{},
    scrollbar_marker_revision: u64 = 0,
    scrollbar_marker_budget: usize = 0,
    scrollbar_paint_cache: ?ScrollbarPaintKey = null,
    quick_select_hwnd: ?HWND = null,
    quick_select_placement: ChildPlacement = .{},
    quick_select_session: ?QuickSelectSession = null,
    quick_select_uia_provider: ?*win32_uia.PaletteListProvider = null,
    pwd: ?[:0]const u8 = null,
    taskbar_progress: ?win32_taskbar_progress.ProgressReport = null,
    /// What this terminal's programs reported through OSC 7501.
    program_status: win32_program_status.Records = .{},
    /// When this surface last raised a program status notification, in
    /// `GetTickCount64` milliseconds.
    program_status_notified_ms: ?u64 = null,
    /// A notification the rate limit held back is waiting; see
    /// `App.flushProgramStatusNotifications`.
    program_status_notify_pending: bool = false,
    inspector_visible: bool = false,
    paint_pending: bool = false,
    live_resize_repaint_deferred: bool = false,
    renderer_gl_prepared: bool = false,
    /// OpenGL failed before core init (the eager WGL context or GL loading);
    /// renderer init falls back to the Direct3D 11 beta with this error,
    /// which it consumes.
    renderer_gl_error: ?anyerror = null,
    renderer_repaint_requested: std.atomic.Value(bool) = .init(false),
    renderer_repaint_retry_pending: std.atomic.Value(bool) = .init(false),
    /// One-shot post-show frame handshake for #224. Only ever touched from
    /// the UI thread (`WM_SHOWWINDOW`, `WM_WINDOWPOSCHANGED`, `WM_PAINT` and
    /// the `SwapBuffers` that `WM_PAINT` drives), so it needs no atomics.
    first_frame: first_frame.State = .{},
    draw_in_progress: bool = false,
    ime_composing: bool = false,
    deferred_char: DeferredCharState = .{},
    undo_capture_suspended: bool = false,
    render_trace: RenderTrace = .{},
    memory_stage_trace: MemoryStageTrace = .{},
    /// Per-surface bounded undo stack for terminal-local replayable
    /// actions (`clear_screen`, `reset`). Structural history that
    /// retains live tabs/surfaces lives on `Host` because it crosses
    /// pane boundaries and outlives the triggering surface.
    undo_stack: win32_undo.UndoStack = undefined,
    /// Per-pane docked search bar state. The pure state machine
    /// lives in `win32_search_bar.zig`; HWNDs below are the live
    /// child controls docked above the pane content.
    search_bar: win32_search_bar.SearchBar = undefined,
    search_bar_frame_rect: RECT = .{ .left = 0, .top = 0, .right = 0, .bottom = 0 },
    search_bar_frame_visible: bool = false,
    search_bar_bg_hwnd: ?HWND = null,
    search_bar_bg_uia_provider: ?*win32_uia.ChromeControlProvider = null,
    search_bar_bg_placement: ChildPlacement = .{},
    search_bar_edit_hwnd: ?HWND = null,
    search_bar_edit_prev_proc: ?*const anyopaque = null,
    search_bar_edit_uia_provider: ?*win32_uia.TerminalProvider = null,
    search_bar_edit_uia_selection: ?[2]u32 = null,
    search_bar_edit_placement: ChildPlacement = .{},
    search_bar_prev_hwnd: ?HWND = null,
    search_bar_next_hwnd: ?HWND = null,
    search_bar_regex_hwnd: ?HWND = null,
    search_bar_case_hwnd: ?HWND = null,
    search_bar_word_hwnd: ?HWND = null,
    search_bar_close_hwnd: ?HWND = null,
    search_bar_button_prev_procs: [6]?*const anyopaque = [_]?*const anyopaque{null} ** 6,
    search_bar_button_uia_providers: [6]?*win32_uia.ChromeControlProvider = [_]?*win32_uia.ChromeControlProvider{null} ** 6,
    search_bar_prev_placement: ChildPlacement = .{},
    search_bar_next_placement: ChildPlacement = .{},
    search_bar_regex_placement: ChildPlacement = .{},
    search_bar_case_placement: ChildPlacement = .{},
    search_bar_word_placement: ChildPlacement = .{},
    search_bar_close_placement: ChildPlacement = .{},
    search_bar_results_hwnd: ?HWND = null,
    search_bar_results_uia_provider: ?*win32_uia.ChromeControlProvider = null,
    search_bar_label_prev_procs: [2]?*const anyopaque = .{ null, null },
    search_bar_results_placement: ChildPlacement = .{},
    search_bar_results_cache: ?[:0]const u8 = null,
    /// Surface's initial reference to an independently allocated OLE
    /// drop target. Detached and released during native-window teardown;
    /// retained COM references keep only the target alive after that.
    drop_target: ?*win32_surface_drop_target.DropTarget = null,
    drop_target_registered: bool = false,
    /// Clipboard operation parked on `HostOverlayMode.confirm` — the
    /// owning `Surface` holds deep-copied payload bytes so the async
    /// accept / cancel callback sees valid data regardless of the
    /// original caller's buffer lifetime. Non-null exactly while an
    /// overlay is pending. Drained by `surfaceConfirmPasteAccept` /
    /// `surfaceConfirmWriteAccept` / the matching cancel callbacks,
    /// and by `Surface.destroyWindow` so a close-while-pending doesn't
    /// leak.
    pending_clipboard_op: ?PendingClipboardOp = null,
    terminal_accessibility: ?*win32_terminal_accessibility.TerminalAccessibilitySession = null,
    /// Close preflight ownership. Normal close paths build both candidates
    /// before HWND/core teardown; `windowDestroyed` consumes them without
    /// allocating after the Surface is already dead.
    pending_close_tree: ?SplitTreeSurface = null,
    pending_shell_close: ?win32_shell.runtime.Prepared = null,

    fn searchBarButtonHwnd(self: *const Surface, role: SearchBarButtonRole) ?HWND {
        return switch (role) {
            .prev => self.search_bar_prev_hwnd,
            .next => self.search_bar_next_hwnd,
            .regex => self.search_bar_regex_hwnd,
            .case_sensitive => self.search_bar_case_hwnd,
            .whole_word => self.search_bar_word_hwnd,
            .close => self.search_bar_close_hwnd,
        };
    }

    fn searchControlUiaName(_: *anyopaque, tag: usize, _: []u8) []const u8 {
        return labels.searchBarButtonName(@enumFromInt(tag));
    }

    fn searchToggleUiaState(ctx: *anyopaque, tag: usize) bool {
        const self: *Surface = @ptrCast(@alignCast(ctx));
        return self.searchBarButtonActive(@enumFromInt(tag));
    }

    fn searchResultsUiaName(ctx: *anyopaque, _: usize, buf: []u8) []const u8 {
        const self: *Surface = @ptrCast(@alignCast(ctx));
        return if (self.search_bar_results_cache) |text|
            std.fmt.bufPrint(buf, "{s}", .{text}) catch "Search results"
        else
            "Search results";
    }

    fn decorativeUiaName(_: *anyopaque, _: usize, _: []u8) []const u8 {
        return "";
    }

    fn scrollbarUiaName(_: *anyopaque, _: usize, _: []u8) []const u8 {
        return "Terminal scrollbar";
    }

    fn scrollbarUiaRangeValue(value: terminal.Scrollbar) win32_uia.ChromeRangeValue {
        const maximum = value.total -| value.len;
        return .{
            .value = @floatFromInt(@min(value.offset, maximum)),
            .minimum = 0,
            .maximum = @floatFromInt(maximum),
            .large_change = @floatFromInt(value.len),
            .small_change = 1,
        };
    }

    fn scrollbarUiaRange(ctx: *anyopaque) win32_uia.ChromeRangeValue {
        const self: *Surface = @ptrCast(@alignCast(ctx));
        return scrollbarUiaRangeValue(self.scrollbar);
    }

    fn createChromeUiaProvider(
        self: *Surface,
        hwnd: HWND,
        state: win32_uia.ChromeControlState,
    ) ?*win32_uia.ChromeControlProvider {
        // Both helpers already bail out unless COM is initialised, so the
        // provider always uses COM threading; callers do not repeat it.
        if (!self.app.com_initialized) return null;
        var threaded_state = state;
        threaded_state.use_com_threading = true;
        return win32_uia.ChromeControlProvider.create(
            std.heap.page_allocator,
            hwnd,
            threaded_state,
        ) catch |err| {
            log.warn("surface chrome UIA provider unavailable err={}", .{err});
            return null;
        };
    }

    fn searchLabelUiaProvider(self: *Surface, hwnd: HWND) ?*win32_uia.ChromeControlProvider {
        if (self.search_bar_bg_hwnd == hwnd) return self.search_bar_bg_uia_provider;
        if (self.search_bar_results_hwnd == hwnd) return self.search_bar_results_uia_provider;
        return null;
    }

    fn searchLabelPrevProc(self: *Surface, hwnd: HWND) ?*const anyopaque {
        if (self.search_bar_bg_hwnd == hwnd) return self.search_bar_label_prev_procs[0];
        if (self.search_bar_results_hwnd == hwnd) return self.search_bar_label_prev_procs[1];
        return null;
    }

    fn searchEditUiaState(self: *Surface) win32_uia.TerminalState {
        return .{
            .ctx = @ptrCast(self),
            .name = &searchEditNameThunk,
            .value = &searchEditValueThunk,
            .snapshot = &searchEditSnapshotThunk,
            .focused = &searchEditFocusedThunk,
            .role = .edit,
            .use_com_threading = self.app.com_initialized,
            .set_value = &searchEditSetValueThunk,
            .select_range = &searchEditSelectRangeThunk,
        };
    }

    fn raiseSearchEditSelectionChangedIfNeeded(self: *Surface) void {
        const hwnd = self.search_bar_edit_hwnd orelse return;
        const provider = self.search_bar_edit_uia_provider orelse return;
        const selection = nativeEditSelection(hwnd);
        if (self.search_bar_edit_uia_selection) |previous| {
            if (std.meta.eql(previous, selection)) return;
        }
        self.search_bar_edit_uia_selection = selection;
        provider.raiseTextSelectionChanged();
    }

    fn searchBarButtonPlacement(self: *Surface, role: SearchBarButtonRole) *ChildPlacement {
        return switch (role) {
            .prev => &self.search_bar_prev_placement,
            .next => &self.search_bar_next_placement,
            .regex => &self.search_bar_regex_placement,
            .case_sensitive => &self.search_bar_case_placement,
            .whole_word => &self.search_bar_word_placement,
            .close => &self.search_bar_close_placement,
        };
    }

    fn searchBarButtonRole(self: *const Surface, hwnd: HWND) ?SearchBarButtonRole {
        for (search_bar_button_roles) |role| {
            if (self.searchBarButtonHwnd(role)) |button_hwnd| {
                if (hwnd == button_hwnd) return role;
            }
        }
        return null;
    }

    fn searchBarButtonActive(self: *const Surface, role: SearchBarButtonRole) bool {
        return switch (role) {
            .regex => self.search_bar.toggles.regex,
            .case_sensitive => self.search_bar.toggles.case_sensitive,
            .whole_word => self.search_bar.toggles.whole_word,
            else => false,
        };
    }

    fn ownsSearchBarControl(self: *const Surface, hwnd: HWND) bool {
        if (self.search_bar_edit_hwnd != null and hwnd == self.search_bar_edit_hwnd.?) return true;
        if (self.search_bar_results_hwnd != null and hwnd == self.search_bar_results_hwnd.?) return true;
        return self.searchBarButtonRole(hwnd) != null;
    }

    fn searchBarButtonPrevProc(self: *const Surface, hwnd: HWND) ?*const anyopaque {
        const role = self.searchBarButtonRole(hwnd) orelse return null;
        return self.search_bar_button_prev_procs[@intFromEnum(role)];
    }

    fn initialDecorationsVisible(config: *const configpkg.Config, opts: SurfaceInitOptions) bool {
        return initialDecorationsVisibleForSource(config, opts.clone_state_from);
    }

    /// The `Surface.init` steps `App.test_surface_init_stage` stands in for.
    const InitStage = enum { gl_context, core_surface };

    pub fn init(
        self: *Surface,
        app: *App,
        title: LPCWSTR,
        config: *const configpkg.Config,
        opts: SurfaceInitOptions,
    ) !void {
        log.debug("surface.init begin", .{});
        const existing_host = if (opts.host_id) |host_id|
            app.findHostById(host_id) orelse return error.InvalidHost
        else
            null;
        var shell_prepared = try app.prepareShellSurfaceCreate(existing_host, opts);
        defer if (shell_prepared) |*prepared| prepared.deinit();

        const host = existing_host orelse
            try app.createHost(title, opts.clone_state_from, opts.quick_terminal);
        const created_host = existing_host == null;
        errdefer if (created_host) {
            // Its shell window was never committed. Clear it, or the focus
            // change while the window is destroyed audits this host as a
            // window the shell is missing.
            host.shell_id = null;
            // As `createHost` unwinds: the Host stays registered through
            // WM_DESTROY, which detaches its shell compositor.
            if (host.hwnd) |host_hwnd| {
                if (sys.DestroyWindow(host_hwnd) == 0) app.detachShellCompositorWindow(host_hwnd);
            }
            app.removeHost(host);
        };
        self.* = .{
            .app = app,
            .host = host,
            .adopted_session = if (opts.adopted_session) |pending| pending.takeAdopted() else null,
            .adopted_console = opts.adopted_session != null,
            .host_id = host.id,
            .host_active = true,
            .window_visible = false,
            .decorations_visible = initialDecorationsVisible(config, opts),
            .scrollbar_config = config.scrollbar,
            .render_trace = RenderTrace.init(app.core_app.alloc),
            // Unlike the render trace there is no single-claimant rule here:
            // the memory stage trace is JSONL and every surface appends its
            // own lifecycle records to the shared file, serialized by a
            // process-wide mutex in `bench_trace`.
            .memory_stage_trace = MemoryStageTrace.init(app.core_app.alloc),
            .undo_stack = win32_undo.UndoStack.init(app.core_app.alloc),
            .search_bar = win32_search_bar.SearchBar.init(app.core_app.alloc),
        };
        // `destroy` never runs for a Surface whose init fails, so free here
        // what it would: the strings, among them the launch command cloned
        // below and a title the core sets as it starts, and the traces.
        errdefer {
            self.freeOwnedStrings();
            self.render_trace.deinit(app.core_app.alloc);
            self.memory_stage_trace.deinit(app.core_app.alloc);
        }
        errdefer if (self.adopted_session) |*session| {
            session.pty.deinit();
            _ = windows.CloseHandle(session.client_process);
            self.adopted_session = null;
        };
        const launch_command = if (app.core_app.first)
            config.@"initial-command" orelse config.command
        else
            config.command;
        if (launch_command) |command| self.launch_command = try command.clone(app.core_app.alloc);
        self.drop_target = try win32_surface_drop_target.DropTarget.create(
            app.core_app.alloc,
            @ptrCast(self),
            &surfaceDropPayloadCallback,
        );
        errdefer {
            self.drop_target.?.deinit();
            self.drop_target = null;
        }
        self.background_opacity_default = normalizedBackgroundOpacity(config.@"background-opacity");
        // First memory-stage sample. Every later stage's private-bytes delta
        // is measured against this one, so it has to be the first thing that
        // happens after the trace field exists and before any window, DC,
        // GL or terminal allocation.
        self.noteBenchmarkMemoryStage(.surface_begin, null);

        const hwnd = sys.CreateWindowExW(
            0,
            class_name,
            std.unicode.utf8ToUtf16LeStringLiteral(""),
            surfaceWindowStyle(),
            0,
            0,
            10,
            10,
            host.hwnd,
            null,
            app.hinstance,
            self,
        ) orelse return lastError();
        errdefer _ = sys.DestroyWindow(hwnd);
        self.hwnd = hwnd;

        // Register the OLE drop target so Explorer / browser drops
        // land as typed input in the terminal. Failure is non-fatal:
        // the user loses the feature but the terminal still works.
        // Requires the STA apartment that `App.init` brought up via
        // `OleInitialize`.
        if (self.drop_target.?.register(hwnd)) {
            self.drop_target_registered = true;
        } else |err| {
            std.log.warn("drop target register failed hwnd={*} err={}", .{ hwnd, err });
        }
        errdefer if (self.drop_target_registered) {
            self.drop_target.?.revoke(hwnd);
            self.drop_target_registered = false;
        };

        const content_rect = host.contentRect() catch host.contentRectFromClient(.{
            .left = 0,
            .top = 0,
            .right = 1280,
            .bottom = 800,
        });
        _ = applyChildRect(hwnd, &self.placement, content_rect);
        self.placement.visible = false;
        self.placement.visible_known = true;
        log.debug("surface.init hwnd created", .{});
        self.noteBenchmarkMemoryStage(.child_hwnd_created, null);

        if (app.test_surface_init_stage) |stage| {
            try stage(self, .gl_context);
            self.noteBenchmarkMemoryStage(.gl_context_created, null);
        } else if (!build_config.d3d11 or (config.renderer == .opengl and !gl_startup.openGLUnavailable())) {
            // `ensureGLContext` publishes the pixel format before its stage
            // note, which only emits the wgl_* provenance fields after that.
            if (self.ensureGLContext()) |_| {
                log.debug("surface.init gl context created", .{});
            } else |err| {
                // Renderer init falls back to the Direct3D 11 beta.
                if (!build_config.d3d11) return err;
                self.renderer_gl_error = err;
            }
        }
        errdefer self.destroyGL();

        // `addSurface` below stops a running quit timer. If init then fails,
        // restart it once this Surface has left `windows`, or an app left
        // with no window would never quit.
        const quit_timer_was_running = app.quit_timer_id != null;
        try app.windows.append(app.core_app.alloc, self);
        errdefer {
            app.removeWindow(self);
            if (quit_timer_was_running) app.startQuitTimer();
        }
        log.debug("surface.init appended to app windows", .{});
        try app.core_app.addSurface(self);
        errdefer app.core_app.deleteSurface(self);
        log.debug("surface.init added to core app", .{});

        const prev_active_tab = host.active_tab;
        const prev_tab_count = host.tabs.items.len;
        var inserted_tab_index: ?usize = null;
        var split_rollback: ?SplitSurfaceAttachRollback = null;
        defer commitSplitSurfaceAttach(&split_rollback);
        if (opts.tab_id) |tab_id| {
            for (host.tabs.items) |*tab| {
                if (tab.id == tab_id) {
                    const inserted = try SplitTreeSurface.init(app.core_app.alloc, self);
                    defer {
                        var cleanup = inserted;
                        cleanup.deinit();
                    }
                    const focus_handle = tab.findHandle(@constCast(opts.clone_state_from.?)) orelse tab.focused;
                    const next_tree = try tab.tree.split(
                        app.core_app.alloc,
                        focus_handle,
                        opts.split_direction,
                        0.5,
                        &inserted,
                    );
                    const prev_tree = tab.tree;
                    const prev_focused = tab.focused;
                    tab.tree = next_tree;
                    tab.focused = tab.findHandle(self) orelse focus_handle;
                    split_rollback = .{
                        .tab = tab,
                        .tree = prev_tree,
                        .focused = prev_focused,
                    };
                    break;
                }
            } else return error.InvalidTab;
        } else {
            const tab_id = host.nextTabId();
            inserted_tab_index = requestedTabInsertIndex(opts.tab_insert_index, host.tabs.items.len);
            {
                var tab = try Tab.init(app.core_app.alloc, tab_id, self);
                errdefer tab.deinit();
                try host.tabs.insert(app.core_app.alloc, inserted_tab_index.?, tab);
            }
        }

        if (shell_prepared) |*prepared| {
            self.shell_id = prepared.created.pane;
            if (host.shell_id == null) host.shell_id = prepared.created.window;
            if (inserted_tab_index) |index| {
                host.tabs.items[index].shell_id = prepared.created.tab;
            }
        }
        // Rollback the tab entry if core_surface.init or later init steps fail.
        // Without this, a zombie tab with a dangling surface pointer would remain
        // in host.tabs, causing use-after-free on subsequent refreshChrome/layout.
        errdefer {
            // The chrome may have given the new tab a button and a UIA
            // provider, which the tab must not outlive (`Tab.deinit`), and a
            // reader was told about the button.
            var had_button = false;
            if (inserted_tab_index) |index| if (index < host.tabs.items.len) {
                had_button = host.tabs.items[index].button_hwnd != null;
                host.destroyTabButton(&host.tabs.items[index]);
            };
            rollbackFailedSurfaceAttach(
                &host.tabs,
                &host.active_tab,
                prev_active_tab,
                prev_tab_count,
                inserted_tab_index,
                &split_rollback,
            );
            if (had_button) host.notifyTabListUiaChanged();
            // The core's `set_title` may have relabelled a host that stays
            // for the tabs it had; `windowDestroyed` would refresh them.
            if (!created_host) runUiActionOrLog("failed surface chrome refresh failed", host.refreshChrome());
        }

        // The core opens the pty at the size read below. Give a new split its
        // pane's rect now, as `layout` will when activation shows it: the
        // split reset zoom, and the new pane, which the tab now focuses, has
        // no search bar. Otherwise the pty starts at the whole content size
        // and is resized ~40 ms after spawn, and a prompt drawn before that
        // resize is left with a misplaced cursor. The content rect is the
        // active tab's, so a split made in a background tab whose inspector
        // or decorations differ is still resized once on activation.
        if (split_rollback) |attach| {
            var spatial = try attach.tab.tree.spatial(app.core_app.alloc);
            defer spatial.deinit(app.core_app.alloc);
            const placement = host.splitPanePlacement(
                content_rect,
                spatial,
                attach.tab.focused,
                true,
                false,
            );
            _ = applyChildRect(hwnd, &self.placement, layoutRectToWin32(placement.pane_rect));
        }
        self.size = try app.clientSize(hwnd);
        log.debug("surface.init client size width={} height={}", .{ self.size.width, self.size.height });

        // Set initial content_scale from host DPI before core init
        self.content_scale = .{
            .x = @as(f32, @floatFromInt(host.current_dpi)) / 96.0,
            .y = @as(f32, @floatFromInt(host.current_dpi)) / 96.0,
        };

        if (opts.clone_state_from) |source| {
            if (sharesHostWindowState(self.host_id, source.host_id)) {
                self.copySharedWindowStateFrom(source);
            }
        }

        if (app.test_surface_init_stage) |stage| try stage(self, .core_surface) else {
            try self.core_surface.init(
                app.core_app.alloc,
                config,
                app.core_app,
                app,
                self,
            );
            self.core_initialized = true;
            log.debug("surface.init core surface initialized", .{});
            // The core read the child's size when its init began, and the
            // core's own init-time actions can lay the host out again before
            // it ends. `syncCoreSizeFromClientRect` recorded any such move in
            // `self.size` but could not forward it yet, and from here on it
            // compares against that record, so nothing would ever forward it.
            // The core ignores a size it already has.
            self.core_surface.sizeCallback(self.size) catch |err| {
                log.err("win32 size callback failed err={}", .{err});
            };
        }
        // Stop the core if a later step fails. This runs first, while the GL
        // context and the window its threads draw to are still alive.
        errdefer self.deinitCore();

        // Seed the dynamic title after core init's automatic command title,
        // but before any path can show the host. No UI mailbox has drained
        // yet, so later console title messages still win. A configured title
        // was already applied by the core and remains authoritative.
        if (opts.adopted_session) |pending| if (config.title == null) {
            self.setTitle(pending.title) catch |err| {
                log.warn("adopted window startup title failed err={}", .{err});
            };
        };

        // Same-host tabs/splits must stay hidden through init, but they still
        // need an initial occlusion sync so hidden child GL surfaces stop
        // rendering before activation ordering runs.
        const activate_during_init = shouldShowSurfaceImmediately(opts.host_id);
        self.setVisible(activate_during_init);
        sys.DragAcceptFiles(hwnd, 1);

        if (sys.GetFocus() == hwnd) {
            self.window_focused = true;
        }

        // Both the core and renderer default to focused, so always send the
        // actual state. Otherwise the first focus event may be ignored as
        // unchanged for a surface that started unfocused.
        self.focusChanged(self.window_focused);
        if (activate_during_init) {
            // Must stay ahead of every path below that can show the host
            // window (`SW_SHOWNOACTIVATE` / `presentWindow`): applying the
            // layered style to an already-visible window is what produces an
            // opaque-then-fade flash. No unit test observes that ordering
            // — see the doc comment on `applyInitialBackgroundOpacity`.
            self.applyInitialBackgroundOpacity(opts.clone_state_from);
            try host.refreshChrome();
            try host.layout();
            // The top-level host was created hidden and stays hidden until GL
            // and core initialization have succeeded, so a startup failure
            // reaches the fatal dialog without first presenting a blank host
            // window. Same-host tabs and splits never take this path.
            if (opts.show.showCommand()) |show_command| {
                if (host.hwnd) |host_hwnd| {
                    _ = sys.ShowWindow(host_hwnd, show_command);
                    _ = sys.UpdateWindow(host_hwnd);
                }
            }
            if (opts.show.takesFocus()) self.presentWindow();
            if (app.update_startup_ready) {
                // The first window of a start that opened none (initial-window
                // off) is where the failed-install banner can first show.
                app.reportFailedInstallerApply();
                app.maybeScheduleAutomaticUpdateCheck();
            }
            try self.requestRepaint();
        }

        if (opts.clone_state_from) |source| {
            if (!sharesHostWindowState(self.host_id, source.host_id)) {
                try self.inheritWindowStateFrom(source);
            }
        }
        if (shell_prepared) |*prepared| {
            try prepared.commit(&app.shell_runtime);
            self.shell_committed = true;
            // The caller's activation shows and focuses the new pane, which
            // is the model's `focus_surface`.
            app.applyShellEffects(prepared.effects(), .{ .focus = false });
            if (self.window_focused) app.commitShellSurfaceFocus(self);
        }
        // Existing-host tab/split creation is intentionally provisional here:
        // the shell reducer selects the new entity before the caller activates
        // its native surface. The next activation performs the stable audit.
        if (opts.host_id == null)
            app.auditShellNativeMapping("surface-create")
        else
            app.shell_audit_after_activation = true;
        // Only now does WM_DESTROY own the Surface: it runs `destroy`, which
        // frees it. Set any earlier, a failed step above has its unwinding
        // DestroyWindow free the Surface under these errdefers, and then
        // `createWindowSurface` frees it again.
        self.destroy_on_wm_destroy = true;
        // A terminal opened after a last-host close (quit-after-last-window-
        // closed = false, or inside its delay) is part of the session again.
        // Not before init commits: a failed one leaves no window, and the
        // last-host-close snapshot must still stand.
        app.session_state_saved_before_last_host_close = false;
    }

    test "Surface.init that fails after the core starts is unwound once, by init" {
        if (builtin.os.tag != .windows) return error.SkipZigTest;

        var core_app: CoreApp = undefined;
        var app: App = undefined;
        var host: Host = undefined;
        var existing: Surface = undefined;
        var session: TestSession = .{};
        try session.init(.{
            .core_app = &core_app,
            .app = &app,
            .hosts = &.{.{ .storage = &host, .register = true, .next_tab_id = 2 }},
            .surfaces = &.{.{ .storage = &existing, .host = &host }},
            .tabs = &.{.{ .host = &host, .surface = &existing, .id = 1 }},
            .shell_runtime_initialized = true,
        });
        defer session.deinit();
        // With COM, a tab button gets a UIA provider, as in the app.
        app.initComApartment();
        defer if (app.com_initialized) sys.OleUninitialize();
        try app.ensureWindowClass();
        defer _ = sys.UnregisterClassW(class_name, app.hinstance);
        const host_hwnd = try createTestHostWindow();
        defer _ = sys.DestroyWindow(host_hwnd);
        host.hwnd = host_hwnd;
        // The rollback's chrome refresh caches the window title, which
        // `Host.deinit` would free and the test session does not.
        defer if (host.cached_window_title) |value| std.testing.allocator.free(value);

        var shell_window = try app.shell_runtime.prepare(.create_window);
        defer shell_window.deinit();
        try shell_window.commit(&app.shell_runtime);
        host.shell_id = shell_window.created.window;

        const Stage = struct {
            var stale: bool = false;
            var surface_hwnd: ?HWND = null;

            fn run(surface: *Surface, stage: InitStage) anyerror!void {
                surface_hwnd = surface.hwnd;
                if (stage != .core_surface) return;
                // What the core's `set_title` leaves as it starts: the
                // title, and a button with a UIA provider for the new tab.
                // `syncTabButtons` cannot make the button here, since the
                // test executable has no manifest for the layered chrome.
                surface.title = try surface.app.core_app.alloc.dupeZ(u8, "PKG-05");
                const owner = surface.host.?;
                const tab = &owner.tabs.items[owner.tabs.items.len - 1];
                tab.button_hwnd = sys.CreateWindowExW(
                    0,
                    prompt_button_class,
                    std.unicode.utf8ToUtf16LeStringLiteral(""),
                    c.WS_CHILD,
                    0,
                    0,
                    1,
                    1,
                    owner.hwnd,
                    null,
                    surface.app.hinstance,
                    null,
                ) orelse return lastError();
                tab.uia_provider = owner.createChromeUiaProvider(tab.button_hwnd.?, owner.tabItemUiaState(tab.id));
                // Something commits to the shell runtime meanwhile, as an
                // interleaved focus change can, so the new tab's prepared
                // transaction no longer applies.
                if (stale) surface.app.shell_runtime.revision +%= 1;
            }
        };
        Stage.stale = true;
        Stage.surface_hwnd = null;
        app.test_surface_init_stage = &Stage.run;

        // The app has no window, and its quit timer is counting down.
        app.running = true;
        app.config.@"quit-after-last-window-closed-delay" = .{ .duration = 60 * std.time.ns_per_s };
        app.startQuitTimer();
        defer app.stopQuitTimer();
        try std.testing.expect(app.quit_timer_id != null);
        // The owner's last window already took the session's final snapshot.
        app.session_state_saved_before_last_host_close = true;

        // A reader was told about the new tab's button, so it hears that the
        // button is gone again when init fails.
        const root = try win32_uia.RootProvider.create(std.testing.allocator, @ptrFromInt(0x1));
        defer _ = win32_uia.RootProvider.Release(&root.base);
        host.root_uia_provider = root;
        defer host.root_uia_provider = null;
        const announced = win32_uia.events.testing_structure_changes;

        // Before the fix, the unwinding DestroyWindow sent WM_DESTROY, which
        // freed the Surface; the errdefers then read it and
        // `createWindowSurface` freed it a second time. The title, the tab's
        // UIA provider (`Tab.deinit` asserts it is gone) and the quit timer
        // `addSurface` stopped are left for init's errdefers to undo.
        try std.testing.expectError(
            error.StaleRevision,
            app.createWindowSurface(&app.config, default_title, .{ .host_id = host.id }),
        );
        try std.testing.expectEqual(announced + 1, win32_uia.events.testing_structure_changes);
        app.running = false;
        try std.testing.expect(sys.IsWindow(Stage.surface_hwnd.?) == 0);
        try std.testing.expectEqual(@as(usize, 1), host.tabs.items.len);
        try std.testing.expectEqual(&existing, host.tabs.items[0].focusedSurface().?);
        try std.testing.expectEqual(@as(usize, 0), app.windows.items.len);
        try std.testing.expectEqual(@as(usize, 0), core_app.surfaces.items.len);
        try std.testing.expect(app.quit_timer_id != null);
        // No terminal opened, so `terminate` must still keep that snapshot
        // rather than save the empty app over it.
        try std.testing.expect(app.session_state_saved_before_last_host_close);

        // Once init returns, the window owns the Surface: destroying it frees
        // the Surface once, and its tab and button with it.
        Stage.stale = false;
        const created = try app.createWindowSurface(&app.config, default_title, .{ .host_id = host.id });
        try std.testing.expect(created.destroy_on_wm_destroy);
        // A terminal that did open is part of the session again.
        try std.testing.expect(!app.session_state_saved_before_last_host_close);
        try std.testing.expectEqual(@as(usize, 2), host.tabs.items.len);
        // `destroy` unregisters the surfaces whose core it stops, and the
        // stub started none.
        core_app.deleteSurface(created);
        try std.testing.expect(sys.DestroyWindow(created.hwnd.?) != 0);
        try std.testing.expectEqual(@as(usize, 1), host.tabs.items.len);
        try std.testing.expectEqual(@as(usize, 0), app.windows.items.len);
    }

    test "Surface.init that fails before the core starts destroys the host window it created" {
        if (builtin.os.tag != .windows) return error.SkipZigTest;

        var core_app: CoreApp = undefined;
        var app: App = undefined;
        var session: TestSession = .{};
        try session.init(.{ .core_app = &core_app, .app = &app });
        defer session.deinit();
        const hinstance = app.hinstance;
        defer {
            // `createHost` registers its classes and nothing unregisters them.
            _ = sys.UnregisterClassW(class_name, hinstance);
            _ = sys.UnregisterClassW(host_class_name, hinstance);
            _ = sys.UnregisterClassW(palette_list_class_name, hinstance);
            _ = sys.UnregisterClassW(scrollbar_class_name, hinstance);
        }
        try app.ensureWindowClass();

        const Stage = struct {
            var host_hwnd: ?HWND = null;

            fn run(surface: *Surface, stage: InitStage) anyerror!void {
                std.debug.assert(stage == .gl_context);
                host_hwnd = surface.host.?.hwnd;
                // As a lost or below-floor GPU fails a new window.
                return error.TestGLContextFailed;
            }
        };
        Stage.host_hwnd = null;
        app.test_surface_init_stage = &Stage.run;
        // A new window forwarded in after the owner's last window closed
        // and took the session's final snapshot.
        app.session_state_saved_before_last_host_close = true;

        try std.testing.expectError(
            error.TestGLContextFailed,
            app.createWindowSurface(&app.config, default_title, .{}),
        );
        // No window opened, so `terminate` must keep that snapshot rather
        // than delete the session for an app with no windows.
        try std.testing.expect(app.session_state_saved_before_last_host_close);
        const host_hwnd = Stage.host_hwnd.?;
        defer if (sys.IsWindow(host_hwnd) != 0) {
            _ = sys.DestroyWindow(host_hwnd);
        };
        // Before the fix the Host was freed and its hidden window left behind.
        try std.testing.expect(sys.IsWindow(host_hwnd) == 0);
        try std.testing.expectEqual(@as(usize, 0), app.hosts.items.len);
    }

    pub fn deinit(self: *Surface) void {
        self.destroy();
    }

    pub fn core(self: *Surface) *CoreSurface {
        return &self.core_surface;
    }

    pub fn takeAdoptedSession(self: *Surface) ?ptypkg.AdoptedSession {
        const result = self.adopted_session;
        self.adopted_session = null;
        return result;
    }

    pub fn ref(self: *Surface, alloc: Allocator) !*Surface {
        _ = alloc;
        return self;
    }

    pub fn unref(self: *Surface, alloc: Allocator) void {
        _ = self;
        _ = alloc;
    }

    pub fn eql(a: *const Surface, b: *const Surface) bool {
        return a == b;
    }

    pub fn rtApp(self: *const Surface) *App {
        return self.app;
    }

    pub fn close(self: *const Surface, process_active: bool) void {
        // Core routes `process_active = true` here when
        // `config.confirm-close-surface` is set AND the terminal
        // cursor is not at a shell prompt — see
        // `Surface.needsConfirmQuit()`. Honour it with the non-modal
        // `HostOverlayMode.confirm` overlay: a chrome-themed Accept /
        // Cancel pair, focus trap, Esc cancels, Enter accepts. No
        // pump re-entry (unlike `MessageBoxW`).
        //
        // Cannot be `*const self` in practice: the overlay owns a
        // callback pointer back to this Surface for the accept
        // path, so we need the address. Zig lets us take `@constCast`
        // here — the stored pointer is only dereferenced back on the
        // UI thread, exactly where the core caller already ran.
        if (process_active) {
            const mutable: *Surface = @constCast(self);
            const host = mutable.host orelse {
                // No host = no overlay available = fall back to the
                // direct destroy. Shouldn't happen in practice; the
                // Win32 apprt always attaches a Host before close
                // paths fire.
                _ = mutable.requestClose();
                return;
            };
            // Not always the key that closed a terminal in front: a read-only
            // terminal whose program exits closes itself and asks, in
            // whichever tab it is.
            var title_buf: [32]u8 = undefined;
            var prompt: ConfirmPrompt = .{
                .title = "Close this terminal?",
                .body = "A process is still running. Closing this surface will terminate it.",
                .accept_label = "Close",
                .cancel_label = "Cancel",
                // Nothing to preview: this prompt is about a running
                // process, not about a payload.
            };
            const named_body = host.nameBackgroundTerminal(&prompt, mutable, &title_buf);
            defer if (named_body) |text| mutable.app.core_app.alloc.free(text);
            host.showConfirm(
                prompt,
                &surfaceConfirmCloseAccept,
                null,
                @ptrCast(mutable),
            ) catch |err| {
                // Cannot bypass the confirmation on overlay setup
                // failure — core asked us to protect a running
                // process, and unilaterally destroying the HWND here
                // would defeat `confirm-close-surface` every time
                // the overlay couldn't render. Leave the surface
                // alive; the user can retry the close action, and
                // if the overlay keeps failing that's a separate
                // (and loud) bug to file.
                std.log.warn("confirm overlay unavailable err={}; declining close to honour confirm-close-surface", .{err});
            };
            return;
        }
        const mutable: *Surface = @constCast(self);
        _ = mutable.requestClose();
    }

    /// Core's `confirm-close-surface` answer for this pane (a running
    /// process, `always`, or read-only mode), for a close that ends more
    /// than this pane. A pane whose core is not up has no process to lose.
    fn needsCloseConfirm(self: *Surface) bool {
        if (!self.core_initialized) return false;
        return self.core_surface.needsConfirmQuit();
    }

    fn requestClose(self: *Surface) bool {
        const hwnd = self.hwnd orelse return false;
        if (self.pending_close_tree != null or self.pending_shell_close != null) return false;
        const found = self.app.findTabForSurface(self) orelse {
            // Detached structural-history objects are deliberately outside
            // active ShellState and can be destroyed during history disposal.
            if (self.host) |host| if (host.structural_history_disposing) {
                return sys.DestroyWindow(hwnd) != 0;
            };
            log.err("refusing unpreflighted surface close: native tab mapping missing", .{});
            return false;
        };
        const handle = found.tab.findHandle(self) orelse return false;

        var next_tree: ?SplitTreeSurface = null;
        if (found.tab.tree.nodes.len > 1) {
            next_tree = found.tab.tree.remove(self.app.core_app.alloc, handle) catch |err| {
                log.warn("surface close preflight tree build failed err={}", .{err});
                return false;
            };
        }
        defer if (next_tree) |*tree| tree.deinit();

        if (!self.invalidateStructuralHistoryForClose()) return false;

        var shell_close: ?win32_shell.runtime.Prepared = null;
        if (self.app.shell_runtime_initialized) {
            const pane_id = self.shell_id orelse {
                log.err("refusing surface close: shell pane mapping missing", .{});
                return false;
            };
            const intent: win32_shell.intent.Intent = if (found.tab.tree.nodes.len > 1)
                .{ .close_pane = pane_id }
            else close_tab: {
                const tab_id = found.tab.shell_id orelse {
                    log.err("refusing surface close: shell tab mapping missing", .{});
                    return false;
                };
                break :close_tab .{ .close_tab = tab_id };
            };
            shell_close = self.app.shell_runtime.prepare(intent) catch |err| {
                log.err("surface close shell preflight rejected err={}", .{err});
                return false;
            };
        }
        defer if (shell_close) |*prepared| prepared.deinit();

        self.pending_close_tree = next_tree;
        next_tree = null;
        self.pending_shell_close = shell_close;
        shell_close = null;
        if (sys.DestroyWindow(hwnd) != 0) return true;

        if (self.pending_close_tree) |*tree| tree.deinit();
        self.pending_close_tree = null;
        if (self.pending_shell_close) |*prepared| prepared.deinit();
        self.pending_shell_close = null;
        return false;
    }

    pub fn captureUndoClearScreen(self: *Surface) !void {
        try self.captureUndoTerminalState(.clear_screen);
    }

    pub fn captureUndoReset(self: *Surface) !void {
        try self.captureUndoTerminalState(.reset);
    }

    pub fn invalidateRedoForSnapshotlessLocalAction(self: *Surface) void {
        self.undo_stack.clearRedo();
        self.invalidateRedoForNewLocalAction();
    }

    fn invalidateRedoForNewLocalAction(self: *Surface) void {
        if (self.host) |host| _ = host.clearStructuralRedo();
    }

    fn invalidateRedoForUnsupportedStructuralAction(self: *Surface) void {
        self.undo_stack.clearRedo();
        if (self.host) |host| _ = host.clearStructuralRedo();
    }

    fn invalidateRedoForUnsupportedTabStructuralAction(self: *Surface) void {
        const found = self.app.findTabForSurface(self) orelse {
            self.invalidateRedoForUnsupportedStructuralAction();
            return;
        };
        found.tab.clearRedoHistory();
        _ = found.host.clearStructuralRedo();
    }

    fn invalidateStructuralHistoryForClose(self: *Surface) bool {
        const found = self.app.findTabForSurface(self) orelse return true;
        found.tab.clearRedoHistory();
        return found.host.tryClearStructuralHistory(.normal);
    }

    fn invalidateStructuralHistoryForDestroy(self: *Surface) void {
        const found = self.app.findTabForSurface(self) orelse return;
        found.tab.clearRedoHistoryExcept(self);
        if (found.tab.tree.nodes.len == 1) {
            found.host.clearStructuralHistory(.normal);
            return;
        }
        _ = found.host.clearStructuralRedo();
    }

    fn pushUndoEntryAndInvalidateRedo(
        self: *Surface,
        entry: win32_undo.Entry,
    ) !void {
        // Redo invalidation must happen AFTER the new undo entry is
        // committed. If the push fails, the action is aborted and the
        // existing redo branch must remain reachable.
        try self.undo_stack.push(entry);
        self.invalidateRedoForNewLocalAction();
        self.app.scheduleUndoPruneTimer();
    }

    fn captureUndoTerminalState(self: *Surface, kind: win32_undo.Kind) !void {
        if (self.undo_capture_suspended) return;

        self.undo_stack.discardExpired(self.app.undoCutoffTimestampMs());
        const captured = captured: {
            self.core_surface.renderer_state.mutex.lock();
            defer self.core_surface.renderer_state.mutex.unlock();
            break :captured .{
                .bytes = try captureTerminalUndoStateBytes(
                    self.app.core_app.alloc,
                    self.core_surface.renderer_state.terminal,
                ),
                .generation = self.core_surface.io.pty_clear_generation,
            };
        };
        const state_bytes = captured.bytes;
        // Ownership moves into `entry` below.

        var entry: win32_undo.Entry = .{
            .kind = kind,
            .snapshot = switch (kind) {
                .clear_screen => .{ .clear_screen = .{ .state_bytes = state_bytes } },
                .reset => .{ .reset = .{ .state_bytes = state_bytes } },
            },
            .timestamp_ms = sys.GetTickCount64(),
            .sequence_id = self.app.nextUndoSequence(),
            .pty_clear_generation = captured.generation,
        };
        errdefer entry.deinit(self.app.core_app.alloc);
        try self.pushUndoEntryAndInvalidateRedo(entry);
    }

    fn captureSessionScrollback(
        self: *Surface,
        alloc: Allocator,
        max_lines: usize,
        remaining_budget: *usize,
    ) !?win32_session_state.ScrollbackSnapshot {
        if (max_lines == 0 or self.secure_input_ever_engaged) return null;
        // An end-session save is a sent message. It can arrive while this
        // surface is mid-init or mid-teardown, still in its tab tree but
        // without a live core, or while this thread waits inside a call made
        // under the renderer mutex (the core's copy path holds it across
        // `EmptyClipboard`, which sends to the previous clipboard owner).
        if (!self.core_initialized) return null;
        if (!self.core_surface.renderer_state.mutex.tryLock()) return null;
        defer self.core_surface.renderer_state.mutex.unlock();
        return captureTerminalScrollbackSnapshotAlloc(
            alloc,
            self.app.core_app.alloc,
            self.core_surface.renderer_state.terminal,
            max_lines,
            remaining_budget,
            unixMillis(),
        );
    }

    fn restoreSessionScrollback(
        self: *Surface,
        snapshot: win32_session_state.ScrollbackSnapshot,
        max_lines: usize,
    ) !bool {
        var scrollbar: terminal.Scrollbar = .zero;
        var restored_lines: usize = 0;
        {
            self.core_surface.renderer_state.mutex.lock();
            defer self.core_surface.renderer_state.mutex.unlock();
            restored_lines = try restoreTerminalScrollbackSnapshot(
                self.core_surface.renderer_state.terminal,
                snapshot,
                max_lines,
            );
            scrollbar = self.core_surface.renderer_state.terminal.screens.active.pages.scrollbar();
        }
        self.setScrollbar(scrollbar) catch |err| {
            log.warn("win32 session restore: snapshot scrollbar sync failed err={}", .{err});
        };
        self.requestRepaint() catch |err| {
            log.warn("win32 session restore: snapshot repaint request failed err={}", .{err});
        };
        return restored_lines > 0;
    }

    fn restoreUndoSnapshot(self: *Surface, entry: *const win32_undo.Entry) void {
        const alloc = self.app.core_app.alloc;
        const state_bytes = switch (entry.snapshot) {
            .clear_screen => |value| value.state_bytes,
            .reset => |value| value.state_bytes,
        };
        var restored: RestoredTerminalUndoState = .{};

        {
            self.core_surface.renderer_state.mutex.lock();
            defer self.core_surface.renderer_state.mutex.unlock();
            restored = restoreTerminalUndoState(
                self.core_surface.renderer_state.terminal,
                state_bytes,
                entry.pty_clear_generation != self.core_surface.io.pty_clear_generation,
            );
        }

        // Undo snapshots are serialized terminal state and may predate the
        // normal title setters. Keep the title-report cache on the same
        // control-byte policy as live OSC and automation title updates.
        appendSanitizedTitle(alloc, &self.title, restored.title) catch |err| {
            log.warn("undo snapshot title cache sync failed err={}", .{err});
        };
        appendOwnedString(alloc, &self.pwd, restored.pwd) catch |err| {
            log.warn("undo snapshot pwd cache sync failed err={}", .{err});
        };
        self.setScrollbar(restored.scrollbar) catch |err| {
            log.warn("undo snapshot scrollbar sync failed err={}", .{err});
        };
        self.refreshWindowTitle() catch |err| {
            log.warn("undo snapshot window title refresh failed err={}", .{err});
        };
        self.requestRepaint() catch |err| {
            log.warn("undo snapshot repaint request failed err={}", .{err});
        };
    }

    fn applyLocalUndoEntry(
        self: *Surface,
        entry: *const win32_undo.Entry,
        mode: enum { undo, redo },
    ) ?[]const u8 {
        switch (mode) {
            .undo => {
                self.restoreUndoSnapshot(entry);
                return switch (entry.kind) {
                    .clear_screen => "Clear screen undone.",
                    .reset => "Terminal reset undone.",
                };
            },

            .redo => {
                self.undo_capture_suspended = true;
                defer self.undo_capture_suspended = false;

                if (!self.reapplyUndoableAction(entry.kind)) return null;
                return switch (entry.kind) {
                    .clear_screen => "Clear screen redone.",
                    .reset => "Terminal reset redone.",
                };
            },
        }
    }

    fn reapplyUndoableAction(self: *Surface, kind: win32_undo.Kind) bool {
        switch (kind) {
            .clear_screen => {
                {
                    self.core_surface.renderer_state.mutex.lock();
                    defer self.core_surface.renderer_state.mutex.unlock();
                    if (self.core_surface.io.terminal.screens.active_key == .alternate) return false;
                }
                self.core_surface.io.queueMessage(
                    .{ .clear_screen = .{ .history = true } },
                    .unlocked,
                );
                return true;
            },

            .reset => {
                // The reset action itself: it keeps the Win32 input mode
                // ConPTY asked for and clears ConPTY's buffer too. Capture is
                // suspended, so it records no undo entry of its own.
                _ = self.core_surface.performBindingAction(.reset) catch |err| {
                    log.warn("redo reset failed err={}", .{err});
                    return false;
                };
                var scrollbar: terminal.Scrollbar = .zero;
                {
                    self.core_surface.renderer_state.mutex.lock();
                    defer self.core_surface.renderer_state.mutex.unlock();
                    scrollbar = self.core_surface.renderer_state.terminal.screens.active.pages.scrollbar();
                }

                appendOwnedString(self.app.core_app.alloc, &self.title, null) catch |err| {
                    log.warn("redo reset title cache clear failed err={}", .{err});
                };
                appendOwnedString(self.app.core_app.alloc, &self.pwd, null) catch |err| {
                    log.warn("redo reset pwd cache clear failed err={}", .{err});
                };
                self.setScrollbar(scrollbar) catch |err| {
                    log.warn("redo reset scrollbar sync failed err={}", .{err});
                };
                self.refreshWindowTitle() catch |err| {
                    log.warn("redo reset window title refresh failed err={}", .{err});
                };
                self.requestRepaint() catch |err| {
                    log.warn("redo reset repaint request failed err={}", .{err});
                };
                return true;
            },
        }
    }

    fn canReapplyUndoableAction(self: *Surface, kind: win32_undo.Kind) bool {
        switch (kind) {
            .clear_screen => {
                self.core_surface.renderer_state.mutex.lock();
                defer self.core_surface.renderer_state.mutex.unlock();
                return self.core_surface.io.terminal.screens.active_key != .alternate;
            },
            .reset => return true,
        }
    }

    fn localRedoUnavailableMessage(kind: win32_undo.Kind) []const u8 {
        return switch (kind) {
            .clear_screen => "Redo unavailable in alternate screen.",
            .reset => unreachable,
        };
    }

    fn applyLatestLocalUndo(self: *Surface) !?[]const u8 {
        const entry = (try self.undo_stack.popForUndo()) orelse return null;
        return self.applyLocalUndoEntry(entry, .undo);
    }

    fn applyLatestLocalRedo(self: *Surface) !?[]const u8 {
        const next = self.undo_stack.peekRedo() orelse return null;
        if (!self.canReapplyUndoableAction(next.kind)) return localRedoUnavailableMessage(next.kind);

        const entry = (try self.undo_stack.popForRedo()) orelse return null;
        const kind = entry.kind;
        const message = self.applyLocalUndoEntry(entry, .redo);
        if (message == null) {
            self.undo_stack.restoreLastRedoPop();
            return localRedoUnavailableMessage(kind);
        }
        return message;
    }

    fn present(self: *Surface) void {
        self.app.activateSurface(self);
    }

    fn presentWindow(self: *Surface) void {
        if (self.host) |host| {
            host.present();
            if (self.hwnd) |hwnd| _ = sys.SetFocus(hwnd);
            return;
        }
        const hwnd = self.hwnd orelse return;
        _ = sys.ShowWindow(hwnd, c.SW_SHOW);
        _ = sys.SetForegroundWindow(hwnd);
        _ = sys.SetFocus(hwnd);
    }

    fn windowHwnd(self: *const Surface) ?HWND {
        if (self.host) |host| return host.hwnd;
        return self.hwnd;
    }

    /// Whether the top-level window carries `WS_SYSMENU`: fullscreen strips
    /// it, and so does `window-decoration = none` on a frameless window, on
    /// Windows 10 and for the quick terminal (`undecoratedKeepsFrame`).
    /// `SC_KEYMENU` on such a window has no menu to open.
    fn hasWindowMenu(self: *const Surface) bool {
        const top = self.windowHwnd() orelse return false;
        const style: usize = @bitCast(sys.GetWindowLongPtrW(top, c.GWL_STYLE));
        return (style & c.WS_SYSMENU) != 0;
    }

    pub fn getTitle(self: *Surface) ?[:0]const u8 {
        return self.effectiveTitle();
    }

    fn terminalUiaProvider(self: *Surface) !*win32_uia.TerminalProvider {
        if (self.terminal_accessibility == null) {
            self.terminal_accessibility = try win32_terminal_accessibility.TerminalAccessibilitySession.create(
                std.heap.page_allocator,
                .{
                    .ctx = @ptrCast(self),
                    .hwnd = terminalAccessibilityHwnd,
                    .name = terminalAccessibilityName,
                    .focused = terminalAccessibilityFocused,
                    .capture = terminalAccessibilityCapture,
                    .scroll = terminalAccessibilityScroll,
                    .viewport = terminalAccessibilityViewport,
                    .defer_provider_release = terminalAccessibilityDeferProviderRelease,
                },
                c.WM_WINHOSTTY_UIA_QUERY_REFRESH,
                c.TERMINAL_UIA_TIMER_ID,
            );
        }
        const provider = try self.terminal_accessibility.?.acquireProvider();
        self.syncTerminalAccessibilityOutputInterest();
        return provider;
    }

    fn syncTerminalAccessibilityOutputInterest(self: *Surface) void {
        const interested = if (self.terminal_accessibility) |session|
            session.outputInterested()
        else
            false;
        if (!interested) {
            if (self.terminal_accessibility) |session| {
                session.resetSemanticOutputContinuity();
            }
        }
        self.core_surface.setTerminalOutputInterested(interested);
    }

    fn drainTerminalAccessibilityOutput(self: *Surface) void {
        self.syncTerminalAccessibilityOutputInterest();
        const session = self.terminal_accessibility orelse return;
        if (!session.outputInterested()) return;
        self.core_surface.drainTerminalOutput(
            @ptrCast(session),
            terminalAccessibilityOutputCallback,
        );
    }

    pub fn getContentScale(self: *const Surface) !apprt.ContentScale {
        return self.content_scale;
    }

    pub fn getSize(self: *const Surface) !apprt.SurfaceSize {
        return try App.resolveSurfaceSizeWithContext(
            self.app,
            self.size,
            self.hwnd,
            App.clientSize,
        );
    }

    pub fn getCursorPos(self: *const Surface) !apprt.CursorPos {
        return self.cursor_pos;
    }

    pub fn supportsClipboard(
        self: *const Surface,
        clipboard_type: apprt.Clipboard,
    ) bool {
        _ = self;
        return clipboard_type == .standard;
    }

    pub fn clipboardRequest(
        self: *Surface,
        clipboard_type: apprt.Clipboard,
        state: apprt.ClipboardRequest,
    ) !bool {
        if (clipboard_type != .standard) return false;
        // A program's read that would only be declined does not read the
        // clipboard first.
        if (state == .osc_52_read and self.core_surface.config.clipboard_read == .ask) {
            self.declineProgramRequest() catch |err| {
                log.info("clipboard read request declined err={}", .{err});
                return false;
            };
        }

        // `str` is always owned by `core_app.alloc`, so one defer covers both
        // clipboard reads and the synthesized empty-string fallback.
        const str: [:0]u8 = (try self.readClipboardText()) orelse switch (state) {
            .paste => return false,
            .osc_52_read => try self.app.core_app.alloc.dupeZ(u8, ""),
            .osc_52_write => unreachable,
        };
        defer self.app.core_app.alloc.free(str);

        self.core_surface.completeClipboardRequest(
            state,
            str,
            false,
        ) catch |err| switch (err) {
            error.UnsafePaste,
            error.UnauthorizedPaste,
            => {
                // Defer to the non-modal confirm overlay; dupes
                // `str` into surface-owned storage so the local
                // `text` lifetime doesn't need to span the async
                // gap. On accept `surfaceConfirmPasteAccept` calls
                // `completeClipboardRequest(state, …, true)`.
                self.requestPasteConfirm(state, str) catch |inner| {
                    std.log.warn("paste confirm dispatch failed err={}", .{inner});
                    return false;
                };
            },

            else => return err,
        };

        return true;
    }

    pub fn setClipboard(
        self: *Surface,
        clipboard_type: apprt.Clipboard,
        contents: []const apprt.ClipboardContent,
        confirm: bool,
    ) !void {
        if (clipboard_type != .standard) return;
        if (confirm) {
            // Non-modal confirm path: dup `contents` into surface-owned
            // storage + show the overlay. On accept
            // `surfaceConfirmWriteAccept` runs the same html-then-
            // plain branch as below; on cancel the dup is freed and
            // no write happens. Fire-and-forget from core's POV.
            self.requestWriteConfirm(clipboard_type, contents) catch |err| {
                std.log.warn("clipboard write confirm dispatch failed err={}", .{err});
            };
            return;
        }

        // Scan for text/html and text/plain. When both are offered
        // (e.g. `copy_to_clipboard = .html` emits both), write them
        // in a single OpenClipboard/EmptyClipboard/Close cycle so
        // consumers that understand CF_HTML (Word, WordPad, OneNote)
        // get the styled fragment and consumers that don't (Notepad,
        // cmd.exe) still get usable plain text.
        var html_content: ?[]const u8 = null;
        var plain_content: ?[]const u8 = null;
        for (contents) |content| {
            if (std.mem.eql(u8, content.mime, "text/html")) {
                html_content = content.data;
            } else if (std.mem.eql(u8, content.mime, "text/plain")) {
                plain_content = content.data;
            }
        }

        if (html_content) |html| {
            try self.writeClipboardHtml(html, plain_content);
            return;
        }
        if (plain_content) |plain| {
            try self.writeClipboardText(plain);
            return;
        }
    }

    pub fn defaultTermioEnv(self: *const Surface) !std.process.EnvMap {
        var env = try internal_os.getEnvMap(self.app.core_app.alloc);
        errdefer env.deinit();

        if (env.get("USERPROFILE") == null) {
            var buf: [std.fs.max_path_bytes]u8 = undefined;
            if (try internal_os.windows.knownFolderPathUtf8(
                &internal_os.windows.FOLDERID_Profile,
                &buf,
            )) |profile| {
                try env.put("USERPROFILE", profile);
            }
        }

        if (env.get("LOCALAPPDATA") == null) {
            var buf: [std.fs.max_path_bytes]u8 = undefined;
            if (try internal_os.windows.knownFolderPathUtf8(
                &internal_os.windows.FOLDERID_LocalAppData,
                &buf,
            )) |local_appdata| {
                try env.put("LOCALAPPDATA", local_appdata);
            }
        }

        return env;
    }

    pub fn redrawInspector(self: *Surface) void {
        if (!self.inspector_visible) return;
        self.requestRepaint() catch |err| {
            log.err("win32 inspector repaint request failed err={}", .{err});
        };
    }

