    try std.testing.expect(!sharedHostWindowOpacityEquals(&a, &b));

    b.background_opacity_force_opaque = false;
    b.background_opacity_default = 0.5001;
    try std.testing.expect(sharedHostWindowOpacityEquals(&a, &b));
}

